// ============================================================================
// Small utilities
// ============================================================================

static EPOCH: OnceLock<Instant> = OnceLock::new();

fn init_epoch() {
    let _ = EPOCH.set(Instant::now());
}

fn now_us() -> u64 {
    EPOCH.get().map(|e| e.elapsed().as_micros() as u64).unwrap_or(0)
}

fn format_us(us: u64) -> String {
    let secs = us / 1_000_000;
    let (h, m, s) = (secs / 3600, (secs / 60) % 60, secs % 60);
    if h > 0 { format!("{h:02}:{m:02}:{s:02}") } else { format!("{m:02}:{s:02}") }
}

/// A short duration, in the unit that suits it.
///
/// `format_us` is for the length of a recording and starts at minutes; this is for
/// the length of one step, where the interesting range is a millisecond to a few
/// seconds and "00:00" says nothing at all.
fn format_ms(us: u64) -> String {
    if us < 1_000 {
        format!("{us} \u{00b5}s")
    } else if us < 10_000_000 {
        format!("{:.0} ms", us as f64 / 1000.0)
    } else {
        format!("{:.1} s", us as f64 / 1_000_000.0)
    }
}

/// A file size a person can read at a glance.
fn bytes(n: u64) -> String {
    match n {
        0..=1023 => format!("{n} B"),
        1024..=1_048_575 => format!("{:.0} KB", n as f64 / 1024.0),
        _ => format!("{:.1} MB", n as f64 / 1_048_576.0),
    }
}

/// xorshift64* - the only randomness we need is playback jitter, so no dependency.
struct Rng(u64);

impl Rng {
    fn new() -> Self {
        let seed = now_us() ^ 0x9E37_79B9_7F4A_7C15 ^ ((std::process::id() as u64) << 32);
        Self(if seed == 0 { 0x2545_F491_4F6C_DD1D } else { seed })
    }
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn below(&mut self, bound: u64) -> u64 {
        if bound == 0 { 0 } else { self.next_u64() % bound }
    }
    /// Uniform value in `-span..=span`.
    fn signed(&mut self, span: i64) -> i64 {
        if span <= 0 { 0 } else { (self.next_u64() % (span as u64 * 2 + 1)) as i64 - span }
    }
    /// Uniform value in `-1.0..=1.0`.
    fn unit(&mut self) -> f32 {
        self.below(2001) as f32 / 1000.0 - 1.0
    }
}

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

/// At most `n` characters, with an ellipsis where something was cut.
///
/// By characters and not by bytes: everything this is used on can contain text the
/// screen was read for, and slicing a string at byte `n` panics the moment that text
/// is Cyrillic.
fn clip(s: &str, n: usize) -> String {
    if s.chars().count() <= n {
        return s.to_string();
    }
    s.chars().take(n.saturating_sub(1)).collect::<String>() + "…"
}

// ============================================================================
// Paths
// ============================================================================

mod paths {
    use std::path::{Path, PathBuf};
    use std::sync::OnceLock;

    static DATA_DIR: OnceLock<PathBuf> = OnceLock::new();

    fn is_writable(dir: &Path) -> bool {
        let probe = dir.join(".macro_recorder_write_test");
        match std::fs::File::create(&probe) {
            Ok(_) => {
                let _ = std::fs::remove_file(&probe);
                true
            }
            Err(_) => false,
        }
    }

    fn exe_dir() -> Option<PathBuf> {
        Some(std::env::current_exe().ok()?.parent()?.to_path_buf())
    }

    #[cfg(windows)]
    fn roaming_dir() -> Option<PathBuf> {
        known_folders::get_known_folder_path(known_folders::KnownFolder::RoamingAppData)
            .map(|p| p.join("MacroRecorder"))
    }

    #[cfg(not(windows))]
    fn roaming_dir() -> Option<PathBuf> {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".config/macro-recorder"))
    }

    /// Portable (next to the exe) when possible, otherwise %APPDATA%.
    pub fn data_dir() -> &'static Path {
        DATA_DIR.get_or_init(|| {
            if let Some(dir) = exe_dir()
                && is_writable(&dir) {
                    return dir;
                }
            if let Some(dir) = roaming_dir()
                && std::fs::create_dir_all(&dir).is_ok() && is_writable(&dir) {
                    return dir;
                }
            PathBuf::from(".")
        })
    }

    pub fn config_path() -> PathBuf {
        data_dir().join("config.json")
    }
    pub fn default_macro_path() -> PathBuf {
        data_dir().join("macro.json")
    }
    pub fn sub_dir(name: &str) -> PathBuf {
        let dir = data_dir().join(name);
        let _ = std::fs::create_dir_all(&dir);
        dir
    }
    pub fn log_dir() -> PathBuf {
        sub_dir("logs")
    }
    pub fn profiles_dir() -> PathBuf {
        sub_dir("profiles")
    }
    pub fn lang_dir() -> PathBuf {
        sub_dir("lang")
    }
    pub fn templates_dir() -> PathBuf {
        sub_dir("templates")
    }
    pub fn expansions_path() -> PathBuf {
        data_dir().join("expansions.json")
    }

    /// Creates the folders the documentation tells people to look for.
    ///
    /// `sub_dir` makes a folder the moment something touches it, which meant
    /// `templates/` only appeared once a PNG had already been saved - no use to
    /// somebody who wanted to drop one in beforehand.
    pub fn ensure_dirs() {
        let _ = log_dir();
        let _ = profiles_dir();
        let _ = lang_dir();
        let _ = templates_dir();
    }
}

/// Editor for what a step does when it does not find what it was looking for.
///
/// One row, everywhere it applies, so the answer to "what happens if this is not
/// there" is in the same place on every step that can ask it.
fn miss_ui(ui: &mut egui::Ui, s: &Strings, salt: &str, miss: &mut OnMiss) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(s.m_onmiss);
        let cur = miss.index();
        egui::ComboBox::from_id_salt(format!("{salt}_miss"))
            .selected_text(miss.name(s))
            .width(150.0)
            .show_ui(ui, |ui| {
                for i in 0..OnMiss::COUNT {
                    let opt = OnMiss::from_index(i);
                    if ui.selectable_label(cur == i, opt.name(s)).clicked() && cur != i {
                        *miss = opt;
                        changed = true;
                    }
                }
            });
        if let OnMiss::Recover { name } = miss {
            ui.label(s.f_recovery_name);
            changed |= ui
                .add(egui::TextEdit::singleline(name).desired_width(140.0))
                .changed();
        }
        if let OnMiss::Retry { times, delay_ms } = miss {
            changed |= ui.add(egui::DragValue::new(times).range(1..=100)).changed();
            ui.label(s.m_times);
            changed |= ui
                .add(egui::DragValue::new(delay_ms).range(0..=600_000).speed(50.0))
                .changed();
            ui.label(s.m_delay);
        }
    });
    changed
}

/// Editor for a search area. The same four choices wherever an image is looked for.
fn area_ui(ui: &mut egui::Ui, s: &Strings, salt: &str, area: &mut SearchArea) -> bool {
    let mut changed = false;
    let names = [s.a_full, s.a_window, s.a_rect, s.a_near, s.a_anchor];
    let mut idx = match area {
        SearchArea::FullScreen => 0,
        SearchArea::ActiveWindow => 1,
        SearchArea::Rect { .. } => 2,
        SearchArea::NearLast { .. } => 3,
        SearchArea::NearAnchor { .. } => 4,
    };
    ui.horizontal_wrapped(|ui| {
        ui.label(s.f_area);
        egui::ComboBox::from_id_salt(format!("{salt}_area"))
            .selected_text(names[idx])
            .width(150.0)
            .show_ui(ui, |ui| {
                for (i, n) in names.iter().enumerate() {
                    if ui.selectable_label(idx == i, *n).clicked() {
                        idx = i;
                    }
                }
            });
        // Switching kind keeps the numbers the old kind had, so flicking between them
        // while setting one up does not throw the work away.
        let want = match idx {
            1 => SearchArea::ActiveWindow,
            2 => match area {
                SearchArea::Rect { .. } => area.clone(),
                _ => SearchArea::Rect { x: 0, y: 0, w: 600, h: 400 },
            },
            3 => match area {
                SearchArea::NearLast { .. } => area.clone(),
                _ => SearchArea::NearLast { margin: 100 },
            },
            4 => match area {
                SearchArea::NearAnchor { .. } => area.clone(),
                _ => SearchArea::NearAnchor {
                    anchor: String::new(),
                    dx: -150,
                    dy: 0,
                    w: 300,
                    h: 120,
                },
            },
            _ => SearchArea::FullScreen,
        };
        if want != *area {
            *area = want;
            changed = true;
        }
        match area {
            SearchArea::Rect { x, y, w, h } => {
                for (label, v) in [("X", x), ("Y", y)] {
                    ui.label(label);
                    changed |=
                        ui.add(egui::DragValue::new(v).range(-32000..=32000)).changed();
                }
                for (label, v) in [("W", w), ("H", h)] {
                    ui.label(label);
                    changed |= ui.add(egui::DragValue::new(v).range(1..=32000)).changed();
                }
            }
            SearchArea::NearLast { margin } => {
                ui.label(s.f_margin);
                changed |= ui.add(egui::DragValue::new(margin).range(8..=2000)).changed();
            }
            _ => {}
        }
    });
    // The anchor gets its own row: a name, a picker and four numbers do not fit
    // beside the kind chooser on any sensible window width.
    if let SearchArea::NearAnchor { anchor, dx, dy, w, h } = area {
        ui.horizontal_wrapped(|ui| {
            ui.label(s.f_anchor);
            changed |= ui
                .add(egui::TextEdit::singleline(anchor).desired_width(120.0))
                .changed();
            changed |= template_picker(ui, &format!("{salt}_anchor"), anchor);
            for (label, v) in [("dX", dx), ("dY", dy)] {
                ui.label(label);
                changed |= ui.add(egui::DragValue::new(v).range(-32000..=32000)).changed();
            }
            for (label, v) in [("W", w), ("H", h)] {
                ui.label(label);
                changed |= ui.add(egui::DragValue::new(v).range(1..=32000)).changed();
            }
        });
    }
    changed
}

/// One line describing what an element query is looking for.
/// The editor for one target: its name, how hard to try, and every way of finding
/// it.
///
/// The cascade is shown as a list in the order it will actually be tried, with the
/// ones the reliability setting has switched off greyed rather than hidden — the
/// point of the setting is visible only if you can see what it left out.
fn target_ui(
    ui: &mut egui::Ui,
    s: &Strings,
    salt: &str,
    t: &mut Target,
    reliability: &mut Reliability,
) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(s.tg_label);
        changed |= ui
            .add(egui::TextEdit::singleline(&mut t.label).desired_width(160.0))
            .changed();
        ui.label(s.f_reliability);
        let mut ri = reliability.index();
        egui::ComboBox::from_id_salt(format!("{salt}rel"))
            .selected_text(reliability.name(s))
            .width(130.0)
            .show_ui(ui, |ui| {
                for i in 0..Reliability::COUNT {
                    let r = Reliability::from_index(i);
                    if ui.selectable_label(ri == i, r.name(s)).clicked() {
                        ri = i;
                    }
                }
            });
        let want = Reliability::from_index(ri);
        if want != *reliability {
            *reliability = want;
            changed = true;
        }
    });

    // Which methods this setting will actually use, so the greying below is the
    // truth rather than a guess about it.
    let live: Vec<Method> = t.cascade(*reliability);
    let will_try = |m: &Method| live.iter().any(|l| l == m);

    ui.label(egui::RichText::new(s.tg_methods).strong());
    let mut remove: Option<usize> = None;
    // Shown in the order they will be tried, which is not the order they are stored
    // in: a cascade built by hand must read the same way as one built by recording.
    let mut order: Vec<usize> = (0..t.methods.len()).collect();
    order.sort_by_key(|&i| std::cmp::Reverse(t.methods[i].rank()));

    for (row, &i) in order.iter().enumerate() {
        let on = will_try(&t.methods[i]);
        ui.horizontal_wrapped(|ui| {
            let head = if on {
                egui::RichText::new(format!("{}.", row + 1)).strong()
            } else {
                egui::RichText::new("—").weak()
            };
            ui.label(head);
            let mut mi = t.methods[i].index();
            egui::ComboBox::from_id_salt(format!("{salt}m{i}"))
                .selected_text(t.methods[i].name(s))
                .width(150.0)
                .show_ui(ui, |ui| {
                    for k in 0..Method::COUNT {
                        let m = Method::from_index(k);
                        if ui.selectable_label(mi == k, m.name(s)).clicked() {
                            mi = k;
                        }
                    }
                });
            if mi != t.methods[i].index() {
                t.methods[i] = Method::from_index(mi);
                changed = true;
            }
            if ui.button("🗑").clicked() {
                remove = Some(i);
            }
        });
        // The method's own fields, indented under it.
        ui.indent(format!("{salt}i{i}"), |ui| {
            let salt = format!("{salt}f{i}");
            match &mut t.methods[i] {
                Method::Element { query } => changed |= query_ui(ui, s, &salt, query),
                Method::Image { template, threshold, area, edge } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.f_template);
                        changed |= template_picker(ui, &salt, template);
                        changed |= ui
                            .add(egui::Slider::new(threshold, 0.5..=1.0).text(s.img_threshold))
                            .changed();
                    });
                    changed |= area_ui(ui, s, &salt, area);
                    changed |=
                        ui.checkbox(edge, s.f_edge).changed();
                }
                Method::Text { needle, x, y, w, h, prep } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.f_needle);
                        changed |= ui
                            .add(egui::TextEdit::singleline(needle).desired_width(160.0))
                            .changed();
                    });
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.f_region);
                        for (v, range) in [
                            (x, -32_768..=32_767),
                            (y, -32_768..=32_767),
                            (w, 1..=8_192),
                            (h, 1..=8_192),
                        ] {
                            changed |=
                                ui.add(egui::DragValue::new(v).range(range)).changed();
                        }
                    });
                    changed |= prep_picker(ui, s, &salt, prep);
                }
                Method::WindowPoint { window, dx, dy } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.tgt_title);
                        changed |= ui
                            .add(egui::TextEdit::singleline(window).desired_width(160.0))
                            .changed();
                        for v in [dx, dy] {
                            changed |= ui
                                .add(egui::DragValue::new(v).range(-32_768..=32_767))
                                .changed();
                        }
                    });
                }
                Method::Point { x, y } => {
                    ui.horizontal_wrapped(|ui| {
                        for v in [x, y] {
                            changed |= ui
                                .add(egui::DragValue::new(v).range(-32_768..=32_767))
                                .changed();
                        }
                    });
                }
            }
        });
    }
    if let Some(i) = remove {
        t.methods.remove(i);
        changed = true;
    }
    if ui.button(s.tg_add_method).clicked() {
        // A new way starts as the strongest kind that is not already there, because
        // adding a second coordinate is never what anybody means.
        let next = (0..Method::COUNT)
            .map(Method::from_index)
            .find(|m| !t.methods.iter().any(|e| e.index() == m.index()))
            .unwrap_or_else(|| Method::from_index(4));
        t.methods.push(next);
        changed = true;
    }
    changed
}

/// The editor for "which window": the four ways of naming one, the name, and
/// whether to look it up afresh every time.
fn window_ref_ui(ui: &mut egui::Ui, s: &Strings, salt: &str, w: &mut WindowRef) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(s.f_by);
        let mut bi = w.by.index();
        egui::ComboBox::from_id_salt(format!("{salt}by"))
            .selected_text(w.by.name(s))
            .width(160.0)
            .show_ui(ui, |ui| {
                for i in 0..By::COUNT {
                    let b = By::from_index(i);
                    if ui.selectable_label(bi == i, b.name(s)).clicked() {
                        bi = i;
                    }
                }
            });
        let want = By::from_index(bi);
        if want != w.by {
            w.by = want;
            changed = true;
        }
        changed |= ui
            .add(egui::TextEdit::singleline(&mut w.value).desired_width(200.0))
            .changed();
        // Only for the two that name a program, and only because the path is the one
        // nobody types by hand.
        if matches!(w.by, By::Executable) && ui.button("…").clicked()
            && let Some(picked) =
                rfd::FileDialog::new().add_filter("Program", &["exe"]).pick_file()
            {
                w.value = picked.to_string_lossy().to_string();
                changed = true;
            }
    });
    changed |= ui
        .checkbox(&mut w.re_acquire, s.f_reacquire)
        .changed();
    changed
}

fn describe_query(q: &uia::Query) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !q.control.is_empty() {
        parts.push(q.control.clone());
    }
    if !q.name.is_empty() {
        parts.push(format!("\"{}\"", q.name));
    }
    if !q.automation_id.is_empty() {
        parts.push(format!("#{}", q.automation_id));
    }
    if parts.is_empty() {
        parts.push("?".into());
    }
    parts.join(" ")
}

/// Editor for an element query.
fn query_ui(ui: &mut egui::Ui, s: &Strings, salt: &str, q: &mut uia::Query) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(s.f_name);
        changed |= ui
            .add(egui::TextEdit::singleline(&mut q.name).desired_width(150.0))
            .changed();
        let names: Vec<&str> =
            uia::CONTROLS.iter().map(|(n, _)| if n.is_empty() { s.f_any } else { *n }).collect();
        let mut idx = uia::CONTROLS
            .iter()
            .position(|(n, _)| n.eq_ignore_ascii_case(&q.control))
            .unwrap_or(0);
        ui.label(s.f_control);
        egui::ComboBox::from_id_salt(format!("{salt}_ctl"))
            .selected_text(names[idx])
            .width(96.0)
            .show_ui(ui, |ui| {
                for (i, n) in names.iter().enumerate() {
                    if ui.selectable_label(idx == i, *n).clicked() {
                        idx = i;
                    }
                }
            });
        let want = uia::CONTROLS[idx].0.to_string();
        if want != q.control {
            q.control = want;
            changed = true;
        }
    });
    ui.horizontal_wrapped(|ui| {
        ui.label(s.f_autoid);
        changed |= ui
            .add(egui::TextEdit::singleline(&mut q.automation_id).desired_width(130.0))
            .changed();
        changed |= ui.checkbox(&mut q.in_front, s.f_in_front).changed();
    });
    changed
}

/// Picker for where a piece of text is read from.
fn source_picker(
    ui: &mut egui::Ui,
    s: &Strings,
    salt: &str,
    src: &mut TextSource,
) -> bool {
    let names = [s.t_clipboard, s.t_wintitle, s.t_process, s.t_file];
    let mut idx = src.index();
    let mut changed = false;
    egui::ComboBox::from_id_salt(format!("{salt}_src"))
        .selected_text(names[idx])
        .width(140.0)
        .show_ui(ui, |ui| {
            for (i, n) in names.iter().enumerate() {
                if ui.selectable_label(idx == i, *n).clicked() {
                    idx = i;
                }
            }
        });
    if idx != src.index() {
        *src = TextSource::from_index(idx);
        changed = true;
    }
    if let TextSource::File(path) = src {
        changed |= ui
            .add(egui::TextEdit::singleline(path).desired_width(160.0))
            .changed();
    }
    changed
}

/// Picker for where a piece of text is sent.
fn sink_picker(ui: &mut egui::Ui, s: &Strings, salt: &str, sink: &mut TextSink) -> bool {
    let names = [s.t_clipboard, s.t_file];
    let mut idx = sink.index();
    let mut changed = false;
    egui::ComboBox::from_id_salt(format!("{salt}_sink"))
        .selected_text(names[idx])
        .width(120.0)
        .show_ui(ui, |ui| {
            for (i, n) in names.iter().enumerate() {
                if ui.selectable_label(idx == i, *n).clicked() {
                    idx = i;
                }
            }
        });
    if idx != sink.index() {
        *sink = TextSink::from_index(idx);
        changed = true;
    }
    if let TextSink::File { path, append } = sink {
        changed |= ui
            .add(egui::TextEdit::singleline(path).desired_width(150.0))
            .changed();
        changed |= ui.checkbox(append, s.f_append).changed();
    }
    changed
}

/// Editor for a script value: a number, or a piece of text.
///
/// The kind is a visible choice rather than something guessed from what was typed.
/// Guessing would make `007` and `7` the same value on some days and not others.
fn value_ui(ui: &mut egui::Ui, s: &Strings, salt: &str, v: &mut Value) -> bool {
    let mut changed = false;
    let names = [s.v_number, s.v_text];
    let mut idx = usize::from(v.is_text());
    egui::ComboBox::from_id_salt(format!("{salt}_kind"))
        .selected_text(names[idx])
        .width(78.0)
        .show_ui(ui, |ui| {
            for (i, n) in names.iter().enumerate() {
                if ui.selectable_label(idx == i, *n).clicked() {
                    idx = i;
                }
            }
        });
    if (idx == 1) != v.is_text() {
        // Carried across rather than reset: flicking between the two while setting
        // one up should not throw away what was typed.
        *v = if idx == 1 { Value::Str(v.as_text()) } else { Value::Num(v.as_num()) };
        changed = true;
    }
    match v {
        Value::Num(n) => changed |= ui.add(egui::DragValue::new(n).speed(0.5)).changed(),
        Value::Str(t) => {
            changed |= ui
                .add(egui::TextEdit::singleline(t).desired_width(150.0))
                .changed()
        }
    }
    changed
}

/// Picker for what is done to a region's pixels before it is read.
fn prep_picker(ui: &mut egui::Ui, s: &Strings, salt: &str, prep: &mut ocr::Prep) -> bool {
    let names = [s.p_none, s.p_ui, s.p_small, s.p_game, s.p_digits, s.p_auto];
    let mut idx = prep.index().min(names.len() - 1);
    ui.label(s.f_prep);
    egui::ComboBox::from_id_salt(format!("{salt}_prep"))
        .selected_text(names[idx])
        .width(118.0)
        .show_ui(ui, |ui| {
            for (i, n) in names.iter().enumerate() {
                if ui.selectable_label(idx == i, *n).clicked() {
                    idx = i;
                }
            }
        });
    let want = ocr::Prep::from_index(idx);
    if want != *prep {
        *prep = want;
        return true;
    }
    false
}

/// Picker for the expected format, with a box for the pattern when one is wanted.
fn expect_picker(ui: &mut egui::Ui, s: &Strings, salt: &str, e: &mut ocr::Expect) -> bool {
    let names = [s.x_any, s.x_int, s.x_dec, s.x_time, s.x_pattern];
    let mut idx = e.index().min(names.len() - 1);
    let mut changed = false;
    ui.label(s.f_expect);
    egui::ComboBox::from_id_salt(format!("{salt}_expect"))
        .selected_text(names[idx])
        .width(104.0)
        .show_ui(ui, |ui| {
            for (i, n) in names.iter().enumerate() {
                if ui.selectable_label(idx == i, *n).clicked() {
                    idx = i;
                }
            }
        });
    if idx != e.index() {
        *e = ocr::Expect::from_index(idx);
        changed = true;
    }
    if let ocr::Expect::Pattern(p) = e {
        changed |= ui
            .add(egui::TextEdit::singleline(p).desired_width(90.0))
            .changed();
    }
    changed
}

fn action_index(a: &expander::Action) -> usize {
    match a {
        expander::Action::Text => 0,
        expander::Action::PlayMacro => 1,
        expander::Action::StopAll => 2,
        expander::Action::RunProgram => 3,
    }
}

fn action_from_index(i: usize) -> expander::Action {
    match i {
        1 => expander::Action::PlayMacro,
        2 => expander::Action::StopAll,
        3 => expander::Action::RunProgram,
        _ => expander::Action::Text,
    }
}

fn trigger_index(t: &expander::Trigger) -> usize {
    match t {
        expander::Trigger::Inherit => 0,
        expander::Trigger::Delimiter => 1,
        expander::Trigger::Prefix(_) => 2,
        expander::Trigger::Instant => 3,
    }
}

fn trigger_from_index(i: usize, prefix: &str) -> expander::Trigger {
    match i {
        1 => expander::Trigger::Delimiter,
        2 => expander::Trigger::Prefix(if prefix.is_empty() {
            ";;".to_string()
        } else {
            prefix.to_string()
        }),
        3 => expander::Trigger::Instant,
        _ => expander::Trigger::Inherit,
    }
}

/// PNG files sitting in the templates folder.
///
/// Read on demand rather than cached: the list only matters while a picker is open,
/// and somebody who has just saved a new template expects to see it there at once.
fn template_names() -> Vec<String> {
    let mut out: Vec<String> = std::fs::read_dir(paths::templates_dir())
        .into_iter()
        .flatten()
        .flatten()
        .filter_map(|e| {
            let p = e.path();
            // A folder of PNGs is one template with several variants - the same
            // button in two themes, say - and `load_template_set` has always loaded
            // it. This list did not know that, so the checker reported a folder
            // template as a missing picture and the packager left it out. Harmless
            // while the check was a button somebody pressed; not harmless now that
            // an error stands between the user and the Run button.
            if p.is_dir() {
                if !has_png_inside(&p) {
                    return None;
                }
                return Some(p.file_name()?.to_string_lossy().into_owned());
            }
            if !p.extension().is_some_and(|x| x.eq_ignore_ascii_case("png")) {
                return None;
            }
            Some(p.file_stem()?.to_string_lossy().into_owned())
        })
        .collect();
    out.sort_unstable();
    out.dedup();
    out
}

fn has_png_inside(dir: &Path) -> bool {
    std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .flatten()
        .any(|e| e.path().extension().is_some_and(|x| x.eq_ignore_ascii_case("png")))
}

/// Is there a picture by this name, in either of the two shapes one can take?
///
/// `claim.png`, or a folder `claim/` with variants in it. One function, because the
/// checker, the packager and the resource audit all have to agree with the loader
/// about what counts as present, and three copies of this rule disagreed.
fn template_exists(name: &str) -> bool {
    let base = paths::templates_dir().join(name.trim());
    if base.is_dir() {
        return has_png_inside(&base);
    }
    base.with_extension("png").exists()
}

/// A dropdown of saved templates beside the name field, so a script juggling
/// several pictures needs none of their names typed from memory.
fn template_picker(ui: &mut egui::Ui, salt: &str, current: &mut String) -> bool {
    let mut changed = false;
    // No text of its own: egui paints the arrow itself, as a shape rather than
    // a glyph. The chevron that used to be here, U+25BE, is in the monospace
    // font and not in the proportional one this is drawn with, so it was an
    // empty square beside a perfectly good arrow for several releases.
    egui::ComboBox::from_id_salt(salt).selected_text("").width(26.0).show_ui(
        ui,
        |ui| {
            let names = template_names();
            if names.is_empty() {
                ui.label("templates/");
            }
            for name in names {
                if ui.selectable_label(*current == name, name.as_str()).clicked() {
                    *current = name;
                    changed = true;
                }
            }
        },
    );
    changed
}

// ============================================================================
// Text expander
// ============================================================================

/// Turns a typed abbreviation into a longer piece of text.
///
/// The engine watches the keyboard hook, keeps a short rolling buffer of the
/// characters that came out of it, and when the tail of that buffer matches an entry
/// it deletes what was typed and writes the replacement instead.
///
/// Three things about it are worth knowing before reading the code.
///
/// **The buffer is a privacy surface.** It holds what you have just typed, in any
/// application, which is a short step from what a keylogger holds. So it never
/// reaches the log at any level, never reaches the disk, is capped at 64 characters,
/// and is emptied whenever the foreground window changes.
///
/// **The hook must not do the work.** Detecting a match happens in the hook callback,
/// which Windows will silently unhook if it dawdles. Everything after that - the
/// backspaces, the replacement, the clipboard - is handed to a worker thread.
///
/// **Some input cannot be handled and is refused rather than guessed at.** An IME
/// commits characters that never correspond to the keystrokes the hook saw, and a
/// dead key turns two keystrokes into one character. In both cases the count of
/// backspaces needed is unknowable, so the buffer is emptied and nothing fires.
pub mod expander {
    use serde::{Deserialize, Serialize};

    /// When an entry fires.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub enum Trigger {
        /// Follow the global setting. What almost every entry should say.
        Inherit,
        /// After the abbreviation and then a delimiter: `addr` then a space.
        Delimiter,
        /// As soon as the abbreviation is typed, but only behind a marker: `;;sig`.
        Prefix(String),
        /// The moment the abbreviation appears, anywhere. Short ones will misfire.
        Instant,
    }

    /// How the replacement gets into the application.
    #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
    pub enum Insert {
        /// One synthetic keystroke per character. Works everywhere, slow for long text.
        Type,
        /// Through the clipboard and Ctrl+V. Instant, but not every window pastes
        /// that way and the clipboard has to be borrowed and given back.
        Paste,
    }

    /// What an entry does when it fires.
    ///
    /// A text expander that can also start and stop the thing this application is for
    /// stops being a bolted-on extra: `;farm` starts the macro, `;stop` ends it, and
    /// the abbreviation becomes a command line that works in any window.
    #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize, Default)]
    pub enum Action {
        /// Replace the abbreviation with the text. What every entry did until now.
        #[default]
        Text,
        /// Play the macro. If the text names a file, load that one first.
        PlayMacro,
        /// Stop whatever is running - recording, playback, everything.
        StopAll,
        /// Hand the text to the shell, the way the `Run` script step does.
        RunProgram,
    }

    /// How much the capitals matter.
    ///
    /// The documentation up to 1.5.0 said `ADDR` and `addr` were the same
    /// abbreviation. They were not - the comparison was exact, and the shouted
    /// version simply did nothing. This is the field that makes the question
    /// answerable rather than accidental.
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
    pub enum Case {
        /// Only the abbreviation exactly as written fires. What every entry has
        /// always done, so it stays the default and no existing book changes.
        #[default]
        Exact,
        /// Any casing fires; the replacement is used exactly as stored.
        Ignore,
        /// Any casing fires, and the replacement is shaped like what was typed:
        /// `addr` as written, `ADDR` shouted, `Addr` capitalised.
        Follow,
    }

    impl Case {
        pub const COUNT: usize = 3;
        pub fn index(self) -> usize {
            match self {
                Case::Exact => 0,
                Case::Ignore => 1,
                Case::Follow => 2,
            }
        }
        pub fn from_index(i: usize) -> Self {
            match i {
                1 => Case::Ignore,
                2 => Case::Follow,
                _ => Case::Exact,
            }
        }
    }

    /// The shape of what was actually typed, for `Case::Follow`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Shape {
        /// `addr`, or anything else that is not one of the two below.
        AsWritten,
        /// `ADDR` - every cased letter is a capital, and there are at least two.
        Shouted,
        /// `Addr` - the first cased letter is a capital and the rest are not.
        Capitalised,
    }

    /// Works out the shape of a typed abbreviation.
    ///
    /// A single capital letter is `Capitalised`, not `Shouted`: `A` is far more
    /// likely to be the start of a sentence than a shout, and shouting a one-letter
    /// abbreviation looks the same either way.
    pub fn shape_of(typed: &[char]) -> Shape {
        let cased: Vec<char> = typed.iter().copied().filter(|c| c.is_alphabetic()).collect();
        if cased.is_empty() {
            return Shape::AsWritten;
        }
        let uppers = cased.iter().filter(|c| c.is_uppercase()).count();
        if uppers == cased.len() && cased.len() > 1 {
            Shape::Shouted
        } else if uppers == 1 && cased[0].is_uppercase() {
            Shape::Capitalised
        } else {
            Shape::AsWritten
        }
    }

    /// Re-shapes a replacement to match what was typed.
    ///
    /// Only the literal text is touched. A `{clipboard}` or a `{date}` keeps whatever
    /// casing it arrives with, because shouting somebody's clipboard back at them is
    /// not what "preserve case" means to anyone.
    pub fn reshape(text: &str, shape: Shape) -> String {
        match shape {
            Shape::AsWritten => text.to_string(),
            Shape::Shouted => text.to_uppercase(),
            Shape::Capitalised => {
                let mut out = String::with_capacity(text.len());
                let mut done = false;
                for c in text.chars() {
                    if !done && c.is_alphabetic() {
                        out.extend(c.to_uppercase());
                        done = true;
                    } else {
                        out.push(c);
                    }
                }
                out
            }
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct Entry {
        #[serde(default = "yes")]
        pub enabled: bool,
        pub abbr: String,
        pub text: String,
        #[serde(default = "inherit")]
        pub trigger: Trigger,
        #[serde(default = "typing")]
        pub insert: Insert,
        #[serde(default)]
        pub action: Action,
        /// Absent from every book written before 1.6.0, and `Exact` is what those
        /// books have always done.
        #[serde(default)]
        pub case: Case,
    }

    fn yes() -> bool {
        true
    }
    fn inherit() -> Trigger {
        Trigger::Inherit
    }
    fn typing() -> Insert {
        Insert::Type
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct Book {
        /// The master switch. Off until asked for: this one types into other people's
        /// windows.
        #[serde(default)]
        pub enabled: bool,
        /// What `Trigger::Inherit` resolves to.
        #[serde(default = "delimiter")]
        pub default_trigger: Trigger,
        /// Characters that count as the end of a word.
        #[serde(default = "default_delims")]
        pub delimiters: String,
        /// Window titles, matched case-insensitively by substring, where the expander
        /// stays quiet. A password manager and a terminal belong here.
        #[serde(default)]
        pub excluded_windows: Vec<String>,
        #[serde(default)]
        pub entries: Vec<Entry>,
    }

    fn delimiter() -> Trigger {
        Trigger::Delimiter
    }
    fn default_delims() -> String {
        " \t\n.,;:!?)]}\"'".to_string()
    }

    impl Default for Book {
        fn default() -> Self {
            Self {
                enabled: false,
                default_trigger: Trigger::Delimiter,
                delimiters: default_delims(),
                excluded_windows: Vec::new(),
                entries: vec![
                    Entry {
                        enabled: true,
                        abbr: "addr".into(),
                        text: "221B Baker Street\nLondon".into(),
                        trigger: Trigger::Inherit,
                        insert: Insert::Type,
                        action: Action::Text,
                        case: Case::Exact,
                    },
                    Entry {
                        enabled: true,
                        abbr: "today".into(),
                        text: "{date}".into(),
                        trigger: Trigger::Inherit,
                        insert: Insert::Type,
                        action: Action::Text,
                        case: Case::Exact,
                    },
                    Entry {
                        enabled: true,
                        abbr: ";sig".into(),
                        text: "Kind regards,\n{cursor}".into(),
                        trigger: Trigger::Instant,
                        insert: Insert::Type,
                        action: Action::Text,
                        case: Case::Exact,
                    },
                    Entry {
                        enabled: true,
                        abbr: ";stop".into(),
                        text: String::new(),
                        trigger: Trigger::Instant,
                        insert: Insert::Type,
                        action: Action::StopAll,
                        case: Case::Exact,
                    },
                ],
            }
        }
    }

    /// One piece of a rendered replacement.
    ///
    /// A replacement is a list rather than a string because `{key:Tab}` and `{cursor}`
    /// cannot be expressed as characters: a keystroke has to be sent as a keystroke,
    /// and the cursor is moved after everything else has landed.
    #[derive(Clone, Debug, PartialEq)]
    pub enum Segment {
        Text(String),
        Key(u16),
        Cursor,
    }

    /// What the hook decided, for the worker to carry out.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Fire {
        /// Characters to delete, including the delimiter when there was one.
        pub backspaces: usize,
        pub segments: Vec<Segment>,
        pub insert: Insert,
        pub action: Action,
        /// The entry's raw text, for the actions that read it as a path.
        pub payload: String,
    }

    pub fn is_delimiter(book: &Book, c: char) -> bool {
        book.delimiters.contains(c)
    }

    fn resolve(book: &Book, t: &Trigger) -> Trigger {
        match t {
            Trigger::Inherit => match &book.default_trigger {
                Trigger::Inherit => Trigger::Delimiter,
                other => other.clone(),
            },
            other => other.clone(),
        }
    }

    /// Does `buf` end with `needle`, and is the character before it a word boundary?
    ///
    /// Returns the characters that actually matched, so the caller can see how they
    /// were capitalised. Comparison is per character rather than over lowercased
    /// strings: `to_lowercase` may turn one character into two, and a length that
    /// changed under the comparison would take the wrong number of backspaces with it.
    fn ends_on_boundary<'a>(
        book: &Book,
        buf: &'a [char],
        needle: &str,
        case: Case,
    ) -> Option<&'a [char]> {
        let n: Vec<char> = needle.chars().collect();
        if n.is_empty() || buf.len() < n.len() {
            return None;
        }
        let tail = &buf[buf.len() - n.len()..];
        let same = match case {
            Case::Exact => tail == &n[..],
            // Cyrillic, Greek and the rest: `eq_ignore_ascii_case` would quietly say
            // no, and this program ships in six languages.
            _ => tail
                .iter()
                .zip(n.iter())
                .all(|(a, b)| a == b || a.to_lowercase().eq(b.to_lowercase())),
        };
        if !same {
            return None;
        }
        // Without this, `addr` fires inside `readdr`.
        let boundary = match buf.len().checked_sub(n.len() + 1).map(|i| buf[i]) {
            Some(prev) => is_delimiter(book, prev),
            None => true,
        };
        boundary.then_some(tail)
    }

    /// Decides whether the character just typed completed an abbreviation.
    ///
    /// `allow_text` is false while a macro is replaying: an entry that types would
    /// fight with the macro, but one that only starts or stops something is exactly
    /// what somebody reaching for `;stop` wants.
    pub fn match_at(
        book: &Book,
        buf: &[char],
        typed: char,
        allow_text: bool,
    ) -> Option<Fire> {
        if !book.enabled || buf.is_empty() {
            return None;
        }
        let mut best: Option<(usize, Shape, &Entry)> = None;
        for e in book
            .entries
            .iter()
            .filter(|e| e.enabled && !e.abbr.is_empty())
            .filter(|e| allow_text || e.action != Action::Text)
        {
            let hit = match resolve(book, &e.trigger) {
                Trigger::Instant => ends_on_boundary(book, buf, &e.abbr, e.case)
                    .map(|m| (e.abbr.chars().count(), shape_of(m))),
                Trigger::Prefix(p) => {
                    let whole = format!("{p}{}", e.abbr);
                    // Shaped from the abbreviation only: the marker in `;;Sig` is
                    // punctuation and has no case to speak of.
                    ends_on_boundary(book, buf, &whole, e.case).map(|m| {
                        let skip = m.len().saturating_sub(e.abbr.chars().count());
                        (whole.chars().count(), shape_of(&m[skip..]))
                    })
                }
                _ => {
                    // The delimiter itself is the last character in the buffer, so the
                    // abbreviation has to be checked against everything before it.
                    if !is_delimiter(book, typed) {
                        None
                    } else {
                        let head = &buf[..buf.len() - 1];
                        ends_on_boundary(book, head, &e.abbr, e.case)
                            .map(|m| (e.abbr.chars().count() + 1, shape_of(m)))
                    }
                }
            };
            if let Some((back, shape)) = hit {
                // Longest wins, so `;sign` beats `;sig`.
                if best.is_none_or(|(b, _, _)| back > b) {
                    best = Some((back, shape, e));
                }
            }
        }
        let (backspaces, shape, entry) = best?;
        // A command reads its text as a path, so expanding placeholders in it and
        // splitting it into keystrokes would be nonsense.
        if entry.action != Action::Text {
            return Some(Fire {
                backspaces,
                segments: Vec::new(),
                insert: entry.insert,
                action: entry.action,
                payload: entry.text.clone(),
            });
        }
        let mut segments = render(&entry.text);
        // Only the literal pieces, and only when the entry asked for it.
        if entry.case == Case::Follow && shape != Shape::AsWritten {
            for seg in segments.iter_mut() {
                if let Segment::Text(t) = seg {
                    *t = reshape(t, shape);
                }
                // A `Capitalised` shape has spent itself on the first letter of the
                // first piece of text; anything after that is left alone.
                if shape == Shape::Capitalised && matches!(seg, Segment::Text(_)) {
                    break;
                }
            }
        }
        // In delimiter mode the delimiter was eaten with the abbreviation, so it has
        // to come back or the next word runs into the replacement.
        if matches!(resolve(book, &entry.trigger), Trigger::Delimiter) {
            match segments.last_mut() {
                Some(Segment::Text(t)) => t.push(typed),
                _ => segments.push(Segment::Text(typed.to_string())),
            }
        }
        Some(Fire {
            backspaces,
            segments,
            insert: entry.insert,
            action: Action::Text,
            payload: String::new(),
        })
    }

    /// Splits a replacement into segments, expanding the placeholders.
    ///
    /// A backslash escapes the next character, which is how a replacement can contain
    /// a literal `{date}`.
    pub fn render(text: &str) -> Vec<Segment> {
        let mut out: Vec<Segment> = Vec::new();
        let mut lit = String::new();
        let mut it = text.chars().peekable();
        let push_lit = |out: &mut Vec<Segment>, lit: &mut String| {
            if !lit.is_empty() {
                out.push(Segment::Text(std::mem::take(lit)));
            }
        };
        while let Some(c) = it.next() {
            match c {
                '\\' => {
                    if let Some(n) = it.next() {
                        lit.push(n);
                    }
                }
                '{' => {
                    let mut token = String::new();
                    let mut closed = false;
                    for t in it.by_ref() {
                        if t == '}' {
                            closed = true;
                            break;
                        }
                        token.push(t);
                    }
                    if !closed {
                        // An unclosed brace is a typo, not a token. Show it as typed.
                        lit.push('{');
                        lit.push_str(&token);
                        continue;
                    }
                    let (name, arg) = match token.split_once(':') {
                        Some((n, a)) => (n.trim(), a),
                        None => (token.trim(), ""),
                    };
                    match name {
                        "cursor" => {
                            push_lit(&mut out, &mut lit);
                            out.push(Segment::Cursor);
                        }
                        "key" => {
                            if let Some(vk) = key_by_name(arg.trim()) {
                                push_lit(&mut out, &mut lit);
                                out.push(Segment::Key(vk));
                            }
                        }
                        "date" => lit.push_str(&stamp(if arg.is_empty() {
                            "yyyy-MM-dd"
                        } else {
                            arg
                        })),
                        "time" => {
                            lit.push_str(&stamp(if arg.is_empty() { "HH:mm" } else { arg }))
                        }
                        "datetime" => lit.push_str(&stamp(if arg.is_empty() {
                            "yyyy-MM-dd HH:mm"
                        } else {
                            arg
                        })),
                        "clipboard" => lit.push_str(&clipboard_text()),
                        "random" => {
                            let choices: Vec<&str> =
                                arg.split('|').filter(|s| !s.is_empty()).collect();
                            if !choices.is_empty() {
                                let i = (super::now_us() as usize) % choices.len();
                                lit.push_str(choices[i]);
                            }
                        }
                        // Anything unrecognised is left as the user wrote it, which is
                        // friendlier than swallowing a typo silently.
                        _ => {
                            lit.push('{');
                            lit.push_str(&token);
                            lit.push('}');
                        }
                    }
                }
                _ => lit.push(c),
            }
        }
        push_lit(&mut out, &mut lit);
        out
    }

    pub fn key_by_name(name: &str) -> Option<u16> {
        Some(match name.to_ascii_lowercase().as_str() {
            "tab" => 0x09,
            "enter" | "return" => 0x0D,
            "esc" | "escape" => 0x1B,
            "space" => 0x20,
            "backspace" => 0x08,
            "delete" | "del" => 0x2E,
            "home" => 0x24,
            "end" => 0x23,
            "up" => 0x26,
            "down" => 0x28,
            "left" => 0x25,
            "right" => 0x27,
            "pageup" => 0x21,
            "pagedown" => 0x22,
            _ => return None,
        })
    }

    /// Formats the current local time. A hand-rolled subset of the .NET patterns,
    /// which read better to a non-programmer than strftime and cost less than a date
    /// library.
    pub fn stamp(fmt: &str) -> String {
        let (y, mo, d, h, mi, sec) = local_now();
        fmt.replace("yyyy", &format!("{y:04}"))
            .replace("yy", &format!("{:02}", y % 100))
            .replace("MM", &format!("{mo:02}"))
            .replace("dd", &format!("{d:02}"))
            .replace("HH", &format!("{h:02}"))
            .replace("mm", &format!("{mi:02}"))
            .replace("ss", &format!("{sec:02}"))
    }

    #[cfg(windows)]
    fn local_now() -> (u16, u16, u16, u16, u16, u16) {
        unsafe {
            let t = windows::Win32::System::SystemInformation::GetLocalTime();
            (t.wYear, t.wMonth, t.wDay, t.wHour, t.wMinute, t.wSecond)
        }
    }

    #[cfg(not(windows))]
    fn local_now() -> (u16, u16, u16, u16, u16, u16) {
        (2026, 1, 1, 0, 0, 0)
    }

    #[cfg(windows)]
    fn clipboard_text() -> String {
        super::platform::clipboard_text()
    }

    #[cfg(not(windows))]
    fn clipboard_text() -> String {
        String::new()
    }

    // ---- live state ------------------------------------------------------

    use crossbeam_channel::Sender;
    use parking_lot::Mutex;
    use std::sync::LazyLock;
    use std::sync::OnceLock;
    use std::sync::atomic::{AtomicIsize, Ordering};

    static BOOK: LazyLock<Mutex<Book>> = LazyLock::new(|| Mutex::new(Book::default()));
    /// The characters typed recently. Capped, never logged, never written to disk.
    static BUF: LazyLock<Mutex<Vec<char>>> = LazyLock::new(|| Mutex::new(Vec::new()));
    static LAST_WINDOW: AtomicIsize = AtomicIsize::new(0);
    static TX: OnceLock<Sender<Fire>> = OnceLock::new();

    const BUF_MAX: usize = 64;

    pub fn snapshot() -> Book {
        BOOK.lock().clone()
    }

    pub fn enabled() -> bool {
        BOOK.lock().enabled
    }

    pub fn set_enabled(on: bool) {
        BOOK.lock().enabled = on;
        reset();
    }

    /// Swaps in a book edited elsewhere. The buffer goes with it: entries that no
    /// longer exist must not fire off half-typed words.
    pub fn replace(book: Book) {
        *BOOK.lock() = book;
        reset();
    }

    pub fn reset() {
        BUF.lock().clear();
    }

    pub fn load() {
        let path = super::paths::expansions_path();
        let book = std::fs::read_to_string(&path)
            .ok()
            .and_then(|t| match serde_json::from_str::<Book>(&t) {
                Ok(b) => Some(b),
                Err(e) => {
                    tracing::warn!("expansions.json could not be read: {e}");
                    None
                }
            });
        match book {
            Some(b) => *BOOK.lock() = b,
            None => {
                let d = Book::default();
                let _ = save(&d);
                *BOOK.lock() = d;
            }
        }
    }

    pub fn save(book: &Book) -> std::io::Result<()> {
        let text = serde_json::to_string_pretty(book)
            .map_err(|e| std::io::Error::other(e.to_string()))?;
        std::fs::write(super::paths::expansions_path(), text)
    }

    pub fn save_current() -> std::io::Result<()> {
        let b = BOOK.lock().clone();
        save(&b)
    }

    // ---- the hook side ---------------------------------------------------

    /// Feeds one keystroke in. Called from the keyboard hook, so it does the least
    /// it can get away with and hands anything slow to the worker.
    #[cfg(windows)]
    pub fn on_key(vk: u16, scan: u16, down: bool) {
        use super::win32::*;
        if !down {
            return;
        }
        // Never while the application is doing its own thing: expanding into a
        // recording writes the expansion into the macro, and expanding during
        // playback fights with it.
        // Recording swallows the expander whole: the keystrokes would go into the
        // macro and the expansion with them. Playback only rules out the entries that
        // type, which is what leaves `;stop` able to stop it.
        let mut allow_text = true;
        if let Some(st) = super::GLOBAL_STATE.get() {
            if st.recording.load(Ordering::Relaxed) {
                reset();
                return;
            }
            allow_text = !st.playing.load(Ordering::Relaxed);
        }
        let book = BOOK.lock().clone();
        if !book.enabled || book.entries.is_empty() {
            return;
        }

        unsafe {
            let fg = GetForegroundWindow();
            // A buffer carried from one window into another would match text the
            // user never typed here, so the window change empties it.
            if LAST_WINDOW.swap(fg.0 as isize, Ordering::Relaxed) != fg.0 as isize {
                reset();
            }
            if window_excluded(&book, fg) {
                reset();
                return;
            }

            // A modifier pressed by itself types nothing and moves nothing, and
            // treating it as the end of a word broke the commonest case there is:
            // Alt+Shift switches the keyboard layout, so a Cyrillic word followed by
            // an English one had the buffer cleared in between, and the second word
            // looked like the start of a line. Which is how `предt1` expanded.
            let modifier_itself = matches!(
                vk,
                0x10..=0x12       // Shift, Ctrl, Alt
                    | 0x14        // Caps Lock
                    | 0x5B..=0x5C // Win
                    | 0xA0..=0xA5 // the left and right halves of each
            );
            if modifier_itself {
                return;
            }
            let ctrl = GetAsyncKeyState(VK_CONTROL.0 as i32) < 0;
            let alt = GetAsyncKeyState(VK_MENU.0 as i32) < 0;
            let win = GetAsyncKeyState(VK_LWIN.0 as i32) < 0
                || GetAsyncKeyState(VK_RWIN.0 as i32) < 0;
            // A Win combination never writes into the focused field, so it leaves the
            // word alone too - Win+Space being the other way people change layout.
            if win {
                return;
            }
            // Ctrl and Alt combinations do edit and do move the caret: Ctrl+A,
            // Ctrl+V, Ctrl+Backspace. Those really are the end of a word.
            if ctrl || alt {
                reset();
                return;
            }

            let mut ks = [0u8; 256];
            if GetAsyncKeyState(VK_SHIFT.0 as i32) < 0 {
                ks[VK_SHIFT.0 as usize] = 0x80;
            }
            if GetKeyState(VK_CAPITAL.0 as i32) & 1 != 0 {
                ks[VK_CAPITAL.0 as usize] = 0x01;
            }

            let layout = GetKeyboardLayout(GetWindowThreadProcessId(fg, None));
            let mut out = [0u16; 8];
            let n = ToUnicodeEx(vk as u32, scan as u32, &ks, &mut out, 0, Some(layout));
            if n < 0 {
                // A dead key: the next keystroke will produce one character out of
                // two, and the count of backspaces stops being knowable. Flush the
                // kernel's dead-key state and give up on this word.
                let _ = ToUnicodeEx(vk as u32, scan as u32, &ks, &mut out, 0, Some(layout));
                reset();
                return;
            }
            if n == 0 {
                // Arrows, function keys, Home, End: no character, and the caret may
                // have moved somewhere the buffer knows nothing about.
                reset();
                return;
            }
            let text = String::from_utf16_lossy(&out[..n as usize]);
            for c in text.chars() {
                feed(&book, c, allow_text);
            }
        }
    }

    #[cfg(not(windows))]
    pub fn on_key(_vk: u16, _scan: u16, _down: bool) {}

    /// Adds one character and fires if it completed an abbreviation.
    fn feed(book: &Book, raw: char, allow_text: bool) {
        let c = match raw {
            '\r' => '\n',
            '\u{8}' => {
                BUF.lock().pop();
                return;
            }
            c if (c as u32) < 0x20 && c != '\t' && c != '\n' => {
                reset();
                return;
            }
            c => c,
        };
        let fire = {
            let mut buf = BUF.lock();
            buf.push(c);
            if buf.len() > BUF_MAX {
                let cut = buf.len() - BUF_MAX;
                buf.drain(..cut);
            }
            match match_at(book, &buf, c, allow_text) {
                Some(f) => {
                    buf.clear();
                    Some(f)
                }
                None => None,
            }
        };
        if let Some(f) = fire
            && let Some(tx) = TX.get() {
                let _ = tx.try_send(f);
            }
    }

    #[cfg(windows)]
    fn window_excluded(book: &Book, hwnd: super::win32::HWND) -> bool {
        use super::win32::*;
        if book.excluded_windows.is_empty() {
            return false;
        }
        unsafe {
            let mut buf = [0u16; 256];
            let n = GetWindowTextW(hwnd, &mut buf);
            if n <= 0 {
                return false;
            }
            let title = String::from_utf16_lossy(&buf[..n as usize]).to_lowercase();
            book.excluded_windows
                .iter()
                .any(|x| !x.trim().is_empty() && title.contains(&x.trim().to_lowercase()))
        }
    }

    // ---- the worker side -------------------------------------------------

    pub fn start_worker() {
        let (tx, rx) = crossbeam_channel::unbounded::<Fire>();
        if TX.set(tx).is_err() {
            return;
        }
        let _ = std::thread::Builder::new().name("expander".into()).spawn(move || {
            for f in rx {
                // The keystroke that triggered this was let through rather than
                // swallowed, so give the application a moment to draw it before
                // deleting it again.
                std::thread::sleep(std::time::Duration::from_millis(12));
                deliver(&f);
            }
        });
    }

    #[cfg(windows)]
    fn deliver(f: &Fire) {
        for _ in 0..f.backspaces {
            tap(0x08);
        }
        if f.action != Action::Text {
            run_action(f);
            return;
        }
        // Everything after the cursor marker has to be walked back over at the end.
        let mut after_cursor: Option<usize> = None;
        let plain: Option<&str> = match f.segments.as_slice() {
            [Segment::Text(t)] => Some(t.as_str()),
            _ => None,
        };
        if f.insert == Insert::Paste
            && let Some(t) = plain
                && paste(t) {
                    return;
                }
        for seg in &f.segments {
            match seg {
                Segment::Text(t) => {
                    for c in t.chars() {
                        match c {
                            // A carriage return is half of a Windows line ending and
                            // has nothing of its own to show.
                            '\r' => continue,
                            // Edit controls ignore U+000A and U+0009 arriving as
                            // unicode scan codes. A line break has to be a real
                            // Return, and a tab a real Tab.
                            '\n' => tap(0x0D),
                            '\t' => tap(0x09),
                            _ => unicode_char(c),
                        }
                        if let Some(n) = after_cursor.as_mut() {
                            *n += 1;
                        }
                    }
                }
                Segment::Key(vk) => tap(*vk),
                Segment::Cursor => after_cursor = Some(0),
            }
        }
        for _ in 0..after_cursor.unwrap_or(0) {
            tap(0x25); // VK_LEFT
        }
    }

    #[cfg(not(windows))]
    fn deliver(_f: &Fire) {}

    /// Carries out a command entry. On the worker thread, never in the hook.
    fn run_action(f: &Fire) {
        let Some(state) = super::GLOBAL_STATE.get() else {
            return;
        };
        match f.action {
            Action::StopAll => super::stop_everything(state),
            Action::RunProgram => super::run_program(f.payload.trim(), ""),
            Action::PlayMacro => {
                let path = f.payload.trim();
                if !path.is_empty() {
                    // A named file makes the abbreviation a launcher rather than a
                    // second Play button.
                    match super::load_macro(std::path::Path::new(path)) {
                        Ok(data) => *state.macro_data.lock() = data,
                        Err(e) => {
                            tracing::warn!("expander could not load {path}: {e}");
                            return;
                        }
                    }
                }
                super::start_playback(state);
            }
            Action::Text => {}
        }
    }

    #[cfg(windows)]
    fn tap(vk: u16) {
        use super::win32::*;
        // Virtual key alone is not enough. This project already learned that once -
        // the replay path sends scan codes because that is what games and a good many
        // controls actually read - and a synthetic Return with no scan code behind it
        // is exactly the kind of keystroke that arrives nowhere.
        let extended = matches!(
            vk,
            0x21..=0x28 // PageUp, PageDown, End, Home, arrows
                | 0x2D    // Insert
                | 0x2E    // Delete
                | 0x5B    // Left Win
                | 0x5C    // Right Win
                | 0xA3    // Right Ctrl
                | 0xA5 // Right Alt
        );
        unsafe {
            let scan = MapVirtualKeyW(vk as u32, MAPVK_VK_TO_VSC) as u16;
            for up in [false, true] {
                let mut input = INPUT { r#type: INPUT_KEYBOARD, ..Default::default() };
                input.Anonymous.ki.wVk = VIRTUAL_KEY(vk);
                input.Anonymous.ki.wScan = scan;
                let mut flags = KEYBD_EVENT_FLAGS(0);
                if up {
                    flags |= KEYEVENTF_KEYUP;
                }
                if extended {
                    flags |= KEYEVENTF_EXTENDEDKEY;
                }
                input.Anonymous.ki.dwFlags = flags;
                SendInput(&[input], std::mem::size_of::<INPUT>() as i32);
            }
        }
    }

    #[cfg(windows)]
    fn unicode_char(c: char) {
        use super::win32::*;
        let mut units = [0u16; 2];
        for unit in c.encode_utf16(&mut units).iter() {
            unsafe {
                for up in [false, true] {
                    let mut input = INPUT { r#type: INPUT_KEYBOARD, ..Default::default() };
                    input.Anonymous.ki.wScan = *unit;
                    input.Anonymous.ki.dwFlags = if up {
                        KEYEVENTF_UNICODE | KEYEVENTF_KEYUP
                    } else {
                        KEYEVENTF_UNICODE
                    };
                    SendInput(&[input], std::mem::size_of::<INPUT>() as i32);
                }
            }
        }
    }

    /// Borrows the clipboard, pastes, and gives it back. Returns false when the
    /// clipboard would not cooperate, so the caller can type the text instead.
    #[cfg(windows)]
    fn paste(text: &str) -> bool {
        use super::win32::*;
        let saved = clipboard_text();
        // Windows edit controls want CRLF, and normalising first keeps text that
        // already had it from gaining a second carriage return.
        let text = text.replace("\r\n", "\n").replace('\n', "\r\n");
        unsafe {
            if !set_clipboard_text(&text) {
                return false;
            }
            let ctrl = VIRTUAL_KEY(0x11);
            let v = VIRTUAL_KEY(0x56);
            for (key, up) in [(ctrl, false), (v, false), (v, true), (ctrl, true)] {
                let mut input = INPUT { r#type: INPUT_KEYBOARD, ..Default::default() };
                input.Anonymous.ki.wVk = key;
                input.Anonymous.ki.dwFlags =
                    if up { KEYEVENTF_KEYUP } else { KEYBD_EVENT_FLAGS(0) };
                SendInput(&[input], std::mem::size_of::<INPUT>() as i32);
            }
            // Long enough for the target to have taken the data before it is replaced.
            std::thread::sleep(std::time::Duration::from_millis(120));
            if !saved.is_empty() {
                set_clipboard_text(&saved);
            }
        }
        true
    }

    #[cfg(windows)]
    fn set_clipboard_text(text: &str) -> bool {
        super::platform::set_clipboard_text(text)
    }
}

// ============================================================================
// Self-test instrumentation
// ============================================================================

/// Scaffolding for `--selftest`, and for the user-facing test run.
///
/// The scheduler cannot be judged from outside the process: an event that fires
/// 40 ms late looks exactly like one that fires on time. So a self-test run is made
/// *dry* - every call into Windows is suppressed and nothing moves on screen - while
/// the real scheduler, the real frame guard and the real slip logic run untouched,
/// and each dispatch is timestamped against the moment it was due.
///
/// Since 1.6.0 the same switch is what **Test run** in the window is built on. That
/// is deliberate and it is the whole reason the feature was cheap: the suppression
/// has been exercised by every self-test since 1.3, so the one thing a test run must
/// never do - let a keystroke escape - is the one thing already under test. There is
/// exactly one flag, checked at exactly the five places that can reach `SendInput`,
/// because two flags would eventually disagree and the disagreement would be a real
/// click on somebody's real desktop.
///
/// Cost when idle: one relaxed load, on paths that were about to enter a syscall
/// anyway.
mod selftest {
    use parking_lot::Mutex;
    use std::sync::LazyLock;
    use std::sync::atomic::{AtomicBool, AtomicI64, AtomicU64, AtomicUsize, Ordering};

    static DRY: AtomicBool = AtomicBool::new(false);
    /// Tracing is separate from dryness: the churn test runs dry for ten minutes and
    /// would otherwise fill memory with a trace nobody reads.
    static TRACING: AtomicBool = AtomicBool::new(false);
    /// Net synthetic presses outstanding. Has to come back to zero after a stop.
    static HELD: AtomicI64 = AtomicI64::new(0);
    /// Playback loops currently running, and the most that ever ran at once.
    static LIVE: AtomicI64 = AtomicI64::new(0);
    static PEAK_LIVE: AtomicI64 = AtomicI64::new(0);
    static STALL_AT: AtomicUsize = AtomicUsize::new(usize::MAX);
    static STALL_US: AtomicU64 = AtomicU64::new(0);
    static SLIPS: AtomicU64 = AtomicU64::new(0);
    static SLIPPED_US: AtomicU64 = AtomicU64::new(0);
    /// Inputs that were built and then not sent. The proof a test run stayed dry:
    /// a run that reports zero suppressed sends did not suppress anything, it just
    /// did not get that far.
    static SUPPRESSED: AtomicU64 = AtomicU64::new(0);
    /// Dangerous steps stepped over rather than performed.
    static SKIPPED: AtomicU64 = AtomicU64::new(0);
    /// (scheduled, actual), both on the playback clock.
    static TRACE: LazyLock<Mutex<Vec<(u64, u64)>>> = LazyLock::new(|| Mutex::new(Vec::new()));

    pub fn dry() -> bool {
        DRY.load(Ordering::Relaxed)
    }

    /// The gate in front of every `SendInput`, and the counter behind it.
    ///
    /// One function rather than a bare `dry()` at each site so that "was it
    /// suppressed" and "was it counted" cannot drift apart: there is no way to
    /// suppress a send without recording that it happened.
    pub fn send_blocked() -> bool {
        if dry() {
            SUPPRESSED.fetch_add(1, Ordering::Relaxed);
            true
        } else {
            false
        }
    }

    /// Same idea for a step that is performed by something other than `SendInput` -
    /// launching a program, shutting the machine down - and must not be performed
    /// during a test run.
    pub fn note_skipped() {
        SKIPPED.fetch_add(1, Ordering::Relaxed);
    }

    pub fn suppressed() -> u64 {
        SUPPRESSED.load(Ordering::Relaxed)
    }
    pub fn skipped() -> u64 {
        SKIPPED.load(Ordering::Relaxed)
    }

    /// Turns the suppression on or off for a run that is not a self-test.
    ///
    /// Separate from `arm_dry` because the counters mean different things to the two
    /// callers: a self-test wants them cleared per test, a test run wants them
    /// cleared per run and then reported to the person watching.
    pub fn set_dry(on: bool) {
        if on {
            SUPPRESSED.store(0, Ordering::Relaxed);
            SKIPPED.store(0, Ordering::Relaxed);
            HELD.store(0, Ordering::Relaxed);
        }
        DRY.store(on, Ordering::Relaxed);
    }

    /// Arms a run. `stall_at` is the event index to freeze the thread on, which is
    /// how the anti-burst logic gets something to prove itself against.
    pub fn arm(expected: usize, stall_at: usize, stall_us: u64) {
        let mut t = TRACE.lock();
        t.clear();
        t.reserve(expected);
        drop(t);
        STALL_AT.store(stall_at, Ordering::Relaxed);
        STALL_US.store(stall_us, Ordering::Relaxed);
        SLIPS.store(0, Ordering::Relaxed);
        SLIPPED_US.store(0, Ordering::Relaxed);
        TRACING.store(true, Ordering::Relaxed);
        DRY.store(true, Ordering::Relaxed);
    }

    /// Suppresses the OS calls without collecting a trace.
    pub fn arm_dry() {
        HELD.store(0, Ordering::Relaxed);
        LIVE.store(0, Ordering::Relaxed);
        PEAK_LIVE.store(0, Ordering::Relaxed);
        SUPPRESSED.store(0, Ordering::Relaxed);
        SKIPPED.store(0, Ordering::Relaxed);
        DRY.store(true, Ordering::Relaxed);
    }

    pub fn held() -> i64 {
        HELD.load(Ordering::Relaxed)
    }
    pub fn live() -> i64 {
        LIVE.load(Ordering::Relaxed)
    }
    pub fn peak_live() -> i64 {
        PEAK_LIVE.load(Ordering::Relaxed)
    }

    /// Counts a press or a release on its way out.
    ///
    /// A stop that leaves this above zero is the failure this application can least
    /// afford: a key still down after the macro has finished.
    pub fn note_input(kind: &crate::InputEventKind) {
        if !dry() {
            return;
        }
        let down = match kind {
            crate::InputEventKind::Key { down, .. }
            | crate::InputEventKind::MouseButton { down, .. } => *down,
            _ => return,
        };
        if down {
            HELD.fetch_add(1, Ordering::Relaxed);
        } else {
            HELD.fetch_sub(1, Ordering::Relaxed);
        }
    }

    /// Counts a playback loop for as long as it runs, however it leaves.
    pub struct LoopGuard;

    impl Drop for LoopGuard {
        fn drop(&mut self) {
            LIVE.fetch_sub(1, Ordering::Relaxed);
        }
    }

    pub fn enter_playback() -> LoopGuard {
        HELD.store(0, Ordering::Relaxed);
        let n = LIVE.fetch_add(1, Ordering::Relaxed) + 1;
        PEAK_LIVE.fetch_max(n, Ordering::Relaxed);
        LoopGuard
    }

    /// Ends a run and hands back what it collected: trace, slip count, slipped time.
    pub fn disarm() -> (Vec<(u64, u64)>, u64, u64) {
        DRY.store(false, Ordering::Relaxed);
        TRACING.store(false, Ordering::Relaxed);
        STALL_AT.store(usize::MAX, Ordering::Relaxed);
        let trace = std::mem::take(&mut *TRACE.lock());
        (trace, SLIPS.load(Ordering::Relaxed), SLIPPED_US.load(Ordering::Relaxed))
    }

    /// Records one dispatch, then freezes if this is the armed index.
    ///
    /// The freeze happens after the record, so the stall shows up as lateness on the
    /// events that follow - which is exactly where the scheduler has to deal with it.
    pub fn note(index: usize, scheduled_us: u64, actual_us: u64) {
        if !TRACING.load(Ordering::Relaxed) {
            return;
        }
        TRACE.lock().push((scheduled_us, actual_us));
        if index == STALL_AT.load(Ordering::Relaxed) {
            let us = STALL_US.load(Ordering::Relaxed);
            if us > 0 {
                std::thread::sleep(std::time::Duration::from_micros(us));
            }
        }
    }

    pub fn note_slip(late_us: u64) {
        SLIPS.fetch_add(1, Ordering::Relaxed);
        SLIPPED_US.fetch_add(late_us, Ordering::Relaxed);
    }
}

// ============================================================================
// Hotkeys
// ============================================================================

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub struct Hotkey {
    pub vk: u32,
    #[serde(default)]
    pub ctrl: bool,
    #[serde(default)]
    pub alt: bool,
    #[serde(default)]
    pub shift: bool,
}

impl Hotkey {
    const fn plain(vk: u32) -> Self {
        Self { vk, ctrl: false, alt: false, shift: false }
    }
    fn label(&self) -> String {
        if self.vk == 0 {
            return "—".into();
        }
        let mut s = String::new();
        if self.ctrl {
            s.push_str("Ctrl+");
        }
        if self.alt {
            s.push_str("Alt+");
        }
        if self.shift {
            s.push_str("Shift+");
        }
        s.push_str(&vk_name(self.vk));
        s
    }
}

/// Human name for a virtual-key code.
fn vk_name(vk: u32) -> String {
    match vk {
        0x00 => "—".into(),
        0x08 => "Backspace".into(),
        0x09 => "Tab".into(),
        0x0D => "Enter".into(),
        0x10 => "Shift".into(),
        0x11 => "Ctrl".into(),
        0x12 => "Alt".into(),
        0x13 => "Pause".into(),
        0x14 => "CapsLock".into(),
        0x1B => "Esc".into(),
        0x20 => "Space".into(),
        0x21 => "PageUp".into(),
        0x22 => "PageDown".into(),
        0x23 => "End".into(),
        0x24 => "Home".into(),
        0x25 => "Left".into(),
        0x26 => "Up".into(),
        0x27 => "Right".into(),
        0x28 => "Down".into(),
        0x2C => "PrintScreen".into(),
        0x2D => "Insert".into(),
        0x2E => "Delete".into(),
        0x30..=0x39 => char::from(b'0' + (vk - 0x30) as u8).to_string(),
        0x41..=0x5A => char::from(b'A' + (vk - 0x41) as u8).to_string(),
        0x5B => "LWin".into(),
        0x5C => "RWin".into(),
        0x60..=0x69 => format!("Num{}", vk - 0x60),
        0x6A => "Num*".into(),
        0x6B => "Num+".into(),
        0x6D => "Num-".into(),
        0x6E => "Num.".into(),
        0x6F => "Num/".into(),
        0x70..=0x87 => format!("F{}", vk - 0x6F),
        0x90 => "NumLock".into(),
        0x91 => "ScrollLock".into(),
        0xBA => ";".into(),
        0xBB => "=".into(),
        0xBC => ",".into(),
        0xBD => "-".into(),
        0xBE => ".".into(),
        0xBF => "/".into(),
        0xC0 => "`".into(),
        0xDB => "[".into(),
        0xDC => "\\".into(),
        0xDD => "]".into(),
        0xDE => "'".into(),
        _ => format!("VK 0x{vk:02X}"),
    }
}

/// Hot-path copies of the hotkey virtual keys.
///
/// The keyboard hook fires *before* WM_HOTKEY is dispatched, so without this filter
/// every hotkey press would be recorded into the macro.
static HK_VK: [AtomicU32; 7] = [
    AtomicU32::new(0x75), // F6 record
    AtomicU32::new(0x76), // F7 play
    AtomicU32::new(0x78), // F9 emergency stop
    AtomicU32::new(0x77), // F8 pause
    AtomicU32::new(0),    // faster
    AtomicU32::new(0),    // slower
    AtomicU32::new(0),    // skip step
];

/// Bit mask of hotkeys that failed to register.
static HK_FAILED: AtomicU32 = AtomicU32::new(0);
static HOOK_THREAD_ID: AtomicU32 = AtomicU32::new(0);

static PENDING_HOTKEYS: Mutex<[Hotkey; 7]> = Mutex::new([
    Hotkey::plain(0x75),
    Hotkey::plain(0x76),
    Hotkey::plain(0x78),
    Hotkey::plain(0x77),
    Hotkey::plain(0),
    Hotkey::plain(0),
    Hotkey::plain(0),
]);

/// 0 = idle, 1..=4 = capture the next key press for that hotkey slot.
static CAPTURE_SLOT: AtomicU32 = AtomicU32::new(0);
static CAPTURED_KEY: Mutex<Option<Hotkey>> = Mutex::new(None);

/// Keys offered in the dropdown next to each binding.
///
/// "Press a key" covers everything, but a plain list is guaranteed to work even if
/// the window never sees the key press - including keys egui does not report at all
/// (Pause, ScrollLock, NumPad).
const HOTKEY_CHOICES: [(&str, u32); 26] = [
    ("—", 0x00),
    ("F1", 0x70), ("F2", 0x71), ("F3", 0x72), ("F4", 0x73),
    ("F5", 0x74), ("F6", 0x75), ("F7", 0x76), ("F8", 0x77),
    ("F9", 0x78), ("F10", 0x79), ("F11", 0x7A), ("F12", 0x7B),
    ("Pause", 0x13), ("ScrollLock", 0x91), ("Insert", 0x2D), ("Delete", 0x2E),
    ("Home", 0x24), ("End", 0x23), ("PageUp", 0x21), ("PageDown", 0x22),
    ("Num0", 0x60), ("Num1", 0x61), ("Num*", 0x6A), ("Num-", 0x6D), ("Num+", 0x6B),
];

/// Starts binding mode for one hotkey slot.
fn begin_capture(slot: u32) {
    CAPTURE_SLOT.store(slot, Ordering::Relaxed);
    *CAPTURED_KEY.lock() = None;
    // Without this the currently bound keys are eaten by RegisterHotKey and would
    // never arrive as window input, so F6-F9 could not be rebound onto each other.
    request_hotkey_message(WM_APP_HK_OFF);
}

/// Leaves binding mode and puts the global hotkeys back.
fn end_capture() {
    CAPTURE_SLOT.store(0, Ordering::Relaxed);
    request_hotkey_message(WM_APP_REHOTKEY);
}

/// Maps an egui key to a Windows virtual-key code.
///
/// This is the capture path used while the window has focus; the low-level hook
/// covers the rest (and keys egui never reports).
fn egui_key_to_vk(key: egui::Key) -> Option<u32> {
    use egui::Key as K;
    Some(match key {
        K::A => 0x41, K::B => 0x42, K::C => 0x43, K::D => 0x44, K::E => 0x45,
        K::F => 0x46, K::G => 0x47, K::H => 0x48, K::I => 0x49, K::J => 0x4A,
        K::K => 0x4B, K::L => 0x4C, K::M => 0x4D, K::N => 0x4E, K::O => 0x4F,
        K::P => 0x50, K::Q => 0x51, K::R => 0x52, K::S => 0x53, K::T => 0x54,
        K::U => 0x55, K::V => 0x56, K::W => 0x57, K::X => 0x58, K::Y => 0x59,
        K::Z => 0x5A,
        K::Num0 => 0x30, K::Num1 => 0x31, K::Num2 => 0x32, K::Num3 => 0x33,
        K::Num4 => 0x34, K::Num5 => 0x35, K::Num6 => 0x36, K::Num7 => 0x37,
        K::Num8 => 0x38, K::Num9 => 0x39,
        K::F1 => 0x70, K::F2 => 0x71, K::F3 => 0x72, K::F4 => 0x73,
        K::F5 => 0x74, K::F6 => 0x75, K::F7 => 0x76, K::F8 => 0x77,
        K::F9 => 0x78, K::F10 => 0x79, K::F11 => 0x7A, K::F12 => 0x7B,
        K::Tab => 0x09, K::Backspace => 0x08, K::Enter => 0x0D, K::Space => 0x20,
        K::Insert => 0x2D, K::Delete => 0x2E, K::Home => 0x24, K::End => 0x23,
        K::PageUp => 0x21, K::PageDown => 0x22,
        K::ArrowUp => 0x26, K::ArrowDown => 0x28,
        K::ArrowLeft => 0x25, K::ArrowRight => 0x27,
        _ => return None,
    })
}

/// Pulls a binding out of this frame's window input, if binding mode is active.
fn capture_from_window(ctx: &egui::Context) -> Option<Hotkey> {
    ctx.input(|i| {
        for ev in &i.events {
            if let egui::Event::Key { key, pressed: true, modifiers, .. } = ev {
                if *key == egui::Key::Escape {
                    return Some(Hotkey::plain(0)); // treated as "cancel" by the caller
                }
                if let Some(vk) = egui_key_to_vk(*key) {
                    return Some(Hotkey {
                        vk,
                        ctrl: modifiers.ctrl,
                        alt: modifiers.alt,
                        shift: modifiers.shift,
                    });
                }
            }
        }
        None
    })
}

fn publish_hotkeys(cfg: &AppConfig) {
    let hk = [
        cfg.hotkey_record,
        cfg.hotkey_play,
        cfg.hotkey_stop,
        cfg.hotkey_pause,
        cfg.hotkey_faster,
        cfg.hotkey_slower,
        cfg.hotkey_skip,
    ];
    for (i, k) in hk.iter().enumerate() {
        HK_VK[i].store(k.vk, Ordering::Relaxed);
    }
    *PENDING_HOTKEYS.lock() = hk;
}

fn is_hotkey_vk(vk: u32) -> bool {
    HK_VK.iter().any(|a| {
        let v = a.load(Ordering::Relaxed);
        v != 0 && v == vk
    })
}

fn request_hotkey_message(msg: u32) {
    #[cfg(windows)]
    {
        let tid = HOOK_THREAD_ID.load(Ordering::Relaxed);
        if tid != 0 {
            unsafe {
                let _ = win32::PostThreadMessageW(tid, msg, win32::WPARAM(0), win32::LPARAM(0));
            }
        }
    }
    #[cfg(not(windows))]
    let _ = msg;
}

fn request_hotkey_refresh() {
    request_hotkey_message(WM_APP_REHOTKEY);
}

// ============================================================================
// Configuration
// ============================================================================

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(default)]
pub struct AppConfig {
    // appearance
    pub default_lang: usize,
    pub default_theme: usize,
    pub transparent_ui: bool,
    pub always_on_top: bool,
    pub tray_enabled: bool,
    pub close_to_tray: bool,

    // playback
    pub loop_play: bool,
    pub play_count_limit: u64,
    pub speed: f64,
    pub absolute_mouse: bool,
    pub repeat_delay_ms: u64,
    pub jitter_pct: u64,
    pub use_window_anchor: bool,
    /// Also stretch coordinates when the anchored window changed size.
    pub anchor_scale: bool,
    /// Glide along a curved path instead of teleporting the cursor.
    pub human_mouse: bool,
    /// 0-100: how far the arc bows away from the straight line.
    pub human_curve: u64,
    /// Random spread applied to every target point, in pixels.
    pub mouse_jitter_px: i32,
    /// Hold presses long enough for a game running at a low frame rate to see them.
    pub frame_guard: bool,
    /// The slowest frame rate the target is expected to drop to. The fallback for
    /// when nothing has been measured yet.
    pub frame_guard_fps: u64,
    /// Size the guard from the measured window latency instead of the figure above.
    pub frame_guard_auto: bool,
    /// Keep probing the target window and show the numbers.
    pub perf_enabled: bool,

    // recording
    pub capture_mouse_moves: bool,
    /// Desktop Duplication rather than GDI for every screen grab. On by default;
    /// it falls back on its own where it cannot run, so the switch is here for the
    /// machine where it runs badly rather than not at all.
    #[serde(default = "yes")]
    pub fast_capture: bool,
    /// BCP-47 tag for the text recogniser, or empty for the Windows display
    /// languages. Empty is the default and is what every version before 1.7.0 did.
    ///
    /// It exists because the two are often not the same language: a Russian Windows
    /// reading an English game turned `Gems: 1,250` into `Gems :` and read the zero
    /// of `02:34` as a Cyrillic letter. The recogniser was reading the wrong
    /// alphabet, and no pixel preparation can argue it out of that.
    #[serde(default)]
    pub ocr_lang: String,
    /// Keep a small square of the screen around every click while recording, so the
    /// recording can be turned into steps that look for the button.
    #[serde(default)]
    pub record_click_shots: bool,
    /// The side of that square, in pixels.
    #[serde(default = "shot_size_default")]
    pub click_shot_size: u32,
    /// What the generated `Click image` steps do when the picture is not there.
    /// Not `Continue`: a step this program wrote, that cannot find the button it
    /// was cut from, has nothing useful to do next.
    #[serde(default = "shot_miss_default")]
    pub click_shot_miss: OnMiss,
    pub mouse_sample_ms: u64,
    pub record_window_anchor: bool,
    /// Write down what the machine was doing when a recording was made.
    ///
    /// On, because the whole value of it is being there afterwards - nobody turns
    /// this on in advance of the problem it explains. It goes into the macro file,
    /// which is why it can be turned off: the front window's title and the name of
    /// its executable are in it, and a macro is a thing people send each other.
    #[serde(default = "yes")]
    pub record_session_info: bool,

    // time limit
    pub time_limit_enabled: bool,
    pub time_limit_h: u64,
    pub time_limit_m: u64,
    pub time_limit_s: u64,
    pub action_on_completion: usize,
    pub shutdown_delay_s: u64,

    // pixel stop condition
    pub pixel_enabled: bool,
    pub pixel_x: i32,
    pub pixel_y: i32,
    pub pixel_r: u8,
    pub pixel_g: u8,
    pub pixel_b: u8,
    pub pixel_tolerance: u32,
    /// 0 = stop when the pixel matches, 1 = stop when it stops matching.
    pub pixel_mode: usize,

    // hotkeys
    pub hotkey_record: Hotkey,
    pub hotkey_play: Hotkey,
    pub hotkey_stop: Hotkey,
    pub hotkey_pause: Hotkey,
    pub hotkey_faster: Hotkey,
    pub hotkey_slower: Hotkey,
    pub hotkey_skip: Hotkey,

    // schedule
    pub schedule_enabled: bool,
    pub schedule_h: u32,
    pub schedule_m: u32,
    /// Bit 0 = Monday … bit 6 = Sunday.
    pub schedule_days: u8,

    // target window
    pub target_title: String,
    /// How `target_title` is matched. `Title` is what it has always meant, so an
    /// existing `config.json` keeps behaving as it did.
    #[serde(default)]
    pub target_by: usize,
    pub target_pause_unfocused: bool,

    // files
    pub recent_files: Vec<String>,
    pub compress_on_save: bool,

    // image search
    pub img_threshold: f64,
    pub img_multiscale: bool,
    pub img_region_enabled: bool,
    pub img_rx: i32,
    pub img_ry: i32,
    pub img_rw: i32,
    pub img_rh: i32,
    /// Photograph the screen when a step fails and ends the run. On by default,
    /// unlike the other diagnostics here: it costs nothing until something goes
    /// wrong, and what it keeps is the one thing that cannot be reconstructed
    /// afterwards.
    #[serde(default = "yes")]
    pub failure_shots: bool,
    /// Draw a see-through window over everything showing what the script just
    /// looked at. Off by default: it is a diagnostic, not a feature to leave on.
    #[serde(default)]
    pub debug_overlay: bool,
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            default_lang: 0,
            default_theme: 0,
            transparent_ui: true,
            always_on_top: true,
            tray_enabled: true,
            close_to_tray: true,

            loop_play: true,
            play_count_limit: 1,
            speed: 1.0,
            absolute_mouse: true,
            repeat_delay_ms: 0,
            jitter_pct: 0,
            use_window_anchor: false,
            anchor_scale: true,
            human_mouse: false,
            human_curve: 35,
            mouse_jitter_px: 0,
            // Off by default: most macros drive ordinary desktop software, which
            // reads its input queue as fast as the queue fills.
            frame_guard: false,
            frame_guard_fps: 30,
            frame_guard_auto: true,
            perf_enabled: false,

            capture_mouse_moves: true,
            fast_capture: true,
            ocr_lang: String::new(),
            record_click_shots: false,
            click_shot_size: 64,
            click_shot_miss: OnMiss::Stop,
            mouse_sample_ms: 5,
            record_window_anchor: false,
            record_session_info: true,

            time_limit_enabled: false,
            time_limit_h: 0,
            time_limit_m: 0,
            time_limit_s: 0,
            action_on_completion: 0,
            shutdown_delay_s: 60,

            pixel_enabled: false,
            pixel_x: 0,
            pixel_y: 0,
            pixel_r: 255,
            pixel_g: 0,
            pixel_b: 0,
            pixel_tolerance: 20,
            pixel_mode: 0,

            hotkey_record: Hotkey::plain(0x75), // F6
            hotkey_play: Hotkey::plain(0x76),   // F7
            hotkey_pause: Hotkey::plain(0x77),  // F8
            hotkey_stop: Hotkey::plain(0x78),   // F9
            hotkey_faster: Hotkey::plain(0),
            hotkey_slower: Hotkey::plain(0),
            hotkey_skip: Hotkey::plain(0),

            schedule_enabled: false,
            schedule_h: 9,
            schedule_m: 0,
            schedule_days: 0b0111_1111,

            target_title: String::new(),
            target_by: 0,
            target_pause_unfocused: false,

            recent_files: Vec::new(),
            compress_on_save: false,

            img_threshold: 0.85,
            img_multiscale: false,
            img_region_enabled: false,
            img_rx: 0,
            img_ry: 0,
            img_rw: 800,
            img_rh: 600,
            failure_shots: true,
            debug_overlay: false,
        }
    }
}

/// A name for a set of playback settings that already existed separately.
///
/// Every one of these switches has been in the panel for releases; what was missing
/// was any hint about which combinations go together. Somebody automating a game
/// needs the frame guard and the target window and does not want timing jitter;
/// somebody automating a form wants none of it. That is knowledge the program had
/// and never offered.
///
/// Deliberately *not* stored in `config.json`. The profile is worked out from the
/// settings every time it is shown, so it can never disagree with them - tick one
/// box by hand and the name becomes `Custom`, because that is what it now is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlaybackProfile {
    /// Ordinary desktop software: exact timing, nothing added.
    Desktop,
    /// A game: hold presses long enough for a low frame rate to see them, and wait
    /// while the window is not in front.
    Game,
    /// Movement and timing that do not look like a machine.
    HumanLike,
    /// Something else, which is a perfectly good answer.
    Custom,
}

impl PlaybackProfile {
    pub const COUNT: usize = 4;
    /// `Custom` last: it is the one nobody picks on purpose.
    const NAMED: [PlaybackProfile; 3] =
        [PlaybackProfile::Desktop, PlaybackProfile::Game, PlaybackProfile::HumanLike];

    fn index(self) -> usize {
        match self {
            PlaybackProfile::Desktop => 0,
            PlaybackProfile::Game => 1,
            PlaybackProfile::HumanLike => 2,
            PlaybackProfile::Custom => 3,
        }
    }

    fn from_index(i: usize) -> Self {
        match i {
            0 => PlaybackProfile::Desktop,
            1 => PlaybackProfile::Game,
            2 => PlaybackProfile::HumanLike,
            _ => PlaybackProfile::Custom,
        }
    }

    fn name(self, s: &Strings) -> &'static str {
        match self {
            PlaybackProfile::Desktop => s.pp_desktop,
            PlaybackProfile::Game => s.pp_game,
            PlaybackProfile::HumanLike => s.pp_human,
            PlaybackProfile::Custom => s.pp_custom,
        }
    }

    /// The settings this profile is, as (jitter, human, curve, aim spread, guard,
    /// guard auto, pause while not in front).
    ///
    /// One tuple rather than seven scattered assignments, so `apply` and `matches`
    /// cannot drift apart - a profile that could not be recognised after being
    /// applied would flicker to `Custom` the moment it was chosen.
    fn settings(self) -> Option<(u64, bool, u64, i32, bool, bool, bool)> {
        Some(match self {
            PlaybackProfile::Desktop => (0, false, 35, 0, false, true, false),
            PlaybackProfile::Game => (0, false, 35, 0, true, true, true),
            PlaybackProfile::HumanLike => (12, true, 35, 2, false, true, false),
            PlaybackProfile::Custom => return None,
        })
    }

    fn apply(self, cfg: &mut AppConfig) {
        let Some((jitter, human, curve, spread, guard, auto, pause)) = self.settings() else {
            return;
        };
        cfg.jitter_pct = jitter;
        cfg.human_mouse = human;
        cfg.human_curve = curve;
        cfg.mouse_jitter_px = spread;
        cfg.frame_guard = guard;
        cfg.frame_guard_auto = auto;
        cfg.target_pause_unfocused = pause;
    }

    fn matches(self, cfg: &AppConfig) -> bool {
        self.settings()
            == Some((
                cfg.jitter_pct,
                cfg.human_mouse,
                cfg.human_curve,
                cfg.mouse_jitter_px,
                cfg.frame_guard,
                cfg.frame_guard_auto,
                cfg.target_pause_unfocused,
            ))
    }

    /// Which profile the settings currently spell out, if any.
    fn detect(cfg: &AppConfig) -> Self {
        Self::NAMED.into_iter().find(|p| p.matches(cfg)).unwrap_or(PlaybackProfile::Custom)
    }
}

impl AppConfig {
    fn sanitize(&mut self) {
        self.default_lang = self.default_lang.min(6);
        self.default_theme = self.default_theme.min(THEME_NAMES.len() - 1);
        self.play_count_limit = self.play_count_limit.clamp(1, 9999);
        self.speed = if self.speed.is_finite() { self.speed.clamp(0.05, 10.0) } else { 1.0 };
        self.repeat_delay_ms = self.repeat_delay_ms.min(600_000);
        self.jitter_pct = self.jitter_pct.min(50);
        self.human_curve = self.human_curve.min(100);
        self.mouse_jitter_px = self.mouse_jitter_px.clamp(0, 60);
        self.frame_guard_fps = self.frame_guard_fps.clamp(5, 240);
        self.schedule_h = self.schedule_h.min(23);
        self.schedule_m = self.schedule_m.min(59);
        self.target_title.truncate(120);
        self.mouse_sample_ms = self.mouse_sample_ms.clamp(1, 100);
        self.time_limit_h = self.time_limit_h.min(240);
        self.time_limit_m = self.time_limit_m.min(59);
        self.time_limit_s = self.time_limit_s.min(59);
        self.action_on_completion = self.action_on_completion.min(EndAction::COUNT - 1);
        self.shutdown_delay_s = self.shutdown_delay_s.min(600);
        self.pixel_tolerance = self.pixel_tolerance.min(255);
        self.pixel_mode = self.pixel_mode.min(1);
        self.recent_files.truncate(8);
        self.img_threshold = if self.img_threshold.is_finite() {
            self.img_threshold.clamp(0.3, 1.0)
        } else {
            0.85
        };
        self.img_rw = self.img_rw.clamp(8, 32000);
        self.img_rh = self.img_rh.clamp(8, 32000);
    }

    fn time_limit_us(&self) -> u64 {
        (self.time_limit_h * 3600 + self.time_limit_m * 60 + self.time_limit_s) * 1_000_000
    }

    fn push_recent(&mut self, path: &Path) {
        let s = path.to_string_lossy().to_string();
        self.recent_files.retain(|p| p != &s);
        self.recent_files.insert(0, s);
        self.recent_files.truncate(8);
    }
}

fn load_config_from(path: &Path) -> AppConfig {
    let mut cfg = std::fs::read_to_string(path)
        .ok()
        .and_then(|s| serde_json::from_str::<AppConfig>(&s).ok())
        .unwrap_or_default();
    cfg.sanitize();
    cfg
}

fn load_config() -> AppConfig {
    load_config_from(&paths::config_path())
}

fn save_config_to(path: &Path, cfg: &AppConfig) -> Result<()> {
    let json = serde_json::to_string_pretty(cfg)?;
    std::fs::write(path, json).with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

fn save_config(cfg: &AppConfig) -> Result<()> {
    save_config_to(&paths::config_path(), cfg)
}

/// Named setting profiles stored in `<data>/profiles/<name>.json`.
fn list_profiles() -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(entries) = std::fs::read_dir(paths::profiles_dir()) {
        for e in entries.flatten() {
            let p = e.path();
            if p.extension().and_then(|x| x.to_str()) == Some("json")
                && let Some(stem) = p.file_stem().and_then(|x| x.to_str()) {
                    out.push(stem.to_string());
                }
        }
    }
    out.sort();
    out
}

fn profile_path(name: &str) -> PathBuf {
    let safe: String = name
        .chars()
        .map(|c| if c.is_alphanumeric() || c == '-' || c == '_' || c == ' ' { c } else { '_' })
        .collect();
    paths::profiles_dir().join(format!("{}.json", safe.trim()))
}

// ============================================================================
// Macro model & storage
// ============================================================================

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum MouseButton {
    Left,
    Right,
    Middle,
    X1,
    X2,
}

impl MouseButton {
    fn from_index(i: usize) -> Self {
        match i {
            1 => Self::Right,
            2 => Self::Middle,
            3 => Self::X1,
            4 => Self::X2,
            _ => Self::Left,
        }
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
pub enum InputEventKind {
    Key { vk: u16, scan: u16, down: bool, extended: bool },
    MouseMove { x: i32, y: i32, dx: i32, dy: i32 },
    MouseButton { button: MouseButton, down: bool, x: i32, y: i32 },
    MouseWheel { delta: i32, x: i32, y: i32, horizontal: bool },
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
pub struct MacroEvent {
    pub t_us: u64,
    pub kind: InputEventKind,
}

/// A square of screen kept from around one recorded click.
///
/// The missing half of recording. A recording is a list of coordinates, and
/// coordinates are the brittle part: the window moves, the resolution changes, the
/// list opens one row lower, and every click lands somewhere it should not. The
/// cure has been in the program since 1.2 - a `Click image` step finds the button
/// wherever it is - but it had to be built by hand afterwards, from screenshots
/// taken separately, by somebody who remembered which button each click was for.
///
/// The one moment that information exists for free is the moment of the click. So
/// it is taken then, and the offer to use it is made when the recording stops.
#[derive(Clone)]
pub struct ClickShot {
    /// Where this click landed in `events`.
    pub index: usize,
    pub button: MouseButton,
    /// Screen coordinates of the click itself.
    pub x: i32,
    pub y: i32,
    /// Top-left of the square, so the click's offset inside it is recoverable.
    pub left: i32,
    pub top: i32,
    pub w: u32,
    pub h: u32,
    /// RGBA, opaque - ready to be a PNG without further thought.
    pub rgba: Vec<u8>,
    /// The scale the square was cut at, for the sidecar.
    pub dpi: u32,

    // ---- what else was true at that moment (1.6.0) -------------------------
    //
    // The square answers "what did it look like". These answer "what was it", and
    // between them they are what lets the program propose a better way of finding
    // it again. All of it is free at the moment of the click and impossible to
    // recover afterwards.
    /// Title of the window that was in front.
    pub window: String,
    /// The executable behind it, without its path: `RobloxPlayerBeta.exe`.
    pub process: String,
    /// Where that window was, so the click can be expressed relative to it.
    pub win_rect: Option<(i32, i32, i32, i32)>,
    /// The interface element under the cursor, if the application exposes one.
    /// `None` in every game engine, which is the normal answer rather than a
    /// failure.
    pub element: Option<uia::Query>,
}

impl ClickShot {
    /// Where the click landed inside its window, if there was one.
    ///
    /// The cheapest durable improvement on a bare coordinate: a window that has
    /// moved or been re-opened somewhere else still gets clicked in the right place,
    /// and it costs one subtraction rather than a search.
    pub fn window_offset(&self) -> Option<(i32, i32)> {
        let (wx, wy, ww, wh) = self.win_rect?;
        if ww <= 0 || wh <= 0 {
            return None;
        }
        let (dx, dy) = (self.x - wx, self.y - wy);
        // A click outside the window it was supposedly in is a click on something
        // else - a menu that had taken over, a different monitor - and anchoring to
        // that window would be worse than the coordinate.
        (dx >= 0 && dy >= 0 && dx < ww && dy < wh).then_some((dx, dy))
    }
}

/// A recording of a hundred clicks holds 100 x 64 x 64 x 4 = 1.6 MB of squares.
/// Ten times that is still small, and past it the offer stops being useful anyway.
const MAX_CLICK_SHOTS: usize = 1000;

/// A name for a place in the recording.
///
/// The fix for the trap the documentation has always warned about: a `Play events`
/// step names events by number, and deleting an event in the editor leaves every
/// number saying what it said. `Play events 73…184` silently becomes a different
/// hundred and eleven events.
///
/// A marker is moved by the same edits that move the events, so a step that plays
/// "Start inventory" to "After inventory" keeps meaning that. The numbers are still
/// there underneath — this is a name for one, not a replacement for it.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Marker {
    pub name: String,
    /// Index of the event this marker sits before.
    pub at: usize,
}

/// The two markers a `Play events` step is expressed between, when it is.
///
/// Deliberately *beside* `from`/`to` rather than instead of them. A file written
/// with markers still carries the numbers those markers resolved to, so:
///
///   * a build older than format 4 ignores the names and plays the numbers, which is
///     the right thing rather than an error;
///   * a marker that somebody deleted leaves a step that still plays what it last
///     played, instead of a step that plays nothing or everything.
///
/// The numbers are refreshed from the names whenever the macro is normalised, so the
/// two cannot drift apart while the markers exist.
pub type Between = (String, String);

/// Moves every marker to keep pointing at the same action after an edit.
///
/// `at` is the first index that changed and `delta` is how many events were inserted
/// (positive) or removed (negative). A marker inside a removed region collapses onto
/// its start rather than being dropped: the name is the part the user wrote down.
fn shift_markers(markers: &mut [Marker], at: usize, delta: isize) {
    for m in markers.iter_mut() {
        if m.at <= at {
            continue;
        }
        m.at = if delta >= 0 {
            m.at.saturating_add(delta as usize)
        } else {
            m.at.saturating_sub((-delta) as usize).max(at)
        };
    }
}

/// Position of the window that was in the foreground when recording started.
///
/// Lets playback re-anchor absolute coordinates if that window has since moved.
#[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, Eq)]
pub struct WindowAnchor {
    pub title: String,
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
}

/// The machine a recording was made on, as it was at that moment.
///
/// Not used to reproduce anything. Every value here is written down so that the
/// difference between then and now can be *stated* - which is the whole point.
/// "Why does this macro click twenty pixels low today?" is unanswerable from a list
/// of coordinates and obvious from `150 % → 100 %`.
///
/// Deliberately nothing is enforced from these. A macro recorded on two monitors at
/// 150 % must still run on one at 100 % - badly, perhaps, and now it says so first.
///
/// Every field defaults, because every macro written before format 5 has none of
/// them, and a recording made with the metadata switched off has none either.
#[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, Eq)]
pub struct RecordingInfo {
    /// Local time the recording started: `2026-08-27 11:42`. A string for the same
    /// reason `runlog::Run::started` is one - it is shown, never computed with.
    #[serde(default)]
    pub when: String,
    /// The whole virtual desktop, which is what a recorded coordinate is relative to.
    #[serde(default)]
    pub screen_w: i32,
    #[serde(default)]
    pub screen_h: i32,
    /// Dots per inch of the display the recording was made on. 96 is 100 %.
    #[serde(default)]
    pub dpi: u32,
    /// How many displays there were, and which one the front window was on, counting
    /// from 1 in the order Windows enumerates them.
    #[serde(default)]
    pub monitors: u32,
    #[serde(default)]
    pub monitor: u32,
    /// Executable of the window in front, without its path.
    #[serde(default)]
    pub process: String,
    /// That window's title and rectangle. Kept beside the anchor rather than instead
    /// of it: the anchor is used, this is only ever reported.
    #[serde(default)]
    pub window: String,
    #[serde(default)]
    pub window_rect: Option<(i32, i32, i32, i32)>,
    /// Keyboard layout in front, as its BCP-47-ish name: `en-US`, `ru-RU`.
    ///
    /// A recording of typing replays scan codes, so the layout does not change what
    /// is sent - but it does change what appears, and a macro that typed `hello` on
    /// an English layout types `руддщ` on a Russian one.
    #[serde(default)]
    pub layout: String,
    /// The program that made it, so a file found in a folder can say where it is from.
    #[serde(default)]
    pub app: String,
}

impl RecordingInfo {
    /// What is true of this machine, right now.
    fn here() -> Self {
        let (vw, vh) = {
            let (_, _, w, h) = platform::virtual_screen_rect();
            (w, h)
        };
        let (monitors, monitor) = platform::monitor_here();
        let (y, mo, d, _, h, mi) = platform::local_time();
        Self {
            when: format!("{y:04}-{mo:02}-{d:02} {h:02}:{mi:02}"),
            screen_w: vw,
            screen_h: vh,
            dpi: platform::current_dpi(),
            monitors,
            monitor,
            process: platform::foreground_process(),
            window: platform::foreground_title().unwrap_or_default(),
            window_rect: platform::foreground_rect(),
            layout: platform::keyboard_layout(),
            app: format!("Macro Recorder {}", env!("CARGO_PKG_VERSION")),
        }
    }

    /// Scale as a percentage, the way Windows displays it.
    pub fn scale_pct(&self) -> u32 {
        if self.dpi == 0 { 100 } else { (self.dpi * 100).div_ceil(96) }
    }

    /// Nothing was written down. Every macro from before format 5 looks like this.
    pub fn is_empty(&self) -> bool {
        self.when.is_empty() && self.dpi == 0 && self.screen_w == 0
    }
}

// ============================================================================
// Script model
// ============================================================================

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum Cmp {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    /// Text containment, the one comparison that only makes sense once a variable
    /// can hold text. Forgiving in the same way screen-text matching is.
    Has,
}

impl Cmp {
    fn test(self, a: f64, b: f64) -> bool {
        match self {
            Cmp::Eq => (a - b).abs() < f64::EPSILON,
            Cmp::Ne => (a - b).abs() >= f64::EPSILON,
            Cmp::Lt => a < b,
            Cmp::Le => a <= b,
            Cmp::Gt => a > b,
            Cmp::Ge => a >= b,
            // Numbers do not contain one another. Whoever asked for this meant the
            // text, so the text is what answers.
            Cmp::Has => Value::Num(a).as_text().contains(&Value::Num(b).as_text()),
        }
    }

    /// The comparison a script actually asks for, once a variable can hold text.
    ///
    /// Two things that both read as numbers are compared as numbers, whichever kind
    /// they are stored as: a count read off the screen into text and then compared
    /// against 10 has to work. Anything else is compared as text, trimmed and with
    /// case ignored, because screen text is never exactly what a human reads.
    fn test_values(self, a: &Value, b: &Value) -> bool {
        if self == Cmp::Has {
            let (x, y) = (a.as_text(), b.as_text());
            return crate::ocr::text_matches(&x, &y);
        }
        if let (Some(x), Some(y)) = (a.numeric(), b.numeric()) {
            return self.test(x, y);
        }
        let (x, y) = (a.as_text(), b.as_text());
        let (x, y) = (x.trim().to_lowercase(), y.trim().to_lowercase());
        match self {
            Cmp::Eq => x == y,
            Cmp::Ne => x != y,
            Cmp::Lt => x < y,
            Cmp::Le => x <= y,
            Cmp::Gt => x > y,
            Cmp::Ge => x >= y,
            Cmp::Has => x.contains(&y),
        }
    }

    fn symbol(self) -> &'static str {
        match self {
            Cmp::Eq => "==",
            Cmp::Ne => "!=",
            Cmp::Lt => "<",
            Cmp::Le => "<=",
            Cmp::Gt => ">",
            Cmp::Ge => ">=",
            Cmp::Has => "has",
        }
    }
    const ALL: [Cmp; 7] =
        [Cmp::Eq, Cmp::Ne, Cmp::Lt, Cmp::Le, Cmp::Gt, Cmp::Ge, Cmp::Has];
}

/// What a script variable holds.
///
/// Numbers only, until now. That made the three most useful things on a screen -
/// what the text recognition read, what the window is called, what is on the
/// clipboard - impossible to keep hold of. One more kind covers all three. It stops
/// there deliberately: lists, tables and functions would turn the step list into a
/// programming language, and a programming language cannot be edited with a mouse.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Value {
    Num(f64),
    Str(String),
}

impl Default for Value {
    fn default() -> Self {
        Value::Num(0.0)
    }
}

impl Value {
    /// The number this holds, if it holds one. Text that reads as a number counts:
    /// a variable filled from the screen should not need converting before it can
    /// be compared against a count.
    pub fn numeric(&self) -> Option<f64> {
        match self {
            Value::Num(n) => Some(*n),
            Value::Str(s) => {
                let t = s.trim();
                if t.is_empty() { None } else { t.parse::<f64>().ok() }
            }
        }
    }

    /// The number, with anything unreadable counting as zero. What every step that
    /// wants a coordinate or a count uses.
    pub fn as_num(&self) -> f64 {
        self.numeric().unwrap_or(0.0)
    }

    pub fn as_text(&self) -> String {
        match self {
            // Whole numbers print without a tail: a count that shows as `7.0` in a
            // log or a clipboard is noise.
            Value::Num(n) => {
                if n.fract() == 0.0 && n.abs() < 1e15 {
                    format!("{n:.0}")
                } else {
                    format!("{n}")
                }
            }
            Value::Str(s) => s.clone(),
        }
    }

    pub fn is_text(&self) -> bool {
        matches!(self, Value::Str(_))
    }
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.as_text())
    }
}

/// Replaces `{name}` with what the variable holds.
///
/// `{{` is a literal brace, and a name nobody set is left exactly as written rather
/// than becoming an empty string - a step whose text silently loses a word is much
/// harder to diagnose than one that shows the placeholder it could not fill.
/// Values a macro can ask for without anybody having declared them.
///
/// Nine names, and nothing that needs a new kind of variable: every one of them is
/// text or a number, which is the ceiling this program keeps on purpose. They are
/// written `{clipboard}`, `{time}` and so on, and the command palette can insert
/// them so nobody has to memorise the list.
///
/// A variable of the same name wins. Somebody who set `time` to something meant
/// their `time`, and silently overruling it would be the surprising choice.
const BUILT_INS: [&str; 9] = [
    "clipboard",
    "window.title",
    "process.name",
    "time",
    "date",
    "mouse.x",
    "mouse.y",
    "screen.width",
    "screen.height",
];

/// What one of those names is worth right now.
///
/// Each is read at the moment it is asked for rather than cached: `{time}` in a loop
/// that runs for four hours has to be four hours of different answers.
fn built_in(name: &str) -> Option<String> {
    let (y, mo, d, _, h, mi) = platform::local_time();
    Some(match name {
        "clipboard" => platform::clipboard_text(),
        "window.title" => platform::foreground_title().unwrap_or_default(),
        "process.name" => platform::foreground_process(),
        "time" => format!("{h:02}:{mi:02}"),
        "date" => format!("{y:04}-{mo:02}-{d:02}"),
        "mouse.x" => platform::cursor_pos().0.to_string(),
        "mouse.y" => platform::cursor_pos().1.to_string(),
        "screen.width" => platform::virtual_screen_rect().2.to_string(),
        "screen.height" => platform::virtual_screen_rect().3.to_string(),
        _ => return None,
    })
}

fn expand_vars(text: &str, vars: &std::collections::HashMap<String, Value>) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    loop {
        // Both braces, because a doubled one of either kind is a literal, the same
        // rule Rust's own format strings use.
        let Some(at) = rest.find(['{', '}']) else {
            out.push_str(rest);
            return out;
        };
        out.push_str(&rest[..at]);
        rest = &rest[at..];
        if rest.starts_with("{{") || rest.starts_with("}}") {
            out.push_str(&rest[..1]);
            rest = &rest[2..];
            continue;
        }
        if rest.starts_with('}') {
            // A closing brace with nothing open is just a brace.
            out.push('}');
            rest = &rest[1..];
            continue;
        }
        match rest.find('}') {
            Some(end) => {
                let name = &rest[1..end];
                // A variable of the same name wins over a built-in: somebody who
                // set `time` meant their `time`.
                match vars.get(name) {
                    Some(v) => out.push_str(&v.as_text()),
                    None => match built_in(name) {
                        Some(v) => out.push_str(&v),
                        // An unknown name is left exactly as written rather than
                        // becoming an empty string, so a typo is visible instead of
                        // silently deleting part of the text.
                        None => out.push_str(&rest[..=end]),
                    },
                }
                rest = &rest[end + 1..];
            }
            // An unclosed brace is text, not an error.
            None => {
                out.push_str(rest);
                return out;
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum VarOp {
    Set,
    Add,
    Sub,
    Mul,
}

impl VarOp {
    fn apply(self, cur: f64, v: f64) -> f64 {
        match self {
            VarOp::Set => v,
            VarOp::Add => cur + v,
            VarOp::Sub => cur - v,
            VarOp::Mul => cur * v,
        }
    }

    /// The same, once either side can be text.
    ///
    /// Adding to text joins it, which is how a message is built up a piece at a
    /// time. Taking away from it or multiplying it is meaningless, so those read
    /// both sides as numbers and answer with a number.
    fn apply_values(self, cur: &Value, v: &Value) -> Value {
        if self == VarOp::Set {
            return v.clone();
        }
        if self == VarOp::Add && (cur.is_text() || v.is_text()) {
            let joined = match (cur.numeric(), v.numeric()) {
                // Two numbers written as text are still two numbers.
                (Some(a), Some(b)) => return Value::Num(a + b),
                _ => format!("{}{}", cur.as_text(), v.as_text()),
            };
            return Value::Str(joined);
        }
        Value::Num(self.apply(cur.as_num(), v.as_num()))
    }
    fn symbol(self) -> &'static str {
        match self {
            VarOp::Set => "=",
            VarOp::Add => "+=",
            VarOp::Sub => "-=",
            VarOp::Mul => "*=",
        }
    }
    const ALL: [VarOp; 4] = [VarOp::Set, VarOp::Add, VarOp::Sub, VarOp::Mul];
}

/// Is the picture there, given what we decided last time?
///
/// One threshold makes a wobbling score flip between found and lost several times a
/// second: 79, 81, 79, 82 around a threshold of 80 reads as four state changes and a
/// script that acts on each of them. Two thresholds - one to appear, a lower one to
/// disappear - turn that into one state change, which is what a Schmitt trigger is for
/// and what every noisy sensor since has needed.
fn match_decision(score: f64, appear_at: f64, lose_at: f64, was_present: bool) -> bool {
    // A `lose_at` of zero, or one that is not actually lower, means the caller wants
    // the old all-or-nothing behaviour.
    let lo = if lose_at > 0.0 && lose_at < appear_at { lose_at } else { appear_at };
    if was_present { score >= lo } else { score >= appear_at }
}

/// Folds one observation into a rolling history and answers "N of the last M".
///
/// A single frame is not evidence. A score of 83, then 51, then 74 is noise finding
/// something briefly plausible; 82, 84, 83 is an object. `within` is capped at 32
/// because the history is a bitmask, which is enough for several seconds of looking.
fn stable_enough(history: &mut u32, raw: bool, of: u32, within: u32) -> bool {
    let m = within.clamp(1, 32);
    *history = (*history << 1) | u32::from(raw);
    if of <= 1 && m <= 1 {
        return raw;
    }
    let mask = if m >= 32 { u32::MAX } else { (1u32 << m) - 1 };
    (*history & mask).count_ones() >= of.clamp(1, m)
}

/// Where a piece of text comes from.
///
/// The three that are not a file are the reason variables learnt to hold text at
/// all: what the window is called, what is running, and what was last copied.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Default)]
pub enum TextSource {
    #[default]
    Clipboard,
    /// Title of the window in front.
    WindowTitle,
    /// Executable name of the window in front, such as `RobloxPlayerBeta.exe`.
    ProcessName,
    /// A file, read as text. Capped, because a script should not be able to pull a
    /// gigabyte into a variable by naming the wrong path.
    File(String),
}

impl TextSource {
    pub fn index(&self) -> usize {
        match self {
            TextSource::Clipboard => 0,
            TextSource::WindowTitle => 1,
            TextSource::ProcessName => 2,
            TextSource::File(_) => 3,
        }
    }
    pub fn from_index(i: usize) -> Self {
        match i {
            1 => TextSource::WindowTitle,
            2 => TextSource::ProcessName,
            3 => TextSource::File(String::new()),
            _ => TextSource::Clipboard,
        }
    }
}

/// Where a piece of text goes.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Default)]
pub enum TextSink {
    #[default]
    Clipboard,
    File {
        path: String,
        /// Add to the end rather than replace. A log wants this; a hand-off file
        /// does not.
        append: bool,
    },
}

impl TextSink {
    pub fn index(&self) -> usize {
        match self {
            TextSink::Clipboard => 0,
            TextSink::File { .. } => 1,
        }
    }
    pub fn from_index(i: usize) -> Self {
        match i {
            1 => TextSink::File { path: String::new(), append: false },
            _ => TextSink::Clipboard,
        }
    }
}

/// Most a file read into a variable is allowed to be.
const TEXT_FILE_CAP: u64 = 1 << 20;

/// Serde default for a flag that is on unless a file says otherwise.
fn yes_bool() -> bool {
    true
}

/// What the debug overlay draws, written by whatever last looked at the screen.
///
/// A global rather than something threaded through the engine: the looking happens
/// on the playback thread and the drawing on the UI thread, and the only thing the
/// two need to agree about is a few rectangles.
#[derive(Clone, Debug, Default)]
pub struct Sighting {
    /// Where the search was allowed to look.
    pub area: Option<(i32, i32, i32, i32)>,
    /// Where it found something, and how sure it was.
    pub hit: Option<(i32, i32, i32, i32, f32)>,
    /// The rectangle text was last read from.
    pub text: Option<(i32, i32, i32, i32)>,
    /// The element UI Automation last returned.
    pub element: Option<(i32, i32, i32, i32)>,
    /// One line: what was looked for and what came back.
    pub note: String,
    /// Bumped on every write. The overlay redraws when this changes and not
    /// otherwise: a layered window repainted ten times a second for no reason is a
    /// visible flicker and a pointless slice of a core.
    pub seq: u64,
}

static SIGHTING: Mutex<Sighting> = Mutex::new(Sighting {
    area: None,
    hit: None,
    text: None,
    element: None,
    note: String::new(),
    seq: 0,
});

/// What the variables window shows, written by the interpreter before each step.
///
/// The other half of the overlay. The overlay says where the script is looking;
/// this says what it has found out so far, which is the half you need when the
/// script is looking in the right place and still doing the wrong thing.
#[derive(Clone, Debug, Default)]
pub struct ScriptView {
    /// Every variable, sorted, already rendered to text. Sorted here rather than in
    /// the window so the rows do not dance about between frames.
    pub vars: Vec<(String, String)>,
    /// Which step is about to run, and how it reads.
    pub pc: usize,
    pub step: String,
    /// How many `Call` steps deep this is.
    pub depth: u32,
    /// True while the interpreter is parked waiting for "next step".
    pub waiting: bool,
    pub running: bool,
    pub seq: u64,
}

static SCRIPT_VIEW: Mutex<Option<ScriptView>> = Mutex::new(None);

/// Off unless the variables window is open. A run nobody is watching pays one
/// relaxed load per step for this.
static WATCHING_VARS: AtomicBool = AtomicBool::new(false);

pub fn watching_vars() -> bool {
    WATCHING_VARS.load(Ordering::Relaxed)
}

pub fn set_watching_vars(on: bool) {
    WATCHING_VARS.store(on, Ordering::Relaxed);
    if !on {
        *SCRIPT_VIEW.lock() = None;
    }
}

pub fn script_view() -> Option<ScriptView> {
    SCRIPT_VIEW.lock().clone()
}

fn note_script_view(f: impl FnOnce(&mut ScriptView)) {
    if !watching_vars() {
        return;
    }
    let mut slot = SCRIPT_VIEW.lock();
    let v = slot.get_or_insert_with(ScriptView::default);
    f(v);
    v.seq = v.seq.wrapping_add(1);
}

/// Off unless the overlay window is open. Every write below is behind this, so a
/// script that is not being watched pays one relaxed load per look.
static WATCHING: AtomicBool = AtomicBool::new(false);

pub fn watching() -> bool {
    WATCHING.load(Ordering::Relaxed)
}

/// Records what was just looked at, if anybody is watching.
fn note_sighting(f: impl FnOnce(&mut Sighting)) {
    if !watching() {
        return;
    }
    let mut s = SIGHTING.lock();
    f(&mut s);
    s.seq = s.seq.wrapping_add(1);
}

/// One way of finding something, tried, and what came of it.
///
/// The program has always worked these out and thrown all but the winner away. A
/// cascade that ends in a click tells you nothing about the two rungs above it that
/// failed - and those two are the whole story when the click lands in the wrong
/// place, or takes four seconds, or works today and not tomorrow.
///
/// Nothing here is computed for the sake of the trace. The score, the threshold and
/// the elapsed time are numbers the resolver already had in its hand.
#[derive(Clone, Debug)]
pub struct Attempt {
    /// Which rung, as a `Method` index, so the window can name it in the user's
    /// language rather than in whatever language the run happened to log in.
    pub method: usize,
    pub ok: bool,
    /// The number that decided it, in the program's own vocabulary: `0.61 < 0.85`,
    /// `element unavailable`, `exact`. Empty where there was no number.
    pub detail: String,
    pub took_us: u64,
}

/// What one step did, kept so that it can be explained afterwards.
#[derive(Clone, Debug)]
pub struct StepTrace {
    /// Where the step is in the list, and its identity, so a trace still points at
    /// the right step after somebody inserts a line above it.
    pub pc: usize,
    pub id: u64,
    /// How the step reads in the editor, rendered when the trace was taken.
    pub step: String,
    /// The target's label, when the step aims at one.
    pub label: String,
    pub attempts: Vec<Attempt>,
    /// Where the recording said it was, and where it actually turned out to be.
    /// The pair that answers "why is it clicking twenty pixels low".
    pub recorded: Option<(i32, i32)>,
    pub actual: Option<(i32, i32)>,
    pub took_us: u64,
    pub ok: bool,
    /// How many times the step had already been tried when this one was taken.
    pub tries: u32,
    /// Which cycle of the run this was, counting from one.
    pub cycle: u64,
}

/// How many step traces are kept.
///
/// A ring rather than a log. A macro that loops two hundred times overnight would
/// otherwise accumulate a trace per step per turn, and the answer to "why did that
/// happen" is always about the last few - by the time there are thousands, nobody
/// is reading them, and the memory is real.
const TRACE_KEEP: usize = 64;

/// A deque rather than a vector, because the oldest is what leaves: dropping the
/// front of a `Vec` moves the other sixty-three every time a step runs, and a tight
/// loop runs a step several hundred times a second.
static TRACES: Mutex<std::collections::VecDeque<StepTrace>> =
    Mutex::new(std::collections::VecDeque::new());

/// Bumped on every push, so the window can tell "no traces yet" from "the same
/// traces as last frame" without comparing the vectors.
static TRACE_SEQ: AtomicU64 = AtomicU64::new(0);

fn push_trace(t: StepTrace) {
    let mut v = TRACES.lock();
    if v.len() >= TRACE_KEEP {
        v.pop_front();
    }
    v.push_back(t);
    TRACE_SEQ.fetch_add(1, Ordering::Relaxed);
}

/// Newest first, which is the order somebody looking for what just happened wants.
pub fn traces() -> Vec<StepTrace> {
    TRACES.lock().iter().rev().cloned().collect()
}

pub fn trace_seq() -> u64 {
    TRACE_SEQ.load(Ordering::Relaxed)
}

fn clear_traces() {
    TRACES.lock().clear();
    TRACE_SEQ.fetch_add(1, Ordering::Relaxed);
}

/// Something the script can ask about the screen or about itself.
/// Where on the screen an image step is allowed to look.
///
/// Measured on a 2560x1440 desktop, one full-screen step costs 111 ms - 43 to copy the
/// screen and 68 to sweep it - which caps a polling loop at about nine looks a second.
/// A few hundred pixels square costs closer to twelve. Nothing else in this release
/// buys as much.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Default)]
pub enum SearchArea {
    /// Everything, across every monitor. Correct, and the slowest thing here.
    #[default]
    FullScreen,
    /// Whatever window is in front right now.
    ActiveWindow,
    Rect { x: i32, y: i32, w: i32, h: i32 },
    /// Around where this same template was last seen, which for anything that stays
    /// put is a few hundred pixels rather than four million.
    NearLast { margin: i32 },
    /// Find another picture first, then look in a rectangle placed relative to
    /// where that one landed.
    ///
    /// This is what a threshold cannot do. A row of identical buttons is identical;
    /// which one to press is decided by the heading above it, and an anchor is how
    /// a script says so. Two searches instead of one, and usually faster anyway,
    /// because the second is confined to a few hundred pixels.
    NearAnchor {
        anchor: String,
        /// Where the rectangle sits relative to the centre of the anchor.
        dx: i32,
        dy: i32,
        w: i32,
        h: i32,
    },
}

/// What a step that did not find what it was looking for should do about it.
///
/// Until 1.5.0 there was only the first of these, and it was not a choice anybody
/// had made - a `Click image` whose picture was not on screen did nothing at all
/// and the script walked on to the next step. That is right for a poll inside a
/// `While` and wrong for everything else, and the difference between the two is a
/// macro that stops when the game logs you out and one that clicks at an empty
/// desktop until morning.
///
/// `Continue` stays the default so that every macro written before this release
/// behaves exactly as it did.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum OnMiss {
    /// Walk on to the next step. What every version before 1.5.0 did, always.
    #[default]
    Continue,
    /// End the run. The whole point of the field: a night macro that has lost its
    /// footing should stop, not keep going.
    Stop,
    /// Leave the innermost `While`, exactly as a `Break` step would. For a loop
    /// that is looking for one of several things.
    Break,
    /// Run the recovery block with this name, then try once more.
    ///
    /// The next rung above `Retry`. Retrying is right when the thing was simply not
    /// there yet; it is useless when something is *in the way* - an error box, a
    /// login that expired, a dialog nobody expected - because looking again at the
    /// same obstructed screen gives the same answer.
    ///
    /// The block is an ordinary run of steps in this same list, so it is built with
    /// the same buttons as everything else and is visible rather than hidden behind
    /// an edit dialog. If the step still cannot be done after the block has run, the
    /// script stops - for the same reason `Retry` stops, which is that a recovery
    /// that gives up quietly is the trap this whole enum exists to close.
    Recover { name: String },
    /// Look again, up to `times` more times, `delay_ms` apart - and stop the run if
    /// it is still not there.
    ///
    /// The stop at the end is deliberate and is the reason this is not spelled
    /// "retry, then carry on". A retry that gives up quietly is the trap this whole
    /// enum exists to close; somebody who wants that can set `Continue` and put the
    /// step in a loop, which says so.
    Retry { times: u32, delay_ms: u64 },
}

impl OnMiss {
    const COUNT: usize = 5;

    fn index(&self) -> usize {
        match self {
            OnMiss::Continue => 0,
            OnMiss::Stop => 1,
            OnMiss::Break => 2,
            OnMiss::Retry { .. } => 3,
            OnMiss::Recover { .. } => 4,
        }
    }

    fn from_index(i: usize) -> Self {
        match i {
            1 => OnMiss::Stop,
            2 => OnMiss::Break,
            3 => OnMiss::Retry { times: 3, delay_ms: 500 },
            4 => OnMiss::Recover { name: "recover".into() },
            _ => OnMiss::Continue,
        }
    }

    fn name(&self, s: &Strings) -> &'static str {
        match self {
            OnMiss::Continue => s.m_continue,
            OnMiss::Stop => s.m_stop,
            OnMiss::Break => s.m_break,
            OnMiss::Retry { .. } => s.m_retry,
            OnMiss::Recover { .. } => s.m_recover,
        }
    }

    /// How many extra looks this policy asks for.
    fn retries(&self) -> (u32, u64) {
        match self {
            OnMiss::Retry { times, delay_ms } => (*times, *delay_ms),
            _ => (0, 0),
        }
    }
}

/// A step that looks for something always carries one of these, and it is always
/// `Continue` unless somebody said otherwise.
fn miss_default() -> OnMiss {
    OnMiss::Continue
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub enum Condition {
    Always,
    Var { name: String, cmp: Cmp, value: Value },
    /// A template from the `templates/` folder is on screen.
    Image {
        template: String,
        threshold: f64,
        #[serde(default)]
        area: SearchArea,
        /// Confidence at which a picture already found counts as gone. Zero, or
        /// anything not below `threshold`, keeps the single-threshold behaviour.
        #[serde(default)]
        lose_at: f64,
        /// Require the match in `stable_of` of the last `stable_in` looks. Both at
        /// zero or one means every look decides on its own.
        #[serde(default)]
        stable_of: u32,
        #[serde(default)]
        stable_in: u32,
        /// Match outlines instead of greys. Survives a theme change and a
        /// highlight; costs one extra pass over each plane.
        #[serde(default)]
        edge: bool,
    },
    Pixel { x: i32, y: i32, r: u8, g: u8, b: u8, tol: u32 },
    Window { title: String },
    /// An interface element Windows knows about is there.
    ///
    /// The first rung of the cascade: ask the application what is on screen before
    /// resorting to looking at the pixels. Silent in anything that draws its own
    /// interface, which includes every game engine, so a script that has to work
    /// there falls through to the picture search below.
    Element { query: uia::Query },
    /// A process with this name is running. The name is matched without its path
    /// and without case, so `roblox` finds `RobloxPlayerBeta.exe`.
    Process { name: String },
    /// Text recognised inside a screen rectangle contains `needle`.
    Text {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        needle: String,
        /// What is done to the pixels first. Absent in every file written before
        /// 1.4.0, which is exactly the old behaviour.
        #[serde(default)]
        prep: ocr::Prep,
    },
}

impl Condition {
    fn kind_index(&self) -> usize {
        match self {
            Condition::Always => 0,
            Condition::Var { .. } => 1,
            Condition::Image { .. } => 2,
            Condition::Pixel { .. } => 3,
            Condition::Window { .. } => 4,
            Condition::Text { .. } => 5,
            Condition::Process { .. } => 6,
            Condition::Element { .. } => 7,
        }
    }
    fn from_index(i: usize) -> Self {
        match i {
            1 => Condition::Var {
                name: "count".into(),
                cmp: Cmp::Lt,
                value: Value::Num(10.0),
            },
            2 => Condition::Image {
                template: String::new(),
                threshold: 0.85,
                area: SearchArea::default(),
                lose_at: 0.0,
                stable_of: 0,
                stable_in: 0,
                edge: false,
            },
            3 => Condition::Pixel { x: 0, y: 0, r: 255, g: 0, b: 0, tol: 20 },
            4 => Condition::Window { title: String::new() },
            5 => Condition::Text {
                x: 0,
                y: 0,
                w: 400,
                h: 120,
                needle: String::new(),
                prep: ocr::Prep::default(),
            },
            6 => Condition::Process { name: String::new() },
            7 => Condition::Element { query: uia::Query::default() },
            _ => Condition::Always,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub enum StepKind {
    /// Replays a slice of the recorded events, honouring their original timing.
    PlayEvents {
        from: usize,
        to: usize,
        /// Names for the two ends. When set, these are what the step means and
        /// `from`/`to` are refreshed from them; see [`Between`].
        #[serde(default)]
        between: Option<Between>,
    },
    Wait { ms: u64 },
    /// Blocks until a condition becomes true (or false, when `appear` is off).
    WaitFor {
        cond: Condition,
        appear: bool,
        timeout_ms: u64,
        /// Wait for as long as this step has usually needed, instead of the fixed
        /// number beside it.
        ///
        /// The fixed number stays and becomes the ceiling: what is learned is how
        /// long to wait *patiently*, not permission to wait for ever. With no
        /// history - a new step, a new machine, a copied macro - it is exactly the
        /// fixed number, which is what it has always been.
        #[serde(default)]
        adaptive: bool,
        /// What a timeout means. A wait that gives up used to be indistinguishable
        /// from a wait that succeeded, which is the quietest failure in the program.
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    ClickImage {
        template: String,
        threshold: f64,
        button: MouseButton,
        #[serde(default)]
        area: SearchArea,
        #[serde(default)]
        edge: bool,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Looks for a picture and writes what it found into variables, without clicking.
    FindImage {
        template: String,
        threshold: f64,
        #[serde(default)]
        area: SearchArea,
        /// Prefix for the results: `<var>.found`, `.x`, `.y`, `.w`, `.h`, `.score`.
        var: String,
        #[serde(default)]
        edge: bool,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    Click { x: i32, y: i32, button: MouseButton },
    Key { vk: u16, down: bool },
    SetVar { name: String, op: VarOp, value: Value },
    If { cond: Condition },
    Else,
    EndIf,
    While { cond: Condition },
    EndWhile,
    Break,
    Run { path: String, args: String },
    Exit,
    Log { text: String },
    /// Finds an interface element and writes what it found into variables.
    FindElement {
        query: uia::Query,
        /// Prefix for the results: `<var>` itself is the text, and `<var>.found`,
        /// `.x`, `.y`, `.w`, `.h`, `.name` carry the rest.
        var: String,
        /// How long to keep looking. An interface that is still drawing itself is
        /// the normal case just after a click.
        #[serde(default)]
        timeout_ms: u64,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Presses an interface element.
    ClickElement {
        query: uia::Query,
        button: MouseButton,
        /// Ask the application to press it rather than clicking at it. Nothing
        /// moves on screen, the window need not even be in front, and a control
        /// that has shifted since it was found is still the one that is pressed.
        #[serde(default = "yes_bool")]
        invoke: bool,
        #[serde(default)]
        timeout_ms: u64,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Recognises a screen rectangle and stores what it says, as text.
    ReadText {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        var: String,
        #[serde(default)]
        prep: ocr::Prep,
    },
    /// Puts the clipboard, a window title, a process name or a file into a variable.
    GetText { source: TextSource, var: String },
    /// Sends text - with `{name}` filled in from the variables - to the clipboard or
    /// to a file.
    PutText { sink: TextSink, text: String },
    /// Runs another macro file's script here, then carries on.
    ///
    /// The reuse that people ask for when they ask for functions, without becoming
    /// a language. A subroutine is an ordinary macro: it is edited in this same
    /// editor, played on its own to test it, and shared between projects as a file.
    /// There is no parameter list and no return value - the variables are the same
    /// ones, so a caller sets `target` before the call and reads `result` after it,
    /// which is what a list of steps can express without growing a grammar.
    ///
    /// Nesting is capped at `MAX_CALL_DEPTH`, which is what keeps a file that calls
    /// itself from being a stack overflow.
    Call {
        /// A file name, resolved next to the macro that named it and then in the
        /// data folder. `.json` is added when no extension is given.
        path: String,
        /// What a file that will not load means. The same four choices as a search
        /// that found nothing, for the same reason.
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Presses one thing on screen, however it can be found.
    ///
    /// The 1.6.0 step, and the one the Add menu offers first. `Click image`,
    /// `Press element` and `Click` all still work and still load — this is what they
    /// should have been: one step that says *what* to press and lets the program
    /// work out *how*.
    ClickTarget {
        target: Target,
        button: MouseButton,
        /// Ask the application to press it when the element method is what resolved.
        /// Nothing moves on screen and the window need not be in front.
        #[serde(default = "yes_bool")]
        invoke: bool,
        #[serde(default)]
        reliability: Reliability,
        #[serde(default)]
        timeout_ms: u64,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Waits for one thing on screen to be findable, however it can be found.
    WaitTarget {
        target: Target,
        /// Wait for it to turn up, or to go away.
        #[serde(default = "yes_bool")]
        appear: bool,
        #[serde(default)]
        reliability: Reliability,
        timeout_ms: u64,
        /// Wait for as long as this step has usually needed, with `timeout_ms` as
        /// the ceiling. The same field `Wait for` carries, for the same reason.
        #[serde(default)]
        adaptive: bool,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Reads the words at one thing on screen into a variable.
    ///
    /// Proposal #20's `Read "Gems"` instead of a rectangle nobody can check by
    /// looking at it.
    ReadTarget {
        target: Target,
        var: String,
        #[serde(default)]
        reliability: Reliability,
        #[serde(default)]
        prep: ocr::Prep,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Does one thing to one window.
    ///
    /// One step kind with a dropdown rather than eleven entries in the Add menu.
    /// The count is the point: eleven here and eleven more later is exactly the
    /// "100+ action types" failure this project has written down as a thing never
    /// to do.
    Window {
        window: WindowRef,
        action: WindowAction,
        /// The two numbers for `move to` and `resize to`, ignored otherwise.
        #[serde(default)]
        x: i32,
        #[serde(default)]
        y: i32,
        /// How long the three waiting actions wait.
        #[serde(default)]
        timeout_ms: u64,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Copy, paste, set, read, clear, or wait for the clipboard to change.
    Clipboard {
        action: ClipAction,
        /// For `set`, the text to put there, with `{name}` filled in.
        #[serde(default)]
        text: String,
        /// For `read` and `wait for a change`, where to put what was found.
        #[serde(default)]
        var: String,
        #[serde(default)]
        timeout_ms: u64,
        #[serde(default = "miss_default")]
        miss: OnMiss,
    },
    /// Says something, from the tray, without stealing the keyboard.
    ///
    /// The thing a night macro needs and a message box cannot do: a message box
    /// takes the foreground, and taking the foreground away from the thing being
    /// automated is how a macro breaks the run it is reporting on.
    Notify { title: String, body: String },
    /// Writes a picture of the screen to a file.
    Screenshot {
        /// Where to put it. Empty means the runs folder, named after the step.
        #[serde(default)]
        path: String,
        /// Whole screen when this is off, the window in front when it is on.
        #[serde(default)]
        active_window: bool,
    },
    /// A name for a run of steps, and nothing else.
    ///
    /// **No runtime meaning at all.** `resolve_blocks` treats it as a no-op and the
    /// interpreter walks straight through. That is the whole design: a group that
    /// could change control flow would be a fourth kind of block for somebody to
    /// reason about - after `If`, `While` and `Recovery` - bought for nothing. What
    /// it buys instead is a list of forty steps that reads as six things.
    Group { name: String },
    /// Closes a `Group`.
    EndGroup,
    /// Opens a block that only runs when something sends the script here.
    ///
    /// Skipped in normal flow. A step whose miss policy is `Recover` jumps into the
    /// block with this name, runs it, comes back, and tries once more.
    Recovery { name: String },
    /// Closes a `Recovery` block and returns to the step that failed.
    EndRecovery,
    /// Recognises a screen rectangle and stores the number it finds.
    ReadNumber {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        var: String,
        #[serde(default)]
        prep: ocr::Prep,
        /// What the reading is supposed to look like. Wrong-shaped readings are
        /// refused rather than turned into a number nobody asked for, and with
        /// `Auto` this is also what picks the profile.
        #[serde(default)]
        expect: ocr::Expect,
    },
}

impl StepKind {
    /// Order used by the "Add" menu and the kind picker.
    const COUNT: usize = 35;

    fn index(&self) -> usize {
        match self {
            StepKind::PlayEvents { .. } => 0,
            StepKind::Wait { .. } => 1,
            StepKind::WaitFor { .. } => 2,
            StepKind::ClickImage { .. } => 3,
            StepKind::Click { .. } => 4,
            StepKind::Key { .. } => 5,
            StepKind::SetVar { .. } => 6,
            StepKind::If { .. } => 7,
            StepKind::Else => 8,
            StepKind::EndIf => 9,
            StepKind::While { .. } => 10,
            StepKind::EndWhile => 11,
            StepKind::Break => 12,
            StepKind::Run { .. } => 13,
            StepKind::Exit => 14,
            StepKind::Log { .. } => 15,
            StepKind::ReadNumber { .. } => 16,
            StepKind::FindImage { .. } => 17,
            StepKind::ReadText { .. } => 18,
            StepKind::GetText { .. } => 19,
            StepKind::PutText { .. } => 20,
            StepKind::FindElement { .. } => 21,
            StepKind::ClickElement { .. } => 22,
            StepKind::Call { .. } => 23,
            // The three that should be reached for first are last in this list and
            // first in the menu: the index is a file-format number and reordering it
            // would silently rewrite every macro anybody has saved.
            StepKind::ClickTarget { .. } => 24,
            StepKind::WaitTarget { .. } => 25,
            StepKind::ReadTarget { .. } => 26,
            StepKind::Window { .. } => 27,
            StepKind::Clipboard { .. } => 28,
            StepKind::Notify { .. } => 29,
            StepKind::Screenshot { .. } => 30,
            StepKind::Recovery { .. } => 31,
            StepKind::EndRecovery => 32,
            StepKind::Group { .. } => 33,
            StepKind::EndGroup => 34,
        }
    }

    fn from_index(i: usize) -> Self {
        match i {
            1 => StepKind::Wait { ms: 1000 },
            2 => StepKind::WaitFor {
                adaptive: false,
                cond: Condition::Image {
                    template: String::new(),
                    threshold: 0.85,
                    area: SearchArea::default(),
                    lose_at: 0.0,
                    stable_of: 0,
                    stable_in: 0,
                    edge: false,
                },
                appear: true,
                timeout_ms: 10_000,
                miss: OnMiss::Continue,
            },
            3 => StepKind::ClickImage {
                template: String::new(),
                threshold: 0.85,
                button: MouseButton::Left,
                area: SearchArea::default(),
                edge: false,
                miss: OnMiss::Continue,
            },
            4 => StepKind::Click { x: 0, y: 0, button: MouseButton::Left },
            5 => StepKind::Key { vk: 0x20, down: true },
            6 => StepKind::SetVar {
                name: "count".into(),
                op: VarOp::Add,
                value: Value::Num(1.0),
            },
            7 => StepKind::If { cond: Condition::Always },
            8 => StepKind::Else,
            9 => StepKind::EndIf,
            10 => StepKind::While { cond: Condition::Always },
            11 => StepKind::EndWhile,
            12 => StepKind::Break,
            13 => StepKind::Run { path: String::new(), args: String::new() },
            14 => StepKind::Exit,
            15 => StepKind::Log { text: String::new() },
            16 => StepKind::ReadNumber {
                x: 0,
                y: 0,
                w: 300,
                h: 80,
                var: "amount".into(),
                prep: ocr::Prep::default(),
                expect: ocr::Expect::default(),
            },
            17 => StepKind::FindImage {
                template: String::new(),
                threshold: 0.85,
                area: SearchArea::default(),
                var: "target".into(),
                edge: false,
                miss: OnMiss::Continue,
            },
            18 => StepKind::ReadText {
                x: 0,
                y: 0,
                w: 400,
                h: 120,
                var: "line".into(),
                prep: ocr::Prep::default(),
            },
            19 => StepKind::GetText {
                source: TextSource::default(),
                var: "text".into(),
            },
            20 => StepKind::PutText {
                sink: TextSink::default(),
                text: "{text}".into(),
            },
            21 => StepKind::FindElement {
                query: uia::Query::default(),
                var: "elem".into(),
                timeout_ms: 0,
                miss: OnMiss::Continue,
            },
            22 => StepKind::ClickElement {
                query: uia::Query::default(),
                button: MouseButton::Left,
                invoke: true,
                timeout_ms: 2000,
                miss: OnMiss::Continue,
            },
            23 => StepKind::Call { path: String::new(), miss: OnMiss::Stop },
            24 => StepKind::ClickTarget {
                target: Target::default(),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 2000,
                miss: OnMiss::Stop,
            },
            25 => StepKind::WaitTarget {
                target: Target::default(),
                appear: true,
                reliability: Reliability::Maximum,
                timeout_ms: 10_000,
                adaptive: false,
                miss: OnMiss::Stop,
            },
            26 => StepKind::ReadTarget {
                target: Target::default(),
                var: "text".into(),
                reliability: Reliability::Maximum,
                prep: ocr::Prep::default(),
                miss: OnMiss::Stop,
            },
            27 => StepKind::Window {
                window: WindowRef::default(),
                action: WindowAction::Activate,
                x: 0,
                y: 0,
                timeout_ms: 10_000,
                miss: OnMiss::Stop,
            },
            28 => StepKind::Clipboard {
                action: ClipAction::Copy,
                text: String::new(),
                var: "clip".into(),
                timeout_ms: 5000,
                miss: OnMiss::Stop,
            },
            29 => StepKind::Notify {
                title: APP_TITLE.into(),
                body: String::new(),
            },
            30 => StepKind::Screenshot { path: String::new(), active_window: false },
            31 => StepKind::Recovery { name: "recover".into() },
            32 => StepKind::EndRecovery,
            33 => StepKind::Group { name: "Group".into() },
            34 => StepKind::EndGroup,
            _ => StepKind::PlayEvents { from: 0, to: 0, between: None },
        }
    }

    fn name(&self, s: &Strings) -> &'static str {
        match self {
            StepKind::PlayEvents { .. } => s.k_play,
            StepKind::Wait { .. } => s.k_wait,
            StepKind::WaitFor { .. } => s.k_waitfor,
            StepKind::ClickImage { .. } => s.k_clickimg,
            StepKind::Click { .. } => s.k_click,
            StepKind::Key { .. } => s.k_key,
            StepKind::SetVar { .. } => s.k_setvar,
            StepKind::If { .. } => s.k_if,
            StepKind::Else => s.k_else,
            StepKind::EndIf => s.k_endif,
            StepKind::While { .. } => s.k_while,
            StepKind::EndWhile => s.k_endwhile,
            StepKind::Break => s.k_break,
            StepKind::Run { .. } => s.k_run,
            StepKind::Exit => s.k_exit,
            StepKind::Log { .. } => s.k_log,
            StepKind::ReadNumber { .. } => s.k_readnum,
            StepKind::FindImage { .. } => s.k_findimg,
            StepKind::ReadText { .. } => s.k_readtext,
            StepKind::GetText { .. } => s.k_gettext,
            StepKind::PutText { .. } => s.k_puttext,
            StepKind::FindElement { .. } => s.k_findelem,
            StepKind::ClickElement { .. } => s.k_clickelem,
            StepKind::Call { .. } => s.k_call,
            StepKind::ClickTarget { .. } => s.k_clicktarget,
            StepKind::WaitTarget { .. } => s.k_waittarget,
            StepKind::ReadTarget { .. } => s.k_readtarget,
            StepKind::Window { .. } => s.k_window,
            StepKind::Clipboard { .. } => s.k_clipboard,
            StepKind::Notify { .. } => s.k_notify,
            StepKind::Screenshot { .. } => s.k_screenshot,
            StepKind::Recovery { .. } => s.k_recovery,
            StepKind::EndRecovery => s.k_endrecovery,
            StepKind::Group { .. } => s.k_group,
            StepKind::EndGroup => s.k_endgroup,
        }
    }

    /// The policy this step carries, if it is one that can miss.
    ///
    /// Cloned rather than copied since 1.6.0: `Recover` names a block, and a name is
    /// a String. The clone is one small allocation on a path that was about to look
    /// at the screen, which costs milliseconds.
    fn miss(&self) -> OnMiss {
        match self {
            StepKind::WaitFor { miss, .. }
            | StepKind::ClickImage { miss, .. }
            | StepKind::FindImage { miss, .. }
            | StepKind::FindElement { miss, .. }
            | StepKind::ClickElement { miss, .. }
            | StepKind::ClickTarget { miss, .. }
            | StepKind::WaitTarget { miss, .. }
            | StepKind::ReadTarget { miss, .. }
            | StepKind::Window { miss, .. }
            | StepKind::Clipboard { miss, .. }
            | StepKind::Call { miss, .. } => miss.clone(),
            _ => OnMiss::Continue,
        }
    }

    /// Whether this step does something a test run must not do for real.
    ///
    /// Input is handled elsewhere and handled completely: suppressing `SendInput`
    /// makes every click and keystroke harmless. These two are the steps that reach
    /// past the input queue - one starts a process, the other closes the program -
    /// and no amount of input suppression makes either of them safe to rehearse.
    ///
    /// `PutText` to a file is deliberately *not* here. Writing the file the macro
    /// was written to write is the observable the person testing came to check, and
    /// a test run that quietly wrote nothing would be lying about whether the macro
    /// works. Steps that destroy something get added to this list when they exist;
    /// steps that merely produce output do not.
    fn dangerous(&self) -> bool {
        match self {
            StepKind::Run { .. } | StepKind::Exit => true,
            // Closing somebody's window can lose their work, and no amount of input
            // suppression makes that safe to rehearse. The other ten window actions
            // are harmless and are performed normally.
            StepKind::Window { action, .. } => action.dangerous(),
            _ => false,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ScriptStep {
    pub kind: StepKind,
    #[serde(default = "yes")]
    pub enabled: bool,
    /// This step's identity, for anything that has to remember something about it
    /// between runs.
    ///
    /// Position is not identity. A step's index changes the first time anybody
    /// inserts a line above it, and statistics or learned timings keyed by index
    /// would then silently belong to a different step - which is the worst kind of
    /// wrong, because the numbers still look plausible.
    ///
    /// Zero means "not assigned yet", which is what every step in every file written
    /// before 1.6.0 has. `normalize` fills those in, so an old macro acquires ids the
    /// first time it is loaded and keeps them from then on.
    #[serde(default)]
    pub id: u64,
}

fn yes() -> bool {
    true
}

impl ScriptStep {
    /// A step with no id yet. It gets one when the macro is next normalised, which
    /// is before it can be saved or run.
    fn new(kind: StepKind) -> Self {
        Self { kind, enabled: true, id: 0 }
    }
}

fn describe_condition(c: &Condition, s: &Strings) -> String {
    match c {
        Condition::Always => s.c_always.to_string(),
        Condition::Var { name, cmp, value } => format!("{name} {} {value}", cmp.symbol()),
        Condition::Image { template, threshold, .. } => {
            format!("{}: {template} ≥ {threshold:.2}", s.c_image)
        }
        Condition::Pixel { x, y, r, g, b, tol } => {
            format!("{}: ({x},{y}) = {r},{g},{b} ±{tol}", s.c_pixel)
        }
        Condition::Window { title } => format!("{}: {title}", s.c_window),
        Condition::Text { x, y, w, h, needle, .. } => {
            format!("{}: \"{needle}\" @ ({x},{y} {w}x{h})", s.c_text)
        }
        Condition::Process { name } => format!("{}: {name}", s.c_process),
        Condition::Element { query } => format!("{}: {}", s.c_element, describe_query(query)),
    }
}

/// The tail a step's line gets when it will do something other than walk on.
///
/// Only shown when it is not the default: a list where every line ends in "carry
/// on" says nothing, and a list where one line ends in "stop the script" says
/// exactly where the run can end.
fn describe_miss(kind: &StepKind, s: &Strings) -> String {
    match kind.miss() {
        OnMiss::Continue => String::new(),
        OnMiss::Retry { times, delay_ms } => {
            format!("  ⟲ {times}×{delay_ms}ms → {}", s.m_stop)
        }
        other => format!("  ⚠ {}", other.name(s)),
    }
}

fn describe_step(step: &ScriptStep, s: &Strings, total_events: usize) -> String {
    let name = step.kind.name(s);
    match &step.kind {
        StepKind::PlayEvents { from, to, .. } => {
            let covered = to.saturating_sub(*from) + 1;
            format!("{name} {from}…{to}  ({covered}/{total_events})")
        }
        StepKind::Wait { ms } => format!("{name} {ms} ms"),
        StepKind::WaitFor { cond, appear, timeout_ms, .. } => format!(
            "{name} {} {} ({timeout_ms} ms){}",
            describe_condition(cond, s),
            if *appear { s.f_appear } else { s.f_gone },
            describe_miss(&step.kind, s)
        ),
        StepKind::FindImage { template, threshold, var, .. } => {
            format!("{name} {template} ≥ {threshold:.2} → {var}{}", describe_miss(&step.kind, s))
        }
        StepKind::ClickImage { template, threshold, .. } => {
            format!("{name}: {template} ≥ {threshold:.2}{}", describe_miss(&step.kind, s))
        }
        StepKind::Call { path, .. } => {
            format!("{name} {path}{}", describe_miss(&step.kind, s))
        }
        StepKind::ClickTarget { target, reliability, .. } => format!(
            "{name} {}  [{}]{}",
            target.describe(s),
            target.describe_cascade(*reliability, s),
            describe_miss(&step.kind, s)
        ),
        StepKind::WaitTarget { target, appear, timeout_ms, .. } => format!(
            "{name} {} {} ({timeout_ms} ms){}",
            target.describe(s),
            if *appear { s.f_appear } else { s.f_gone },
            describe_miss(&step.kind, s)
        ),
        StepKind::Clipboard { action, text, var, .. } => {
            let tail = if action.uses_text() {
                format!(" \u{201c}{text}\u{201d}")
            } else if action.uses_var() {
                format!(" \u{2192} {var}")
            } else {
                String::new()
            };
            format!("{name}: {}{tail}{}", action.name(s), describe_miss(&step.kind, s))
        }
        StepKind::Notify { title, body } => format!("{name}: {title} \u{2014} {body}"),
        StepKind::Screenshot { path, active_window } => format!(
            "{name}: {}{}",
            if *active_window { s.a_window } else { s.a_full },
            if path.trim().is_empty() { String::new() } else { format!(" \u{2192} {path}") }
        ),
        StepKind::Recovery { name: n } => format!("{name} \u{201c}{n}\u{201d}"),
        StepKind::Group { name: n } => format!("\u{25b8} {n}"),
        StepKind::Window { window, action, x, y, .. } => {
            let arg = if action.uses_xy() { format!(" {x},{y}") } else { String::new() };
            format!(
                "{name}: {} — {}{arg}{}",
                window.describe(s),
                action.name(s),
                describe_miss(&step.kind, s)
            )
        }
        StepKind::ReadTarget { target, var, .. } => format!(
            "{name} {} → {var}{}",
            target.describe(s),
            describe_miss(&step.kind, s)
        ),
        StepKind::Click { x, y, button } => format!("{name} ({x}, {y}) {button:?}"),
        StepKind::Key { vk, down } => {
            format!("{name} {} {}", vk_name(*vk as u32), if *down { s.st_down } else { s.st_up })
        }
        StepKind::SetVar { name: v, op, value } => {
            format!("{name} {v} {} {value}", op.symbol())
        }
        StepKind::If { cond } | StepKind::While { cond } => {
            format!("{name} {}", describe_condition(cond, s))
        }
        StepKind::Run { path, args } => format!("{name} {path} {args}"),
        StepKind::Log { text } => format!("{name}: {text}"),
        StepKind::ReadNumber { x, y, w, h, var, .. } => {
            format!("{name} ({x},{y} {w}x{h}) → {var}")
        }
        StepKind::ReadText { x, y, w, h, var, .. } => {
            format!("{name} ({x},{y} {w}x{h}) → {var}")
        }
        StepKind::FindElement { query, var, .. } => {
            format!("{name}: {} → {var}{}", describe_query(query), describe_miss(&step.kind, s))
        }
        StepKind::ClickElement { query, invoke, .. } => {
            format!(
                "{name}: {}{}{}",
                describe_query(query),
                if *invoke { " ⚡" } else { "" },
                describe_miss(&step.kind, s)
            )
        }
        StepKind::GetText { source, var } => {
            let from = match source {
                TextSource::Clipboard => s.t_clipboard.to_string(),
                TextSource::WindowTitle => s.t_wintitle.to_string(),
                TextSource::ProcessName => s.t_process.to_string(),
                TextSource::File(p) => p.clone(),
            };
            format!("{name}: {from} → {var}")
        }
        StepKind::PutText { sink, text } => {
            let to = match sink {
                TextSink::Clipboard => s.t_clipboard.to_string(),
                TextSink::File { path, append } => {
                    format!("{path}{}", if *append { " +" } else { "" })
                }
            };
            format!("{name}: \"{text}\" → {to}")
        }
        _ => name.to_string(),
    }
}

/// The span a bulk edit covers, given what is picked out.
///
/// Non-contiguous picks are widened to the whole span between the first and last.
/// Wrapping steps 3 and 9 in an `If` while leaving 4 to 8 outside it is not a thing
/// the linear list can express, and silently doing something else would be worse
/// than doing the obvious thing.
fn selection_span(marked: &std::collections::BTreeSet<usize>, fallback: usize) -> (usize, usize) {
    match (marked.iter().next(), marked.iter().next_back()) {
        (Some(&a), Some(&b)) => (a, b),
        _ => (fallback, fallback),
    }
}

/// Wraps a run of steps in an opener and a closer.
///
/// The closer goes in first: inserting at the front would shift the index the
/// closer was measured against, and getting that backwards is how a wrap ends up
/// enclosing one step too few.
fn wrap_steps(
    script: &mut Vec<ScriptStep>,
    from: usize,
    to: usize,
    open: StepKind,
    close: StepKind,
) {
    if script.is_empty() {
        return;
    }
    let from = from.min(script.len() - 1);
    let to = to.min(script.len() - 1).max(from);
    script.insert(to + 1, ScriptStep::new(close));
    script.insert(from, ScriptStep::new(open));
}

/// Copies a run of steps in directly after itself.
///
/// The copies get no ids: `normalize` hands out fresh ones, so a duplicated step is
/// a new step with its own history rather than a second claimant to the original's.
fn duplicate_steps(script: &mut Vec<ScriptStep>, from: usize, to: usize) {
    if script.is_empty() {
        return;
    }
    let from = from.min(script.len() - 1);
    let to = to.min(script.len() - 1).max(from);
    let copies: Vec<ScriptStep> = script[from..=to]
        .iter()
        .map(|st| ScriptStep { kind: st.kind.clone(), enabled: st.enabled, id: 0 })
        .collect();
    for (n, st) in copies.into_iter().enumerate() {
        script.insert(to + 1 + n, st);
    }
}

/// Moves a run of steps one place up or down, as a block.
fn move_steps(script: &mut [ScriptStep], from: usize, to: usize, down: bool) -> bool {
    if script.is_empty() {
        return false;
    }
    let (from, to) = (from.min(script.len() - 1), to.min(script.len() - 1));
    if down {
        if to + 1 >= script.len() {
            return false;
        }
        // Rotating the span plus the one step past it moves the block down by one
        // without touching anything else.
        script[from..=to + 1].rotate_right(1);
    } else {
        if from == 0 {
            return false;
        }
        script[from - 1..=to].rotate_left(1);
    }
    true
}

/// Where each block-opening step jumps to.
#[derive(Clone, Debug, Default)]
pub struct Blocks {
    /// For `If`: the matching `Else`, if any.
    pub else_of: Vec<Option<usize>>,
    /// For `If`/`While`: the matching `EndIf`/`EndWhile`.
    pub end_of: Vec<Option<usize>>,
    /// For `Else`/`EndWhile`: the step that opened the block.
    pub start_of: Vec<Option<usize>>,
}

/// Matches block openers with their closers.
///
/// Resolved once before the script runs, so the interpreter itself never has to
/// scan for a matching `EndIf` - and an unbalanced script is reported up front
/// instead of behaving strangely halfway through.
fn resolve_blocks(steps: &[ScriptStep]) -> std::result::Result<Blocks, String> {
    let n = steps.len();
    let mut b = Blocks {
        else_of: vec![None; n],
        end_of: vec![None; n],
        start_of: vec![None; n],
    };
    // (index, is_while)
    let mut stack: Vec<(usize, bool)> = Vec::new();
    // Recovery blocks are counted separately from If and While. They are not nested
    // inside the control flow - they sit beside it, and a `Recovery` opened inside an
    // `If` would be a block the interpreter jumps into from outside the `If`, which
    // is not a thing that can be reasoned about.
    let mut recovery_open: Option<usize> = None;
    let mut group_open: Vec<usize> = Vec::new();

    for (i, st) in steps.iter().enumerate() {
        match st.kind {
            // A group is checked for balance and otherwise ignored: it opens and
            // closes nothing the interpreter cares about, but an unclosed one would
            // still confuse every reader of the list.
            StepKind::Group { .. } => group_open.push(i),
            StepKind::EndGroup => {
                if group_open.pop().is_none() {
                    return Err(format!("End group #{i}"));
                }
            }
            StepKind::Recovery { .. } => {
                if let Some(open) = recovery_open {
                    return Err(format!("Recovery #{open}"));
                }
                if !stack.is_empty() {
                    return Err(format!("Recovery #{i}"));
                }
                recovery_open = Some(i);
            }
            StepKind::EndRecovery => {
                if recovery_open.take().is_none() {
                    return Err(format!("End recovery #{i}"));
                }
            }
            StepKind::If { .. } => stack.push((i, false)),
            StepKind::While { .. } => stack.push((i, true)),
            StepKind::Else => match stack.last() {
                Some(&(open, false)) => {
                    if b.else_of[open].is_some() {
                        return Err(format!("{} #{i}", "Else"));
                    }
                    b.else_of[open] = Some(i);
                    b.start_of[i] = Some(open);
                }
                _ => return Err(format!("Else #{i}")),
            },
            StepKind::EndIf => match stack.pop() {
                Some((open, false)) => {
                    b.end_of[open] = Some(i);
                    b.start_of[i] = Some(open);
                    if let Some(e) = b.else_of[open] {
                        b.end_of[e] = Some(i);
                    }
                }
                Some((open, true)) => return Err(format!("While #{open}")),
                None => return Err(format!("End if #{i}")),
            },
            StepKind::EndWhile => match stack.pop() {
                Some((open, true)) => {
                    b.end_of[open] = Some(i);
                    b.start_of[i] = Some(open);
                }
                Some((open, false)) => return Err(format!("If #{open}")),
                None => return Err(format!("End while #{i}")),
            },
            _ => {}
        }
    }
    if let Some(open) = recovery_open {
        return Err(format!("Recovery #{open}"));
    }
    if let Some(open) = group_open.last() {
        return Err(format!("Group #{open}"));
    }
    if let Some(&(open, _)) = stack.last() {
        return Err(format!("#{open}"));
    }
    Ok(b)
}

/// Index of the first step that can never run.
///
/// Anything after an `Exit` at the outermost level is dead: the program is gone
/// before it gets there. Easy to create by accident, invisible without a marker.
fn first_unreachable(steps: &[ScriptStep]) -> Option<usize> {
    let depths = script_depths(steps);
    steps.iter().enumerate().find_map(|(i, st)| {
        if matches!(st.kind, StepKind::Exit) && st.enabled && depths[i] == 0 && i + 1 < steps.len()
        {
            Some(i + 1)
        } else {
            None
        }
    })
}

/// Indentation level of every step, for the editor list.
fn script_depths(steps: &[ScriptStep]) -> Vec<usize> {
    let mut out = Vec::with_capacity(steps.len());
    let mut depth = 0usize;
    for st in steps {
        match st.kind {
            // Groups and recovery blocks indent their contents too. They have no
            // runtime meaning between them, but the indentation is the whole reason
            // a group exists.
            StepKind::EndIf
            | StepKind::EndWhile
            | StepKind::EndGroup
            | StepKind::EndRecovery => depth = depth.saturating_sub(1),
            StepKind::Else => {}
            _ => {}
        }
        let shown = match st.kind {
            StepKind::Else => depth.saturating_sub(1),
            _ => depth,
        };
        out.push(shown);
        if matches!(
            st.kind,
            StepKind::If { .. }
                | StepKind::While { .. }
                | StepKind::Group { .. }
                | StepKind::Recovery { .. }
        ) {
            depth += 1;
        }
    }
    out
}

/// Macro container, format version 5.
///
/// v1 files were a bare `[MacroEvent, ...]` array; v2 had no `script` or `vars`; v3
/// had no `markers`; v4 had no `recorded`. All of them are still accepted on load,
/// and all of them come back out as the current version.
///
/// Reading forwards is the direction that had never been considered. Serde drops
/// fields it does not know about without a word, so a file written by a later
/// version used to load here looking perfectly healthy, lose everything new in it,
/// and be written back as this version - the loss visible nowhere until the machine
/// that wrote it opened it again. `from_future` is how that is now noticed; refusing
/// to save over it is what the window does about it.
#[derive(Clone, Debug, Serialize, Deserialize, Default)]
pub struct MacroData {
    #[serde(default = "format_version")]
    pub version: u32,
    /// Set on load when the file said a version this build does not know.
    ///
    /// Never written to disk and never round-tripped: it is a fact about where this
    /// copy in memory came from, not a property of the macro.
    #[serde(skip)]
    pub from_future: u32,
    /// Full recording length, including trailing idle time.
    #[serde(default)]
    pub duration_us: u64,
    #[serde(default)]
    pub anchor: Option<WindowAnchor>,
    pub events: Vec<MacroEvent>,
    /// Optional program. Empty means "just replay the events", which is what every
    /// macro recorded before version 3 does.
    #[serde(default)]
    pub script: Vec<ScriptStep>,
    /// Starting values for the script's variables.
    #[serde(default)]
    pub vars: std::collections::BTreeMap<String, Value>,
    /// Names for places in the recording. Absent from every file written before
    /// format 4, which is exactly the old behaviour.
    #[serde(default)]
    pub markers: Vec<Marker>,
    /// The machine this was recorded on, as it was at that moment. Absent from every
    /// file written before format 5, and from every macro that was written by hand.
    ///
    /// Nothing reads this to decide anything. It exists so that the difference
    /// between the machine that recorded and the machine that is replaying can be
    /// put into words before the run rather than guessed at after it.
    #[serde(default)]
    pub recorded: Option<RecordingInfo>,
}

fn format_version() -> u32 {
    5
}

fn shot_size_default() -> u32 {
    64
}

fn shot_miss_default() -> OnMiss {
    OnMiss::Stop
}

impl MacroData {
    fn new(events: Vec<MacroEvent>, duration_us: u64) -> Self {
        Self {
            version: format_version(),
            from_future: 0,
            duration_us,
            anchor: None,
            events,
            script: Vec::new(),
            vars: Default::default(),
            markers: Vec::new(),
            recorded: None,
        }
    }

    /// Gives every step without an id one, and repairs any duplicates.
    ///
    /// Called from `normalize`, so it happens on load, on save and after an edit.
    /// New ids continue from the highest already in the file rather than starting at
    /// one: a step that is deleted must not hand its number to the next step
    /// created, or the statistics of the dead step become the statistics of the new
    /// one.
    ///
    /// Duplicates are repaired rather than tolerated because copying a step is the
    /// obvious way to get two - and two steps sharing an identity would pool their
    /// timings into an average belonging to neither.
    fn assign_step_ids(&mut self) {
        let mut next = self.script.iter().map(|st| st.id).max().unwrap_or(0);
        let mut seen: std::collections::HashSet<u64> = std::collections::HashSet::new();
        for st in self.script.iter_mut() {
            if st.id == 0 || !seen.insert(st.id) {
                next += 1;
                st.id = next;
                seen.insert(next);
            }
        }
    }

    /// Where a marker sits, by name and ignoring case.
    fn marker_at(&self, name: &str) -> Option<usize> {
        self.markers
            .iter()
            .find(|m| m.name.trim().eq_ignore_ascii_case(name.trim()))
            .map(|m| m.at)
    }

    /// Brings every named `Play events` range back in step with its markers.
    ///
    /// Called from `normalize`, so it happens on load, on save and after an edit -
    /// which is every moment the two could have drifted. A range whose markers have
    /// gone is left exactly as it was: the numbers it last resolved to are a better
    /// answer than nothing, and the checker reports the missing name separately.
    fn refresh_ranges(&mut self) {
        let total = self.events.len();
        if total == 0 {
            return;
        }
        // Collected first: the loop below needs `&mut self.script` and the lookup
        // needs `&self.markers`.
        let resolved: Vec<Option<(usize, usize)>> = self
            .script
            .iter()
            .map(|st| match &st.kind {
                StepKind::PlayEvents { between: Some((a, b)), .. } => {
                    let (a, b) = (self.marker_at(a)?, self.marker_at(b)?);
                    // The end marker names the place *after* the region, which is how
                    // somebody puts one down: "after inventory" is not part of it.
                    if b == 0 || a >= b {
                        return None;
                    }
                    Some((a.min(total - 1), (b - 1).min(total - 1)))
                }
                _ => None,
            })
            .collect();
        for (st, hit) in self.script.iter_mut().zip(resolved) {
            if let (StepKind::PlayEvents { from, to, .. }, Some((a, b))) = (&mut st.kind, hit) {
                *from = a;
                *to = b;
            }
        }
    }

    fn has_script(&self) -> bool {
        self.script.iter().any(|s| s.enabled)
    }
    fn is_empty(&self) -> bool {
        self.events.is_empty() && self.script.is_empty()
    }
    fn last_t(&self) -> u64 {
        self.events.last().map(|e| e.t_us).unwrap_or(0)
    }
    fn cycle_len_us(&self) -> u64 {
        self.duration_us.max(self.last_t()).max(1)
    }
    /// Sorts non-monotonic timestamps and rejects obviously broken files.
    fn normalize(&mut self) -> Result<()> {
        if self.events.is_empty() && self.script.is_empty() {
            anyhow::bail!("macro contains no events and no script");
        }
        if let Err(e) = resolve_blocks(&self.script) {
            anyhow::bail!("script has unbalanced blocks near {e}");
        }
        if self.events.len() > MAX_EVENTS {
            anyhow::bail!("macro contains {} events (limit {MAX_EVENTS})", self.events.len());
        }
        if !self.events.windows(2).all(|w| w[0].t_us <= w[1].t_us) {
            warn!("macro timestamps are not monotonic - sorting");
            self.events.sort_by_key(|e| e.t_us);
        }
        let last = self.last_t();
        if self.duration_us < last {
            self.duration_us = last;
        }
        // Everything this build reads it also writes at this version, so a file that
        // has been through here once says what it is. A file from a later version is
        // left saying so - the number is the evidence, and `from_future` is what
        // stops it being written back over the original.
        if self.version < format_version() {
            self.version = format_version();
        }
        self.assign_step_ids();
        // A marker past the end of the recording is a marker for events that were
        // deleted; clamping beats dropping it, because the name is the part somebody
        // wrote down.
        let end = self.events.len();
        for m in self.markers.iter_mut() {
            m.at = m.at.min(end);
        }
        self.refresh_ranges();
        Ok(())
    }
}

fn is_compressed_path(path: &Path) -> bool {
    matches!(
        path.extension().and_then(|e| e.to_str()).map(|e| e.to_ascii_lowercase()).as_deref(),
        Some("mrz") | Some("gz")
    )
}

fn gzip(bytes: &[u8]) -> Result<Vec<u8>> {
    use std::io::Write as _;
    let mut enc = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::best());
    enc.write_all(bytes)?;
    Ok(enc.finish()?)
}

/// The most a compressed macro is allowed to expand to.
///
/// Deflate reaches about 1000:1 on a repetitive stream, so a one-megabyte tail can
/// ask for a gigabyte of memory. With `panic = "abort"` a failed allocation is not
/// an error anybody handles - it is the process gone, mid-macro, with keys held.
/// 512 MB is far beyond any real recording: the event cap is four million events,
/// which is roughly 400 MB of JSON at its most verbose.
const MAX_INFLATED: u64 = 512 * 1024 * 1024;

fn gunzip(bytes: &[u8]) -> Result<Vec<u8>> {
    use std::io::Read as _;
    let mut out = Vec::new();
    // `take` rather than a check afterwards: the point is never to allocate the
    // gigabyte, not to notice having done so.
    let read = flate2::read::GzDecoder::new(bytes).take(MAX_INFLATED + 1);
    let mut read = read;
    read.read_to_end(&mut out)?;
    if out.len() as u64 > MAX_INFLATED {
        anyhow::bail!("compressed data expands past {MAX_INFLATED} bytes - refusing it");
    }
    Ok(out)
}

fn save_macro(path: &Path, data: &MacroData) -> Result<()> {
    let bytes = if is_compressed_path(path) {
        gzip(&serde_json::to_vec(data)?)?
    } else {
        serde_json::to_vec_pretty(data)?
    };
    std::fs::write(path, bytes).with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

fn parse_macro(text: &str) -> Result<MacroData> {
    let mut data = match serde_json::from_str::<MacroData>(text) {
        Ok(d) => d,
        Err(obj_err) => match serde_json::from_str::<Vec<MacroEvent>>(text) {
            Ok(events) => {
                let dur = events.last().map(|e| e.t_us).unwrap_or(0);
                info!("loaded legacy v1 macro ({} events)", events.len());
                MacroData::new(events, dur)
            }
            Err(_) => return Err(anyhow::Error::new(obj_err).context("unrecognised macro format")),
        },
    };
    // The direction nobody had looked in. Serde discards fields it does not know
    // about silently, so a file from a later version loads here looking complete,
    // and saving it writes back what survived - which is the newer half deleted, at
    // the one moment the user believed they were being careful.
    //
    // Loading it is still right: most of it will work, and refusing outright would
    // strand somebody whose other machine is one release ahead. Saving over it is
    // what has to stop, and the window is what stops it.
    if data.version > format_version() {
        warn!(
            "this macro says format {}; this build knows {}. Anything newer in it \
             has already been dropped, and saving would write the loss back to disk",
            data.version,
            format_version()
        );
        data.from_future = data.version;
    }
    data.normalize()?;
    Ok(data)
}

fn load_macro(path: &Path) -> Result<MacroData> {
    let bytes = std::fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    let text = if is_compressed_path(path) {
        String::from_utf8(gunzip(&bytes)?)?
    } else {
        String::from_utf8(bytes).context("macro file is not valid UTF-8")?
    };
    parse_macro(&text)
}

// ---------------------------------------------------------------------------
// AutoHotkey export
// ---------------------------------------------------------------------------

/// Writes an AutoHotkey v2 script that reproduces the macro.
///
/// Coordinates are emitted in screen space (`CoordMode "Mouse", "Screen"`), and the
/// gaps between events become `Sleep` calls, so the timing survives the trip.
fn export_ahk(path: &Path, data: &MacroData, loops: u64) -> Result<()> {
    use std::fmt::Write as _;
    let mut s = String::with_capacity(data.events.len() * 48);
    s.push_str("#Requires AutoHotkey v2.0\n");
    s.push_str("; Generated by Macro Recorder\n");
    s.push_str("CoordMode \"Mouse\", \"Screen\"\n");
    s.push_str("SetKeyDelay -1, -1\nSetMouseDelay -1\n\n");
    s.push_str("Esc::ExitApp\n\n");
    if loops == 0 {
        s.push_str("Loop {\n");
    } else {
        let _ = writeln!(s, "Loop {loops} {{");
    }

    let mut prev = 0u64;
    for ev in &data.events {
        let gap_ms = (ev.t_us.saturating_sub(prev)) / 1000;
        if gap_ms > 0 {
            let _ = writeln!(s, "    Sleep {gap_ms}");
        }
        prev = ev.t_us;
        match ev.kind {
            InputEventKind::MouseMove { x, y, .. } => {
                let _ = writeln!(s, "    MouseMove {x}, {y}, 0");
            }
            InputEventKind::MouseButton { button, down, x, y } => {
                let name = match button {
                    MouseButton::Left => "Left",
                    MouseButton::Right => "Right",
                    MouseButton::Middle => "Middle",
                    MouseButton::X1 => "X1",
                    MouseButton::X2 => "X2",
                };
                let state = if down { "D" } else { "U" };
                let _ = writeln!(s, "    Click {x}, {y}, \"{name}\", \"{state}\"");
            }
            InputEventKind::MouseWheel { delta, horizontal, .. } => {
                let dir = match (horizontal, delta >= 0) {
                    (false, true) => "WheelUp",
                    (false, false) => "WheelDown",
                    (true, true) => "WheelRight",
                    (true, false) => "WheelLeft",
                };
                let n = (delta.abs() / 120).max(1);
                let _ = writeln!(s, "    Click \"{dir}\", {n}");
            }
            InputEventKind::Key { vk, down, .. } => {
                let state = if down { "down" } else { "up" };
                // vk<hex> is always valid in AHK and sidesteps name mapping entirely.
                let _ = writeln!(s, "    Send \"{{vk{vk:02X} {state}}}\"");
            }
        }
    }

    let tail_ms = data.duration_us.saturating_sub(prev) / 1000;
    if tail_ms > 0 {
        let _ = writeln!(s, "    Sleep {tail_ms}");
    }
    s.push_str("}\n");

    std::fs::write(path, s).with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Self-running executable export
// ---------------------------------------------------------------------------

/// Playback settings baked into an exported executable.
#[derive(Clone, Debug, Serialize, Deserialize)]
struct Payload {
    #[serde(default)]
    loops: u64,
    #[serde(default = "one_f64")]
    speed: f64,
    #[serde(default)]
    absolute_mouse: bool,
    #[serde(default)]
    repeat_delay_ms: u64,
    #[serde(default)]
    macro_data: MacroData,
}

fn one_f64() -> f64 {
    1.0
}

/// The largest appended payload that will be believed.
///
/// A macro is JSON and then gzip; 64 MB of that is a recording nobody has made.
/// The number exists so that a length read out of a file cannot become the size of
/// an allocation.
const MAX_PAYLOAD: u64 = 64 * 1024 * 1024;

/// Returns the offset where an appended payload starts, if this image has one.
///
/// Everything after the magic is attacker-controlled: this is the only place in the
/// program that takes a length out of bytes it did not write and then acts on it,
/// so the length is checked three ways before it is used. `16 + len` is a
/// `checked_add` because in a release build - where overflow checks are off - a
/// length of `u64::MAX - 15` wraps it to zero, and a `checked_sub` of zero
/// succeeds. That was the hole: the subtraction looked careful and the addition
/// underneath it was not.
fn payload_offset(bytes: &[u8]) -> Option<usize> {
    if bytes.len() < 16 {
        return None;
    }
    let tail = &bytes[bytes.len() - 8..];
    if tail != PAYLOAD_MAGIC {
        return None;
    }
    let mut len = [0u8; 8];
    len.copy_from_slice(&bytes[bytes.len() - 16..bytes.len() - 8]);
    let len = u64::from_le_bytes(len);
    if len > MAX_PAYLOAD {
        return None;
    }
    let total = 16u64.checked_add(len)?;
    let start = (bytes.len() as u64).checked_sub(total)?;
    Some(start as usize)
}

/// Copies this executable and appends the macro, producing a standalone player.
///
/// A PE image ignores trailing bytes, which is the same trick self-extracting
/// archives use - no compiler or linker is involved.
fn export_self_running_exe(dest: &Path, payload: &Payload) -> Result<()> {
    let exe = std::env::current_exe().context("locating the current executable")?;
    let mut bytes = std::fs::read(&exe).with_context(|| format!("reading {}", exe.display()))?;
    if let Some(off) = payload_offset(&bytes) {
        bytes.truncate(off); // never nest payloads
    }
    let blob = gzip(&serde_json::to_vec(payload)?)?;
    bytes.extend_from_slice(&blob);
    bytes.extend_from_slice(&(blob.len() as u64).to_le_bytes());
    bytes.extend_from_slice(PAYLOAD_MAGIC);
    std::fs::write(dest, bytes).with_context(|| format!("writing {}", dest.display()))?;
    Ok(())
}

/// Reads a payload appended to our own image, if any.
///
/// Only the 16-byte footer is read on a normal launch, so the usual startup path
/// never pulls the whole multi-megabyte image off disk.
fn read_self_payload() -> Option<Payload> {
    use std::io::{Read as _, Seek as _, SeekFrom};

    let exe = std::env::current_exe().ok()?;
    let mut file = std::fs::File::open(&exe).ok()?;
    let size = file.metadata().ok()?.len();
    if size < 16 {
        return None;
    }

    let mut footer = [0u8; 16];
    file.seek(SeekFrom::End(-16)).ok()?;
    file.read_exact(&mut footer).ok()?;
    if &footer[8..] != PAYLOAD_MAGIC {
        return None;
    }
    let len = u64::from_le_bytes(footer[..8].try_into().ok()?);
    // Three refusals before a single byte is allocated: a length larger than any
    // real payload, a length whose footer arithmetic overflows, and a length that
    // claims more bytes than the file holds. Only then is the read sized by it.
    if len > MAX_PAYLOAD {
        warn!("this executable's footer claims a {len}-byte payload - ignoring it");
        return None;
    }
    let total = 16u64.checked_add(len)?;
    let start = size.checked_sub(total)?;

    let mut blob = vec![0u8; len as usize];
    file.seek(SeekFrom::Start(start)).ok()?;
    file.read_exact(&mut blob).ok()?;

    let json = match gunzip(&blob) {
        Ok(j) => j,
        Err(e) => {
            warn!("this executable's payload would not decompress: {e}");
            return None;
        }
    };
    // `normalize` is what caps the event count and rejects unbalanced blocks. It
    // ran on files opened through the file dialog and never on this path, which
    // meant the one input nobody chose was the one input nobody checked.
    let mut payload = serde_json::from_slice::<Payload>(&json).ok()?;
    if let Err(e) = payload.macro_data.normalize() {
        warn!("this executable's payload is not a usable macro: {e}");
        return None;
    }
    payload.speed = payload.speed.clamp(0.05, 10.0);
    Some(payload)
}

// ============================================================================
// Windows, named
// ============================================================================

/// Which window a step means.
///
/// `target_title` - a fragment of a title, matched anywhere in it - has been the
/// whole of this since the feature existed, and a title is the least stable thing a
/// window has. A browser tab changes it. A document changes it. A game changes it
/// when it loads.
///
/// The other three ways are all more stable and all were already available to the
/// program; they simply had nowhere to be written down.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub struct WindowRef {
    #[serde(default)]
    pub by: By,
    pub value: String,
    /// Find it again after a restart, an HWND change or a title change.
    ///
    /// On by default, because the case it covers - the game crashed and was
    /// restarted, and the macro should carry on - is the case a night run is for.
    #[serde(default = "yes")]
    pub re_acquire: bool,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum By {
    /// Part of the title, matched anywhere in it and ignoring case. What
    /// `target_title` has always been, and what it loads as.
    #[default]
    Title,
    /// The whole title, exactly.
    TitleExact,
    /// The process name, with or without `.exe`: `roblox` finds
    /// `RobloxPlayerBeta.exe`. Survives every title change there is.
    Process,
    /// The executable's full path. The strongest of the four, and the one nobody
    /// types by hand.
    Executable,
}

impl By {
    pub const COUNT: usize = 4;
    pub fn index(self) -> usize {
        match self {
            By::Title => 0,
            By::TitleExact => 1,
            By::Process => 2,
            By::Executable => 3,
        }
    }
    pub fn from_index(i: usize) -> Self {
        match i {
            1 => By::TitleExact,
            2 => By::Process,
            3 => By::Executable,
            _ => By::Title,
        }
    }
    pub fn name(self, s: &Strings) -> &'static str {
        match self {
            By::Title => s.by_title,
            By::TitleExact => s.by_title_exact,
            By::Process => s.by_process,
            By::Executable => s.by_exe,
        }
    }
}

impl WindowRef {
    /// The plain old title fragment, which is what every existing setting is.
    pub fn from_title(title: &str) -> Self {
        Self { by: By::Title, value: title.to_string(), re_acquire: true }
    }

    pub fn is_empty(&self) -> bool {
        self.value.trim().is_empty()
    }

    pub fn describe(&self, s: &Strings) -> String {
        if self.is_empty() {
            return s.tg_empty.to_string();
        }
        format!("{}: {}", self.by.name(s), self.value.trim())
    }
}

/// What to do to a window.
///
/// One step kind with a dropdown, and not nine entries in the Add menu. The count is
/// the point: nine separate actions here plus nine more later is exactly the "100+
/// action types" failure the project has written down as a thing never to do.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum WindowAction {
    /// Bring it to the front and give it the keyboard.
    #[default]
    Activate,
    Minimize,
    Maximize,
    Restore,
    Close,
    Move,
    Resize,
    Centre,
    /// Block until it is the window in front.
    WaitActive,
    /// Block until it exists at all.
    WaitAppears,
    /// Block until it is gone.
    WaitClosed,
}

impl WindowAction {
    pub const COUNT: usize = 11;

    pub fn index(self) -> usize {
        match self {
            WindowAction::Activate => 0,
            WindowAction::Minimize => 1,
            WindowAction::Maximize => 2,
            WindowAction::Restore => 3,
            WindowAction::Close => 4,
            WindowAction::Move => 5,
            WindowAction::Resize => 6,
            WindowAction::Centre => 7,
            WindowAction::WaitActive => 8,
            WindowAction::WaitAppears => 9,
            WindowAction::WaitClosed => 10,
        }
    }

    pub fn from_index(i: usize) -> Self {
        match i {
            1 => WindowAction::Minimize,
            2 => WindowAction::Maximize,
            3 => WindowAction::Restore,
            4 => WindowAction::Close,
            5 => WindowAction::Move,
            6 => WindowAction::Resize,
            7 => WindowAction::Centre,
            8 => WindowAction::WaitActive,
            9 => WindowAction::WaitAppears,
            10 => WindowAction::WaitClosed,
            _ => WindowAction::Activate,
        }
    }

    pub fn name(self, s: &Strings) -> &'static str {
        match self {
            WindowAction::Activate => s.wa_activate,
            WindowAction::Minimize => s.wa_minimize,
            WindowAction::Maximize => s.wa_maximize,
            WindowAction::Restore => s.wa_restore,
            WindowAction::Close => s.wa_close,
            WindowAction::Move => s.wa_move,
            WindowAction::Resize => s.wa_resize,
            WindowAction::Centre => s.wa_centre,
            WindowAction::WaitActive => s.wa_wait_active,
            WindowAction::WaitAppears => s.wa_wait_appears,
            WindowAction::WaitClosed => s.wa_wait_closed,
        }
    }

    /// Whether this one blocks, and therefore uses the time limit.
    pub fn waits(self) -> bool {
        matches!(
            self,
            WindowAction::WaitActive | WindowAction::WaitAppears | WindowAction::WaitClosed
        )
    }

    /// Whether this one uses the two numbers beside it.
    pub fn uses_xy(self) -> bool {
        matches!(self, WindowAction::Move | WindowAction::Resize)
    }

    /// Closing a window is the one of these that can lose somebody's work.
    pub fn dangerous(self) -> bool {
        matches!(self, WindowAction::Close)
    }
}

/// What to do with the clipboard.
///
/// The clipboard has been reachable since 1.4 — `Get text` reads it, `Put text`
/// writes it — but only as a source and a sink among others. Two things were
/// missing and neither had a workaround: pressing the keys that copy or paste in
/// whatever application is in front, and *waiting for the clipboard to change*,
/// which is how a macro knows a copy actually happened rather than guessing at a
/// delay.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum ClipAction {
    /// Send Ctrl+C to whatever is in front.
    #[default]
    Copy,
    /// Send Ctrl+V.
    Paste,
    /// Put the step's text on the clipboard, with `{name}` filled in.
    Set,
    /// Read the clipboard into a variable.
    Get,
    Clear,
    /// Block until the clipboard is different from what it is now.
    WaitChange,
}

impl ClipAction {
    pub const COUNT: usize = 6;
    pub fn index(self) -> usize {
        match self {
            ClipAction::Copy => 0,
            ClipAction::Paste => 1,
            ClipAction::Set => 2,
            ClipAction::Get => 3,
            ClipAction::Clear => 4,
            ClipAction::WaitChange => 5,
        }
    }
    pub fn from_index(i: usize) -> Self {
        match i {
            1 => ClipAction::Paste,
            2 => ClipAction::Set,
            3 => ClipAction::Get,
            4 => ClipAction::Clear,
            5 => ClipAction::WaitChange,
            _ => ClipAction::Copy,
        }
    }
    pub fn name(self, s: &Strings) -> &'static str {
        match self {
            ClipAction::Copy => s.cb_copy,
            ClipAction::Paste => s.cb_paste,
            ClipAction::Set => s.cb_set,
            ClipAction::Get => s.cb_get,
            ClipAction::Clear => s.cb_clear,
            ClipAction::WaitChange => s.cb_wait,
        }
    }
    /// Whether the step's text field means anything for this action.
    pub fn uses_text(self) -> bool {
        matches!(self, ClipAction::Set)
    }
    /// Whether the step's variable field means anything.
    pub fn uses_var(self) -> bool {
        matches!(self, ClipAction::Get | ClipAction::WaitChange)
    }
}

// ============================================================================
// Targets
// ============================================================================

/// A thing on screen, and every way this program knows of finding it.
///
/// The centre of 1.6.0, and the answer to the question the whole product is about.
/// A recorded click is a coordinate, and a coordinate is the most brittle way of
/// saying where something is: the window moves, the resolution changes, the list
/// opens one row lower, and the click lands somewhere it should not.
///
/// The program has been able to do better since 1.2 — ask Windows for the button by
/// name, or find its picture — but only as separate steps that somebody had to
/// choose between and build by hand. A `Target` is those same abilities written down
/// as *one thing with a name and several ways of being found*, tried in order until
/// one works.
///
/// The user never writes the cascade. They pick a word — Maximum, Balanced, Fast —
/// and the cascade is what that word means. That is the difference between this and
/// `try / catch / catch`.
#[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
pub struct Target {
    /// What the user sees in the step list: `Start`. Not a file name and not a
    /// coordinate. The whole point is that the step reads as the thing it does.
    pub label: String,
    /// Tried in order; the first that resolves wins. Empty is a target that names
    /// nothing, which the checker complains about.
    pub methods: Vec<Method>,
}

/// One way of finding a target.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub enum Method {
    /// Ask the application. No threshold, no pixels, and it survives a theme change,
    /// a move and a resize. Silent in anything that draws its own interface.
    Element { query: uia::Query },
    /// Look for its picture.
    Image {
        template: String,
        threshold: f64,
        #[serde(default)]
        area: SearchArea,
        #[serde(default)]
        edge: bool,
    },
    /// Find the words next to it, and aim at where they are.
    Text {
        needle: String,
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        #[serde(default)]
        prep: ocr::Prep,
    },
    /// A fixed offset inside a named window. Survives the window moving or being
    /// re-opened elsewhere, which is most of what goes wrong with a coordinate.
    WindowPoint { window: String, dx: i32, dy: i32 },
    /// A screen coordinate. The last resort, and labelled as such everywhere it
    /// appears.
    Point { x: i32, y: i32 },
}

impl Method {
    pub const COUNT: usize = 5;

    pub fn index(&self) -> usize {
        match self {
            Method::Element { .. } => 0,
            Method::Image { .. } => 1,
            Method::Text { .. } => 2,
            Method::WindowPoint { .. } => 3,
            Method::Point { .. } => 4,
        }
    }

    pub fn from_index(i: usize) -> Self {
        match i {
            0 => Method::Element { query: uia::Query::default() },
            1 => Method::Image {
                template: String::new(),
                threshold: 0.85,
                area: SearchArea::NearLast { margin: 160 },
                edge: false,
            },
            2 => Method::Text {
                needle: String::new(),
                x: 0,
                y: 0,
                w: 400,
                h: 120,
                prep: ocr::Prep::default(),
            },
            3 => Method::WindowPoint { window: String::new(), dx: 0, dy: 0 },
            _ => Method::Point { x: 0, y: 0 },
        }
    }

    pub fn name(&self, s: &Strings) -> &'static str {
        match self {
            Method::Element { .. } => s.mt_element,
            Method::Image { .. } => s.mt_image,
            Method::Text { .. } => s.mt_text,
            Method::WindowPoint { .. } => s.mt_window,
            Method::Point { .. } => s.mt_point,
        }
    }

    /// How durable this way of finding something is, for sorting a cascade and for
    /// scoring a macro.
    ///
    /// The order is the one the README has described since 1.2 and is not a matter
    /// of taste: asking the application what is on screen beats looking at the
    /// pixels, looking at the pixels beats reading them as words, and all three beat
    /// trusting a number written down last Tuesday.
    pub fn rank(&self) -> u8 {
        match self {
            Method::Element { .. } => 4,
            Method::Image { .. } => 3,
            Method::Text { .. } => 2,
            Method::WindowPoint { .. } => 1,
            Method::Point { .. } => 0,
        }
    }

    /// Whether this method actually says anything. An unfilled one would either
    /// match everything or nothing, and both are worse than not being there.
    pub fn is_filled(&self) -> bool {
        match self {
            Method::Element { query } => !query.is_empty(),
            Method::Image { template, .. } => !template.trim().is_empty(),
            Method::Text { needle, w, h, .. } => {
                !needle.trim().is_empty() && *w > 0 && *h > 0
            }
            Method::WindowPoint { window, .. } => !window.trim().is_empty(),
            Method::Point { .. } => true,
        }
    }
}

/// How hard to try, in the only vocabulary a user should need.
///
/// This is the whole interface to the cascade. Nobody chooses an order of methods;
/// they choose how much they care, and the order is what that means.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum Reliability {
    /// Every method that could be built, most durable first.
    #[default]
    Maximum,
    /// The two that survive a layout change, and the coordinate behind them.
    Balanced,
    /// One method: whichever is cheapest to check. For a step in a tight loop where
    /// the cost of looking is the point.
    Fast,
}

impl Reliability {
    pub const COUNT: usize = 3;

    pub fn index(self) -> usize {
        match self {
            Reliability::Maximum => 0,
            Reliability::Balanced => 1,
            Reliability::Fast => 2,
        }
    }
    pub fn from_index(i: usize) -> Self {
        match i {
            1 => Reliability::Balanced,
            2 => Reliability::Fast,
            _ => Reliability::Maximum,
        }
    }
    pub fn name(self, s: &Strings) -> &'static str {
        match self {
            Reliability::Maximum => s.rel_max,
            Reliability::Balanced => s.rel_balanced,
            Reliability::Fast => s.rel_fast,
        }
    }

    /// Which of the methods available for a target this setting keeps, in the order
    /// it wants them tried.
    pub fn arrange(self, mut methods: Vec<Method>) -> Vec<Method> {
        methods.retain(|m| m.is_filled());
        // Sorted rather than assumed: a cascade built by hand, or by an older
        // version, must end up in the same order as one built today. Most durable
        // first, hence the reversed key.
        methods.sort_by_key(|m| std::cmp::Reverse(m.rank()));
        match self {
            Reliability::Maximum => methods,
            // Everything that survives a layout change, plus one fallback so the
            // step still does something when the interface is unrecognisable.
            Reliability::Balanced => {
                let mut out: Vec<Method> = methods.iter().filter(|m| m.rank() >= 3).cloned().collect();
                if let Some(last) = methods.iter().find(|m| m.rank() < 3) {
                    out.push(last.clone());
                }
                if out.is_empty() { methods } else { out }
            }
            Reliability::Fast => methods.into_iter().take(1).collect(),
        }
    }
}

impl Target {
    /// The methods this target will actually try, in order.
    pub fn cascade(&self, reliability: Reliability) -> Vec<Method> {
        reliability.arrange(self.methods.clone())
    }

    /// How this target reads in the step list: the label if it has one, otherwise
    /// whatever its best method is called.
    pub fn describe(&self, s: &Strings) -> String {
        if !self.label.trim().is_empty() {
            return format!("“{}”", self.label.trim());
        }
        match self.methods.iter().max_by_key(|m| m.rank()) {
            Some(Method::Element { query }) => describe_query(query),
            Some(Method::Image { template, .. }) => template.clone(),
            Some(Method::Text { needle, .. }) => format!("“{needle}”"),
            Some(Method::WindowPoint { window, dx, dy }) => format!("{window} +{dx},{dy}"),
            Some(Method::Point { x, y }) => format!("({x}, {y})"),
            None => s.tg_empty.to_string(),
        }
    }

    /// A one-line summary of the cascade, for the inspector.
    pub fn describe_cascade(&self, reliability: Reliability, s: &Strings) -> String {
        let names: Vec<&str> = self.cascade(reliability).iter().map(|m| m.name(s)).collect();
        if names.is_empty() {
            return s.tg_empty.to_string();
        }
        names.join(" → ")
    }

    /// Everything a recording knew about one click, turned into a target.
    ///
    /// This is where recording stops producing coordinates. Every method that could
    /// be built from what was captured is built; which of them get used is then a
    /// matter of one dropdown rather than of what was recorded.
    pub fn from_click(shot: &ClickShot, template: Option<&str>) -> Self {
        let mut methods: Vec<Method> = Vec::new();
        if let Some(q) = shot.element.as_ref() {
            methods.push(Method::Element { query: q.clone() });
        }
        if let Some(name) = template {
            methods.push(Method::Image {
                template: name.to_string(),
                threshold: 0.85,
                // Near where it was last seen, widening to the whole screen when it
                // is not there: the first look of a run is a full sweep because
                // nothing has been seen yet, which is the right place to spend it.
                area: SearchArea::NearLast { margin: 160 },
                edge: false,
            });
        }
        if let Some((dx, dy)) = shot.window_offset()
            && !shot.window.trim().is_empty() {
                methods.push(Method::WindowPoint {
                    window: shot.window.clone(),
                    dx,
                    dy,
                });
            }
        // Always last, and always present: a target that resolves no other way must
        // still do what the recording did.
        methods.push(Method::Point { x: shot.x, y: shot.y });

        // The label is what a person would call it. The element's name is the only
        // thing here that is one; everything else would be a file name or a number
        // pretending to be a name.
        let label = shot
            .element
            .as_ref()
            .map(|q| {
                if !q.name.trim().is_empty() {
                    q.name.trim().to_string()
                } else {
                    q.automation_id.trim().to_string()
                }
            })
            .unwrap_or_default();

        Target { label, methods }
    }
}

// ============================================================================
// Packaging
// ============================================================================

/// Base64, both ways, in fifty lines.
///
/// A dependency for this would be a dependency for one function, which is the trade
/// `Cargo.toml` already refuses twice over - `rand` and `bincode-next` are both gone
/// for the same reason. The alternative was storing template bytes as a JSON array
/// of numbers, which gzip crushes back down but which turns a hand-inspectable file
/// into four hundred thousand comma-separated integers.
mod b64 {
    const ALPHABET: &[u8; 64] =
        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    pub fn encode(bytes: &[u8]) -> String {
        let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
        for chunk in bytes.chunks(3) {
            let b = [
                chunk[0],
                chunk.get(1).copied().unwrap_or(0),
                chunk.get(2).copied().unwrap_or(0),
            ];
            let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
            out.push(ALPHABET[(n >> 18) as usize & 63] as char);
            out.push(ALPHABET[(n >> 12) as usize & 63] as char);
            // The tail is padded rather than truncated: a decoder that has to guess
            // how many bytes the last group held is a decoder that guesses wrong.
            out.push(if chunk.len() > 1 {
                ALPHABET[(n >> 6) as usize & 63] as char
            } else {
                '='
            });
            out.push(if chunk.len() > 2 {
                ALPHABET[n as usize & 63] as char
            } else {
                '='
            });
        }
        out
    }

    fn value(c: u8) -> Option<u32> {
        Some(match c {
            b'A'..=b'Z' => (c - b'A') as u32,
            b'a'..=b'z' => (c - b'a') as u32 + 26,
            b'0'..=b'9' => (c - b'0') as u32 + 52,
            b'+' => 62,
            b'/' => 63,
            _ => return None,
        })
    }

    /// `None` on anything that is not base64. A package with a corrupt picture in it
    /// should say so rather than produce a template made of noise.
    pub fn decode(text: &str) -> Option<Vec<u8>> {
        let clean: Vec<u8> =
            text.bytes().filter(|c| !c.is_ascii_whitespace() && *c != b'=').collect();
        let mut out = Vec::with_capacity(clean.len() / 4 * 3);
        for group in clean.chunks(4) {
            let mut n = 0u32;
            for (i, c) in group.iter().enumerate() {
                n |= value(*c)? << (18 - 6 * i);
            }
            // How many bytes this group really carried, from how many characters
            // survived the padding strip.
            let keep = match group.len() {
                4 => 3,
                3 => 2,
                2 => 1,
                _ => return None,
            };
            for i in 0..keep {
                out.push((n >> (16 - 8 * i)) as u8);
            }
        }
        Some(out)
    }
}

/// A macro and everything it needs, in one file.
///
/// The limitation the README has always listed: an exported `.exe` that searches for
/// pictures needs the `templates/` folder beside it, and a `Call` step names a file
/// that has to travel with it. Neither survives being emailed to somebody.
///
/// Deliberately still gzipped JSON rather than a zip: `flate2` is already here, a zip
/// crate would not be, and the format keeps the property the project sells - open it
/// in a text editor and read it. The pictures are base64 inside it, which is the only
/// concession.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MacroPackage {
    #[serde(default = "pkg_version")]
    pub version: u32,
    pub main: MacroData,
    /// Every macro a `Call` step names, by the name it names.
    #[serde(default)]
    pub macros: std::collections::BTreeMap<String, MacroData>,
    /// `claim.png` → base64 of the file. The sidecar's DPI rides along beside it.
    #[serde(default)]
    pub templates: std::collections::BTreeMap<String, String>,
    #[serde(default)]
    pub template_dpi: std::collections::BTreeMap<String, u32>,
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub created: String,
    /// What this package is able to do, worked out when it was built.
    ///
    /// Written down rather than recomputed on import so that the list shown before
    /// running something can be compared against what the steps actually say. They
    /// should agree; a package where they do not is one worth refusing.
    #[serde(default)]
    pub declared: Vec<String>,
}

fn pkg_version() -> u32 {
    1
}

/// Everything the package would need to carry, worked out from the macro.
///
/// Shared by the inspector and the exporter, so the checklist somebody reads is
/// built by the same code that then does the packing. A checklist that came from a
/// second implementation would eventually disagree with it.
pub struct Deps {
    /// Template name → whether the file is on disk.
    pub templates: Vec<(String, bool)>,
    /// `Call` path → whether it resolves.
    pub macros: Vec<(String, bool)>,
}

impl Deps {
    pub fn all_present(&self) -> bool {
        self.templates.iter().all(|(_, ok)| *ok) && self.macros.iter().all(|(_, ok)| *ok)
    }
    pub fn missing(&self) -> usize {
        self.templates.iter().filter(|(_, ok)| !ok).count()
            + self.macros.iter().filter(|(_, ok)| !ok).count()
    }
}

/// Walks a macro and every macro it calls, collecting what they need.
///
/// Recursive through `Call`, capped the same way the interpreter is: a macro that
/// calls itself must not make the exporter loop.
fn collect_deps(data: &MacroData, here: Option<&Path>) -> Deps {
    let mut templates: std::collections::BTreeSet<String> = Default::default();
    let mut macros: std::collections::BTreeSet<String> = Default::default();
    let mut seen: std::collections::BTreeSet<String> = Default::default();

    fn walk(
        data: &MacroData,
        here: Option<&Path>,
        depth: u32,
        templates: &mut std::collections::BTreeSet<String>,
        macros: &mut std::collections::BTreeSet<String>,
        seen: &mut std::collections::BTreeSet<String>,
    ) {
        if depth > MAX_CALL_DEPTH {
            return;
        }
        for st in data.script.iter().filter(|st| st.enabled) {
            for name in health::templates_of(&st.kind) {
                if !name.trim().is_empty() {
                    templates.insert(name.trim().to_string());
                }
            }
            if let StepKind::Call { path, .. } = &st.kind {
                let p = path.trim();
                // A path built out of variables cannot be resolved without running
                // the macro, so it cannot be packed either. The inspector reports it
                // as a dependency it could not follow.
                if p.is_empty() || p.contains('{') || !seen.insert(p.to_string()) {
                    continue;
                }
                macros.insert(p.to_string());
                if let Some(child) = resolve_call_path(p, here).and_then(|f| load_macro(&f).ok()) {
                    walk(&child, here, depth + 1, templates, macros, seen);
                }
            }
        }
    }
    walk(data, here, 0, &mut templates, &mut macros, &mut seen);

    Deps {
        templates: templates
            .into_iter()
            .map(|n| {
                let ok = template_exists(&n);
                (n, ok)
            })
            .collect(),
        macros: macros
            .into_iter()
            .map(|n| {
                let ok = resolve_call_path(&n, here).is_some();
                (n, ok)
            })
            .collect(),
    }
}

/// What is in `templates/`, set against what a macro actually asks for.
///
/// Note what `unused` means, because it is the whole design of this feature: *not
/// named by this macro*. The folder is shared by every macro on the machine, and
/// this program cannot see the ones that are not open. A picture that four other
/// macros depend on will appear in this list, and if the wording ever shortens to
/// "unused" somebody will delete it.
///
/// Which is also why nothing here deletes anything. The list is the feature; the
/// removal is one file at a time, by hand, with the name in front of you.
pub struct Resources {
    /// Named by the macro and present.
    pub used: Vec<String>,
    /// Named by the macro and not there. The same fact `TemplateMissing` reports,
    /// repeated here because a person looking at the folder wants both halves.
    pub missing: Vec<String>,
    /// In the folder, not named by this macro, with what it takes up.
    pub unused: Vec<(String, u64)>,
    /// Files whose pictures are pixel-for-pixel the same, grouped.
    pub duplicates: Vec<Vec<String>>,
}

impl Resources {
    pub fn nothing_to_say(&self) -> bool {
        self.unused.is_empty() && self.duplicates.is_empty() && self.missing.is_empty()
    }

    pub fn unused_bytes(&self) -> u64 {
        self.unused.iter().map(|(_, n)| n).sum()
    }
}

/// A picture's identity, as its size and its pixels.
///
/// The bytes of the file would have been cheaper and would have been wrong: the
/// same picture cropped again, or opened and re-saved in a different editor, is a
/// different file and the same picture - and that is exactly the duplicate somebody
/// accumulates without noticing. Decoding is the only honest way to answer, and it
/// only happens when the button is pressed.
fn picture_key(path: &Path) -> Option<u64> {
    let img = image::open(path).ok()?.to_rgba8();
    let (w, h) = (img.width(), img.height());
    // FNV-1a. Not a security hash and not pretending to be one: the cost of a
    // collision here is two unrelated pictures listed together, which the user sees
    // and dismisses.
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for b in w
        .to_le_bytes()
        .iter()
        .chain(h.to_le_bytes().iter())
        .chain(img.as_raw().iter())
    {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(0x1000_0000_01b3);
    }
    Some(hash)
}

fn audit_resources(data: &MacroData, here: Option<&Path>) -> Resources {
    let deps = collect_deps(data, here);
    let wanted: std::collections::BTreeSet<String> =
        deps.templates.iter().map(|(n, _)| n.to_lowercase()).collect();
    let (mut used, mut missing) = (Vec::new(), Vec::new());
    for (n, ok) in &deps.templates {
        if *ok { used.push(n.clone()) } else { missing.push(n.clone()) }
    }

    let dir = paths::templates_dir();
    let mut unused: Vec<(String, u64)> = Vec::new();
    let mut by_picture: BTreeMap<u64, Vec<String>> = BTreeMap::new();
    for name in template_names() {
        let png = dir.join(format!("{name}.png"));
        let folder = dir.join(&name);
        if !wanted.contains(&name.to_lowercase()) {
            // A folder template has no `<name>.png` to measure, and reporting `0 B`
            // for a folder holding three pictures reads as "an empty file, delete
            // it" - the one impression this list must never give. Add the variants
            // up instead.
            let size = if folder.is_dir() {
                std::fs::read_dir(&folder)
                    .into_iter()
                    .flatten()
                    .flatten()
                    .filter_map(|e| e.metadata().ok().map(|m| m.len()))
                    .sum()
            } else {
                std::fs::metadata(&png).map(|m| m.len()).unwrap_or(0)
            };
            unused.push((name.clone(), size));
        }
        // Only single files. A folder template's variants are supposed to be
        // different pictures of the same thing, and calling two of them duplicates
        // would be calling the feature a fault.
        if !folder.is_dir()
            && let Some(k) = picture_key(&png)
        {
            by_picture.entry(k).or_default().push(name);
        }
    }
    let mut duplicates: Vec<Vec<String>> =
        by_picture.into_values().filter(|g| g.len() > 1).collect();
    duplicates.sort();

    Resources { used, missing, unused, duplicates }
}

/// The file a `Call` path names, looked for the same three places the interpreter
/// looks and in the same order.
fn resolve_call_path(path: &str, here: Option<&Path>) -> Option<std::path::PathBuf> {
    let mut candidate = std::path::PathBuf::from(path.trim());
    if candidate.extension().is_none() {
        candidate.set_extension("json");
    }
    if candidate.is_absolute() {
        return candidate.exists().then_some(candidate);
    }
    let tries = [
        here.map(|d| d.join(&candidate)),
        Some(paths::data_dir().join(&candidate)),
        Some(paths::sub_dir("macros").join(&candidate)),
    ];
    tries.into_iter().flatten().find(|p| p.exists())
}

/// Builds a package from a macro, pulling in everything it names.
fn build_package(data: &MacroData, here: Option<&Path>, name: &str) -> Result<MacroPackage> {
    let deps = collect_deps(data, here);
    let mut templates = std::collections::BTreeMap::new();
    let mut template_dpi = std::collections::BTreeMap::new();
    for (n, present) in &deps.templates {
        if !present {
            continue;
        }
        let png = paths::templates_dir().join(format!("{n}.png"));
        match std::fs::read(&png) {
            Ok(bytes) => {
                templates.insert(format!("{n}.png"), b64::encode(&bytes));
                if let Some(meta) = load_template_meta(&png) {
                    template_dpi.insert(format!("{n}.png"), meta.dpi);
                }
            }
            Err(e) => warn!("packaging: could not read {}: {e}", png.display()),
        }
    }
    let mut macros = std::collections::BTreeMap::new();
    for (n, present) in &deps.macros {
        if !present {
            continue;
        }
        if let Some(child) = resolve_call_path(n, here).and_then(|f| load_macro(&f).ok()) {
            macros.insert(n.clone(), child);
        }
    }
    let (created, _) = runlog::stamp();
    Ok(MacroPackage {
        version: pkg_version(),
        main: data.clone(),
        macros,
        templates,
        template_dpi,
        name: name.to_string(),
        created,
        declared: Vec::new(),
    })
}

fn save_package(path: &Path, pkg: &MacroPackage) -> Result<()> {
    let bytes = gzip(&serde_json::to_vec(pkg)?)?;
    std::fs::write(path, bytes).with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

fn load_package(path: &Path) -> Result<MacroPackage> {
    let bytes = std::fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    // Written gzipped, but a hand-edited one is worth accepting: the whole point of
    // JSON here is that somebody can open it.
    let text = match gunzip(&bytes) {
        Ok(plain) => String::from_utf8(plain)?,
        Err(_) => String::from_utf8(bytes).context("package is neither gzip nor UTF-8")?,
    };
    let mut pkg: MacroPackage = serde_json::from_str(&text).context("unrecognised package")?;
    pkg.main.normalize()?;
    for m in pkg.macros.values_mut() {
        m.normalize()?;
    }
    Ok(pkg)
}

/// Unpacks the pictures and called macros beside the data folder, so the macro can
/// simply be played.
///
/// Existing files are **not** overwritten: a package should not be able to replace a
/// template somebody else's macro is using just because the names collided. What was
/// skipped is returned, so the window can say so rather than leaving it to be noticed
/// three steps into a run.
fn install_package(pkg: &MacroPackage) -> Result<Vec<String>> {
    let mut skipped = Vec::new();
    let tdir = paths::templates_dir();
    std::fs::create_dir_all(&tdir).ok();
    for (name, data) in &pkg.templates {
        let out = tdir.join(name);
        if out.exists() {
            skipped.push(name.clone());
            continue;
        }
        let Some(bytes) = b64::decode(data) else {
            skipped.push(name.clone());
            warn!("package: {name} is not valid base64 - skipped");
            continue;
        };
        std::fs::write(&out, bytes).with_context(|| format!("writing {}", out.display()))?;
        if let Some(dpi) = pkg.template_dpi.get(name) {
            save_template_meta(&out, &TemplateMeta { dpi: *dpi });
        }
    }
    let mdir = paths::sub_dir("macros");
    std::fs::create_dir_all(&mdir).ok();
    for (name, data) in &pkg.macros {
        let mut out = mdir.join(name.trim());
        if out.extension().is_none() {
            out.set_extension("json");
        }
        if out.exists() {
            skipped.push(name.clone());
            continue;
        }
        save_macro(&out, data)?;
    }
    Ok(skipped)
}

// ============================================================================
// Macro health
// ============================================================================

/// What a macro is about to do, and what is wrong with it, worked out without
/// running it.
///
/// The program has always known these things and never said them. A `Click image`
/// naming a picture that is not in `templates/` fails at four in the morning, on the
/// step it fails on, having already done half a night's work; the file it wants was
/// missing before the run started and could have been said so in a tenth of a
/// second.
///
/// Everything here is a pure function over the macro plus a small `Env` describing
/// what is on disk, so the whole thing is unit-testable without a screen, a window
/// or a file. The two checks that already existed - unbalanced blocks and steps
/// after a top-level `Quit` - are folded in rather than duplicated, so the editor
/// has one answer instead of three.
pub mod health {
    use super::{
        Condition, MacroData, Method, OnMiss, RecordingInfo, ScriptStep, SearchArea, StepKind,
        Strings, Target, first_unreachable, resolve_blocks,
    };
    use std::collections::BTreeSet;

    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub enum Severity {
        /// The macro will misbehave. Not "might".
        Error,
        /// The macro will probably work today and is brittle.
        Warning,
    }

    /// One thing worth saying, kept as a code rather than a sentence so the sentence
    /// can be in the user's language.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Rule {
        // errors
        Unbalanced,
        NoTemplateNamed,
        TemplateMissing,
        CallMissing,
        RangePastEnd,
        QueryEmpty,
        Unreachable,
        RecoveryMissing,
        /// A `Call` chain that comes back to a macro already on it. The interpreter
        /// stops this at eight deep; by then it has done whatever the first seven
        /// levels do, seven times.
        RecursiveCall,
        /// The file says a format this build does not know. Whatever was new in it
        /// is already gone from this copy.
        NewerFormat,
        // warnings
        FixedCoordinates,
        NoTargetWindow,
        WaitCarriesOn,
        LoopWithNoWayOut,
        WholeScreenSearch,
        /// Reads text, and no recogniser language has been chosen.
        OcrNoLanguage,
        /// The display is not the one this was recorded on.
        ScaleChanged,
        ScreenChanged,
    }

    impl Rule {
        pub fn severity(self) -> Severity {
            match self {
                Rule::Unbalanced
                | Rule::NoTemplateNamed
                | Rule::TemplateMissing
                | Rule::CallMissing
                | Rule::RangePastEnd
                | Rule::QueryEmpty
                | Rule::RecoveryMissing
                | Rule::RecursiveCall
                | Rule::NewerFormat
                | Rule::Unreachable => Severity::Error,
                _ => Severity::Warning,
            }
        }

        pub fn text(self, s: &Strings) -> &'static str {
            match self {
                Rule::Unbalanced => s.a_unbalanced,
                Rule::NoTemplateNamed => s.a_no_picture,
                Rule::TemplateMissing => s.a_no_template,
                Rule::CallMissing => s.a_no_call,
                Rule::RangePastEnd => s.a_range,
                Rule::QueryEmpty => s.a_empty_query,
                Rule::Unreachable => s.a_unreachable,
                Rule::RecoveryMissing => s.a_no_recovery,
                Rule::RecursiveCall => s.a_recursive,
                Rule::NewerFormat => s.a_newer_format,
                Rule::FixedCoordinates => s.a_abs_click,
                Rule::NoTargetWindow => s.a_no_target,
                Rule::WaitCarriesOn => s.a_wait_continue,
                Rule::LoopWithNoWayOut => s.a_loop_forever,
                Rule::WholeScreenSearch => s.a_wide_search,
                Rule::OcrNoLanguage => s.a_no_ocr_lang,
                Rule::ScaleChanged => s.a_scale_changed,
                Rule::ScreenChanged => s.a_screen_changed,
            }
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct Finding {
        pub rule: Rule,
        /// The step this is about, when it is about one.
        pub step: Option<usize>,
        /// The name, path or number that makes the sentence specific.
        pub detail: String,
    }

    /// What a macro is able to do, in the sense a permission prompt means it.
    ///
    /// Worked out from the steps rather than declared, so it cannot be wrong about a
    /// macro somebody was handed. This is what gets shown before importing one.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct Caps {
        pub mouse: bool,
        pub keyboard: bool,
        pub screen: bool,
        pub ocr: bool,
        pub uia: bool,
        pub clipboard: bool,
        pub files: bool,
        /// Moves, resizes, minimises or closes other people's windows.
        pub windows: bool,
        /// The three that deserve a ⚠ rather than a ✔.
        pub launch: bool,
        pub power: bool,
        pub external: bool,
    }

    impl Caps {
        /// The ones a person should look twice at.
        pub fn risky(&self) -> bool {
            self.launch || self.power || self.external
        }
    }

    /// How a macro aims, counted. The positive half of the report: a list of what is
    /// wrong says nothing about a macro with nothing wrong with it.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct Aiming {
        pub element: u32,
        pub image: u32,
        pub text: u32,
        pub fixed: u32,
        pub retries: u32,
        pub guarded: u32,
    }

    impl Aiming {
        pub fn total(&self) -> u32 {
            self.element + self.image + self.text + self.fixed
        }
    }

    /// What was looked at and found to be in order.
    ///
    /// The other half of the answer, and the half a list of complaints structurally
    /// cannot give: "nothing is wrong" and "nothing was checked" produce the same
    /// empty list, and they are not the same news at all. Counts rather than ticks,
    /// because *42 steps* is the part that tells somebody the checker saw the macro
    /// they think they are running.
    ///
    /// Deliberately not a third `Severity`. These are not findings - giving them a
    /// severity would mean giving them a colour, a weight in the score and a place
    /// in the sorted list, and the report would then contain forty lines saying
    /// nothing happened.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct Checks {
        /// Steps that will run: disabled ones are notes, not plans.
        pub steps: usize,
        /// Distinct pictures named, and how many of them are on disk.
        pub templates: usize,
        pub templates_ok: usize,
        /// Distinct macros called, and how many of them resolve.
        pub calls: usize,
        pub calls_ok: usize,
        pub balanced: bool,
        pub reachable: bool,
        pub no_recursion: bool,
    }

    impl Checks {
        /// Every check that was actually performed, as (passed, how it reads, which).
        ///
        /// Built here rather than in the window so that the report reads the same in
        /// the log, in `--check` and on screen - three renderers that would otherwise
        /// each have their own opinion about how to count a picture.
        ///
        /// A row about nothing is left out. "0 pictures found" is not reassurance,
        /// it is a line to scroll past, and the point of this block is that every
        /// line in it means something.
        pub fn lines(&self) -> Vec<(bool, String, Line)> {
            let counted = |done: usize, named: usize| {
                // `3` when they are all there, `1 / 3` when they are not: a tick
                // beside a total says nothing about how much of the total was found.
                if done == named { done.to_string() } else { format!("{done} / {named}") }
            };
            let mut out = vec![(true, self.steps.to_string(), Line::Steps)];
            if self.templates > 0 {
                out.push((
                    self.templates == self.templates_ok,
                    counted(self.templates_ok, self.templates),
                    Line::Templates,
                ));
            }
            if self.calls > 0 {
                out.push((
                    self.calls == self.calls_ok,
                    counted(self.calls_ok, self.calls),
                    Line::Calls,
                ));
                // Only worth saying where there is a call to be recursive.
                out.push((self.no_recursion, String::new(), Line::NoRecursion));
            }
            out.push((self.reachable && self.balanced, String::new(), Line::Reachable));
            out
        }
    }

    /// Which sentence one passed check is.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Line {
        Steps,
        Templates,
        Calls,
        NoRecursion,
        Reachable,
    }

    impl Line {
        /// Whether the count is worth printing. "0 pictures found" is noise.
        pub fn counted(self) -> bool {
            matches!(self, Line::Steps | Line::Templates | Line::Calls)
        }

        pub fn text(self, s: &Strings) -> &'static str {
            match self {
                Line::Steps => s.ck_steps,
                Line::Templates => s.ck_templates,
                Line::Calls => s.ck_calls,
                Line::NoRecursion => s.ck_no_recursion,
                Line::Reachable => s.ck_reachable,
            }
        }
    }

    #[derive(Clone, Debug, Default)]
    pub struct Report {
        pub findings: Vec<Finding>,
        pub caps: Caps,
        pub aiming: Aiming,
        pub checks: Checks,
        pub score: u32,
    }

    impl Report {
        pub fn errors(&self) -> usize {
            self.findings.iter().filter(|f| f.rule.severity() == Severity::Error).count()
        }
        pub fn warnings(&self) -> usize {
            self.findings.iter().filter(|f| f.rule.severity() == Severity::Warning).count()
        }
        /// Nothing here says the macro will misbehave.
        ///
        /// What the Run button asks before it starts. Warnings deliberately do not
        /// count: a fixed coordinate is a habit worth mentioning and not a reason to
        /// stand between somebody and their own macro.
        pub fn ready(&self) -> bool {
            self.errors() == 0
        }
    }

    /// What the checker needs to know that is not in the macro itself.
    ///
    /// Passed in rather than looked up, so the rules can be tested against a made-up
    /// disk instead of the real one.
    pub struct Env<'a> {
        /// Template names present, without the `.png`.
        pub templates: &'a BTreeSet<String>,
        /// Whether a `Call` path resolves to a file that loads.
        pub call_exists: &'a dyn Fn(&str) -> bool,
        /// The `Call` paths named inside the macro at this path, for finding a cycle.
        ///
        /// A function rather than a loaded graph because following it means reading
        /// files, and the point of this struct is that the rules themselves never
        /// touch a disk. An unreadable or absent macro answers with an empty list -
        /// a file that is not there is reported by `CallMissing` and must not also
        /// be reported as a cycle.
        pub call_targets: &'a dyn Fn(&str) -> Vec<String>,
        /// What the macro being checked is saved as, when it is saved as anything.
        ///
        /// The root of the call graph. Without it, the commonest recursion of all -
        /// a macro whose own `Call` step names itself - is invisible, because the
        /// walk starts at its children.
        pub self_path: Option<&'a str>,
        /// Whether a target window has been configured for this profile.
        pub target_window: bool,
        /// Whether a recogniser language has been chosen for reading screen text.
        ///
        /// Empty means "the Windows display languages", which is right until the
        /// program being automated is in a different language from Windows - and
        /// then no amount of pixel preparation argues the recogniser out of the
        /// wrong alphabet.
        pub ocr_lang: bool,
        /// This machine, now, for comparing against what the recording was made on.
        /// `None` where there is no screen to ask about.
        pub display: Option<RecordingInfo>,
        /// Whether the run ends by shutting the machine down, restarting it or
        /// putting it to sleep.
        ///
        /// Not in the macro: the end-of-run action is a setting, so a macro file on
        /// its own cannot turn a PC off. The manifest still has to say so, because
        /// what the person running it wants to know is what this run can do - and
        /// with that box ticked, this run can do that.
        pub power_action: bool,
    }

    /// The target a step aims at, if it aims at one.
    fn target_of(step: &StepKind) -> Option<&Target> {
        match step {
            StepKind::ClickTarget { target, .. }
            | StepKind::WaitTarget { target, .. }
            | StepKind::ReadTarget { target, .. } => Some(target),
            _ => None,
        }
    }

    /// Every template a macro looks for, wherever it is named.
    ///
    /// Public because the packager needs exactly this list and a second
    /// implementation of it would eventually disagree about some corner - an anchor
    /// inside a condition, say - and quietly ship a package missing a picture.
    ///
    /// It very nearly did: the first version of this returned only the *target*
    /// pictures and left out the anchors, which `check` collects separately. A
    /// package built from it would have carried the button and not the heading the
    /// button is found relative to, and would have failed on the recipient's machine
    /// and nowhere else. Both lists, from one function, is the point.
    pub fn templates_of(step: &StepKind) -> Vec<&str> {
        templates_used(step).into_iter().chain(anchor_used(step)).collect()
    }

    fn templates_used(step: &StepKind) -> Vec<&str> {
        if let Some(t) = target_of(step) {
            // Only the ways that are actually filled in: a cascade carries every way
            // that could be built when the macro was recorded, and complaining about
            // an empty one would be complaining about the recording having been made
            // in a game.
            return t
                .methods
                .iter()
                .filter_map(|m| match m {
                    Method::Image { template, .. } if !template.trim().is_empty() => {
                        Some(template.as_str())
                    }
                    _ => None,
                })
                .collect();
        }
        match step {
            StepKind::ClickImage { template, .. } | StepKind::FindImage { template, .. } => {
                vec![template.as_str()]
            }
            StepKind::WaitFor { cond: Condition::Image { template, .. }, .. }
            | StepKind::If { cond: Condition::Image { template, .. } }
            | StepKind::While { cond: Condition::Image { template, .. } } => {
                vec![template.as_str()]
            }
            _ => vec![],
        }
    }

    /// An anchor names a second picture, and a missing one fails exactly as loudly.
    fn anchor_used(step: &StepKind) -> Vec<&str> {
        fn name_of(area: &SearchArea) -> Option<&str> {
            match area {
                SearchArea::NearAnchor { anchor, .. } => Some(anchor.as_str()),
                _ => None,
            }
        }
        // A target carries a whole cascade, and every image rung in it may be
        // anchored to a different picture. Missing these was a gap the packaging test found: `templates_used` learned about targets and this did
        // not, so an anchor inside a cascade was invisible to the checker and to the
        // packer alike.
        if let Some(t) = target_of(step) {
            return t
                .methods
                .iter()
                .filter_map(|m| match m {
                    Method::Image { area, .. } => name_of(area),
                    _ => None,
                })
                .collect();
        }
        let area = match step {
            StepKind::ClickImage { area, .. } | StepKind::FindImage { area, .. } => area,
            StepKind::WaitFor { cond: Condition::Image { area, .. }, .. }
            | StepKind::If { cond: Condition::Image { area, .. } }
            | StepKind::While { cond: Condition::Image { area, .. } } => area,
            _ => return Vec::new(),
        };
        name_of(area).into_iter().collect()
    }

    fn caps_of(step: &StepKind, caps: &mut Caps) {
        match step {
            StepKind::PlayEvents { .. } => {
                // A recording is whatever was recorded. Claiming only one of the two
                // would be a manifest that lies by omission.
                caps.mouse = true;
                caps.keyboard = true;
            }
            StepKind::Click { .. } => caps.mouse = true,
            StepKind::Key { .. } => caps.keyboard = true,
            StepKind::ClickImage { .. } => {
                caps.mouse = true;
                caps.screen = true;
            }
            StepKind::FindImage { .. } => caps.screen = true,
            StepKind::ReadText { .. } | StepKind::ReadNumber { .. } => {
                caps.screen = true;
                caps.ocr = true;
            }
            StepKind::FindElement { .. } => caps.uia = true,
            StepKind::ClickElement { .. } => {
                caps.uia = true;
                caps.mouse = true;
            }
            StepKind::GetText { source, .. } => match source {
                super::TextSource::Clipboard => caps.clipboard = true,
                super::TextSource::File(_) => caps.files = true,
                _ => {}
            },
            StepKind::PutText { sink, .. } => match sink {
                super::TextSink::Clipboard => caps.clipboard = true,
                super::TextSink::File { .. } => caps.files = true,
            },
            StepKind::Run { .. } => caps.launch = true,
            StepKind::Call { .. } => caps.external = true,
            StepKind::Clipboard { .. } => {
                caps.clipboard = true;
                // Copy and paste are keystrokes into whatever is in front.
                caps.keyboard = true;
            }
            StepKind::Screenshot { path, .. } => {
                caps.screen = true;
                if !path.trim().is_empty() {
                    caps.files = true;
                }
            }
            StepKind::Window { .. } => caps.windows = true,
            _ => {}
        }
        // A target's capabilities are the union of its ways of being found, because
        // any of them may be the one that runs.
        if let Some(t) = target_of(step) {
            if matches!(step, StepKind::ClickTarget { .. }) {
                caps.mouse = true;
            }
            if matches!(step, StepKind::ReadTarget { .. }) {
                caps.ocr = true;
                caps.screen = true;
            }
            for m in &t.methods {
                match m {
                    Method::Element { .. } => caps.uia = true,
                    Method::Image { .. } => caps.screen = true,
                    Method::Text { .. } => {
                        caps.screen = true;
                        caps.ocr = true;
                    }
                    _ => {}
                }
            }
        }
        // Conditions look at the screen too, and a macro that only ever *waits* for a
        // picture still takes screenshots to do it.
        let cond = match step {
            StepKind::WaitFor { cond, .. } | StepKind::If { cond } | StepKind::While { cond } => {
                Some(cond)
            }
            _ => None,
        };
        match cond {
            Some(Condition::Image { .. }) | Some(Condition::Pixel { .. }) => caps.screen = true,
            Some(Condition::Text { .. }) => {
                caps.screen = true;
                caps.ocr = true;
            }
            Some(Condition::Element { .. }) => caps.uia = true,
            _ => {}
        }
    }

    /// Does this loop have any way of ending other than the run being stopped?
    ///
    /// `Break`, a miss policy that leaves the loop or stops the run, a `Quit`, or a
    /// condition that is anything other than "always". Nested loops swallow their own
    /// `Break`, which is the part worth getting right: a `Break` two levels down does
    /// not end this one.
    fn loop_has_exit(steps: &[ScriptStep], start: usize) -> bool {
        if let StepKind::While { cond } = &steps[start].kind
            && !matches!(cond, Condition::Always) {
                return true;
            }
        let mut depth = 0usize;
        for st in steps.iter().skip(start + 1) {
            match &st.kind {
                StepKind::While { .. } => depth += 1,
                StepKind::EndWhile => {
                    if depth == 0 {
                        return false;
                    }
                    depth -= 1;
                }
                StepKind::Break if depth == 0 && st.enabled => return true,
                StepKind::Exit if st.enabled => return true,
                _ if depth == 0
                    && st.enabled
                    && matches!(st.kind.miss(), OnMiss::Break | OnMiss::Stop) =>
                {
                    return true;
                }
                _ => {}
            }
        }
        // An unbalanced script is already an error; do not also call it endless.
        true
    }

    /// One `Call` path, in the form two spellings of the same file share.
    ///
    /// `child`, `child.json` and `Child.JSON` name one macro, and a cycle spelled
    /// with two of them is still a cycle. The extension is dropped for the same
    /// reason the interpreter adds one: a bare name is the normal way to write these.
    fn call_key(p: &str) -> String {
        let t = p.trim().to_lowercase().replace('\\', "/");
        let t = t.strip_suffix(".json").unwrap_or(&t);
        t.strip_suffix(".mrz").unwrap_or(t).to_string()
    }

    /// The `Call` paths one macro names, ignoring the ones nothing can resolve.
    pub fn calls_of(data: &MacroData) -> Vec<String> {
        data.script
            .iter()
            .filter(|st| st.enabled)
            .filter_map(|st| match &st.kind {
                StepKind::Call { path, .. } => {
                    let p = path.trim();
                    // A path built out of variables is not knowable until the macro
                    // runs, so it can neither be resolved nor be proved to be a cycle.
                    (!p.is_empty() && !p.contains('{')).then(|| p.to_string())
                }
                _ => None,
            })
            .collect()
    }

    /// The first `Call` chain that comes back to a macro already on it.
    ///
    /// Returns the path that closes the loop, which is the one worth naming: it is
    /// the step somebody has to look at. The interpreter survives this - eight deep
    /// and it gives up - but surviving it means having done the first seven levels'
    /// worth of clicking first, which is not what anybody meant.
    ///
    /// The root's own calls come from the macro in hand rather than from its file:
    /// it may never have been saved, and if it has been it may have been edited since.
    /// Returns the `Call` in *this* macro that leads into the cycle, and the path
    /// that closes it. Both, because they are usually not the same step and often
    /// not even in the same file: with `a → b → a` the step somebody has to look at
    /// is the one in `a`, and the name that explains why is `a`.
    fn call_cycle(data: &MacroData, env: &Env) -> Option<(String, String)> {
        fn walk(path: &str, env: &Env, chain: &mut Vec<String>, depth: u32) -> Option<String> {
            // Past any honest depth. A macro nested thirty-two deep without a cycle
            // is not something to hold the Run button for.
            if depth > 32 {
                return None;
            }
            for next in (env.call_targets)(path) {
                let key = call_key(&next);
                if chain.contains(&key) {
                    return Some(next);
                }
                chain.push(key);
                let found = walk(&next, env, chain, depth + 1);
                chain.pop();
                if found.is_some() {
                    return found;
                }
            }
            None
        }

        let mut chain: Vec<String> = env.self_path.map(call_key).into_iter().collect();
        for next in calls_of(data) {
            let key = call_key(&next);
            if chain.contains(&key) {
                return Some((next.clone(), next));
            }
            chain.push(key);
            let found = walk(&next, env, &mut chain, 1);
            chain.pop();
            if let Some(closes) = found {
                return Some((next, closes));
            }
        }
        None
    }

    /// The whole check.
    pub fn check(data: &MacroData, env: &Env) -> Report {
        let mut out = Report::default();
        let steps = &data.script;
        let events = data.events.len();
        out.checks.balanced = true;
        out.checks.reachable = true;
        out.checks.no_recursion = true;

        // Before anything about what the macro says: whether this build is reading
        // all of it. A file from a later version has already lost whatever was new
        // in it by the time it gets here, and every other finding below is about the
        // half that survived.
        if data.from_future > 0 {
            out.findings.push(Finding {
                rule: Rule::NewerFormat,
                step: None,
                detail: format!("{} > {}", data.from_future, super::format_version()),
            });
        }

        if let Err(where_) = resolve_blocks(steps) {
            out.checks.balanced = false;
            out.findings.push(Finding {
                rule: Rule::Unbalanced,
                step: None,
                detail: where_,
            });
        }
        if let Some(from) = first_unreachable(steps) {
            out.checks.reachable = false;
            out.findings.push(Finding {
                rule: Rule::Unreachable,
                step: Some(from),
                detail: (steps.len() - from).to_string(),
            });
        }
        if let Some((entry, closes)) = call_cycle(data, env) {
            out.checks.no_recursion = false;
            out.findings.push(Finding {
                rule: Rule::RecursiveCall,
                // The step in this macro that starts the chain - which is the one
                // the reader can actually click on and change.
                step: steps.iter().position(|st| {
                    st.enabled
                        && matches!(&st.kind, StepKind::Call { path, .. }
                            if call_key(path) == call_key(&entry))
                }),
                // The name that closes the loop, which is what makes it a loop.
                detail: if call_key(&entry) == call_key(&closes) {
                    closes
                } else {
                    format!("{entry} \u{2192} \u{2026} \u{2192} {closes}")
                },
            });
        }

        let mut wants_window = false;
        let mut pictures: BTreeSet<String> = BTreeSet::new();
        let mut called: BTreeSet<String> = BTreeSet::new();

        for (i, st) in steps.iter().enumerate() {
            // A disabled step is a note to self, not a plan. Checking it would fill
            // the report with complaints about steps that are not going to run.
            if !st.enabled {
                continue;
            }
            out.checks.steps += 1;
            let k = &st.kind;
            caps_of(k, &mut out.caps);

            for name in templates_of(k) {
                let trimmed = name.trim();
                if trimmed.is_empty() {
                    out.findings.push(Finding {
                        rule: Rule::NoTemplateNamed,
                        step: Some(i),
                        detail: String::new(),
                    });
                } else if !env.templates.contains(trimmed) {
                    pictures.insert(trimmed.to_string());
                    out.findings.push(Finding {
                        rule: Rule::TemplateMissing,
                        step: Some(i),
                        detail: trimmed.to_string(),
                    });
                } else {
                    // Counted once however many steps name it: three steps looking
                    // for the same button need one file, and "3 pictures found" for
                    // one picture is a count nobody can check against the folder.
                    if pictures.insert(trimmed.to_string()) {
                        out.checks.templates_ok += 1;
                    }
                }
            }

            match k {
                StepKind::PlayEvents { from, to, .. } => {
                    // The trap the documentation warns about: delete events in the
                    // editor and this range still says what it said.
                    if *to >= events || *from > *to {
                        out.findings.push(Finding {
                            rule: Rule::RangePastEnd,
                            step: Some(i),
                            detail: format!("{from}…{to} / {events}"),
                        });
                    }
                }
                StepKind::Call { path, .. } => {
                    let p = path.trim();
                    // A path built out of variables cannot be resolved without running
                    // the macro, and guessing would produce a false alarm every time.
                    if !p.is_empty() && !p.contains('{') {
                        let first = called.insert(call_key(p));
                        if !(env.call_exists)(p) {
                            out.findings.push(Finding {
                                rule: Rule::CallMissing,
                                step: Some(i),
                                detail: p.to_string(),
                            });
                        } else if first {
                            out.checks.calls_ok += 1;
                        }
                    }
                }
                StepKind::FindElement { query, .. } | StepKind::ClickElement { query, .. } => {
                    if query.is_empty() {
                        out.findings.push(Finding {
                            rule: Rule::QueryEmpty,
                            step: Some(i),
                            detail: String::new(),
                        });
                    }
                }
                StepKind::Click { x, y, .. } => {
                    out.aiming.fixed += 1;
                    wants_window = true;
                    out.findings.push(Finding {
                        rule: Rule::FixedCoordinates,
                        step: Some(i),
                        detail: format!("{x}, {y}"),
                    });
                }
                StepKind::WaitFor { miss, timeout_ms, .. } => {
                    if miss.clone() == OnMiss::Continue {
                        out.findings.push(Finding {
                            rule: Rule::WaitCarriesOn,
                            step: Some(i),
                            detail: format!("{timeout_ms} ms"),
                        });
                    }
                }
                StepKind::While { .. } => {
                    if !loop_has_exit(steps, i) {
                        out.findings.push(Finding {
                            rule: Rule::LoopWithNoWayOut,
                            step: Some(i),
                            detail: String::new(),
                        });
                    }
                }
                StepKind::WaitTarget { miss, timeout_ms, .. }
                    if *miss == OnMiss::Continue => {
                        out.findings.push(Finding {
                            rule: Rule::WaitCarriesOn,
                            step: Some(i),
                            detail: format!("{timeout_ms} ms"),
                        });
                    }
                _ => {}
            }

            // A recovery policy that names a block nobody wrote is a step with no
            // way of failing safely - it looks handled and is not.
            if let OnMiss::Recover { name } = k.miss()
                && super::recovery_target(steps, &name).is_none() {
                    out.findings.push(Finding {
                        rule: Rule::RecoveryMissing,
                        step: Some(i),
                        detail: name,
                    });
                }

            // A target is judged by the best way it has of being found. One that can
            // only fall back to a coordinate is a coordinate with extra steps, and
            // should be told so; one that names nothing at all cannot work.
            if let Some(t) = target_of(k) {
                let filled: Vec<&Method> =
                    t.methods.iter().filter(|m| m.is_filled()).collect();
                match filled.iter().map(|m| m.rank()).max() {
                    None => out.findings.push(Finding {
                        rule: Rule::QueryEmpty,
                        step: Some(i),
                        detail: String::new(),
                    }),
                    Some(0) => {
                        wants_window = true;
                        out.findings.push(Finding {
                            rule: Rule::FixedCoordinates,
                            step: Some(i),
                            detail: t.label.clone(),
                        });
                    }
                    _ => {}
                }
            }

            // How this step aims, for the positive half of the report. A target is
            // counted by the best way it has, because that is the one that will
            // normally be the one that works.
            match target_of(k).and_then(|t| {
                t.methods.iter().filter(|m| m.is_filled()).map(|m| m.rank()).max()
            }) {
                Some(4) => out.aiming.element += 1,
                Some(3) => out.aiming.image += 1,
                Some(2) => out.aiming.text += 1,
                Some(_) => out.aiming.fixed += 1,
                None => match k {
                    StepKind::ClickElement { .. } | StepKind::FindElement { .. } => {
                        out.aiming.element += 1
                    }
                    StepKind::ClickImage { .. } | StepKind::FindImage { .. } => {
                        out.aiming.image += 1
                    }
                    StepKind::ReadText { .. } | StepKind::ReadNumber { .. } => {
                        out.aiming.text += 1
                    }
                    _ => {}
                },
            }
            match k.miss() {
                OnMiss::Retry { .. } => {
                    out.aiming.retries += 1;
                    out.aiming.guarded += 1;
                }
                // A recovery block is the strongest guard there is: it does not
                // merely notice the miss, it does something about it.
                OnMiss::Recover { .. } => {
                    out.aiming.retries += 1;
                    out.aiming.guarded += 1;
                }
                OnMiss::Stop | OnMiss::Break => out.aiming.guarded += 1,
                OnMiss::Continue => {}
            }

            // A picture hunted across every monitor at the default confidence is the
            // slowest and least certain way to ask, and it is what a step does when
            // nobody told it otherwise.
            if let StepKind::ClickImage { threshold, area, .. }
            | StepKind::FindImage { threshold, area, .. } = k
            {
                wants_window = true;
                if matches!(area, SearchArea::FullScreen) && (*threshold - 0.85).abs() < 1e-9 {
                    out.findings.push(Finding {
                        rule: Rule::WholeScreenSearch,
                        step: Some(i),
                        detail: format!("{threshold:.2}"),
                    });
                }
            }
        }

        // A flat recording aims by coordinate for its whole length, and it is the
        // case the target window was invented for.
        if steps.is_empty() && events > 0 {
            wants_window = true;
            out.caps.mouse = true;
            out.caps.keyboard = true;
            out.aiming.fixed += 1;
        }
        out.caps.power = env.power_action;
        if wants_window && !env.target_window && data.anchor.is_none() {
            out.findings.push(Finding {
                rule: Rule::NoTargetWindow,
                step: None,
                detail: String::new(),
            });
        }

        // Once for the macro, not once per step. A script with nine `Read number`
        // steps has one thing wrong with it, and nine identical lines would bury the
        // eight other findings under it.
        if out.caps.ocr && !env.ocr_lang {
            out.findings.push(Finding {
                rule: Rule::OcrNoLanguage,
                step: None,
                detail: String::new(),
            });
        }

        // What the recording was made on against what is here now.
        //
        // Only where something positional was actually recorded: a macro that finds
        // everything by element or by picture is indifferent to the scale - pictures
        // carry the scale they were cut at and are matched against it - and telling
        // its author about a resolution change would be telling them about weather.
        if let (Some(then), Some(now)) = (data.recorded.as_ref(), env.display.as_ref())
            && !then.is_empty()
            && (out.aiming.fixed > 0 || events > 0)
        {
            if then.dpi > 0 && now.dpi > 0 && then.dpi != now.dpi {
                out.findings.push(Finding {
                    rule: Rule::ScaleChanged,
                    step: None,
                    detail: format!("{} % → {} %", then.scale_pct(), now.scale_pct()),
                });
            }
            if then.screen_w > 0
                && now.screen_w > 0
                && (then.screen_w != now.screen_w || then.screen_h != now.screen_h)
            {
                out.findings.push(Finding {
                    rule: Rule::ScreenChanged,
                    step: None,
                    detail: format!(
                        "{}×{} → {}×{}",
                        then.screen_w, then.screen_h, now.screen_w, now.screen_h
                    ),
                });
            }
        }

        out.checks.templates = pictures.len();
        out.checks.calls = called.len();
        out.score = score(&out);
        out
    }

    /// One number, and it has to be explainable or it is decoration.
    ///
    /// Start at a hundred. Every error costs twenty, because an error means the macro
    /// does not work. Every warning costs five, and the same warning repeated costs
    /// less each time - twelve fixed coordinates is one habit, not twelve problems,
    /// and a score that collapses to zero over it stops being read.
    fn score(r: &Report) -> u32 {
        let mut penalty = 0i32;
        penalty += r.errors() as i32 * 20;

        let mut seen: Vec<(Rule, u32)> = Vec::new();
        for f in r.findings.iter().filter(|f| f.rule.severity() == Severity::Warning) {
            let n = match seen.iter_mut().find(|(rule, _)| *rule == f.rule) {
                Some((_, n)) => {
                    *n += 1;
                    *n
                }
                None => {
                    seen.push((f.rule, 1));
                    1
                }
            };
            penalty += match n {
                1 => 5,
                2..=4 => 3,
                _ => 1,
            };
        }
        (100 - penalty).clamp(0, 100) as u32
    }
}

/// Looks a macro over without running it, against this machine and this profile.
///
/// One function, because there are now three places that ask - the panel, the Run
/// button and `--check` - and three implementations of "what is on disk" would
/// eventually disagree about a corner. The one that mattered in 1.7.0 was `Call`
/// resolution: the checker had its own copy of the three-places rule, and the
/// headless path had a fourth opinion.
///
/// Everything the pure checker cannot know is gathered here and handed in, which is
/// what keeps `health::check` testable without a disk or a screen.
fn check_macro(data: &MacroData, settings: CheckEnv, current: Option<&Path>) -> health::Report {
    let templates: std::collections::BTreeSet<String> = template_names().into_iter().collect();
    let here = current.and_then(|p| p.parent().map(|d| d.to_path_buf()));
    let call_exists = |path: &str| resolve_call_path(path, here.as_deref()).is_some();
    // Following a call means reading the file. One that will not load answers with
    // an empty list rather than an error: it is already reported as a missing call,
    // and saying the same thing twice in two vocabularies helps nobody.
    let call_targets = |path: &str| {
        resolve_call_path(path, here.as_deref())
            .and_then(|f| load_macro(&f).ok())
            .map(|d| health::calls_of(&d))
            .unwrap_or_default()
    };
    let self_path = current.map(|p| p.to_string_lossy().into_owned());
    health::check(
        data,
        &health::Env {
            templates: &templates,
            call_exists: &call_exists,
            call_targets: &call_targets,
            self_path: self_path.as_deref(),
            target_window: settings.target_window,
            ocr_lang: settings.ocr_lang,
            display: Some(RecordingInfo::here()),
            power_action: settings.power_action,
        },
    )
}

/// The three settings the checker needs that are not in the macro.
///
/// A struct rather than a `&AppConfig` because the same three facts have to be
/// readable from the running state as well: the Run button is not the only way a
/// macro starts - a hotkey and the scheduler start one too, and neither of those has
/// the config in its hand. Two ways of building it and one checker beats a second
/// checker that reads the state and eventually disagrees with the first.
#[derive(Clone, Copy)]
struct CheckEnv {
    target_window: bool,
    ocr_lang: bool,
    power_action: bool,
}

impl CheckEnv {
    fn from_config(cfg: &AppConfig) -> Self {
        Self {
            target_window: !cfg.target_title.trim().is_empty(),
            ocr_lang: !cfg.ocr_lang.trim().is_empty(),
            power_action: cfg.time_limit_enabled
                && EndAction::from_index(cfg.action_on_completion) != EndAction::Stop,
        }
    }

    fn from_state(state: &AppState) -> Self {
        Self {
            target_window: !state.target_title.lock().trim().is_empty(),
            ocr_lang: ocr::language_chosen(),
            power_action: state.time_limit_enabled.load(Ordering::Relaxed)
                && EndAction::from_index(
                    state.action_on_completion.load(Ordering::Relaxed) as usize,
                ) != EndAction::Stop,
        }
    }
}

/// The report as lines of text, for the log and for `--check`.
///
/// The same sentences the panel shows, in English: a scheduled run writes to a file
/// somebody reads later, and a report in a language chosen for the window is a
/// report in the wrong language for the log.
fn report_lines(rep: &health::Report, s: &Strings) -> Vec<String> {
    let mut out = Vec::new();
    for (ok, n, line) in rep.checks.lines() {
        let mark = if ok { '✔' } else { '✖' };
        let text = line.text(s);
        out.push(if line.counted() {
            format!("{mark} {}", text.replace("{}", &n))
        } else {
            format!("{mark} {text}")
        });
    }
    for f in &rep.findings {
        let mark = match f.rule.severity() {
            health::Severity::Error => '✖',
            health::Severity::Warning => '⚠',
        };
        let where_ = f.step.map(|i| format!("#{i} ")).unwrap_or_default();
        let detail = if f.detail.is_empty() {
            String::new()
        } else {
            format!(": {}", f.detail)
        };
        out.push(format!("{mark} {where_}{}{detail}", f.rule.text(s)));
    }
    out
}

// ============================================================================
// Templates
// ============================================================================

/// Ready-made runs of steps for the things people build over and over.
///
/// The best power-per-complexity trade in the whole plan, and the reason is what
/// they are *not*: no new step kinds, no new engine paths, no new grammar. A
/// template is a `Vec<ScriptStep>` built out of steps that already existed, dropped
/// into the list, and edited afterwards like anything else.
///
/// It is also where the two composite actions live that would otherwise have been step kinds. `Wait until an app is
/// ready` is three existing conditions in a row - the process exists, its window
/// appears, the window settles - and making it a step kind would have bought a menu
/// entry at the price of a thirty-fourth thing to learn.
pub mod templates {
    use super::*;

    /// One recipe.
    pub struct Recipe {
        pub name: fn(&Strings) -> &'static str,
        pub build: fn() -> Vec<ScriptStep>,
    }

    fn step(kind: StepKind) -> ScriptStep {
        ScriptStep::new(kind)
    }

    /// A target with nothing filled in but the label, ready for the user to point at
    /// something. Deliberately not left blank: a step that says `Click "the button"`
    /// tells the reader what to replace, and an empty one does not.
    fn placeholder(label: &str) -> Target {
        Target { label: label.into(), methods: vec![Method::from_index(1)] }
    }

    fn repeat_n() -> Vec<ScriptStep> {
        vec![
            step(StepKind::SetVar { name: "count".into(), op: VarOp::Set, value: Value::Num(0.0) }),
            step(StepKind::While {
                cond: Condition::Var {
                    name: "count".into(),
                    cmp: Cmp::Lt,
                    value: Value::Num(10.0),
                },
            }),
            step(StepKind::Wait { ms: 500 }),
            step(StepKind::SetVar { name: "count".into(), op: VarOp::Add, value: Value::Num(1.0) }),
            step(StepKind::EndWhile),
        ]
    }

    fn wait_then_click() -> Vec<ScriptStep> {
        vec![
            step(StepKind::WaitTarget {
                target: placeholder("the button"),
                appear: true,
                reliability: Reliability::Maximum,
                timeout_ms: 15_000,
                adaptive: false,
                miss: OnMiss::Stop,
            }),
            step(StepKind::ClickTarget {
                target: placeholder("the button"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 2000,
                miss: OnMiss::Stop,
            }),
        ]
    }

    fn click_until() -> Vec<ScriptStep> {
        vec![
            step(StepKind::While { cond: Condition::Always }),
            step(StepKind::ClickTarget {
                target: placeholder("the button"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 2000,
                // Inside a poll, walking on is right: the button not being there is
                // the normal case on most turns of this loop.
                miss: OnMiss::Continue,
            }),
            step(StepKind::WaitTarget {
                target: placeholder("what you are waiting for"),
                appear: true,
                reliability: Reliability::Maximum,
                timeout_ms: 1000,
                adaptive: false,
                // Found it, so leave the loop. This is the exit.
                miss: OnMiss::Continue,
            }),
            step(StepKind::If { cond: Condition::Var {
                name: "target.found".into(),
                cmp: Cmp::Ge,
                value: Value::Num(1.0),
            } }),
            step(StepKind::Break),
            step(StepKind::EndIf),
            step(StepKind::EndWhile),
        ]
    }

    fn handle_popup() -> Vec<ScriptStep> {
        vec![
            step(StepKind::Recovery { name: "popup".into() }),
            step(StepKind::ClickTarget {
                target: placeholder("OK"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 2000,
                miss: OnMiss::Continue,
            }),
            step(StepKind::Wait { ms: 500 }),
            step(StepKind::EndRecovery),
        ]
    }

    fn login() -> Vec<ScriptStep> {
        vec![
            step(StepKind::Group { name: "Log in".into() }),
            step(StepKind::ClickTarget {
                target: placeholder("the username box"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 5000,
                miss: OnMiss::Stop,
            }),
            step(StepKind::PutText { sink: TextSink::Clipboard, text: "{user}".into() }),
            step(StepKind::Clipboard {
                action: ClipAction::Paste,
                text: String::new(),
                var: String::new(),
                timeout_ms: 0,
                miss: OnMiss::Stop,
            }),
            step(StepKind::ClickTarget {
                target: placeholder("the password box"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 5000,
                miss: OnMiss::Stop,
            }),
            step(StepKind::PutText { sink: TextSink::Clipboard, text: "{password}".into() }),
            step(StepKind::Clipboard {
                action: ClipAction::Paste,
                text: String::new(),
                var: String::new(),
                timeout_ms: 0,
                miss: OnMiss::Stop,
            }),
            step(StepKind::ClickTarget {
                target: placeholder("Log in"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 5000,
                miss: OnMiss::Stop,
            }),
            step(StepKind::WaitTarget {
                target: placeholder("something only the logged-in page has"),
                appear: true,
                reliability: Reliability::Maximum,
                timeout_ms: 30_000,
                adaptive: true,
                miss: OnMiss::Stop,
            }),
            step(StepKind::EndGroup),
        ]
    }

    fn retry_recover() -> Vec<ScriptStep> {
        vec![
            step(StepKind::ClickTarget {
                target: placeholder("the thing that sometimes fails"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 5000,
                miss: OnMiss::Recover { name: "fix it".into() },
            }),
            step(StepKind::Recovery { name: "fix it".into() }),
            step(StepKind::ClickTarget {
                target: placeholder("whatever is in the way"),
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 2000,
                miss: OnMiss::Continue,
            }),
            step(StepKind::Wait { ms: 500 }),
            step(StepKind::EndRecovery),
        ]
    }

    fn farm_until() -> Vec<ScriptStep> {
        vec![
            step(StepKind::While {
                cond: Condition::Var {
                    name: "gems".into(),
                    cmp: Cmp::Lt,
                    value: Value::Num(500.0),
                },
            }),
            step(StepKind::PlayEvents { from: 0, to: 0, between: None }),
            step(StepKind::ReadTarget {
                target: placeholder("the counter"),
                var: "gems".into(),
                reliability: Reliability::Maximum,
                prep: ocr::Prep::default(),
                miss: OnMiss::Continue,
            }),
            step(StepKind::Log { text: "gems: {gems}".into() }),
            step(StepKind::EndWhile),
        ]
    }

    fn until_time() -> Vec<ScriptStep> {
        vec![
            step(StepKind::While {
                cond: Condition::Var {
                    name: "time".into(),
                    cmp: Cmp::Lt,
                    value: Value::Str("06:00".into()),
                },
            }),
            step(StepKind::PlayEvents { from: 0, to: 0, between: None }),
            step(StepKind::EndWhile),
        ]
    }

    fn until_window_closes() -> Vec<ScriptStep> {
        vec![
            step(StepKind::While { cond: Condition::Window { title: "Game".into() } }),
            step(StepKind::PlayEvents { from: 0, to: 0, between: None }),
            step(StepKind::EndWhile),
        ]
    }

    fn stop_on_text() -> Vec<ScriptStep> {
        vec![
            step(StepKind::While { cond: Condition::Always }),
            step(StepKind::PlayEvents { from: 0, to: 0, between: None }),
            step(StepKind::WaitTarget {
                target: placeholder("the words that mean stop"),
                appear: true,
                reliability: Reliability::Maximum,
                timeout_ms: 500,
                adaptive: false,
                // Leaves the loop the moment the words turn up, and carries on round
                // when they do not. The whole recipe is this one field.
                miss: OnMiss::Continue,
            }),
            step(StepKind::EndWhile),
        ]
    }

    /// `Wait until app ready`, as three conditions rather than a step kind.
    fn app_ready() -> Vec<ScriptStep> {
        vec![
            step(StepKind::Group { name: "Wait until ready".into() }),
            step(StepKind::WaitFor {
                cond: Condition::Process { name: "game.exe".into() },
                appear: true,
                timeout_ms: 60_000,
                adaptive: false,
                miss: OnMiss::Stop,
            }),
            step(StepKind::Window {
                window: WindowRef::from_title("Game"),
                action: WindowAction::WaitAppears,
                x: 0,
                y: 0,
                timeout_ms: 60_000,
                miss: OnMiss::Stop,
            }),
            // The settle: an application that has drawn its window is not always an
            // application that has finished loading into it.
            step(StepKind::WaitFor {
                cond: Condition::Image {
                    template: String::new(),
                    threshold: 0.85,
                    area: SearchArea::ActiveWindow,
                    lose_at: 0.0,
                    stable_of: 3,
                    stable_in: 4,
                    edge: false,
                },
                appear: true,
                timeout_ms: 30_000,
                adaptive: true,
                miss: OnMiss::Continue,
            }),
            step(StepKind::EndGroup),
        ]
    }

    /// `Open and focus application`.
    fn open_and_focus() -> Vec<ScriptStep> {
        vec![
            step(StepKind::Run { path: "notepad".into(), args: String::new() }),
            step(StepKind::Window {
                window: WindowRef::from_title("Notepad"),
                action: WindowAction::WaitAppears,
                x: 0,
                y: 0,
                timeout_ms: 30_000,
                miss: OnMiss::Stop,
            }),
            step(StepKind::Window {
                window: WindowRef::from_title("Notepad"),
                action: WindowAction::Activate,
                x: 0,
                y: 0,
                timeout_ms: 0,
                miss: OnMiss::Stop,
            }),
        ]
    }

    /// Every recipe, in the order the menu shows them.
    pub const ALL: [Recipe; 12] = [
        Recipe { name: |s| s.t_wait_click, build: wait_then_click },
        Recipe { name: |s| s.t_repeat_n, build: repeat_n },
        Recipe { name: |s| s.t_click_until, build: click_until },
        Recipe { name: |s| s.t_popup, build: handle_popup },
        Recipe { name: |s| s.t_retry, build: retry_recover },
        Recipe { name: |s| s.t_login, build: login },
        Recipe { name: |s| s.t_app_ready, build: app_ready },
        Recipe { name: |s| s.t_open_focus, build: open_and_focus },
        Recipe { name: |s| s.t_farm, build: farm_until },
        Recipe { name: |s| s.t_until_time, build: until_time },
        Recipe { name: |s| s.t_until_closed, build: until_window_closes },
        Recipe { name: |s| s.t_stop_text, build: stop_on_text },
    ];
}

// ============================================================================
// Command palette
// ============================================================================

/// Finding a command by typing part of its name.
///
/// Built now rather than later, and that is the whole argument for it. The step
/// menu is already twenty-four entries long; the roadmap adds about a dozen more
/// over the next four phases, and a thirty-six entry drop-down is a worse interface
/// than a thirty-six entry list nobody has to scroll.
///
/// The matcher is subsequence-based, which is what makes `clik` find `Click image`.
/// Anything cleverer would need a scoring model and a corpus, and this is a list of
/// forty short strings.
pub mod palette {
    /// Does `needle` appear in `hay` in order, ignoring case and gaps?
    ///
    /// Returns how tightly it matched, so `wait` ranks `Wait` above `Wait for the
    /// window`. Lower is better; `None` means it did not match at all.
    pub fn score(hay: &str, needle: &str) -> Option<usize> {
        let needle = needle.trim();
        if needle.is_empty() {
            return Some(usize::MAX / 2);
        }
        let hay_l: Vec<char> = hay.to_lowercase().chars().collect();
        let mut spread = 0usize;
        let mut at = 0usize;
        let mut first: Option<usize> = None;
        for c in needle.to_lowercase().chars() {
            if c.is_whitespace() {
                continue;
            }
            let found = hay_l.iter().skip(at).position(|h| *h == c)? + at;
            if let Some(prev) = first {
                let _ = prev;
                spread += found - at;
            } else {
                first = Some(found);
            }
            at = found + 1;
        }
        // A match that starts at the beginning of the name is what was meant far
        // more often than one that starts in the middle of the third word.
        Some(spread + first.unwrap_or(0) * 2 + hay_l.len() / 8)
    }

    /// Ranks `items` against what was typed, best first.
    pub fn rank<'a, T>(items: &'a [T], typed: &str, name: impl Fn(&T) -> &str) -> Vec<&'a T> {
        let mut hits: Vec<(usize, &T)> = items
            .iter()
            .filter_map(|it| score(name(it), typed).map(|s| (s, it)))
            .collect();
        hits.sort_by_key(|(s, _)| *s);
        hits.into_iter().map(|(_, it)| it).collect()
    }
}

/// Why a step could not do what it was told, and what to try instead.
///
/// A named type rather than the three-part tuple this used to return: the middle
/// element is a list of sentences and the last is a rectangle, and neither is
/// guessable from `(String, Vec<String>, Option<(i32, i32, i32, i32)>)`.
#[derive(Clone, Debug, Default)]
pub struct Diagnosis {
    /// The one sentence, in the numbers the program already had.
    pub reason: String,
    /// What to try. Empty means there was nothing useful to say, and it says so.
    pub hints: Vec<String>,
    /// The rectangle worth photographing - where the step was looking.
    pub area: Option<(i32, i32, i32, i32)>,
}

/// Everything the run history knows about one step.
///
/// Kept out of `mod runlog` because both the interpreter and the editor talk about
/// these, and neither of them is about files.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct StepStats {
    pub runs: u32,
    pub ok: u32,
    pub total_us: u64,
    pub worst_us: u64,
}

impl StepStats {
    pub fn average_us(&self) -> u64 {
        if self.runs == 0 { 0 } else { self.total_us / self.runs as u64 }
    }

    pub fn success(&self) -> f64 {
        if self.runs == 0 { 0.0 } else { self.ok as f64 * 100.0 / self.runs as f64 }
    }

    /// A wait long enough for what this step usually needs, with room for a bad day.
    ///
    /// Half again the average, floored at the worst time ever seen, and never below
    /// a fifth of a second. The floor is the important part: an average describes
    /// what usually happens, and a timeout sized to what usually happens is a
    /// timeout that fails on the night it matters.
    pub fn suggested_timeout_ms(&self) -> u64 {
        let avg = self.average_us().saturating_mul(3) / 2;
        (avg.max(self.worst_us) / 1000).max(200)
    }

    /// Enough runs to be worth believing. Below this they are anecdotes.
    pub fn trustworthy(&self) -> bool {
        self.runs >= 5
    }
}

// ============================================================================
// Run history
// ============================================================================

/// What happened, the last few dozen times this was run.
///
/// The log file has always had all of this and none of it has ever been readable:
/// finding out why last night's run stopped meant opening a text file, finding the
/// right day, and reading backwards through several thousand lines of scheduler
/// chatter. A run is one line of JSON, appended when it ends, and the window shows
/// them newest first.
///
/// Written once per run rather than once per step, on purpose. A macro that loops
/// two hundred times overnight must not be doing file I/O between clicks.
pub mod runlog {
    use serde::{Deserialize, Serialize};
    use std::path::PathBuf;

    /// Runs kept on disk. Past this the oldest are dropped, screenshots and all.
    ///
    /// Twenty is roughly a fortnight of nightly runs, and a failure nobody looked at
    /// within a fortnight is not going to be looked at.
    pub const KEEP_RUNS: usize = 20;

    #[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Default)]
    pub enum Outcome {
        /// Ran to the end, however many loops that was.
        #[default]
        Finished,
        /// Somebody pressed stop, or the time limit came up.
        Stopped,
        /// A step could not do what it was told and the policy said to give up.
        Failed,
    }

    /// One run.
    #[derive(Clone, Debug, Serialize, Deserialize, Default)]
    pub struct Run {
        /// Local time it started: `2026-08-26 03:42`. A string because it is only
        /// ever shown, never computed with, and a real date type would be a
        /// dependency for no gain.
        pub started: String,
        pub duration_ms: u64,
        pub loops: u64,
        #[serde(default)]
        pub outcome: Outcome,
        /// True when this was a rehearsal, so a test run can never be mistaken for
        /// evidence that the macro works.
        #[serde(default)]
        pub test_run: bool,
        /// The step that ended it, when one did.
        #[serde(default)]
        pub failed_at: Option<usize>,
        /// How that step reads in the editor.
        #[serde(default)]
        pub failed_step: String,
        /// Why it could not be done, in the numbers the program already knew.
        #[serde(default)]
        pub reason: String,
        /// What to try, worked out from those numbers. Never empty advice: an empty
        /// list means the program had nothing useful to say, and says so.
        #[serde(default)]
        pub hints: Vec<String>,
        /// File name of the screenshot taken at the moment it failed, inside this
        /// run's folder.
        #[serde(default)]
        pub shot: Option<String>,
        /// The run's own folder, relative to the runs directory.
        #[serde(default)]
        pub folder: String,
        /// What each step did during this run, keyed by the step's id.
        ///
        /// Written once at the end of the run with the rest of the record. Keyed by
        /// id rather than by position, because a step's position changes the first
        /// time anybody inserts a line above it, and numbers that then belong to a
        /// different step are worse than no numbers at all.
        #[serde(default)]
        pub steps: Vec<StepRun>,
        /// How much this run had to work for its result.
        ///
        /// `Completed` is not the whole answer and never was. A macro that finished
        /// having fallen back to a coordinate three times, read the screen twice
        /// more than it meant to and gone through a recovery block is a macro that
        /// is about to stop working, and it looked exactly like a healthy one.
        ///
        /// Deliberately four counts and no score. Each is a fact the program
        /// observed; a single number out of a hundred would be an opinion, and an
        /// opinion in the same shape as the pre-flight score - which measures
        /// something else entirely - is an invitation to compare two numbers that
        /// have nothing to do with each other.
        #[serde(default)]
        pub effort: Effort,
    }

    /// What a run had to do beyond simply doing what it was told.
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq, Eq)]
    pub struct Effort {
        /// Targets found by something other than the best way they had.
        pub fallbacks: u32,
        /// Screen readings that needed more than the first preparation profile.
        pub ocr_retries: u32,
        /// Recovery blocks entered, and the time spent inside them.
        pub recoveries: u32,
        pub recovery_ms: u64,
        /// Steps that failed and were carried on from, which `Outcome` cannot say:
        /// a run whose every miss policy is "carry on" finishes, and finishing is
        /// not the same as having worked.
        pub missed: u32,
        /// Steps that ran at all, so the counts above have something to be out of.
        pub steps: u32,
    }

    impl Effort {
        /// Did this run have to do anything unusual at all?
        pub fn quiet(&self) -> bool {
            self.fallbacks == 0
                && self.ocr_retries == 0
                && self.recoveries == 0
                && self.missed == 0
        }
    }

    /// What one step did, across one run.
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default)]
    pub struct StepRun {
        pub id: u64,
        /// How many times it ran. A step inside a loop runs many times per run.
        pub runs: u32,
        pub ok: u32,
        /// Total microseconds spent in it, so an average survives being summed with
        /// other runs without keeping every sample.
        pub total_us: u64,
        /// The single worst time. The number that matters when sizing a timeout.
        pub worst_us: u64,
    }

    /// Everything the history knows about every step, summed across runs.
    ///
    /// A snapshot, read from disk when the caller asks. The interpreter takes one
    /// when a run starts and never looks again: a macro whose timings drift while it
    /// is running cannot be debugged.
    pub fn stats() -> std::collections::HashMap<u64, crate::StepStats> {
        let mut out: std::collections::HashMap<u64, crate::StepStats> =
            std::collections::HashMap::new();
        for run in load() {
            // A rehearsal proves nothing about how long the real thing takes: the
            // input was never sent, so nothing on screen ever responded to it.
            if run.test_run {
                continue;
            }
            for st in run.steps {
                let e = out.entry(st.id).or_default();
                e.runs += st.runs;
                e.ok += st.ok;
                e.total_us += st.total_us;
                e.worst_us = e.worst_us.max(st.worst_us);
            }
        }
        out
    }

    impl Run {
        /// One line for the list.
        pub fn headline(&self) -> String {
            let mark = match self.outcome {
                Outcome::Finished => '✔',
                Outcome::Stopped => '■',
                Outcome::Failed => '✖',
            };
            let test = if self.test_run { " ✔" } else { "" };
            format!("{mark}{test} {}", self.started)
        }

        pub fn shot_path(&self) -> Option<PathBuf> {
            let shot = self.shot.as_ref()?;
            Some(dir().join(&self.folder).join(shot))
        }
    }

    pub fn dir() -> PathBuf {
        crate::paths::sub_dir("runs")
    }

    fn history_path() -> PathBuf {
        dir().join("history.jsonl")
    }

    /// Appends one run and drops whatever is now too old.
    ///
    /// Failure to write is logged and otherwise ignored: a full disk is not a reason
    /// to lose the macro run that just succeeded.
    pub fn append(run: &Run) {
        use std::io::Write as _;
        let d = dir();
        if std::fs::create_dir_all(&d).is_err() {
            return;
        }
        let line = match serde_json::to_string(run) {
            Ok(l) => l,
            Err(e) => {
                tracing::warn!("run history: could not encode the run: {e}");
                return;
            }
        };
        let written = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(history_path())
            .and_then(|mut f| writeln!(f, "{line}"));
        if let Err(e) = written {
            tracing::warn!("run history: could not write it: {e}");
            return;
        }
        prune();
    }

    /// The runs on disk, newest first.
    pub fn load() -> Vec<Run> {
        let Ok(text) = std::fs::read_to_string(history_path()) else {
            return Vec::new();
        };
        let mut out: Vec<Run> = text
            .lines()
            .filter(|l| !l.trim().is_empty())
            // A line that will not parse is skipped rather than fatal: a half-written
            // line from a run that was killed mid-append must not hide the other
            // nineteen.
            .filter_map(|l| serde_json::from_str::<Run>(l).ok())
            .collect();
        out.reverse();
        out
    }

    /// Keeps the newest `KEEP_RUNS` and deletes the folders belonging to the rest.
    fn prune() {
        let runs = load();
        if runs.len() <= KEEP_RUNS {
            return;
        }
        let keep = &runs[..KEEP_RUNS];
        for old in &runs[KEEP_RUNS..] {
            if !old.folder.is_empty() {
                let _ = std::fs::remove_dir_all(dir().join(&old.folder));
            }
        }
        // Rewritten oldest-first, which is the order the file is in.
        let mut text = String::new();
        for r in keep.iter().rev() {
            if let Ok(l) = serde_json::to_string(r) {
                text.push_str(&l);
                text.push('\n');
            }
        }
        let _ = std::fs::write(history_path(), text);
    }

    /// A folder name for one run: sortable, and unique within a session.
    pub fn stamp() -> (String, String) {
        let (y, mo, d, _, h, mi) = crate::platform::local_time();
        let sec = crate::now_us() / 1_000_000 % 60;
        (
            format!("{y:04}-{mo:02}-{d:02} {h:02}:{mi:02}"),
            format!("{y:04}{mo:02}{d:02}_{h:02}{mi:02}{sec:02}"),
        )
    }
}

// ============================================================================
// End-of-run actions
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EndAction {
    Stop,
    Shutdown,
    Reboot,
    Sleep,
    Hibernate,
    LogOff,
}

impl EndAction {
    const COUNT: usize = 6;
    fn from_index(i: usize) -> Self {
        match i {
            1 => Self::Shutdown,
            2 => Self::Reboot,
            3 => Self::Sleep,
            4 => Self::Hibernate,
            5 => Self::LogOff,
            _ => Self::Stop,
        }
    }
}

// ============================================================================
// Image search
// ============================================================================

/// Normalised cross-correlation template matching.
///
/// Written here rather than pulled from a crate on purpose: `template-matching`
/// drags in the whole wgpu stack for a 6 MB app, and `imageproc::match_template`
/// has no mask, no scale search and no coarse pass. What this needs is narrow and
/// specific - search a screen buffer we already own, ignore transparent pixels,
/// tolerate a slightly different size - and that is about 150 lines.
pub mod vision {
    /// Which way round the three colour bytes of a pixel lie.
    ///
    /// The screen hands back BGRA and nothing downstream cares: the search reads a
    /// brightness, and a brightness is the same number whichever end the red
    /// coefficient is applied at. Carrying the order instead of rewriting fourteen
    /// megabytes to hide it is what took the floor under a capture from 5.5 ms to
    /// one `BitBlt`. Only the two places that genuinely need red first - saving a
    /// PNG, and cutting a template - convert, and both are cold.
    #[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
    pub enum Order {
        /// Red, green, blue, alpha. What PNGs and templates hold.
        #[default]
        Rgba,
        /// Blue, green, red, alpha. What GDI hands back.
        Bgra,
    }

    impl Order {
        /// Luma weights for byte 0, 1 and 2 in this order.
        #[inline]
        pub fn weights(self) -> (f32, f32, f32) {
            match self {
                Order::Rgba => (0.299, 0.587, 0.114),
                Order::Bgra => (0.114, 0.587, 0.299),
            }
        }
    }

    /// A rectangle of screen pixels plus where it came from.
    ///
    /// `px` is four bytes a pixel in `order`. The alpha byte is whatever the source
    /// left there - GDI leaves it at zero - and nothing that reads a `Frame` looks
    /// at it: the search throws the haystack's mask away and keeps only the
    /// template's. `to_rgba` is the one way out to a buffer that can be trusted.
    #[derive(Clone)]
    pub struct Frame {
        pub x: i32,
        pub y: i32,
        pub w: u32,
        pub h: u32,
        pub px: Vec<u8>,
        pub order: Order,
    }

    impl Frame {
        /// A frame that already holds red-first pixels.
        pub fn rgba(x: i32, y: i32, w: u32, h: u32, px: Vec<u8>) -> Self {
            Self { x, y, w, h, px, order: Order::Rgba }
        }

        /// True RGBA with an opaque alpha - what a PNG encoder and a template want.
        ///
        /// The only full pass over a captured buffer left in the program, and it
        /// runs when a picture is saved rather than when one is looked for.
        pub fn to_rgba(&self) -> Vec<u8> {
            let mut out = self.px.clone();
            let swap = self.order == Order::Bgra;
            // One pass, not two. The alpha has to be written whatever the order -
            // GDI leaves it at zero, and a template with a zero alpha is a template
            // masked out of its own comparison.
            for p in out.as_chunks_mut::<4>().0 {
                if swap {
                    p.swap(0, 2);
                }
                p[3] = 255;
            }
            out
        }

        /// Cuts the whole frame out as a template.
        pub fn as_template(&self, name: &str) -> Template {
            Template { w: self.w, h: self.h, rgba: self.to_rgba(), name: name.to_string() }
        }
    }

    /// A picture to look for, kept both as pixels and as a prepared grey plane.
    #[derive(Clone)]
    pub struct Template {
        pub w: u32,
        pub h: u32,
        pub rgba: Vec<u8>,
        pub name: String,
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Hit {
        /// Centre of the match, in screen coordinates.
        pub x: i32,
        pub y: i32,
        pub score: f32,
        pub scale: f32,
    }

    fn luma(px: &[u8], i: usize, w: (f32, f32, f32)) -> f32 {
        w.0 * px[i] as f32 + w.1 * px[i + 1] as f32 + w.2 * px[i + 2] as f32
    }

    /// Grey plane plus a mask: fully transparent pixels take no part in the score,
    /// which is what lets a non-rectangular icon be matched.
    ///
    /// Scaled to 0..=1 rather than 0..=255. The correlation does not care - it is
    /// invariant to both - but the one-pass form below subtracts a sum of squares
    /// from a square of sums, and at 255 that subtraction throws away most of an
    /// f32's precision on a large template.
    fn plane(px: &[u8], w: u32, h: u32, order: Order) -> (Vec<f32>, Vec<bool>) {
        let n = (w * h) as usize;
        let mut g = vec![0.0; n];
        let mut m = vec![true; n];
        let k = order.weights();
        for i in 0..n {
            g[i] = luma(px, i * 4, k) * (1.0 / 255.0);
            m[i] = px[i * 4 + 3] >= 16;
        }
        (g, m)
    }

    /// The grey plane only, for a haystack whose mask is thrown away anyway.
    ///
    /// Half the allocation and none of the alpha reads. A screen grab has no alpha
    /// worth reading - GDI leaves it at zero - which is exactly why the search must
    /// not consult it.
    fn plane_grey(px: &[u8], w: u32, h: u32, order: Order) -> Vec<f32> {
        let n = (w * h) as usize;
        let mut g = vec![0.0; n];
        let k = order.weights();
        // Indexed rather than iterated, and `#[allow]`ed rather than "fixed".
        // Measured on a quiet machine, interleaved against the iterator form: this
        // is the hottest loop in the program and indexing is consistently the
        // faster of the two here. Clippy's suggestion is good general advice and
        // wrong in this one place.
        #[allow(clippy::needless_range_loop)]
        for i in 0..n {
            g[i] = luma(px, i * 4, k) * (1.0 / 255.0);
        }
        g
    }

    /// Gradient magnitude, by the Sobel operator.
    ///
    /// What survives a change of theme: a button's outline sits in the same place
    /// whether the panel behind it is light or dark, while its grey level does not.
    /// Correlating the gradients instead of the greys is what makes a template cut
    /// under one theme still match under another, and it is also what makes a
    /// highlighted row match its unhighlighted self.
    ///
    /// The border replicates its neighbour rather than wrapping, so a template cut
    /// tight against an edge still scores sensibly.
    fn sobel(g: &[f32], w: u32, h: u32) -> Vec<f32> {
        let n = (w as usize) * (h as usize);
        let mut out = vec![0.0f32; n];
        if w < 2 || h < 2 || g.len() < n {
            return out;
        }
        let (wu, hu) = (w as usize, h as usize);
        // The interior, where every neighbour exists. Two clamps per neighbour and
        // eight neighbours per pixel is sixteen branches a pixel; over a 3.7
        // megapixel screen that was most of the cost, and none of it was needed
        // anywhere except the one-pixel border.
        for y in 1..hu.saturating_sub(1) {
            let (up, mid, dn) = ((y - 1) * wu, y * wu, (y + 1) * wu);
            for x in 1..wu.saturating_sub(1) {
                let (a, b, c) = (g[up + x - 1], g[up + x], g[up + x + 1]);
                let (d, f) = (g[mid + x - 1], g[mid + x + 1]);
                let (i, j, k) = (g[dn + x - 1], g[dn + x], g[dn + x + 1]);
                let gx = (c + 2.0 * f + k) - (a + 2.0 * d + i);
                let gy = (i + 2.0 * j + k) - (a + 2.0 * b + c);
                out[mid + x] = (gx * gx + gy * gy).sqrt();
            }
        }
        // The border replicates its neighbour rather than wrapping, so a template
        // cut tight against an edge still scores sensibly. Copied from the ring
        // inside it, which is what clamping would have produced anyway.
        if wu >= 3 && hu >= 3 {
            for x in 0..wu {
                let sx = x.clamp(1, wu - 2);
                out[x] = out[wu + sx];
                out[(hu - 1) * wu + x] = out[(hu - 2) * wu + sx];
            }
            for y in 0..hu {
                let sy = y.clamp(1, hu - 2);
                out[y * wu] = out[sy * wu + 1];
                out[y * wu + wu - 1] = out[sy * wu + wu - 2];
            }
        }
        out
    }

    /// Nearest-neighbour box shrink. Good enough: the coarse pass only has to get
    /// close, and the refine pass runs at full resolution.
    fn shrink(src: &[f32], w: u32, h: u32, step: u32) -> (Vec<f32>, u32, u32) {
        if step <= 1 {
            return (src.to_vec(), w, h);
        }
        let (nw, nh) = ((w / step).max(1), (h / step).max(1));
        let mut out = vec![0.0; (nw * nh) as usize];
        for y in 0..nh {
            for x in 0..nw {
                let mut acc = 0.0;
                let mut cnt = 0.0;
                for dy in 0..step {
                    for dx in 0..step {
                        let sx = x * step + dx;
                        let sy = y * step + dy;
                        if sx < w && sy < h {
                            acc += src[(sy * w + sx) as usize];
                            cnt += 1.0;
                        }
                    }
                }
                out[(y * nw + x) as usize] = if cnt > 0.0 { acc / cnt } else { 0.0 };
            }
        }
        (out, nw, nh)
    }

    fn shrink_mask(src: &[bool], w: u32, h: u32, step: u32) -> (Vec<bool>, u32, u32) {
        if step <= 1 {
            return (src.to_vec(), w, h);
        }
        let (nw, nh) = ((w / step).max(1), (h / step).max(1));
        let mut out = vec![false; (nw * nh) as usize];
        for y in 0..nh {
            for x in 0..nw {
                // A coarse pixel counts only if its whole block counted.
                let mut all = true;
                for dy in 0..step {
                    for dx in 0..step {
                        let sx = x * step + dx;
                        let sy = y * step + dy;
                        if sx < w && sy < h && !src[(sy * w + sx) as usize] {
                            all = false;
                        }
                    }
                }
                out[(y * nw + x) as usize] = all;
            }
        }
        (out, nw, nh)
    }

    /// Resamples a template to a different size, nearest neighbour.
    pub fn resize_rgba(rgba: &[u8], w: u32, h: u32, nw: u32, nh: u32) -> Vec<u8> {
        let mut out = vec![0u8; (nw * nh * 4) as usize];
        for y in 0..nh {
            let sy = (y * h / nh).min(h - 1);
            for x in 0..nw {
                let sx = (x * w / nw).min(w - 1);
                let d = ((y * nw + x) * 4) as usize;
                let sidx = ((sy * w + sx) * 4) as usize;
                out[d..d + 4].copy_from_slice(&rgba[sidx..sidx + 4]);
            }
        }
        out
    }

    /// A template ready to be correlated: its mean already taken out, its own
    /// variance already known.
    ///
    /// Both are the same at every position the window can land in, and the old code
    /// worked them out again for each one - a second full pass over the template for
    /// every pixel of the screen. Taking them out of the loop is most of the speed
    /// here; the vector kernel below is the rest.
    struct Prepared {
        /// The template minus its mean, and zero wherever the mask says to ignore.
        /// Because it sums to zero, the window's own mean drops out of the
        /// numerator and the correlation needs one pass instead of two.
        centered: Vec<f32>,
        /// 1.0 where the pixel counts, 0.0 where it does not. Floats rather than
        /// bools so the inner loop multiplies instead of branching.
        mask: Vec<f32>,
        /// True when nothing is masked out, which is every ordinary PNG.
        dense: bool,
        /// Which block kernel to run, or `None` for the plain row-at-a-time loop.
        /// Chosen here rather than at every position: the coarse pass asks for a
        /// score a quarter of a million times, and an atomic load and a branch on
        /// each of them is not free.
        kernel: Option<BlockKernel>,
        w: u32,
        h: u32,
        n: f32,
        dt: f32,
    }

    // ---- one executable, every instruction set ------------------------------
    //
    // The question this answers: can one .exe be built for x86-64, x86-64-v2/v3/v4
    // and znver1..znver5 at once and pick at run time? Not as whole-program builds -
    // `-C target-cpu` is a property of a compilation and rustc emits one. What can
    // live in one executable is every version of the code that the flag would
    // actually have changed, compiled side by side and chosen by CPUID on the way
    // in. For this program that is the correlation kernel: measured at 22 ms against
    // 11 ms, it is the single largest lever in the image search, and every other hot
    // path here waits on the GPU or on Windows rather than on arithmetic.
    //
    // What the nine flags collapse to, honestly:
    //
    //   x86-64, x86-64-v2      -> the SSE2 kernel. v2 adds SSE3..SSE4.2 and POPCNT,
    //                             none of which a float correlation can spend.
    //   sandybridge, bdver1..4 -> the AVX kernel: eight wide, no FMA.
    //   x86-64-v3, znver1..3   -> the AVX2 + FMA kernel.
    //   x86-64-v4, znver4/5    -> the AVX-512 kernel, if it wins the race below.
    //
    // What is not reproducible this way, and is worth being straight about: a
    // `-C target-cpu=znver3` build also gets Zen 3's scheduling model - instruction
    // selection and ordering tuned to that pipeline. `#[target_feature]` enables
    // instructions; it does not switch the tuning model, and nothing at run time
    // can. That part stays with whatever the build was made for. It is also the
    // small part: the step from SSE2 to AVX2 is worth about 2x here, the tuning
    // difference between two processors at the same ISA level is worth a few per
    // cent, and `--selftest simd` prints both numbers on the machine in front of you
    // rather than asking anyone to take that on trust.

    /// The sums for one whole window, in one instruction set.
    ///
    /// # Safety
    /// A pointer of this type is only ever handed out by `Isa::kernel`, which asks
    /// CPUID first, and `score_at` bounds-checks the window before calling through.
    type BlockKernel = unsafe fn(&[f32], u32, &Prepared, u32, u32) -> (f32, f32, f32);

    /// The instruction sets the correlation kernel is compiled for. All of them are
    /// in every build; which one runs is decided from the processor, not from the
    /// flags the executable was made with.
    #[derive(Copy, Clone, PartialEq, Eq, Debug)]
    pub enum Isa {
        /// No vector unit asked for - the portable loop, and the only choice off
        /// x86-64.
        Scalar,
        Sse2,
        Avx,
        Avx2,
        Avx512,
    }

    /// Widest first, which is the order `kernel_for` wants to search in.
    pub const ISAS: [Isa; 5] = [Isa::Avx512, Isa::Avx2, Isa::Avx, Isa::Sse2, Isa::Scalar];

    impl Isa {
        pub fn name(self) -> &'static str {
            match self {
                Isa::Scalar => "scalar",
                Isa::Sse2 => "sse2",
                Isa::Avx => "avx",
                Isa::Avx2 => "avx2",
                Isa::Avx512 => "avx512",
            }
        }

        /// The `-C target-cpu` values that would have produced this kernel, for the
        /// benefit of anyone comparing this against a per-processor build.
        pub fn target_cpus(self) -> &'static str {
            match self {
                Isa::Scalar => "portable fallback",
                Isa::Sse2 => "x86-64, x86-64-v2",
                Isa::Avx => "sandybridge, bdver1-bdver4",
                Isa::Avx2 => "x86-64-v3, znver1, znver2, znver3",
                Isa::Avx512 => "x86-64-v4, znver4, znver5",
            }
        }

        /// How many floats the inner loop takes at a time.
        pub fn width(self) -> u32 {
            match self {
                Isa::Scalar => 1,
                Isa::Sse2 => 4,
                Isa::Avx | Isa::Avx2 => 8,
                Isa::Avx512 => 16,
            }
        }

        fn index(self) -> u8 {
            match self {
                Isa::Scalar => 0,
                Isa::Sse2 => 1,
                Isa::Avx => 2,
                Isa::Avx2 => 3,
                Isa::Avx512 => 4,
            }
        }

        fn from_index(i: u8) -> Option<Isa> {
            match i {
                0 => Some(Isa::Scalar),
                1 => Some(Isa::Sse2),
                2 => Some(Isa::Avx),
                3 => Some(Isa::Avx2),
                4 => Some(Isa::Avx512),
                _ => None,
            }
        }

        /// Parses what `--simd` was given. `auto` is `None` here, which hands the
        /// choice back to the processor.
        ///
        /// The `-C target-cpu` spellings are accepted too, because the obvious thing
        /// to type after reading about a `znver3` build is `--simd znver3`, and
        /// answering that with "not a kernel name" would be pedantry - it maps onto
        /// one of these five, and `--selftest simd` says which.
        pub fn parse(s: &str) -> Option<Isa> {
            match s.trim().to_ascii_lowercase().as_str() {
                "scalar" | "none" | "off" => Some(Isa::Scalar),
                "sse2" | "sse" | "x86-64" | "x86_64" | "x86-64-v2" | "v2" => Some(Isa::Sse2),
                "avx" | "sandybridge" | "ivybridge" | "bdver1" | "bdver2" | "bdver3"
                | "bdver4" => Some(Isa::Avx),
                "avx2" | "fma" | "x86-64-v3" | "v3" | "haswell" | "znver1" | "znver2"
                | "znver3" => Some(Isa::Avx2),
                "avx512" | "avx-512" | "x86-64-v4" | "v4" | "znver4" | "znver5" => {
                    Some(Isa::Avx512)
                }
                _ => None,
            }
        }

        /// Can this processor run it? Asked through `is_x86_feature_detected!`,
        /// which reads CPUID once and remembers.
        pub fn supported(self) -> bool {
            #[cfg(target_arch = "x86_64")]
            {
                match self {
                    Isa::Scalar => true,
                    // Every x86-64 processor has SSE2 - it is in the base
                    // architecture, which is why the `x86-64` and `x86-64-v2` flags
                    // land on the same kernel.
                    Isa::Sse2 => true,
                    Isa::Avx => is_x86_feature_detected!("avx"),
                    Isa::Avx2 => {
                        is_x86_feature_detected!("avx2") && is_x86_feature_detected!("fma")
                    }
                    // The kernel itself only needs avx512f. The other three are what
                    // make this x86-64-v4, and asking for them keeps the tier off
                    // Knights Landing, where 512-bit arithmetic is a different
                    // machine with a different answer.
                    Isa::Avx512 => {
                        is_x86_feature_detected!("avx512f")
                            && is_x86_feature_detected!("avx512vl")
                            && is_x86_feature_detected!("avx512bw")
                            && is_x86_feature_detected!("avx512dq")
                    }
                }
            }
            #[cfg(not(target_arch = "x86_64"))]
            {
                self == Isa::Scalar
            }
        }

        fn kernel(self) -> Option<BlockKernel> {
            #[cfg(target_arch = "x86_64")]
            {
                if !self.supported() {
                    return None;
                }
                match self {
                    Isa::Scalar => None,
                    Isa::Sse2 => Some(sums_block_sse2 as BlockKernel),
                    Isa::Avx => Some(sums_block_avx as BlockKernel),
                    Isa::Avx2 => Some(sums_block_avx2 as BlockKernel),
                    Isa::Avx512 => Some(sums_block_avx512 as BlockKernel),
                }
            }
            #[cfg(not(target_arch = "x86_64"))]
            {
                let _ = self;
                None
            }
        }
    }

    /// 0 = not settled yet, otherwise the tier plus one.
    static CHOSEN: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
    /// 0 = let the processor decide, otherwise the pinned tier plus one.
    static FORCED: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

    /// Pins the kernel, or hands the choice back to the processor with `None`.
    /// `--simd` and `--selftest simd` use this; nothing else should.
    pub fn force_isa(want: Option<Isa>) {
        use std::sync::atomic::Ordering;
        FORCED.store(want.map_or(0, |i| i.index() + 1), Ordering::Relaxed);
        CHOSEN.store(0, Ordering::Relaxed);
    }

    /// Which kernel this process is running. Worked out once and then remembered:
    /// settling it can involve a measurement, and one template search asks a quarter
    /// of a million times.
    ///
    /// Two threads arriving here together can both resolve and both store, and that
    /// is left alone rather than locked. The cost is one extra millisecond of
    /// measurement; there is no wrong answer to be had, because every value either of
    /// them can store is a kernel this processor was confirmed to have.
    pub fn active() -> Isa {
        use std::sync::atomic::Ordering;
        if let Some(i) = Isa::from_index(CHOSEN.load(Ordering::Relaxed).wrapping_sub(1)) {
            return i;
        }
        let picked = resolve();
        CHOSEN.store(picked.index() + 1, Ordering::Relaxed);
        picked
    }

    /// Every kernel in this executable, widest first, with whether this processor
    /// can run it.
    pub fn isa_report() -> Vec<(Isa, bool)> {
        ISAS.iter().copied().map(|i| (i, i.supported())).collect()
    }

    fn widest_supported() -> Isa {
        ISAS.iter().copied().find(|i| i.supported()).unwrap_or(Isa::Scalar)
    }

    fn resolve() -> Isa {
        use std::sync::atomic::Ordering;
        if let Some(f) = Isa::from_index(FORCED.load(Ordering::Relaxed).wrapping_sub(1)) {
            // A pin this processor cannot honour becomes the fastest thing it can
            // run. Refusing would leave the program slower than it was asked to be,
            // and doing that silently would be worse - `--simd` prints what it got.
            return if f.supported() { f } else { widest_supported() };
        }
        let best = widest_supported();
        #[cfg(target_arch = "x86_64")]
        if best == Isa::Avx512 && Isa::Avx2.supported() && !avx512_pays() {
            return Isa::Avx2;
        }
        best
    }

    /// AVX-512 is the one step where wider is not automatically faster.
    ///
    /// On Zen 4 the 512-bit operations are pumped through 256-bit units, and on
    /// several Intel parts they pull the clock down for the whole core; on Zen 5 and
    /// on the server parts they are the real thing. That is a property of the
    /// processor in front of the user, and a table of model numbers would be wrong
    /// within a year - so this races the two kernels once, on a window the size of a
    /// real template, and keeps the winner. About a millisecond, once per process.
    ///
    /// Best-of rather than mean, for the same reason the rest of this project's
    /// benchmarks are: the shortest run is the one that was interrupted least.
    #[cfg(target_arch = "x86_64")]
    fn avx512_pays() -> bool {
        let (Some(wide), Some(narrow)) = (Isa::Avx512.kernel(), Isa::Avx2.kernel()) else {
            return true;
        };
        const W: u32 = 64;
        const H: u32 = 64;
        let n = (W * H) as usize;
        let hay: Vec<f32> = (0..n).map(|i| (i % 251) as f32).collect();
        let p = Prepared {
            centered: (0..n).map(|i| (i % 97) as f32 - 48.0).collect(),
            mask: vec![1.0; n],
            dense: true,
            kernel: None,
            w: W,
            h: H,
            n: n as f32,
            dt: 1.0,
        };
        let round = |k: BlockKernel| -> u128 {
            let t = std::time::Instant::now();
            let mut acc = 0.0f32;
            for _ in 0..48 {
                // SAFETY: `k` came from `Isa::kernel`, which hands back a pointer
                // only for an instruction set CPUID confirmed, and the window is
                // exactly `hay` - H rows of W floats at stride W.
                let (a, b, d) = unsafe { k(&hay, W, &p, 0, 0) };
                acc += a + b + d;
            }
            std::hint::black_box(acc);
            t.elapsed().as_nanos()
        };
        // Warm both, then alternate. Run in one order and not the other, the first
        // AVX-512 batch would pay for the clock transition that the Intel parts make
        // and the second would not - which is the very thing being asked about.
        let _ = (round(wide), round(narrow));
        let (mut fat, mut thin) = (u128::MAX, u128::MAX);
        for _ in 0..5 {
            thin = thin.min(round(narrow));
            fat = fat.min(round(wide));
        }
        // Wider has to be clearly better, not equal. On a tie the 256-bit kernel is
        // the safer one to leave running: it does not pull the clock down for
        // whatever else the user has on the machine.
        fat.saturating_mul(100) < thin.saturating_mul(95)
    }

    /// The widest kernel that has whole vectors to work on, never wider than the one
    /// this process settled on.
    ///
    /// A template narrower than the vector spends all its time in the tail, which is
    /// the plain loop with an extra branch in front of it.
    fn kernel_for(w: u32) -> Option<BlockKernel> {
        let ceiling = active().index();
        ISAS.iter()
            .copied()
            .find(|i| i.index() <= ceiling && i.width() <= w && i.supported())
            .and_then(Isa::kernel)
    }

    fn prepare_template(tpl: &[f32], mask: &[bool], w: u32, h: u32) -> Option<Prepared> {
        let len = (w as usize).checked_mul(h as usize)?;
        if len == 0 || tpl.len() < len || mask.len() < len {
            return None;
        }
        let n = mask[..len].iter().filter(|m| **m).count();
        if n < 4 {
            return None;
        }
        let sum: f32 = (0..len).filter(|i| mask[*i]).map(|i| tpl[i]).sum();
        let mt = sum / n as f32;
        let mut centered = vec![0.0f32; len];
        let mut mf = vec![0.0f32; len];
        let mut dt = 0.0f32;
        for i in 0..len {
            if mask[i] {
                let c = tpl[i] - mt;
                centered[i] = c;
                mf[i] = 1.0;
                dt += c * c;
            }
        }
        // A template with no contrast at all correlates with everything equally,
        // which is not an answer.
        if dt <= f32::EPSILON {
            return None;
        }
        let dense = n == len;
        // Only the dense path has a block kernel. A template with holes in it is
        // rare, and a masked vector kernel would be a second copy of each of four
        // kernels for the case that is not costing the time.
        let kernel = if dense { kernel_for(w) } else { None };
        Some(Prepared {
            centered,
            mask: mf,
            dense,
            kernel,
            w,
            h,
            n: n as f32,
            dt,
        })
    }

    /// Correlation of a prepared template placed at (ox, oy) in the haystack.
    ///
    /// Returns a value in -1.0 ..= 1.0; 1.0 means identical up to brightness and
    /// contrast, which is why a screenshot taken under a different theme still
    /// matches.
    fn score_at(hay: &[f32], hw: u32, p: &Prepared, ox: u32, oy: u32) -> f32 {
        let tw = p.w as usize;
        // Once, up front, instead of once per row: the last row of the window
        // reaches furthest into the haystack, so if it fits, every earlier one does.
        let last = ((oy + p.h - 1) as usize) * (hw as usize) + ox as usize + tw;
        if p.h == 0 || tw == 0 || last > hay.len() || p.centered.len() < tw * p.h as usize
        {
            return -1.0;
        }
        let (sum_i, sum_ii, dot) = match p.kernel {
            // SAFETY: the bounds above cover every row it reads and every float of
            // `centered` it touches, and the pointer was only installed for an
            // instruction set the processor was asked about through CPUID.
            Some(k) => unsafe { k(hay, hw, p, ox, oy) },
            None => {
                let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
                for y in 0..p.h {
                    let hrow = ((oy + y) * hw + ox) as usize;
                    let trow = (y * p.w) as usize;
                    let hs = &hay[hrow..hrow + tw];
                    let cs = &p.centered[trow..trow + tw];
                    let (ra, rb, rd) = if p.dense {
                        sums_dense_scalar(hs, cs)
                    } else {
                        sums_masked(hs, &p.mask[trow..trow + tw], cs)
                    };
                    a += ra;
                    b += rb;
                    d += rd;
                }
                (a, b, d)
            }
        };
        let mi = sum_i / p.n;
        // Cancellation: on a window of one flat colour the sum of squares and the
        // square of the sum are the same number, and in floating point the
        // subtraction can land a whisker *below* zero. The square root of that is
        // NaN, and `NaN <= EPSILON` is false, so the old guard let it through - a
        // NaN score then compares false against everything, which is invisible to a
        // `>` test and quietly poisoned anything collecting the best answer.
        // Clamping the variance is the honest fix: it cannot be negative.
        let di = (sum_ii - p.n * mi * mi).max(0.0);
        let den = (di * p.dt).sqrt();
        // The NaN case is spelled out rather than left to a negated comparison: it
        // is the one that used to slip through, and a reader should not have to
        // work out that `!(x > y)` is true for a value that is neither.
        if den.is_nan() || den <= f32::EPSILON { -1.0 } else { dot / den }
    }

    /// Whether this build is running a vector kernel right now.
    pub fn vectorised() -> bool {
        active() != Isa::Scalar
    }

    /// One row: the sum of the window, the sum of its squares, and its dot product
    /// with the centred template.
    fn sums_dense_scalar(h: &[f32], c: &[f32]) -> (f32, f32, f32) {
        let n = h.len().min(c.len());
        let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
        for i in 0..n {
            let x = h[i];
            a += x;
            b += x * x;
            d += x * c[i];
        }
        (a, b, d)
    }

    /// The same, when some of the template is transparent. The mask is a multiplier
    /// rather than a branch, and the centred template is already zero where it does
    /// not count, so the dot product needs no mask at all.
    fn sums_masked(h: &[f32], m: &[f32], c: &[f32]) -> (f32, f32, f32) {
        let n = h.len().min(m.len()).min(c.len());
        let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
        for i in 0..n {
            let x = h[i] * m[i];
            a += x;
            b += x * h[i];
            d += h[i] * c[i];
        }
        (a, b, d)
    }

    // The four block kernels. All of them take the whole window rather than a row at
    // a time: the accumulators live across every row and are folded down once at the
    // end. Per row it was three horizontal sums for every vector of floats, and on
    // the coarse pass - where a 32-pixel template shrinks to an eight-wide one -
    // that cost more than the multiply-adds it replaced. Measured: row at a time, a
    // 32x32 template came out slower with the vector path on than off.
    //
    // All four also carry two accumulator sets rather than one, and take two vectors
    // per turn of the loop. That is not a micro-optimisation, it is the difference
    // between the tiers coming out in the right order. Written with one set each,
    // the AVX2 kernel measured *slower* than the plain AVX one it exists to beat -
    // 5.3 ms against 4.5 on a 128x128 template - because a single accumulator makes
    // the loop latency-bound rather than throughput-bound, and an FMA's four-cycle
    // latency is longer than a plain add's three. Two independent chains give the
    // pipeline something to do while each one is in flight, and the order comes back
    // out right. `--selftest simd` is where that was caught, and it is why the table
    // it prints has a row per kernel rather than a single speed-up number.
    //
    // # Safety, all four
    // Every row from `oy` to `oy + p.h`, at column `ox` for `p.w` floats, must lie
    // inside `hay`, and `p.centered` must hold `p.w * p.h` of them. `score_at`
    // checks both before calling. The caller must also have established through
    // CPUID that the processor has the instruction set - `Isa::kernel` does.

    /// Baseline x86-64: four floats at a time, and no feature test needed because
    /// SSE2 is part of the architecture. This is the kernel a `-C target-cpu=x86-64`
    /// or `x86-64-v2` build would have had, and it is why the plain build is no
    /// longer stuck on the scalar loop.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "sse2")]
    unsafe fn sums_block_sse2(
        hay: &[f32],
        hw: u32,
        p: &Prepared,
        ox: u32,
        oy: u32,
    ) -> (f32, f32, f32) {
        use std::arch::x86_64::*;
        let tw = p.w as usize;
        unsafe {
            let (mut a0, mut a1) = (_mm_setzero_ps(), _mm_setzero_ps());
            let (mut b0, mut b1) = (_mm_setzero_ps(), _mm_setzero_ps());
            let (mut d0, mut d1) = (_mm_setzero_ps(), _mm_setzero_ps());
            let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
            for y in 0..p.h {
                let hp = hay.as_ptr().add(((oy + y) as usize) * (hw as usize) + ox as usize);
                let cp = p.centered.as_ptr().add((y as usize) * tw);
                let mut i = 0usize;
                while i + 8 <= tw {
                    let x0 = _mm_loadu_ps(hp.add(i));
                    let c0 = _mm_loadu_ps(cp.add(i));
                    let x1 = _mm_loadu_ps(hp.add(i + 4));
                    let c1 = _mm_loadu_ps(cp.add(i + 4));
                    a0 = _mm_add_ps(a0, x0);
                    a1 = _mm_add_ps(a1, x1);
                    b0 = _mm_add_ps(b0, _mm_mul_ps(x0, x0));
                    b1 = _mm_add_ps(b1, _mm_mul_ps(x1, x1));
                    d0 = _mm_add_ps(d0, _mm_mul_ps(x0, c0));
                    d1 = _mm_add_ps(d1, _mm_mul_ps(x1, c1));
                    i += 8;
                }
                if i + 4 <= tw {
                    let x = _mm_loadu_ps(hp.add(i));
                    let c = _mm_loadu_ps(cp.add(i));
                    a0 = _mm_add_ps(a0, x);
                    b0 = _mm_add_ps(b0, _mm_mul_ps(x, x));
                    d0 = _mm_add_ps(d0, _mm_mul_ps(x, c));
                    i += 4;
                }
                while i < tw {
                    let x = *hp.add(i);
                    a += x;
                    b += x * x;
                    d += x * *cp.add(i);
                    i += 1;
                }
            }
            (
                a + hsum128(_mm_add_ps(a0, a1)),
                b + hsum128(_mm_add_ps(b0, b1)),
                d + hsum128(_mm_add_ps(d0, d1)),
            )
        }
    }

    /// Eight floats at a time without FMA: Sandy Bridge and Ivy Bridge, and AMD's
    /// Bulldozer line. Between v2 and v3, which is a gap the psABI levels do not
    /// name but a good many machines still sit in.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "avx")]
    unsafe fn sums_block_avx(
        hay: &[f32],
        hw: u32,
        p: &Prepared,
        ox: u32,
        oy: u32,
    ) -> (f32, f32, f32) {
        use std::arch::x86_64::*;
        let tw = p.w as usize;
        unsafe {
            let (mut a0, mut a1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut b0, mut b1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut d0, mut d1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
            for y in 0..p.h {
                let hp = hay.as_ptr().add(((oy + y) as usize) * (hw as usize) + ox as usize);
                let cp = p.centered.as_ptr().add((y as usize) * tw);
                let mut i = 0usize;
                while i + 16 <= tw {
                    let x0 = _mm256_loadu_ps(hp.add(i));
                    let c0 = _mm256_loadu_ps(cp.add(i));
                    let x1 = _mm256_loadu_ps(hp.add(i + 8));
                    let c1 = _mm256_loadu_ps(cp.add(i + 8));
                    a0 = _mm256_add_ps(a0, x0);
                    a1 = _mm256_add_ps(a1, x1);
                    b0 = _mm256_add_ps(b0, _mm256_mul_ps(x0, x0));
                    b1 = _mm256_add_ps(b1, _mm256_mul_ps(x1, x1));
                    d0 = _mm256_add_ps(d0, _mm256_mul_ps(x0, c0));
                    d1 = _mm256_add_ps(d1, _mm256_mul_ps(x1, c1));
                    i += 16;
                }
                if i + 8 <= tw {
                    let x = _mm256_loadu_ps(hp.add(i));
                    let c = _mm256_loadu_ps(cp.add(i));
                    a0 = _mm256_add_ps(a0, x);
                    b0 = _mm256_add_ps(b0, _mm256_mul_ps(x, x));
                    d0 = _mm256_add_ps(d0, _mm256_mul_ps(x, c));
                    i += 8;
                }
                while i < tw {
                    let x = *hp.add(i);
                    a += x;
                    b += x * x;
                    d += x * *cp.add(i);
                    i += 1;
                }
            }
            (
                a + hsum256(_mm256_add_ps(a0, a1)),
                b + hsum256(_mm256_add_ps(b0, b1)),
                d + hsum256(_mm256_add_ps(d0, d1)),
            )
        }
    }

    /// x86-64-v3 and every Zen up to 3: the same eight floats, with the multiply and
    /// the add fused. This is the kernel the release's `.v3.exe` existed for.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "avx2,fma")]
    unsafe fn sums_block_avx2(
        hay: &[f32],
        hw: u32,
        p: &Prepared,
        ox: u32,
        oy: u32,
    ) -> (f32, f32, f32) {
        use std::arch::x86_64::*;
        let tw = p.w as usize;
        unsafe {
            let (mut a0, mut a1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut b0, mut b1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut d0, mut d1) = (_mm256_setzero_ps(), _mm256_setzero_ps());
            let (mut a, mut b, mut d) = (0.0f32, 0.0f32, 0.0f32);
            for y in 0..p.h {
                let hp = hay.as_ptr().add(((oy + y) as usize) * (hw as usize) + ox as usize);
                let cp = p.centered.as_ptr().add((y as usize) * tw);
                let mut i = 0usize;
                while i + 16 <= tw {
                    let x0 = _mm256_loadu_ps(hp.add(i));
                    let c0 = _mm256_loadu_ps(cp.add(i));
                    let x1 = _mm256_loadu_ps(hp.add(i + 8));
                    let c1 = _mm256_loadu_ps(cp.add(i + 8));
                    a0 = _mm256_add_ps(a0, x0);
                    a1 = _mm256_add_ps(a1, x1);
                    b0 = _mm256_fmadd_ps(x0, x0, b0);
                    b1 = _mm256_fmadd_ps(x1, x1, b1);
                    d0 = _mm256_fmadd_ps(x0, c0, d0);
                    d1 = _mm256_fmadd_ps(x1, c1, d1);
                    i += 16;
                }
                if i + 8 <= tw {
                    let x = _mm256_loadu_ps(hp.add(i));
                    let c = _mm256_loadu_ps(cp.add(i));
                    a0 = _mm256_add_ps(a0, x);
                    b0 = _mm256_fmadd_ps(x, x, b0);
                    d0 = _mm256_fmadd_ps(x, c, d0);
                    i += 8;
                }
                while i < tw {
                    let x = *hp.add(i);
                    a += x;
                    b += x * x;
                    d += x * *cp.add(i);
                    i += 1;
                }
            }
            (
                a + hsum256(_mm256_add_ps(a0, a1)),
                b + hsum256(_mm256_add_ps(b0, b1)),
                d + hsum256(_mm256_add_ps(d0, d1)),
            )
        }
    }

    /// x86-64-v4, znver4 and znver5: sixteen floats at a time, and the leftovers of
    /// a row that is not a multiple of sixteen taken by a masked load rather than
    /// falling out into the scalar loop - which is most of what this tier is worth on
    /// templates cut to whatever size a button happened to be.
    ///
    /// Whether it is used at all is decided by `avx512_pays`, not by CPUID alone.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "avx512f")]
    unsafe fn sums_block_avx512(
        hay: &[f32],
        hw: u32,
        p: &Prepared,
        ox: u32,
        oy: u32,
    ) -> (f32, f32, f32) {
        use std::arch::x86_64::*;
        let tw = p.w as usize;
        unsafe {
            let (mut a0, mut a1) = (_mm512_setzero_ps(), _mm512_setzero_ps());
            let (mut b0, mut b1) = (_mm512_setzero_ps(), _mm512_setzero_ps());
            let (mut d0, mut d1) = (_mm512_setzero_ps(), _mm512_setzero_ps());
            for y in 0..p.h {
                let hp = hay.as_ptr().add(((oy + y) as usize) * (hw as usize) + ox as usize);
                let cp = p.centered.as_ptr().add((y as usize) * tw);
                let mut i = 0usize;
                while i + 32 <= tw {
                    let x0 = _mm512_loadu_ps(hp.add(i));
                    let c0 = _mm512_loadu_ps(cp.add(i));
                    let x1 = _mm512_loadu_ps(hp.add(i + 16));
                    let c1 = _mm512_loadu_ps(cp.add(i + 16));
                    a0 = _mm512_add_ps(a0, x0);
                    a1 = _mm512_add_ps(a1, x1);
                    b0 = _mm512_fmadd_ps(x0, x0, b0);
                    b1 = _mm512_fmadd_ps(x1, x1, b1);
                    d0 = _mm512_fmadd_ps(x0, c0, d0);
                    d1 = _mm512_fmadd_ps(x1, c1, d1);
                    i += 32;
                }
                if i + 16 <= tw {
                    let x = _mm512_loadu_ps(hp.add(i));
                    let c = _mm512_loadu_ps(cp.add(i));
                    a0 = _mm512_add_ps(a0, x);
                    b0 = _mm512_fmadd_ps(x, x, b0);
                    d0 = _mm512_fmadd_ps(x, c, d0);
                    i += 16;
                }
                // The tail, without a second loop. An unmasked load here would read
                // up to fifteen floats past the end of the row, which on the last row
                // of the window is past the end of the haystack.
                let rest = tw - i;
                if rest > 0 {
                    let m: __mmask16 = ((1u32 << rest) - 1) as __mmask16;
                    let z = _mm512_setzero_ps();
                    let x = _mm512_mask_loadu_ps(z, m, hp.add(i));
                    let c = _mm512_mask_loadu_ps(z, m, cp.add(i));
                    a1 = _mm512_add_ps(a1, x);
                    b1 = _mm512_fmadd_ps(x, x, b1);
                    d1 = _mm512_fmadd_ps(x, c, d1);
                }
            }
            (
                _mm512_reduce_add_ps(_mm512_add_ps(a0, a1)),
                _mm512_reduce_add_ps(_mm512_add_ps(b0, b1)),
                _mm512_reduce_add_ps(_mm512_add_ps(d0, d1)),
            )
        }
    }

    /// Folds four lanes down to one.
    ///
    /// Two shuffles and two adds rather than `_mm_hadd_ps`, which is one instruction
    /// fewer and SSE3 - and SSE3 is exactly what the baseline x86-64 tier is not
    /// allowed to assume.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "sse2")]
    unsafe fn hsum128(v: std::arch::x86_64::__m128) -> f32 {
        use std::arch::x86_64::*;
        let hi = _mm_movehl_ps(v, v);
        let s = _mm_add_ps(v, hi);
        let s = _mm_add_ss(s, _mm_shuffle_ps(s, s, 0x55));
        _mm_cvtss_f32(s)
    }

    /// The same for eight lanes. Enabled on plain `avx` rather than `avx2` so that
    /// both 256-bit kernels can share it.
    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "avx")]
    unsafe fn hsum256(v: std::arch::x86_64::__m256) -> f32 {
        use std::arch::x86_64::*;
        // No unsafe block: with the feature enabled these intrinsics are safe, and
        // the caller has already established that the processor has it.
        let s = _mm_add_ps(_mm256_extractf128_ps(v, 1), _mm256_castps256_ps128(v));
        let s = _mm_hadd_ps(s, s);
        let s = _mm_hadd_ps(s, s);
        _mm_cvtss_f32(s)
    }

    /// Best position of `tpl` inside `hay` at one fixed scale.
    /// 0 means "as many as the machine has". Set to 1 to compare a parallel answer
    /// against the answer the single-threaded sweep would have given, which is the
    /// only way to tell a real regression from a template that matches in ten places.
    static MAX_THREADS: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(0);

    pub fn set_max_threads(n: usize) {
        MAX_THREADS.store(n, std::sync::atomic::Ordering::Relaxed);
    }

    /// How many places the coarse pass hands to the fine pass.
    ///
    /// One was not enough, and the failure was the quiet kind. The coarse pass runs
    /// on a shrunken copy; a template much wider than it is tall loses the rows that
    /// tell it apart, so the shrunken copy matches somewhere else just as well.
    /// Measured on a 2560x1440 desktop: a 170x32 button came back **123 px below
    /// itself** with a score of 0.867 - above the default threshold of 0.85, so
    /// nothing was reported as a miss and a `Click image` step would have clicked
    /// the wrong thing. The same template searched inside a 400x200 rectangle scored
    /// 0.9998 in the right place, which is what proved it was the coarse pass and
    /// not the template.
    ///
    /// Four costs four small refinements instead of one - microseconds against the
    /// sweep that produced them - and removes the whole failure mode, because the
    /// true position is reliably *among* the best few coarse answers even when it is
    /// not the first.
    const COARSE_KEEP: usize = 4;

    /// Keeps a shortlist of the best coarse positions, one per neighbourhood.
    ///
    /// Without the separation rule the list fills with four pixels of the same
    /// match, which is one candidate wearing four hats and leaves the real
    /// alternative out.
    fn offer_candidate(
        best: &mut Vec<(u32, u32, f32)>,
        cand: (u32, u32, f32),
        sep: (u32, u32),
    ) {
        // A score that is not a real number is not an answer. Belt and braces
        // alongside the clamp in `score_at`: a shortlist that has taken four of them
        // can never be displaced, because every comparison against NaN is false.
        if !cand.2.is_finite() {
            return;
        }
        if let Some(slot) = best
            .iter_mut()
            .find(|s| s.0.abs_diff(cand.0) < sep.0 && s.1.abs_diff(cand.1) < sep.1)
        {
            if cand.2 > slot.2 {
                *slot = cand;
            }
            return;
        }
        if best.len() < COARSE_KEEP {
            best.push(cand);
            return;
        }
        if let Some(worst) = best.iter_mut().min_by(|a, b| a.2.total_cmp(&b.2))
            && cand.2 > worst.2
        {
            *worst = cand;
        }
    }

    fn find_at_scale(
        hay: &Frame,
        tpl_rgba: &[u8],
        tw: u32,
        th: u32,
        edge: bool,
    ) -> Option<(u32, u32, f32)> {
        if tw == 0 || th == 0 || tw > hay.w || th > hay.h {
            return None;
        }
        let mut hg = plane_grey(&hay.px, hay.w, hay.h, hay.order);
        let (mut tg, tm) = plane(tpl_rgba, tw, th, Order::Rgba);
        if edge {
            hg = sobel(&hg, hay.w, hay.h);
            tg = sobel(&tg, tw, th);
        }

        // Coarse pass on a shrunken copy: a full-resolution sweep of a 4K screen is
        // billions of operations, and the answer is always in the same place anyway.
        // The grid was chosen from the template alone, but the work it implies also
        // depends on the haystack, and a small template on a large screen was
        // pathological: measured on a 2560x1440 desktop, a 32 px template took 465 ms
        // against 64 ms for a 64 px one. It was handed a step of 2, so the coarse pass
        // examined a quarter of every pixel position with a 16x16 kernel - 236 million
        // operations against 25 million for the larger template.
        //
        // So coarsen until the pass fits a budget, and only then: on a small haystack
        // the finer grid is cheap and is kept, which is where its accuracy is worth
        // having.
        const COARSE_BUDGET: u64 = 24_000_000;
        let mut step = (th.min(tw) / 12).clamp(1, 8);
        while step < 8 {
            let positions = (hay.w as u64 / step as u64) * (hay.h as u64 / step as u64);
            let kernel = ((tw / step).max(1) as u64) * ((th / step).max(1) as u64);
            if positions.saturating_mul(kernel) <= COARSE_BUDGET {
                break;
            }
            step += 1;
        }
        let (chay, chw, chh) = shrink(&hg, hay.w, hay.h, step);
        let (ctpl, ctw, cth) = shrink(&tg, tw, th, step);
        let (cmask, _, _) = shrink_mask(&tm, tw, th, step);

        let mut best: Vec<(u32, u32, f32)> = Vec::with_capacity(COARSE_KEEP);
        let coarse = prepare_template(&ctpl, &cmask, ctw, cth);
        if let Some(cp) = coarse.as_ref().filter(|_| ctw <= chw && cth <= chh) {
            let rows = chh - cth + 1;
            let cap = MAX_THREADS.load(std::sync::atomic::Ordering::Relaxed);
            let cores = if cap > 0 {
                cap
            } else {
                std::thread::available_parallelism().map_or(1, |n| n.get())
            };
            // Below a few dozen rows apiece the threads cost more than the work, and a
            // small search area is exactly where that happens.
            let threads = ((rows as usize) / 48).clamp(1, cores);
            let sep = (ctw.max(1), cth.max(1));
            let scan = |lo: u32, hi: u32| {
                let mut keep: Vec<(u32, u32, f32)> = Vec::with_capacity(COARSE_KEEP);
                for oy in lo..hi {
                    for ox in 0..=(chw - ctw) {
                        let sc = score_at(&chay, chw, cp, ox, oy);
                        offer_candidate(&mut keep, (ox, oy, sc), sep);
                    }
                }
                keep
            };
            if threads <= 1 {
                best = scan(0, rows);
            } else {
                let chunk = rows.div_ceil(threads as u32);
                let parts: Vec<Vec<(u32, u32, f32)>> = std::thread::scope(|sc| {
                    let handles: Vec<_> = (0..threads as u32)
                        .map(|t| {
                            let (lo, hi) = (t * chunk, ((t + 1) * chunk).min(rows));
                            sc.spawn(move || scan(lo, hi))
                        })
                        .collect();
                    handles.into_iter().map(|h| h.join().unwrap_or_default()).collect()
                });
                // Merged with the rule the threads themselves used, so the shortlist
                // does not depend on how the rows happened to be divided.
                for part in parts {
                    for c in part {
                        offer_candidate(&mut best, c, sep);
                    }
                }
            }
            // Strongest first, so the fine pass looks at the likeliest place first
            // and ties resolve the way the single-threaded sweep would have.
            best.sort_unstable_by(|a, b| {
                b.2.total_cmp(&a.2).then(a.1.cmp(&b.1)).then(a.0.cmp(&b.0))
            });
        }
        if !best.iter().any(|c| c.2 > -0.5) {
            return None;
        }

        // Refine around each coarse candidate at full resolution and keep the best
        // of them. Refining only the coarse winner is what let a wide, short
        // template come back in the wrong place - see `COARSE_KEEP`.
        let fp = prepare_template(&tg, &tm, tw, th)?;
        let pad = step * 2 + 2;
        let mut fine = (0u32, 0u32, -1.0f32);
        for (bx, by, cs) in &best {
            if *cs < -0.5 {
                continue;
            }
            let cx = bx * step;
            let cy = by * step;
            let x0 = cx.saturating_sub(pad);
            let y0 = cy.saturating_sub(pad);
            let x1 = (cx + pad).min(hay.w - tw);
            let y1 = (cy + pad).min(hay.h - th);
            if x1 < x0 || y1 < y0 {
                continue;
            }
            for oy in y0..=y1 {
                for ox in x0..=x1 {
                    let sc = score_at(&hg, hay.w, &fp, ox, oy);
                    if sc > fine.2 {
                        fine = (ox, oy, sc);
                    }
                }
            }
        }
        (fine.2 > -0.5).then_some(fine)
    }

    /// Looks for `tpl` in `hay`, optionally trying nearby sizes.
    ///
    /// Returns the best hit found even when it is below `threshold`, so the UI can
    /// tell "nothing like it on screen" apart from "almost, try a lower threshold".
    pub fn find(hay: &Frame, tpl: &Template, multiscale: bool) -> Option<Hit> {
        find_mode(hay, tpl, multiscale, false)
    }

    /// The same, with a choice about what is correlated.
    ///
    /// `edge` correlates the outlines instead of the greys. Slower by one pass over
    /// each plane, and the thing to reach for when a template stops matching after
    /// a theme change or under a highlight.
    pub fn find_mode(
        hay: &Frame,
        tpl: &Template,
        multiscale: bool,
        edge: bool,
    ) -> Option<Hit> {
        let scales: &[f32] =
            if multiscale { &[1.0, 0.9, 1.1, 0.8, 1.25] } else { &[1.0] };
        let mut best: Option<Hit> = None;
        for &sc in scales {
            let tw = ((tpl.w as f32 * sc).round() as u32).max(2);
            let th = ((tpl.h as f32 * sc).round() as u32).max(2);
            let rgba = if (sc - 1.0).abs() < f32::EPSILON {
                tpl.rgba.clone()
            } else {
                resize_rgba(&tpl.rgba, tpl.w, tpl.h, tw, th)
            };
            if let Some((ox, oy, score)) = find_at_scale(hay, &rgba, tw, th, edge) {
                let hit = Hit {
                    x: hay.x + ox as i32 + tw as i32 / 2,
                    y: hay.y + oy as i32 + th as i32 / 2,
                    score,
                    scale: sc,
                };
                if best.map(|b| hit.score > b.score).unwrap_or(true) {
                    best = Some(hit);
                }
            }
        }
        best
    }
}

// ============================================================================
// OCR
// ============================================================================

/// Text recognition.
///
/// The backend sits behind a cargo feature so a second one (ONNX models via
/// `oar-ocr`) can be added later without touching anything above this line, and so
/// a build that cannot use WinRT still compiles with `--no-default-features`.
pub mod ocr {
    use serde::{Deserialize, Serialize};

    /// One recognised line, in screen coordinates.
    #[derive(Clone, Debug, PartialEq)]
    pub struct TextBox {
        pub text: String,
        pub x: i32,
        pub y: i32,
        pub w: i32,
        pub h: i32,
    }

    /// What is done to a region's pixels before the engine sees them.
    ///
    /// Windows OCR was built for documents: dark text, light paper, generous size,
    /// and no knobs at all. Screen text is none of those - a pale HUD number over
    /// moving artwork is the hard case - so everything that can be done has to be
    /// done to the pixels first. This is worth more than a second engine would be,
    /// and it adds nothing to the binary.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
    pub enum Prep {
        /// Straight to the engine, bar the enlargement it needs to answer at all.
        /// What every version up to now did.
        #[default]
        None,
        /// Ordinary interface text: grey, with the contrast pulled out to the full
        /// range. Costs nothing when the text was already clean.
        Ui,
        /// The same, enlarged harder. For text too small to have enough pixels.
        Small,
        /// A HUD over artwork: grey, stretched, then cut to black and white at the
        /// threshold that separates them best, so the picture behind stops counting.
        Game,
        /// Digits on a plate: black and white, enlarged hard, nothing else.
        Digits,
        /// Try them in turn and keep the reading that fits the expected format best.
        /// Costs one recognition per rung it has to climb, so it belongs in a step
        /// that runs occasionally, not in a tight polling loop.
        Auto,
    }

    impl Prep {
        /// Everything `Auto` tries, cheapest first.
        pub const LADDER: [Prep; 5] =
            [Prep::None, Prep::Ui, Prep::Small, Prep::Game, Prep::Digits];

        /// The enlargement this profile wants, on top of what the engine needs.
        pub fn min_scale(self) -> u32 {
            match self {
                Prep::Small | Prep::Digits => 3,
                Prep::Game => 2,
                _ => 1,
            }
        }

        pub fn index(self) -> usize {
            match self {
                Prep::None => 0,
                Prep::Ui => 1,
                Prep::Small => 2,
                Prep::Game => 3,
                Prep::Digits => 4,
                Prep::Auto => 5,
            }
        }

        pub fn from_index(i: usize) -> Self {
            match i {
                1 => Prep::Ui,
                2 => Prep::Small,
                3 => Prep::Game,
                4 => Prep::Digits,
                5 => Prep::Auto,
                _ => Prep::None,
            }
        }
    }

    /// Luma, one byte per pixel. Takes the channel order because a screen grab
    /// arrives blue-first and converting it just to weight it would be a wasted
    /// pass over the whole region.
    fn gray_of(px: &[u8], order: crate::vision::Order) -> Vec<u8> {
        let (r, b) = match order {
            crate::vision::Order::Rgba => (299u32, 114u32),
            crate::vision::Order::Bgra => (114u32, 299u32),
        };
        px.as_chunks::<4>().0.iter()
            .map(|p| {
                ((r * p[0] as u32 + 587 * p[1] as u32 + b * p[2] as u32) / 1000) as u8
            })
            .collect()
    }

    /// The darkest and brightest values worth keeping, ignoring `cut` of the pixels
    /// at each end.
    ///
    /// Plain min and max are useless on a screen: one antialiased pixel at pure black
    /// and one at pure white, and the stretch that follows does nothing at all.
    fn ends(g: &[u8], cut: f32) -> (u8, u8) {
        let mut hist = [0u32; 256];
        for &v in g {
            hist[v as usize] += 1;
        }
        let drop = ((g.len() as f32) * cut) as u32;
        let (mut lo, mut hi) = (0u8, 255u8);
        let mut acc = 0u32;
        for (i, &c) in hist.iter().enumerate() {
            acc += c;
            if acc > drop {
                lo = i as u8;
                break;
            }
        }
        acc = 0;
        for (i, &c) in hist.iter().enumerate().rev() {
            acc += c;
            if acc > drop {
                hi = i as u8;
                break;
            }
        }
        (lo, hi)
    }

    /// Pulls the kept range out to the full 0..=255.
    fn stretch(g: &mut [u8], lo: u8, hi: u8) {
        if hi <= lo {
            return;
        }
        let span = (hi - lo) as f32;
        for v in g.iter_mut() {
            *v = (((*v as f32 - lo as f32) / span) * 255.0).clamp(0.0, 255.0) as u8;
        }
    }

    /// Otsu's threshold: the cut that leaves the two halves as unlike each other as
    /// possible.
    ///
    /// Chosen because it has no parameters. How bright a game's HUD is on this
    /// machine, at this time of day, over this background is not something a script
    /// should have to be told.
    pub fn otsu(g: &[u8]) -> u8 {
        let mut hist = [0u64; 256];
        for &v in g {
            hist[v as usize] += 1;
        }
        let total = g.len() as f64;
        if total == 0.0 {
            return 128;
        }
        let sum: f64 = hist.iter().enumerate().map(|(i, &c)| i as f64 * c as f64).sum();
        let (mut w_b, mut sum_b, mut best, mut best_t) = (0.0f64, 0.0f64, -1.0f64, 128u8);
        for (t, &count) in hist.iter().enumerate() {
            w_b += count as f64;
            if w_b == 0.0 {
                continue;
            }
            let w_f = total - w_b;
            if w_f == 0.0 {
                break;
            }
            sum_b += t as f64 * count as f64;
            let d = sum_b / w_b - (sum - sum_b) / w_f;
            let between = w_b * w_f * d * d;
            if between > best {
                best = between;
                best_t = t as u8;
            }
        }
        best_t
    }

    /// Cuts to black and white, ending up with dark text on a light ground whichever
    /// way round it started.
    ///
    /// The engine was trained on documents. Light text on a dark panel is the common
    /// case on a screen and reads markedly worse than its own inverse, so whichever
    /// side is in the minority is taken to be the text.
    fn binarize(g: &mut [u8], t: u8) {
        let dark = g.iter().filter(|&&v| v <= t).count();
        let invert = dark * 2 > g.len();
        for v in g.iter_mut() {
            let light = *v > t;
            *v = if light != invert { 255 } else { 0 };
        }
    }

    fn gray_to_rgba(g: &[u8]) -> Vec<u8> {
        let mut out = vec![0u8; g.len() * 4];
        for (i, &v) in g.iter().enumerate() {
            out[i * 4] = v;
            out[i * 4 + 1] = v;
            out[i * 4 + 2] = v;
            out[i * 4 + 3] = 255;
        }
        out
    }

    /// Applies a profile to a region's pixels.
    ///
    /// Pure and free of anything Windows-shaped, so the whole ladder can be tested
    /// without a screen, an engine or a language pack.
    pub fn prepare(px: &[u8], prep: Prep, order: crate::vision::Order) -> Vec<u8> {
        if prep == Prep::None || px.len() < 4 {
            return px.to_vec();
        }
        let mut g = gray_of(px, order);
        // Digits skips the stretch: it is about to be cut in two anyway, and the
        // stretch only moves where the cut lands.
        if !matches!(prep, Prep::Digits) {
            let (lo, hi) = ends(&g, 0.02);
            stretch(&mut g, lo, hi);
        }
        if matches!(prep, Prep::Game | Prep::Digits) {
            let t = otsu(&g);
            binarize(&mut g, t);
        }
        gray_to_rgba(&g)
    }

    /// What a reading is supposed to look like.
    ///
    /// The useful question is not "how sure is the engine" - that number is on a
    /// scale nobody can interpret, is not comparable between engines, and this one
    /// does not expose it - but "is this the shape of the thing I asked for".
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
    pub enum Expect {
        #[default]
        Any,
        /// Digits, with the separators screens put in them: `1,250` passes.
        Integer,
        /// A number that may carry a decimal point.
        Decimal,
        /// A clock: `2:05` or `1:02:03`.
        Time,
        /// A tiny pattern: `#` one digit, `@` one letter, `?` any one character,
        /// `*` any run including none, everything else itself, case ignored.
        ///
        /// Deliberately not a regular expression. It has to be typeable into a text
        /// box by somebody automating a game, and it must not cost a crate.
        Pattern(String),
    }

    impl Expect {
        pub fn index(&self) -> usize {
            match self {
                Expect::Any => 0,
                Expect::Integer => 1,
                Expect::Decimal => 2,
                Expect::Time => 3,
                Expect::Pattern(_) => 4,
            }
        }

        pub fn from_index(i: usize) -> Self {
            match i {
                1 => Expect::Integer,
                2 => Expect::Decimal,
                3 => Expect::Time,
                4 => Expect::Pattern("##:##".into()),
                _ => Expect::Any,
            }
        }
    }

    /// Does the pattern describe the text?
    pub fn pattern_matches(pat: &str, text: &str) -> bool {
        fn go(p: &[char], t: &[char]) -> bool {
            match p.first() {
                None => t.is_empty(),
                Some('*') => (0..=t.len()).any(|i| go(&p[1..], &t[i..])),
                Some(&c) => match t.first() {
                    None => false,
                    Some(&d) => {
                        let ok = match c {
                            '#' => d.is_ascii_digit(),
                            '@' => d.is_alphabetic(),
                            '?' => true,
                            _ => c.eq_ignore_ascii_case(&d),
                        };
                        ok && go(&p[1..], &t[1..])
                    }
                },
            }
        }
        // A run of stars is one star. Without this, four of them against a long line
        // is exponential, and a pattern typed by hand collects them easily.
        let mut p: Vec<char> = Vec::new();
        for c in pat.chars() {
            if c == '*' && p.last() == Some(&'*') {
                continue;
            }
            p.push(c);
        }
        let t: Vec<char> = text.trim().chars().collect();
        go(&p, &t)
    }

    /// First decimal number in a piece of text.
    ///
    /// `,` is read as a thousands separator and `.` as the point, which is what game
    /// interfaces overwhelmingly use: `1,250.5` is 1250.5.
    pub fn first_decimal(text: &str) -> Option<f64> {
        let mut cur = String::new();
        let mut point = false;
        for ch in text.chars().chain(std::iter::once(' ')) {
            if ch.is_ascii_digit() {
                cur.push(ch);
            } else if ch == ',' && !cur.is_empty() {
                continue;
            } else if ch == '.' && !cur.is_empty() && !point {
                point = true;
                cur.push('.');
            } else if !cur.is_empty() {
                break;
            }
        }
        cur.trim_end_matches('.').parse::<f64>().ok()
    }

    /// Does the reading fit the format that was asked for?
    pub fn accepts(e: &Expect, text: &str) -> bool {
        match e {
            Expect::Any => !text.trim().is_empty(),
            Expect::Integer => first_number(text).is_some(),
            Expect::Decimal => first_decimal(text).is_some(),
            Expect::Time => parse_clock(text).is_some(),
            Expect::Pattern(p) => !p.is_empty() && pattern_matches(p, text),
        }
    }

    /// The number a reading carries, under the format that was asked for.
    pub fn value_of(e: &Expect, text: &str) -> Option<f64> {
        match e {
            Expect::Time => parse_clock(text),
            Expect::Decimal => first_decimal(text),
            Expect::Integer => first_number(text),
            // The old behaviour, and still the right default: a clock reads as
            // seconds, anything else as a plain number.
            _ => parse_clock(text).or_else(|| first_number(text)),
        }
    }

    /// How much a reading looks like what was asked for, from 0 to 1.
    ///
    /// Half of it is whether the format parses at all; half is how much of the text
    /// belongs to the alphabet that format implies. Both halves are needed: a clock
    /// that came back as `O2:3A` fails the first, and a clock lifted out of a
    /// sentence passes the first while failing the second.
    pub fn quality(text: &str, e: &Expect) -> f64 {
        let t = text.trim();
        if t.is_empty() {
            return 0.0;
        }
        let parsed = if accepts(e, t) { 1.0 } else { 0.0 };
        let belongs = |c: char| match e {
            Expect::Integer => c.is_ascii_digit() || matches!(c, ',' | '.'),
            Expect::Decimal => c.is_ascii_digit() || matches!(c, ',' | '.' | '-'),
            Expect::Time => c.is_ascii_digit() || c == ':',
            Expect::Pattern(_) | Expect::Any => {
                c.is_alphanumeric() || c.is_ascii_punctuation()
            }
        };
        let total = t.chars().filter(|c| !c.is_whitespace()).count();
        if total == 0 {
            return 0.0;
        }
        let good = t.chars().filter(|c| !c.is_whitespace() && belongs(*c)).count();
        0.5 * parsed + 0.5 * (good as f64 / total as f64)
    }

    /// Loose text comparison for screen text.
    ///
    /// OCR output is never exactly what a human reads: case wanders, whitespace
    /// doubles up, and stray punctuation appears at the edges. Comparing the
    /// squashed, lower-cased forms is far more useful than an exact match.
    pub fn text_matches(haystack: &str, needle: &str) -> bool {
        fn squash(s: &str) -> String {
            s.to_lowercase()
                .chars()
                .filter(|c| c.is_alphanumeric() || c.is_whitespace())
                .collect::<String>()
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
        }
        let n = squash(needle);
        !n.is_empty() && squash(haystack).contains(&n)
    }

    /// First number in a piece of recognised text.
    ///
    /// Handles the thousands separators OCR picks up from game UIs ("1,250" and
    /// "1 250") and ignores a trailing period so "Gems: 500." reads as 500.
    pub fn first_number(text: &str) -> Option<f64> {
        let mut cur = String::new();
        let mut best: Option<String> = None;
        for ch in text.chars().chain(std::iter::once(' ')) {
            if ch.is_ascii_digit() {
                cur.push(ch);
            } else if (ch == ',' || ch == ' ' || ch == '\u{a0}' || ch == '.') && !cur.is_empty() {
                // Could be a separator inside a number: keep going, decide later.
                cur.push('\u{1}');
            } else if !cur.is_empty() {
                best = Some(std::mem::take(&mut cur));
                break;
            }
        }
        if best.is_none() && !cur.is_empty() {
            best = Some(cur);
        }
        let raw = best?;
        let digits: String = raw.chars().filter(|c| c.is_ascii_digit()).collect();
        digits.parse::<f64>().ok()
    }

    /// Reads a clock like `02:34` or `1:02:03` as a number of seconds.
    pub fn parse_clock(text: &str) -> Option<f64> {
        let cleaned: String = text
            .chars()
            .map(|c| if c.is_ascii_digit() || c == ':' { c } else { ' ' })
            .collect();
        for token in cleaned.split_whitespace() {
            let parts: Vec<&str> = token.split(':').filter(|p| !p.is_empty()).collect();
            if parts.len() < 2 || parts.len() > 3 {
                continue;
            }
            let nums: Option<Vec<f64>> =
                parts.iter().map(|p| p.parse::<f64>().ok()).collect();
            let nums = nums?;
            return Some(match nums.len() {
                2 => nums[0] * 60.0 + nums[1],
                _ => nums[0] * 3600.0 + nums[1] * 60.0 + nums[2],
            });
        }
        None
    }

    /// Joins every recognised line into one string.
    pub fn joined(boxes: &[TextBox]) -> String {
        boxes.iter().map(|b| b.text.as_str()).collect::<Vec<_>>().join("\n")
    }

    /// Enlarges a frame and converts it to the BGRA order SoftwareBitmap expects.
    ///
    /// Nearest neighbour on purpose: rendered glyphs are hard-edged, and smoothing
    /// them on the way up makes recognition worse, not better.
    /// Enlarges a frame into the BGRA order `SoftwareBitmap` expects.
    ///
    /// A frame that already holds BGRA - everything the screen hands back - is
    /// copied four bytes at a time instead of channel by channel. This used to undo
    /// the swap `capture` had just performed: two full passes over the buffer that
    /// cancelled each other out.
    ///
    /// The alpha byte is always written. GDI leaves it at zero, and a zero alpha in
    /// a premultiplied `Bgra8` bitmap is a fully transparent pixel - the engine
    /// would read an empty image and say so.
    #[cfg(all(windows, feature = "winocr"))]
    fn upscale_to_bgra(
        px: &[u8],
        w: u32,
        h: u32,
        k: u32,
        order: crate::vision::Order,
    ) -> (Vec<u8>, u32, u32) {
        let (nw, nh) = (w * k, h * k);
        let mut out = vec![0u8; (nw as usize) * (nh as usize) * 4];
        let swap = order == crate::vision::Order::Rgba;
        for y in 0..nh {
            let sy = y / k;
            for x in 0..nw {
                let sx = x / k;
                let s = ((sy * w + sx) * 4) as usize;
                let d = ((y * nw + x) * 4) as usize;
                if swap {
                    out[d] = px[s + 2];
                    out[d + 1] = px[s + 1];
                    out[d + 2] = px[s];
                } else {
                    out[d] = px[s];
                    out[d + 1] = px[s + 1];
                    out[d + 2] = px[s + 2];
                }
                out[d + 3] = 255;
            }
        }
        (out, nw, nh)
    }

    /// Recognises a region, preparing its pixels first.
    ///
    /// `Auto` is not resolved here: it means "try several", which needs a format to
    /// judge the answers against, and that lives in `read_region_as`.
    pub fn recognize_with(
        frame: &crate::vision::Frame,
        prep: Prep,
    ) -> anyhow::Result<Vec<TextBox>> {
        if prep == Prep::None {
            return recognize_prepared(frame, 1);
        }
        let px = prepare(&frame.px, prep, frame.order);
        // Grey: every channel holds the same byte, so the order label is a
        // formality. `Rgba` is the honest one - `gray_to_rgba` also sets alpha.
        let prepared = crate::vision::Frame::rgba(frame.x, frame.y, frame.w, frame.h, px);
        recognize_prepared(&prepared, prep.min_scale())
    }

    /// The plain reading, with nothing done to the pixels. What 1.3.5 did.
    pub fn recognize(frame: &crate::vision::Frame) -> anyhow::Result<Vec<TextBox>> {
        recognize_with(frame, Prep::None)
    }

    /// Which language the recogniser should read in, or `None` for "whatever this
    /// Windows is set up for".
    ///
    /// Until 1.7.0 there was no choice: the engine was always built from the user's
    /// profile languages. On a Russian Windows an English game read as
    /// `Gems: 1,250` -> `Gems :` with the digits lost entirely, and `02:34` came
    /// back as `а2:34` with a Cyrillic **а** for the zero. Nothing about the picture
    /// was wrong; the recogniser was simply reading the wrong alphabet, and no
    /// amount of pixel preparation could argue it out of that.
    static LANG: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);

    /// Sets the recognition language by BCP-47 tag (`en-US`, `ru-RU`). An empty
    /// string means the profile languages, which is what every version before 1.7.0
    /// did and still the default.
    pub fn set_language(tag: &str) {
        let tag = tag.trim();
        let want = (!tag.is_empty()).then(|| tag.to_string());
        if let Ok(mut slot) = LANG.lock() {
            *slot = want;
        }
    }

    fn chosen_language() -> Option<String> {
        LANG.lock().ok().and_then(|s| s.clone())
    }

    /// Has a recogniser language been picked, or is this still "whatever Windows
    /// displays in"? The checker asks, because a macro reading a game in one
    /// language on a Windows in another reads the right pixels into the wrong
    /// alphabet and reports success.
    pub fn language_chosen() -> bool {
        chosen_language().is_some()
    }

    /// The languages this machine can actually recognise, as (tag, display name).
    ///
    /// Read from the engine rather than from a list of our own: a language pack the
    /// user has not installed must not be offered, because choosing it would fail at
    /// the moment they needed it to work.
    /// Asked once. The interface draws this list every frame the panel is open, and
    /// enumerating WinRT languages sixty times a second to get the same answer would
    /// be a waste; installing a language pack while the program is running is rare
    /// enough to be worth a restart.
    static LANGS: std::sync::OnceLock<Vec<(String, String)>> = std::sync::OnceLock::new();

    pub fn available_languages() -> &'static [(String, String)] {
        LANGS.get_or_init(enumerate_languages)
    }

    #[cfg(all(windows, feature = "winocr"))]
    fn enumerate_languages() -> Vec<(String, String)> {
        use windows::Media::Ocr::OcrEngine;
        let mut out = Vec::new();
        if let Ok(langs) = OcrEngine::AvailableRecognizerLanguages() {
            for l in langs {
                let tag = l.LanguageTag().map(|t| t.to_string_lossy()).unwrap_or_default();
                if tag.is_empty() {
                    continue;
                }
                let name = l
                    .DisplayName()
                    .map(|d| d.to_string_lossy())
                    .unwrap_or_else(|_| tag.clone());
                out.push((tag, name));
            }
        }
        out.sort_by(|a, b| a.1.cmp(&b.1));
        out
    }

    #[cfg(not(all(windows, feature = "winocr")))]
    fn enumerate_languages() -> Vec<(String, String)> {
        Vec::new()
    }

    /// Builds a recogniser for one language, falling back to the profile languages.
    ///
    /// The fallback is not politeness: a language pack can be removed between the
    /// moment it was chosen and the moment a macro runs at four in the morning, and
    /// reading in the wrong alphabet beats not reading at all.
    #[cfg(all(windows, feature = "winocr"))]
    fn engine_for(tag: Option<&str>) -> anyhow::Result<windows::Media::Ocr::OcrEngine> {
        use windows::Globalization::Language;
        use windows::Media::Ocr::OcrEngine;
        if let Some(tag) = tag.map(str::trim).filter(|t| !t.is_empty()) {
            match Language::CreateLanguage(&tag.into())
                .and_then(|l| OcrEngine::TryCreateFromLanguage(&l))
            {
                Ok(engine) => return Ok(engine),
                Err(e) => tracing::warn!(
                    "no text recogniser for '{tag}' on this machine ({e}) - \
                     falling back to the Windows display languages"
                ),
            }
        }
        Ok(OcrEngine::TryCreateFromUserProfileLanguages()?)
    }

    #[cfg(all(windows, feature = "winocr"))]
    fn recognize_prepared(
        frame: &crate::vision::Frame,
        min_scale: u32,
    ) -> anyhow::Result<Vec<TextBox>> {
        use windows::Graphics::Imaging::{BitmapPixelFormat, SoftwareBitmap};
        use windows::Security::Cryptography::CryptographicBuffer;

        if frame.w == 0 || frame.h == 0 {
            return Ok(Vec::new());
        }
        // Windows OCR returns nothing at all for images under 40x40, and small
        // interface text reads much better enlarged. Scale so the short side clears
        // that floor with room to spare, while keeping the long side inside the
        // engine's own limit of roughly 4096 pixels. A profile can ask for more than
        // the floor needs; it can never ask for more than the ceiling allows.
        let short = frame.w.min(frame.h).max(1);
        let long = frame.w.max(frame.h).max(1);
        let want = 64_u32.div_ceil(short);
        let cap = (4000 / long).max(1);
        let scale = want.max(min_scale).clamp(1, 8).min(cap);
        if short * scale < 40 {
            // Fully qualified: this module deliberately imports nothing from the
            // crate root, and an unqualified `warn!` is a rustc attribute here.
            tracing::warn!(
                "region {}x{} is too small for Windows OCR even scaled {scale}x",
                frame.w, frame.h
            );
        }

        let (bgra, bw, bh) =
            upscale_to_bgra(&frame.px, frame.w, frame.h, scale, frame.order);
        let buffer = CryptographicBuffer::CreateFromByteArray(&bgra)?;
        let bitmap = SoftwareBitmap::CreateCopyFromBuffer(
            &buffer,
            BitmapPixelFormat::Bgra8,
            bw as i32,
            bh as i32,
        )?;

        let engine = engine_for(chosen_language().as_deref())?;
        // windows-future 0.3 renamed the blocking wait from get() to join();
        // this runs on the playback thread, so blocking here is intended.
        let result = engine.RecognizeAsync(&bitmap)?.join()?;

        let mut out = Vec::new();
        for line in result.Lines()? {
            let text = line.Text()?.to_string();
            if text.trim().is_empty() {
                continue;
            }
            // A line has no rectangle of its own: take the union of its words.
            let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
            for word in line.Words()? {
                let r = word.BoundingRect()?;
                x0 = x0.min(r.X);
                y0 = y0.min(r.Y);
                x1 = x1.max(r.X + r.Width);
                y1 = y1.max(r.Y + r.Height);
            }
            if x0 > x1 {
                x0 = 0.0;
                y0 = 0.0;
                x1 = 0.0;
                y1 = 0.0;
            }
            let k = scale as f32;
            out.push(TextBox {
                text,
                x: frame.x + (x0 / k) as i32,
                y: frame.y + (y0 / k) as i32,
                w: ((x1 - x0) / k) as i32,
                h: ((y1 - y0) / k) as i32,
            });
        }
        Ok(out)
    }

    #[cfg(not(all(windows, feature = "winocr")))]
    fn recognize_prepared(
        _frame: &crate::vision::Frame,
        _min_scale: u32,
    ) -> anyhow::Result<Vec<TextBox>> {
        Err(anyhow::anyhow!("this build has no OCR backend"))
    }

    /// Recognises a rectangle of the screen.
    pub fn read_region(x: i32, y: i32, w: i32, h: i32) -> anyhow::Result<Vec<TextBox>> {
        let frame = crate::platform::capture(x, y, w, h)
            .ok_or_else(|| anyhow::anyhow!("could not capture the screen"))?;
        recognize(&frame)
    }

    /// What one attempt at a region came back with.
    pub struct Reading {
        pub boxes: Vec<TextBox>,
        /// How well the text fits the format asked for, 0 to 1.
        pub quality: f64,
        /// Which profile produced it. Interesting when `Auto` chose.
        pub prep: Prep,
    }

    impl Reading {
        pub fn text(&self) -> String {
            joined(&self.boxes)
        }
    }

    /// Reads a region, climbing the ladder of profiles when asked to.
    ///
    /// The ladder stops at the first perfect fit rather than always running to the
    /// end: on text that was already clean, `Auto` costs exactly what `None` costs.
    pub fn read_region_as(
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        prep: Prep,
        expect: &Expect,
    ) -> anyhow::Result<Reading> {
        let frame = crate::platform::capture(x, y, w, h)
            .ok_or_else(|| anyhow::anyhow!("could not capture the screen"))?;
        if prep != Prep::Auto {
            let boxes = recognize_with(&frame, prep)?;
            let quality = quality(&joined(&boxes), expect);
            return Ok(Reading { boxes, quality, prep });
        }
        let mut best: Option<Reading> = None;
        let mut last_err: Option<anyhow::Error> = None;
        let mut rungs = 0u64;
        for rung in Prep::LADDER {
            rungs += 1;
            match recognize_with(&frame, rung) {
                Ok(boxes) => {
                    let q = quality(&joined(&boxes), expect);
                    if best.as_ref().is_none_or(|b| q > b.quality) {
                        best = Some(Reading { boxes, quality: q, prep: rung });
                    }
                    if best.as_ref().is_some_and(|b| b.quality >= 0.999) {
                        break;
                    }
                }
                Err(e) => last_err = Some(e),
            }
        }
        // Every rung past the first is a reading the screen did not give up easily.
        // Counted here because here is the only place that knows: the caller asked
        // for `Auto` and got an answer, and the number of goes it took is invisible
        // from outside.
        RETRIES.fetch_add(rungs.saturating_sub(1), std::sync::atomic::Ordering::Relaxed);
        best.ok_or_else(|| {
            last_err.unwrap_or_else(|| anyhow::anyhow!("no profile produced a reading"))
        })
    }

    /// Extra preparation passes, since the program started.
    ///
    /// A free-running counter read as a difference rather than reset, because two
    /// runs cannot overlap but a self-test and a run can, and a counter that one of
    /// them zeroes is a counter the other one misreads.
    static RETRIES: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

    pub fn retries_so_far() -> u64 {
        RETRIES.load(std::sync::atomic::Ordering::Relaxed)
    }
}

// ============================================================================
// UI Automation
// ============================================================================

/// Asking Windows what is on the screen instead of looking at it.
///
/// Where it works, this beats both of the other two: a button found by its name is
/// found at any resolution, under any theme, in any language the application was
/// not translated into, and without a threshold to tune. Where it does not work it
/// is worth saying plainly - and it does not work often:
///
///   * it only sees what an application chooses to expose;
///   * Unity, DirectX, OpenGL and canvas-drawn interfaces expose nothing at all,
///     which includes the game this program was written for;
///   * across a privilege boundary it is limited or silent.
///
/// So the honest arrangement is a cascade: ask here first, fall back to the picture
/// search, then to text recognition, then to fixed coordinates. This is the rung
/// that costs nothing when it works and has to be given up on quickly when it does
/// not.
pub mod uia {
    use serde::{Deserialize, Serialize};

    /// What to look for.
    #[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Default)]
    pub struct Query {
        /// The text a screen reader would read out. Matched without case, exactly
        /// first and then as a substring.
        pub name: String,
        /// The identifier the application gives the control, when it gives one.
        /// Exact, and by far the most reliable thing here when it exists.
        pub automation_id: String,
        /// `Button`, `Edit`, `Text`, `CheckBox`, `List`, `ListItem`, `Tab`,
        /// `TreeItem`, `MenuItem`, `Window`. Empty means any.
        pub control: String,
        /// Search inside the window in front rather than the whole desktop. Much
        /// faster, and almost always what was meant.
        #[serde(default = "yes")]
        pub in_front: bool,
    }

    fn yes() -> bool {
        true
    }

    impl Query {
        /// Does this actually name anything?
        ///
        /// It matters more than it looks. With all three fields empty the conditions
        /// below collapse to "true", and a subtree search for "true" returns the
        /// root - so an unfilled query reported the whole window as found, and
        /// `Press element` fell through to clicking the middle of it. A step that
        /// has just been added from the menu is exactly that query.
        pub fn is_empty(&self) -> bool {
            self.name.trim().is_empty()
                && self.automation_id.trim().is_empty()
                && control_id(&self.control) == 0
        }
    }

    /// What was found.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Found {
        pub name: String,
        /// What the control holds, for the ones that hold something.
        pub value: String,
        /// Centre, in screen coordinates.
        pub x: i32,
        pub y: i32,
        pub w: i32,
        pub h: i32,
    }

    /// The control types worth naming in a picker, and the identifiers Windows uses
    /// for them.
    ///
    /// A short list on purpose: these are the ones an automation script presses,
    /// reads or waits for. The full set has fifty entries and would make the picker
    /// useless.
    pub const CONTROLS: [(&str, i32); 11] = [
        ("", 0),
        ("Button", 50000),
        ("CheckBox", 50002),
        ("ComboBox", 50003),
        ("Edit", 50004),
        ("List", 50008),
        ("ListItem", 50007),
        ("MenuItem", 50011),
        ("Tab", 50018),
        ("Text", 50020),
        ("Window", 50032),
    ];

    pub fn control_id(name: &str) -> i32 {
        CONTROLS
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, id)| *id)
            .unwrap_or(0)
    }

    #[cfg(windows)]
    mod imp {
        use super::{Found, Query, control_id};
        use windows::Win32::Foundation::{HWND, POINT};
        use windows::Win32::System::Com::{CLSCTX_INPROC_SERVER, CoCreateInstance};
        use windows::Win32::System::Variant::{VARIANT, VT_BSTR, VT_I4, VariantClear};
        use windows::Win32::UI::Accessibility::*;
        use windows::Win32::UI::WindowsAndMessaging::GetForegroundWindow;
        use windows::core::{BSTR, Interface};

        thread_local! {
            /// One automation object per thread, kept for the life of the thread.
            ///
            /// Creating it is a COM activation and costs milliseconds; a script that
            /// polls for an element would otherwise pay that on every look.
            static AUTOMATION: std::cell::RefCell<Option<IUIAutomation>> =
                const { std::cell::RefCell::new(None) };
        }

        fn automation() -> Option<IUIAutomation> {
            AUTOMATION.with(|slot| {
                let mut slot = slot.borrow_mut();
                if slot.is_none() {
                    // The caller's thread has already called CoInitializeEx. This is
                    // never reached from the hook thread, where a COM activation
                    // would be a way to have Windows unhook us.
                    *slot = unsafe {
                        CoCreateInstance::<_, IUIAutomation>(
                            &CUIAutomation,
                            None,
                            CLSCTX_INPROC_SERVER,
                        )
                        .ok()
                    };
                }
                slot.clone()
            })
        }

        /// A VARIANT built by hand, released when it goes out of scope.
        ///
        /// windows-rs exposes the raw union here rather than a wrapper, and the union
        /// owns the string it is given, so something has to free it. The conditions
        /// below copy what they need out of it before this drops.
        struct Var(VARIANT);

        impl Var {
            fn int(v: i32) -> Self {
                let mut out = VARIANT::default();
                unsafe {
                    let inner = &mut *out.Anonymous.Anonymous;
                    inner.vt = VT_I4;
                    inner.Anonymous.lVal = v;
                }
                Var(out)
            }

            fn text(s: &str) -> Self {
                let mut out = VARIANT::default();
                unsafe {
                    let inner = &mut *out.Anonymous.Anonymous;
                    inner.vt = VT_BSTR;
                    inner.Anonymous.bstrVal = std::mem::ManuallyDrop::new(BSTR::from(s));
                }
                Var(out)
            }
        }

        impl Drop for Var {
            fn drop(&mut self) {
                unsafe {
                    let _ = VariantClear(&mut self.0);
                }
            }
        }

        /// The element to search from: the window in front, or the desktop.
        fn root(a: &IUIAutomation, in_front: bool) -> Option<IUIAutomationElement> {
            unsafe {
                if in_front {
                    let hwnd: HWND = GetForegroundWindow();
                    if !hwnd.0.is_null()
                        && let Ok(e) = a.ElementFromHandle(hwnd) {
                            return Some(e);
                        }
                }
                a.GetRootElement().ok()
            }
        }

        /// Everything about an element the caller could want, asked for in one trip.
        ///
        /// Every property is a call into another process, and there are several.
        /// Asking one at a time is several round trips into an application that may
        /// be busy; a cache request makes it one.
        fn cache(a: &IUIAutomation) -> Option<IUIAutomationCacheRequest> {
            unsafe {
                let c = a.CreateCacheRequest().ok()?;
                let _ = c.AddProperty(UIA_NamePropertyId);
                let _ = c.AddProperty(UIA_BoundingRectanglePropertyId);
                let _ = c.AddProperty(UIA_ControlTypePropertyId);
                let _ = c.AddPattern(UIA_ValuePatternId);
                let _ = c.AddPattern(UIA_InvokePatternId);
                let _ = c.SetAutomationElementMode(AutomationElementMode_Full);
                Some(c)
            }
        }

        fn pattern<T: Interface>(e: &IUIAutomationElement, id: UIA_PATTERN_ID) -> Option<T> {
            unsafe {
                if let Ok(p) = e.GetCachedPattern(id)
                    && let Ok(t) = p.cast::<T>() {
                        return Some(t);
                    }
                e.GetCurrentPattern(id).ok()?.cast::<T>().ok()
            }
        }

        fn read(e: &IUIAutomationElement) -> Option<Found> {
            unsafe {
                let name = e.CachedName().or_else(|_| e.CurrentName()).unwrap_or_default();
                let value = pattern::<IUIAutomationValuePattern>(e, UIA_ValuePatternId)
                    .and_then(|p| p.CurrentValue().ok())
                    .unwrap_or_default();
                let r = e
                    .CachedBoundingRectangle()
                    .or_else(|_| e.CurrentBoundingRectangle())
                    .ok()?;
                let (w, h) = (r.right - r.left, r.bottom - r.top);
                // A control scrolled out of sight reports an empty rectangle.
                // Reporting its centre as (0, 0) would send a click to the corner of
                // the screen, so it counts as not found.
                if w <= 0 || h <= 0 {
                    return None;
                }
                Some(Found {
                    name: name.to_string(),
                    value: value.to_string(),
                    x: r.left + w / 2,
                    y: r.top + h / 2,
                    w,
                    h,
                })
            }
        }

        /// Conditions for everything that can be matched exactly.
        fn narrow(
            a: &IUIAutomation,
            q: &Query,
            with_name: bool,
        ) -> Option<IUIAutomationCondition> {
            unsafe {
                let mut cond = a.CreateTrueCondition().ok()?;
                let id = control_id(&q.control);
                if id != 0 {
                    let v = Var::int(id);
                    let c = a.CreatePropertyCondition(UIA_ControlTypePropertyId, &v.0).ok()?;
                    cond = a.CreateAndCondition(&cond, &c).ok()?;
                }
                if !q.automation_id.trim().is_empty() {
                    let v = Var::text(q.automation_id.trim());
                    let c =
                        a.CreatePropertyCondition(UIA_AutomationIdPropertyId, &v.0).ok()?;
                    cond = a.CreateAndCondition(&cond, &c).ok()?;
                }
                if with_name && !q.name.trim().is_empty() {
                    let v = Var::text(q.name.trim());
                    let c = a
                        .CreatePropertyConditionEx(
                            UIA_NamePropertyId,
                            &v.0,
                            PropertyConditionFlags_IgnoreCase,
                        )
                        .ok()?;
                    cond = a.CreateAndCondition(&cond, &c).ok()?;
                }
                Some(cond)
            }
        }

        /// One look. The waiting is added by `find`.
        pub fn look(q: &Query) -> Option<(Found, IUIAutomationElement)> {
            if q.is_empty() {
                return None;
            }
            let a = automation()?;
            let root = root(&a, q.in_front)?;
            let cache = cache(&a);
            let want = q.name.trim().to_lowercase();

            unsafe {
                // The exact name first: one call, and the application does the
                // matching. Only when that fails is the wider sweep worth its cost.
                if let Some(cond) = narrow(&a, q, true) {
                    let hit = match &cache {
                        Some(c) => root.FindFirstBuildCache(TreeScope_Subtree, &cond, c).ok(),
                        None => root.FindFirst(TreeScope_Subtree, &cond).ok(),
                    };
                    if let Some(e) = hit
                        && let Some(f) = read(&e) {
                            return Some((f, e));
                        }
                }
                if want.is_empty() {
                    return None;
                }
                // Substring: everything the other conditions allow, filtered here.
                // This is the expensive path, and the reason naming a control type is
                // worth it - it turns a whole tree into a handful of elements.
                let cond = narrow(&a, q, false)?;
                let all = match &cache {
                    Some(c) => root.FindAllBuildCache(TreeScope_Subtree, &cond, c).ok()?,
                    None => root.FindAll(TreeScope_Subtree, &cond).ok()?,
                };
                let n = all.Length().unwrap_or(0);
                for i in 0..n {
                    let Ok(e) = all.GetElement(i) else { continue };
                    let Some(f) = read(&e) else { continue };
                    if f.name.to_lowercase().contains(&want) {
                        return Some((f, e));
                    }
                }
                None
            }
        }

        /// What is under this point, described as a query that would find it again.
        ///
        /// The other direction from `look`, and the whole of what makes recording
        /// able to propose anything: at the moment of a click the interface is on
        /// screen and can be asked what was pressed. An hour later there is nothing
        /// left but a coordinate.
        ///
        /// The element under the cursor is often a label or a panel inside the thing
        /// that was actually pressed, so it walks up the tree until it finds an
        /// ancestor worth naming - one with an automation id, or a control type a
        /// script would press - and stops at the window.
        pub fn at(x: i32, y: i32) -> Option<Query> {
            let a = automation()?;
            unsafe {
                let mut e = a.ElementFromPoint(POINT { x, y }).ok()?;
                for _ in 0..6 {
                    let id = e.CurrentAutomationId().unwrap_or_default().to_string();
                    let name = e.CurrentName().unwrap_or_default().to_string();
                    let ct = e.CurrentControlType().unwrap_or(UIA_CONTROLTYPE_ID(0)).0;
                    let control = super::CONTROLS
                        .iter()
                        .find(|(_, v)| *v == ct)
                        .map(|(n, _)| *n)
                        .unwrap_or("");
                    // A window is where the walk stops: naming the window as the
                    // thing that was clicked is the same mistake as naming the
                    // desktop.
                    if control == "Window" {
                        return None;
                    }
                    // An automation id is the strongest thing here and needs no
                    // name beside it; otherwise a name plus a control type is what a
                    // person would have typed into the picker themselves.
                    let worth_it = !id.trim().is_empty()
                        || (!name.trim().is_empty() && !control.is_empty());
                    if worth_it {
                        return Some(Query {
                            name: if id.trim().is_empty() { name } else { String::new() },
                            automation_id: id,
                            control: control.to_string(),
                            in_front: true,
                        });
                    }
                    let Ok(parent) = control_walker(&a).and_then(|w| w.GetParentElement(&e))
                    else {
                        return None;
                    };
                    e = parent;
                }
                None
            }
        }

        /// The control-view walker, which skips the presentational clutter between a
        /// label and the button it belongs to.
        fn control_walker(a: &IUIAutomation) -> windows::core::Result<IUIAutomationTreeWalker> {
            unsafe { a.ControlViewWalker() }
        }

        /// Presses the element the way the application itself would.
        ///
        /// Better than a synthetic click when it is offered: no cursor moves, no
        /// window has to be in front, and a control that has moved since it was found
        /// is still the control that gets pressed.
        pub fn invoke(e: &IUIAutomationElement) -> bool {
            match pattern::<IUIAutomationInvokePattern>(e, UIA_InvokePatternId) {
                Some(p) => unsafe { p.Invoke().is_ok() },
                None => false,
            }
        }
    }

    #[cfg(not(windows))]
    mod imp {
        use super::{Found, Query};
        pub fn look(q: &Query) -> Option<(Found, ())> {
            let _ = q.is_empty();
            None
        }
        pub fn invoke(_e: &()) -> bool {
            false
        }
        pub fn at(_x: i32, _y: i32) -> Option<Query> {
            None
        }
    }

    /// What is under this screen point, as a query that would find it again.
    ///
    /// `None` in anything that draws its own interface - which is every game engine,
    /// and is the normal answer rather than a failure.
    pub fn at(x: i32, y: i32) -> Option<Query> {
        imp::at(x, y).filter(|q| !q.is_empty())
    }

    /// Looks for an element, waiting up to `timeout_ms` for it to turn up.
    ///
    /// The wait is here rather than in the caller because an interface that is still
    /// drawing itself is the normal case after a click, and a script that has to
    /// write its own retry loop around every element is a script nobody writes.
    pub fn find(q: &Query, timeout_ms: u64) -> Option<Found> {
        if q.is_empty() {
            tracing::warn!("an element step names nothing to look for");
            return None;
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms);
        loop {
            if let Some((f, _)) = imp::look(q) {
                return Some(f);
            }
            if std::time::Instant::now() >= deadline {
                return None;
            }
            std::thread::sleep(std::time::Duration::from_millis(80));
        }
    }

    /// Finds an element and presses it through the application's own pattern.
    ///
    /// Returns what was found when the press went through, and nothing when either
    /// the element was not there or it has no press to offer - which is the caller's
    /// cue to fall back to a real click on the rectangle.
    pub fn press(q: &Query, timeout_ms: u64) -> Option<Found> {
        if q.is_empty() {
            tracing::warn!("an element step names nothing to press");
            return None;
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms);
        loop {
            if let Some((f, e)) = imp::look(q) {
                return imp::invoke(&e).then_some(f);
            }
            if std::time::Instant::now() >= deadline {
                return None;
            }
            std::thread::sleep(std::time::Duration::from_millis(80));
        }
    }
}

// ============================================================================
// Window responsiveness
// ============================================================================

/// How quickly the target window is getting round to its input.
///
/// This is deliberately **not** a frame counter. Reading another process's real
/// present timings means an ETW session against the DXGI providers - what
/// PresentMon does - which needs administrator rights and a schema parser larger
/// than this whole program. `DwmGetCompositionTimingInfo` is no substitute: since
/// Windows 8.1 it reports the compositor, which keeps ticking at the monitor's
/// refresh rate no matter how badly the game underneath it is doing.
///
/// So this measures the quantity that actually matters here instead: how long an
/// empty message takes to travel through the window's own message loop. A normal
/// game loop drains its queue once per frame, so the round-trip lands within about
/// one frame - and that is precisely the delay the frame guard has to cover, since
/// input is handled on the thread that pumps. When a game renders on a separate
/// thread the figure tracks input handling rather than the rendered frame rate,
/// which for this purpose is the more useful of the two.
pub mod perf {
    /// A summary over the last few seconds of probes.
    #[derive(Clone, Copy, Debug, Default)]
    pub struct Stats {
        pub samples: u32,
        pub avg_us: u64,
        /// Mean of the worst 1 % - the "1 % low" of the frame-time vocabulary.
        pub p99_us: u64,
        pub p999_us: u64,
        pub worst_us: u64,
        pub stutters: u32,
        pub found: bool,
    }

    /// Mean of the worst `frac` of the samples.
    ///
    /// Deliberately not a percentile. The 99th percentile of a hundred samples is the
    /// 99th value, which stops one short of the single worst one - precisely the
    /// sample a reader asking for the "1 % low" wants to know about. Averaging the
    /// tail rather than taking its edge also keeps one freak sample from deciding the
    /// answer on its own, which matters because the frame guard is sized from this.
    fn worst_mean(sorted: &[u64], frac: f64) -> u64 {
        if sorted.is_empty() {
            return 0;
        }
        // Always at least one sample, so a short window still answers.
        let k = ((sorted.len() as f64 * frac).ceil() as usize).clamp(1, sorted.len());
        let tail = &sorted[sorted.len() - k..];
        tail.iter().sum::<u64>() / k as u64
    }

    pub fn summarize(samples: &[u64]) -> Stats {
        if samples.is_empty() {
            return Stats::default();
        }
        let mut v = samples.to_vec();
        v.sort_unstable();
        let n = v.len() as u64;
        let avg = v.iter().sum::<u64>() / n;
        // Twice the average, but never less than 8 ms above it: on a window that
        // answers in 200 µs, "twice the average" would call ordinary noise a hitch.
        let hitch = avg.saturating_mul(2).max(avg + 8_000);
        Stats {
            samples: v.len() as u32,
            avg_us: avg,
            p99_us: worst_mean(&v, 0.01),
            p999_us: worst_mean(&v, 0.001),
            worst_us: *v.last().unwrap_or(&0),
            stutters: v.iter().filter(|&&x| x > hitch).count() as u32,
            found: true,
        }
    }
}

// ============================================================================
// Virtual desktop isolation
// ============================================================================

#[cfg(windows)]
mod virtual_desktop {
    use super::win32::*;
    use super::{DESKTOP_TTL_US, now_us};
    use std::cell::RefCell;

    thread_local! {
        static VDM: RefCell<Option<IVirtualDesktopManager>> = const { RefCell::new(None) };
        static CACHE: RefCell<(u64, bool)> = const { RefCell::new((0, true)) };
    }

    pub fn init_thread() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_MULTITHREADED);
            if let Ok(vdm) = CoCreateInstance(&VirtualDesktopManager, None, CLSCTX_ALL) {
                VDM.with(|v| *v.borrow_mut() = Some(vdm));
            }
        }
    }

    fn query(hwnd: HWND) -> bool {
        if hwnd.0.is_null() {
            return true;
        }
        VDM.with(|v| match v.borrow().as_ref() {
            Some(vdm) => unsafe {
                vdm.IsWindowOnCurrentVirtualDesktop(hwnd).unwrap_or_default().as_bool()
            },
            None => true,
        })
    }

    /// True when one of the shell's own window switchers owns the foreground.
    ///
    /// `IsWindowOnCurrentVirtualDesktop` answers honestly and unhelpfully here: Task
    /// View is an overlay drawn *on* the current desktop, so the desktop has not
    /// changed and the check below passes while synthetic clicks land in the switcher
    /// - where they create desktops, close them and move windows between them.
    ///
    /// Asked every time rather than cached, unlike the desktop query: this is two
    /// user32 calls and no COM, and a cache would let a couple of hundred milliseconds
    /// of clicks through before it noticed. Only the two switcher classes are listed.
    /// The Start menu and Search share a class with ordinary packaged apps, and a
    /// macro that silently refuses to run against one of those would be a worse bug
    /// than the one being fixed.
    pub fn shell_switcher_in_front() -> bool {
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.0.is_null() {
                return false;
            }
            let mut buf = [0u16; 64];
            let n = GetClassNameW(hwnd, &mut buf);
            if n <= 0 {
                return false;
            }
            matches!(
                String::from_utf16_lossy(&buf[..n as usize]).as_str(),
                // Windows 11 Task View and Alt+Tab.
                "XamlExplorerHostIslandWindow"
                // Windows 10 Task View.
                | "MultitaskingViewFrame"
            )
        }
    }

    /// Throttled: a COM round-trip per keystroke would get the hook killed.
    pub fn is_app_on_active_desktop_cached(hwnd: HWND) -> bool {
        let now = now_us();
        CACHE.with(|c| {
            let mut c = c.borrow_mut();
            if c.0 == 0 || now.saturating_sub(c.0) >= DESKTOP_TTL_US {
                c.0 = now;
                c.1 = query(hwnd);
            }
            c.1
        })
    }
}

#[cfg(not(windows))]
mod virtual_desktop {
    pub fn init_thread() {}
    pub fn is_app_on_active_desktop_cached(_: ()) -> bool {
        true
    }
    pub fn shell_switcher_in_front() -> bool {
        false
    }
}

// ============================================================================
// Platform layer
// ============================================================================

#[cfg(windows)]
mod platform {
    use super::win32::*;
    use super::{APP_TITLE, EndAction, METRICS_TTL_US, WindowAnchor, now_us, wide};
    use std::ffi::c_void;
    use std::sync::atomic::{AtomicI32, AtomicIsize, AtomicU64, Ordering};

    static HWND_CACHE: AtomicIsize = AtomicIsize::new(0);
    static HWND_LAST_TRY: AtomicU64 = AtomicU64::new(0);
    static VS: [AtomicI32; 4] =
        [AtomicI32::new(0), AtomicI32::new(0), AtomicI32::new(1), AtomicI32::new(1)];
    static VS_LAST: AtomicU64 = AtomicU64::new(0);

    /// Our own top-level window, cached and validated against the process id.
    pub fn app_hwnd() -> HWND {
        let cached = HWND_CACHE.load(Ordering::Relaxed);
        if cached != 0 {
            let hwnd = HWND(cached as *mut c_void);
            if unsafe { IsWindow(Some(hwnd)) }.as_bool() {
                return hwnd;
            }
            HWND_CACHE.store(0, Ordering::Relaxed);
        }
        let now = now_us();
        let last = HWND_LAST_TRY.load(Ordering::Relaxed);
        if last != 0 && now.saturating_sub(last) < 1_000_000 {
            return HWND::default();
        }
        HWND_LAST_TRY.store(now, Ordering::Relaxed);

        unsafe {
            let title = wide(APP_TITLE);
            if let Ok(hwnd) = FindWindowW(None, PCWSTR(title.as_ptr()))
                && !hwnd.0.is_null() {
                    let mut pid = 0u32;
                    let _ = GetWindowThreadProcessId(hwnd, Some(&mut pid));
                    if pid == GetCurrentProcessId() {
                        HWND_CACHE.store(hwnd.0 as isize, Ordering::Relaxed);
                        return hwnd;
                    }
                }
        }
        HWND::default()
    }

    pub fn apply_system_backdrop(hwnd: HWND, backdrop: i32) {
        if hwnd.0.is_null() {
            return;
        }
        unsafe {
            let dark_mode: i32 = 1;
            let _ = DwmSetWindowAttribute(
                hwnd,
                DWMWA_USE_IMMERSIVE_DARK_MODE,
                &dark_mode as *const i32 as *const c_void,
                std::mem::size_of::<i32>() as u32,
            );
            // DWMWA_SYSTEMBACKDROP_TYPE: 1 = none, 2 = Mica, 3 = Acrylic, 4 = Tabbed.
            let backdrop_type: i32 = backdrop;
            let result = DwmSetWindowAttribute(
                hwnd,
                DWMWINDOWATTRIBUTE(38),
                &backdrop_type as *const i32 as *const c_void,
                std::mem::size_of::<i32>() as u32,
            );
            if result.is_err() && backdrop > 1 {
                let bb = DWM_BLURBEHIND {
                    dwFlags: DWM_BB_ENABLE,
                    fEnable: true.into(),
                    hRgnBlur: HRGN::default(),
                    fTransitionOnMaximized: false.into(),
                };
                let _ = DwmEnableBlurBehindWindow(hwnd, &bb);
            }
        }
    }

    fn virtual_screen() -> (i32, i32, i32, i32) {
        let now = now_us();
        let last = VS_LAST.load(Ordering::Relaxed);
        if last == 0 || now.saturating_sub(last) >= METRICS_TTL_US {
            unsafe {
                VS[0].store(GetSystemMetrics(SM_XVIRTUALSCREEN), Ordering::Relaxed);
                VS[1].store(GetSystemMetrics(SM_YVIRTUALSCREEN), Ordering::Relaxed);
                VS[2].store(GetSystemMetrics(SM_CXVIRTUALSCREEN).max(1), Ordering::Relaxed);
                VS[3].store(GetSystemMetrics(SM_CYVIRTUALSCREEN).max(1), Ordering::Relaxed);
            }
            VS_LAST.store(now, Ordering::Relaxed);
        }
        (
            VS[0].load(Ordering::Relaxed),
            VS[1].load(Ordering::Relaxed),
            VS[2].load(Ordering::Relaxed),
            VS[3].load(Ordering::Relaxed),
        )
    }

    /// `w - 1` as the denominator so the right/bottom-most pixel stays reachable.
    pub fn normalize_abs(x: i32, y: i32, vx: i32, vy: i32, vw: i32, vh: i32) -> (i32, i32) {
        let dx = (vw - 1).max(1) as f64;
        let dy = (vh - 1).max(1) as f64;
        let nx = (((x - vx) as f64 / dx) * 65535.0).round().clamp(0.0, 65535.0) as i32;
        let ny = (((y - vy) as f64 / dy) * 65535.0).round().clamp(0.0, 65535.0) as i32;
        (nx, ny)
    }

    pub unsafe fn send_absolute_mouse_move(x: i32, y: i32) {
        unsafe {
            let (vx, vy, vw, vh) = virtual_screen();
            let (nx, ny) = normalize_abs(x, y, vx, vy, vw, vh);
            let input = INPUT {
                r#type: INPUT_MOUSE,
                Anonymous: INPUT_0 {
                    mi: MOUSEINPUT {
                        dx: nx,
                        dy: ny,
                        mouseData: 0,
                        dwFlags: MOUSEEVENTF_MOVE
                            | MOUSEEVENTF_ABSOLUTE
                            | MOUSEEVENTF_VIRTUALDESK,
                        time: 0,
                        dwExtraInfo: 0,
                    },
                },
            };
            if !crate::selftest::send_blocked() {
                SendInput(&[input], std::mem::size_of::<INPUT>() as i32);
            }
        }
    }

    pub fn begin_high_res_timer() {
        unsafe {
            let _ = timeBeginPeriod(1);
        }
    }
    pub fn end_high_res_timer() {
        unsafe {
            let _ = timeEndPeriod(1);
        }
    }

    /// Colour of a screen pixel, or None if the read failed.
    pub fn screen_pixel(x: i32, y: i32) -> Option<(u8, u8, u8)> {
        unsafe {
            let hdc = GetDC(None);
            if hdc.is_invalid() {
                return None;
            }
            let c = GetPixel(hdc, x, y);
            ReleaseDC(None, hdc);
            if c.0 == 0xFFFF_FFFF {
                return None;
            }
            Some(((c.0 & 0xFF) as u8, ((c.0 >> 8) & 0xFF) as u8, ((c.0 >> 16) & 0xFF) as u8))
        }
    }


    // ---------------------------------------------------------------------
    // Desktop Duplication
    // ---------------------------------------------------------------------
    //
    // `BitBlt` out of the desktop DC costs about six milliseconds before it has
    // copied a single useful pixel, and the same blit between two memory DCs of
    // the same size costs 0.13 ms. Both numbers are printed by `--selftest vision`
    // under "Where a capture goes". The gap is the readback: the composited
    // desktop does not live in system memory, and GDI has to go and fetch it every
    // time. Nothing about the destination bitmap changes that - the table prices a
    // DIB section against the device bitmap it replaced and they come out equal.
    //
    // Desktop Duplication is the interface that does not pay it. The compositor
    // hands over the surface it already has, the copy that reaches the CPU is only
    // the rectangle that was asked for, and - the part that matters most for a
    // script polling a settled screen - a frame that has not changed is not sent
    // at all, so the poll costs one sub-rectangle copy out of a texture that is
    // already there.
    //
    // Every failure here falls back to GDI rather than failing the capture: an
    // older machine, a remote session, a driver that says no, a rectangle that
    // straddles two monitors, or a rotated display all keep working exactly as
    // they did.
    #[cfg(windows)]
    mod dupe {
        use super::super::win32::RECT;
        use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
        use windows::Win32::Graphics::Direct3D::{
            D3D_DRIVER_TYPE_HARDWARE, D3D_FEATURE_LEVEL_10_0, D3D_FEATURE_LEVEL_11_0,
        };
        use windows::Win32::Graphics::Direct3D11::{
            D3D11_BOX, D3D11_CPU_ACCESS_READ, D3D11_CREATE_DEVICE_BGRA_SUPPORT,
            D3D11_MAP_READ, D3D11_MAPPED_SUBRESOURCE, D3D11_SDK_VERSION,
            D3D11_TEXTURE2D_DESC, D3D11_USAGE_DEFAULT, D3D11_USAGE_STAGING,
            D3D11CreateDevice, ID3D11Device, ID3D11DeviceContext, ID3D11Texture2D,
        };
        use windows::Win32::Graphics::Dxgi::Common::{
            DXGI_FORMAT_B8G8R8A8_UNORM, DXGI_MODE_ROTATION_IDENTITY, DXGI_SAMPLE_DESC,
        };
        use windows::Win32::Graphics::Dxgi::{
            DXGI_ERROR_ACCESS_LOST, DXGI_ERROR_WAIT_TIMEOUT, DXGI_OUTDUPL_FRAME_INFO,
            IDXGIDevice, IDXGIOutput1, IDXGIOutputDuplication, IDXGIResource,
        };
        use windows::core::Interface as _;

        /// Turned off by a configuration switch. Process-wide, because it is a
        /// setting rather than a discovery.
        static ENABLED: AtomicBool = AtomicBool::new(true);

        // Turned off for good, on this thread, by three consecutive failures - a
        // machine that cannot do this should stop being asked twenty times a
        // second.
        //
        // Per thread rather than process-wide, and that is not a detail. Each
        // thread duplicates the output for itself, so a thread that cannot get one
        // - because another already holds it, because it started while a
        // full-screen application had the output, because the monitor it asked
        // about has since been unplugged - is saying something about itself and
        // not about the machine. A global count would let one unlucky search
        // thread put every future playback back on the slow path for the rest of
        // the session, and nothing would ever say why.
        thread_local! {
            static STRIKES: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
        }
        /// Counts what the fast path actually did, for the benchmark and the log.
        pub static HITS: AtomicU64 = AtomicU64::new(0);
        pub static REUSED: AtomicU64 = AtomicU64::new(0);
        pub static MISSES: AtomicU64 = AtomicU64::new(0);

        const MAX_STRIKES: u64 = 3;

        pub fn set_enabled(on: bool) {
            ENABLED.store(on, Ordering::Relaxed);
            if on {
                // Only this thread's count. Another thread that has given up did so
                // for a reason that flipping a setting does not change; it clears
                // its own when a capture next works.
                STRIKES.with(|c| c.set(0));
            }
        }

        pub fn enabled() -> bool {
            ENABLED.load(Ordering::Relaxed) && STRIKES.with(|c| c.get()) < MAX_STRIKES
        }

        pub fn counters() -> (u64, u64, u64) {
            (
                HITS.load(Ordering::Relaxed),
                REUSED.load(Ordering::Relaxed),
                MISSES.load(Ordering::Relaxed),
            )
        }

        pub fn reset_counters() {
            HITS.store(0, Ordering::Relaxed);
            REUSED.store(0, Ordering::Relaxed);
            MISSES.store(0, Ordering::Relaxed);
        }

        fn strike(why: &str) {
            let n = STRIKES.with(|c| {
                let n = c.get() + 1;
                c.set(n);
                n
            });
            if n == MAX_STRIKES {
                tracing::warn!(
                    "desktop duplication gave up on this thread after {n} failures ({why}); \
                     screen captures fall back to GDI"
                );
            }
        }

        /// One duplicated output plus the textures that go with it.
        ///
        /// `latest` is a full-size copy of the last frame the compositor handed
        /// over, kept on the GPU. It exists so that a poll which finds no new frame
        /// still has the current screen to cut a rectangle out of: a settled screen
        /// sends nothing, and without this the second look would have nothing to
        /// look at.
        struct Dup {
            device: ID3D11Device,
            ctx: ID3D11DeviceContext,
            dup: IDXGIOutputDuplication,
            /// The output's rectangle in desktop coordinates.
            bounds: RECT,
            latest: Option<ID3D11Texture2D>,
            /// Staging texture sized to the last rectangle asked for.
            stage: Option<(ID3D11Texture2D, u32, u32)>,
        }

        thread_local! {
            static DUP: std::cell::RefCell<Option<Dup>> = const {
                std::cell::RefCell::new(None)
            };
        }

        pub fn release() {
            DUP.with(|d| {
                *d.borrow_mut() = None;
            });
            // A run that has ended takes its verdict with it. The next one may find
            // the output free, the resolution settled, or the game closed.
            STRIKES.with(|c| c.set(0));
        }

        /// Builds a duplication for the output that wholly contains `want`.
        ///
        /// A rectangle spanning two monitors is refused rather than stitched: one
        /// duplication is one output, and a script that sweeps both screens is
        /// better served by the path that already handles it than by half a frame.
        unsafe fn build(want: RECT) -> Option<Dup> {
            unsafe {
                let mut device: Option<ID3D11Device> = None;
                let mut ctx: Option<ID3D11DeviceContext> = None;
                let levels = [D3D_FEATURE_LEVEL_11_0, D3D_FEATURE_LEVEL_10_0];
                D3D11CreateDevice(
                    None,
                    D3D_DRIVER_TYPE_HARDWARE,
                    super::super::win32::HMODULE::default(),
                    D3D11_CREATE_DEVICE_BGRA_SUPPORT,
                    Some(&levels),
                    D3D11_SDK_VERSION,
                    Some(&mut device),
                    None,
                    Some(&mut ctx),
                )
                .ok()?;
                let device = device?;
                let ctx = ctx?;

                let dxgi: IDXGIDevice = device.cast().ok()?;
                let adapter = dxgi.GetAdapter().ok()?;
                let mut i = 0u32;
                while let Ok(output) = adapter.EnumOutputs(i) {
                    i += 1;
                    let desc = output.GetDesc().ok()?;
                    // A rotated output arrives rotated, and un-rotating it here
                    // would cost more than the readback it saves.
                    if desc.Rotation != DXGI_MODE_ROTATION_IDENTITY {
                        continue;
                    }
                    let b = desc.DesktopCoordinates;
                    let holds = want.left >= b.left
                        && want.top >= b.top
                        && want.right <= b.right
                        && want.bottom <= b.bottom;
                    if !holds {
                        continue;
                    }
                    let out1: IDXGIOutput1 = output.cast().ok()?;
                    let dup = out1.DuplicateOutput(&device).ok()?;
                    return Some(Dup {
                        device,
                        ctx,
                        dup,
                        bounds: b,
                        latest: None,
                        stage: None,
                    });
                }
                None
            }
        }

        impl Dup {
            /// Pulls the newest frame across, if the compositor has one.
            ///
            /// `Ok(false)` means nothing changed, which is the common answer while a
            /// script waits for a button and is the reason this is fast at all.
            unsafe fn pump(&mut self, patient: bool) -> Result<bool, windows::core::Error> {
                unsafe {
                    let mut info = DXGI_OUTDUPL_FRAME_INFO::default();
                    let mut res: Option<IDXGIResource> = None;
                    // Nothing yet to fall back on: wait briefly for the first
                    // frame. Afterwards never block - a poll that sleeps to learn
                    // that nothing moved is worse than the blit it replaced.
                    //
                    // The wait is short and it is struck against, because the
                    // compositor sends a frame when something *changes*: a screen
                    // that is genuinely frozen sends nothing, and a patient wait
                    // followed by a GDI fallback would then be slower than GDI on
                    // its own. Three of those and this thread stops asking.
                    let timeout = if patient { 60 } else { 0 };
                    match self.dup.AcquireNextFrame(timeout, &mut info, &mut res) {
                        Ok(()) => {}
                        Err(e) if e.code() == DXGI_ERROR_WAIT_TIMEOUT => return Ok(false),
                        Err(e) => return Err(e),
                    }
                    let got = (|| -> Result<bool, windows::core::Error> {
                        let res = res.ok_or_else(|| {
                            windows::core::Error::from(DXGI_ERROR_ACCESS_LOST)
                        })?;
                        // AccumulatedFrames of 0 with a desktop pointer is a
                        // cursor-only update: the pixels behind it did not move,
                        // and the texture it hands over does not hold a desktop
                        // image at all.
                        //
                        // Until 1.7.0 this read `&& self.latest.is_some()`, which
                        // let the very first acquire through - and the first
                        // acquire is the one most likely to be cursor-only,
                        // because a cursor twitch is what wakes the compositor on
                        // an otherwise still screen. The black texture was then
                        // copied in as "the screen", and because `capture` had
                        // returned `Some`, the GDI fallback below it never ran.
                        // The visible symptom was that the *first* image search of
                        // every run silently found nothing: a macro whose first
                        // step was `Click image` with `stop` on a miss ended on
                        // that step, while the same macro inside a `While` loop
                        // corrected itself on the second look and nobody noticed.
                        //
                        // Refusing it whatever the state is the whole fix: with no
                        // first frame yet, `capture` now returns `None` and GDI
                        // answers, which is what it was always meant to do.
                        if info.LastPresentTime == 0 {
                            return Ok(false);
                        }
                        let tex: ID3D11Texture2D = res.cast()?;
                        if self.latest.is_none() {
                            let mut desc = D3D11_TEXTURE2D_DESC::default();
                            tex.GetDesc(&mut desc);
                            desc.Usage = D3D11_USAGE_DEFAULT;
                            desc.BindFlags = 0;
                            desc.CPUAccessFlags = 0;
                            desc.MiscFlags = 0;
                            let mut made: Option<ID3D11Texture2D> = None;
                            self.device.CreateTexture2D(&desc, None, Some(&mut made))?;
                            self.latest = made;
                        }
                        let Some(dst) = self.latest.as_ref() else {
                            return Ok(false);
                        };
                        // Stays on the GPU. The only thing that crosses to the CPU
                        // is the rectangle the caller asked for, below.
                        self.ctx.CopyResource(dst, &tex);
                        Ok(true)
                    })();
                    let _ = self.dup.ReleaseFrame();
                    got
                }
            }

            /// Copies one rectangle of the last frame into system memory, BGRA.
            unsafe fn read(&mut self, x: i32, y: i32, w: u32, h: u32) -> Option<Vec<u8>> {
                unsafe {
                    let src = self.latest.as_ref()?.clone();
                    let fits = self.stage.as_ref().is_some_and(|(_, sw, sh)| *sw == w && *sh == h);
                    if !fits {
                        let desc = D3D11_TEXTURE2D_DESC {
                            Width: w,
                            Height: h,
                            MipLevels: 1,
                            ArraySize: 1,
                            Format: DXGI_FORMAT_B8G8R8A8_UNORM,
                            SampleDesc: DXGI_SAMPLE_DESC { Count: 1, Quality: 0 },
                            Usage: D3D11_USAGE_STAGING,
                            BindFlags: 0,
                            CPUAccessFlags: D3D11_CPU_ACCESS_READ.0 as u32,
                            MiscFlags: 0,
                        };
                        let mut made: Option<ID3D11Texture2D> = None;
                        self.device.CreateTexture2D(&desc, None, Some(&mut made)).ok()?;
                        self.stage = made.map(|t| (t, w, h));
                    }
                    let (stage, _, _) = self.stage.as_ref()?;
                    // Desktop coordinates into output-local ones.
                    let lx = (x - self.bounds.left).max(0) as u32;
                    let ly = (y - self.bounds.top).max(0) as u32;
                    let region = D3D11_BOX {
                        left: lx,
                        top: ly,
                        front: 0,
                        right: lx + w,
                        bottom: ly + h,
                        back: 1,
                    };
                    self.ctx.CopySubresourceRegion(
                        stage,
                        0,
                        0,
                        0,
                        0,
                        &src,
                        0,
                        Some(&region),
                    );
                    let mut map = D3D11_MAPPED_SUBRESOURCE::default();
                    self.ctx.Map(stage, 0, D3D11_MAP_READ, 0, Some(&mut map)).ok()?;
                    let row = (w as usize) * 4;
                    let n = row * (h as usize);
                    let mut buf: Vec<u8> = Vec::with_capacity(n);
                    let pitch = map.RowPitch as usize;
                    if map.pData.is_null() || pitch < row {
                        self.ctx.Unmap(stage, 0);
                        return None;
                    }
                    // The pitch is the driver's, not ours, and is routinely larger
                    // than the row: copying the block whole would shear the image.
                    for r in 0..h as usize {
                        std::ptr::copy_nonoverlapping(
                            (map.pData as *const u8).add(r * pitch),
                            buf.as_mut_ptr().add(r * row),
                            row,
                        );
                    }
                    buf.set_len(n);
                    self.ctx.Unmap(stage, 0);
                    Some(buf)
                }
            }
        }

        /// The fast path. `None` means "GDI, please" and is never an error the
        /// caller has to handle.
        pub fn capture(x: i32, y: i32, w: i32, h: i32) -> Option<Vec<u8>> {
            if !enabled() {
                return None;
            }
            // Saturating, not wrapping. A `Read text` step takes its rectangle from
            // whatever somebody typed into the box, and an x of `i32::MAX` would
            // otherwise wrap `right` to a negative number - which is a rectangle the
            // containment test below would happily accept.
            let want = RECT {
                left: x,
                top: y,
                right: x.saturating_add(w),
                bottom: y.saturating_add(h),
            };
            DUP.with(|cell| {
                let mut slot = cell.borrow_mut();
                let holds = slot.as_ref().is_some_and(|d| {
                    want.left >= d.bounds.left
                        && want.top >= d.bounds.top
                        && want.right <= d.bounds.right
                        && want.bottom <= d.bounds.bottom
                });
                if !holds {
                    *slot = None;
                    *slot = unsafe { build(want) };
                }
                let Some(d) = slot.as_mut() else {
                    MISSES.fetch_add(1, Ordering::Relaxed);
                    strike("no duplicable output holds the rectangle");
                    return None;
                };
                let patient = d.latest.is_none();
                match unsafe { d.pump(patient) } {
                    Ok(true) => {
                        HITS.fetch_add(1, Ordering::Relaxed);
                        STRIKES.with(|c| c.set(0));
                    }
                    Ok(false) if d.latest.is_some() => {
                        // Nothing changed, so the frame already here is the screen.
                        REUSED.fetch_add(1, Ordering::Relaxed);
                        STRIKES.with(|c| c.set(0));
                    }
                    Ok(false) => {
                        // Never got a first frame; GDI can answer this one. A strike,
                        // so a screen that never changes cannot make every capture
                        // pay the wait before falling back anyway.
                        MISSES.fetch_add(1, Ordering::Relaxed);
                        strike("no first frame arrived");
                        return None;
                    }
                    Err(e) => {
                        // Access lost happens on a resolution change, a session
                        // switch, or a full-screen application taking the output.
                        // Rebuilding is the documented cure, and it is not a
                        // failure worth a strike.
                        tracing::debug!("desktop duplication reset: {e}");
                        *slot = None;
                        MISSES.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }
                }
                let out = unsafe { d.read(x, y, w as u32, h as u32) };
                if out.is_none() {
                    MISSES.fetch_add(1, Ordering::Relaxed);
                    *slot = None;
                    strike("the staging copy failed");
                }
                out
            })
        }
    }

    #[cfg(windows)]
    pub use dupe::{
        counters as capture_counters, reset_counters as reset_capture_counters,
        set_enabled as set_fast_capture,
    };

    /// A memory DC and a DIB kept alive between captures, one per thread.
    ///
    /// Three costs used to be paid on every single look at the screen: a memory DC
    /// and a bitmap created and destroyed (GDI object churn, against a per-process
    /// quota of 10 000 objects), a fresh zeroed allocation, and a `GetDIBits` that
    /// copied and reformatted the whole frame a second time.
    ///
    /// A DIB section removes the second copy outright - `BitBlt` writes straight
    /// into memory this process can already read - and caching it removes the
    /// churn. The playback thread looks at the same rectangle thousands of times in
    /// a row, so the cache hits essentially always; a size change throws it away
    /// and builds the next one.
    struct DibCache {
        mem: HDC,
        bmp: HBITMAP,
        old: HGDIOBJ,
        bits: *mut u8,
        w: i32,
        h: i32,
    }

    impl DibCache {
        /// `None` if GDI would not give us either object. Nothing is leaked on the
        /// way out: each step undoes itself.
        unsafe fn new(w: i32, h: i32) -> Option<Self> {
            unsafe {
                let mem = CreateCompatibleDC(None);
                if mem.is_invalid() {
                    return None;
                }
                let info = BITMAPINFO {
                    bmiHeader: BITMAPINFOHEADER {
                        biSize: std::mem::size_of::<BITMAPINFOHEADER>() as u32,
                        biWidth: w,
                        biHeight: -h, // top-down, so row 0 is the top one
                        biPlanes: 1,
                        biBitCount: 32,
                        biCompression: BI_RGB.0,
                        ..Default::default()
                    },
                    ..Default::default()
                };
                let mut bits: *mut c_void = std::ptr::null_mut();
                let made = CreateDIBSection(None, &info, DIB_RGB_COLORS, &mut bits, None, 0);
                let Ok(bmp) = made else {
                    let _ = DeleteDC(mem);
                    return None;
                };
                if bits.is_null() {
                    let _ = DeleteObject(HGDIOBJ(bmp.0));
                    let _ = DeleteDC(mem);
                    return None;
                }
                let old = SelectObject(mem, HGDIOBJ(bmp.0));
                Some(Self { mem, bmp, old, bits: bits as *mut u8, w, h })
            }
        }

        #[inline]
        fn bytes(&self) -> usize {
            (self.w as usize) * (self.h as usize) * 4
        }
    }

    impl Drop for DibCache {
        fn drop(&mut self) {
            unsafe {
                SelectObject(self.mem, self.old);
                let _ = DeleteObject(HGDIOBJ(self.bmp.0));
                let _ = DeleteDC(self.mem);
            }
        }
    }

    thread_local! {
        static DIB: std::cell::RefCell<Option<DibCache>> = const {
            std::cell::RefCell::new(None)
        };
    }

    /// Drops this thread's cached bitmap. Called when a playback run ends, so a
    /// full-screen grab does not sit on 14 MB of committed memory afterwards.
    pub fn release_capture_cache() {
        DIB.with(|c| {
            *c.borrow_mut() = None;
        });
        #[cfg(windows)]
        dupe::release();
    }

    /// Just the screen DC, taken and given back. The fixed cost of asking GDI for
    /// the desktop, with no pixels moved. Benchmark only.
    pub fn probe_screen_dc() -> bool {
        unsafe {
            let screen = GetDC(None);
            if screen.is_invalid() {
                return false;
            }
            ReleaseDC(None, screen);
            true
        }
    }

    /// A capture that stops before the copy out: DC, `BitBlt` into the cached DIB,
    /// DC back. What the frame costs to *reach*, as opposed to to own. Benchmark
    /// only - the pixels are left in the cache and nobody reads them.
    pub fn probe_blt(x: i32, y: i32, w: i32, h: i32) -> bool {
        if w <= 0 || h <= 0 {
            return false;
        }
        unsafe {
            let screen = GetDC(None);
            if screen.is_invalid() {
                return false;
            }
            let ok = DIB.with(|cell| {
                let mut slot = cell.borrow_mut();
                if !slot.as_ref().is_some_and(|c| c.w == w && c.h == h) {
                    *slot = None;
                    *slot = DibCache::new(w, h);
                }
                let Some(cache) = slot.as_ref() else { return false };
                BitBlt(cache.mem, 0, 0, w, h, Some(screen), x, y, SRCCOPY).is_ok()
            });
            ReleaseDC(None, screen);
            ok
        }
    }

    /// The old arrangement: a device-format bitmap made and thrown away each time,
    /// which is what a DIB section replaced. Benchmark only, kept so the claim that
    /// the destination was never the expensive part can be checked rather than
    /// asserted.
    pub fn probe_blt_ddb(x: i32, y: i32, w: i32, h: i32) -> bool {
        if w <= 0 || h <= 0 {
            return false;
        }
        unsafe {
            let screen = GetDC(None);
            if screen.is_invalid() {
                return false;
            }
            let mem = CreateCompatibleDC(Some(screen));
            let bmp = CreateCompatibleBitmap(screen, w, h);
            let old = SelectObject(mem, HGDIOBJ(bmp.0));
            let ok = BitBlt(mem, 0, 0, w, h, Some(screen), x, y, SRCCOPY).is_ok();
            SelectObject(mem, old);
            let _ = DeleteObject(HGDIOBJ(bmp.0));
            let _ = DeleteDC(mem);
            ReleaseDC(None, screen);
            ok
        }
    }

    /// The same blit with no screen at either end: cached DIB to a scratch DIB.
    /// Prices the copy itself, so the screen readback can be told apart from it.
    pub fn probe_blt_mem(w: i32, h: i32) -> bool {
        if w <= 0 || h <= 0 {
            return false;
        }
        unsafe {
            let src = DIB.with(|cell| {
                let mut slot = cell.borrow_mut();
                if !slot.as_ref().is_some_and(|c| c.w == w && c.h == h) {
                    *slot = None;
                    *slot = DibCache::new(w, h);
                }
                slot.as_ref().map(|c| c.mem)
            });
            let Some(src) = src else { return false };
            let Some(dst) = DibCache::new(w, h) else { return false };
            BitBlt(dst.mem, 0, 0, w, h, Some(src), 0, 0, SRCCOPY).is_ok()
        }
    }

    /// Grabs a rectangle of the screen.
    ///
    /// The pixels come back in GDI's own BGRA order and are not touched on the way
    /// out; the `Frame` says which order they are in and the two consumers that
    /// care read that. See `vision::Order`.
    pub fn capture(x: i32, y: i32, w: i32, h: i32) -> Option<crate::vision::Frame> {
        if w <= 0 || h <= 0 {
            return None;
        }
        // A rectangle big enough to overflow the multiply below is not a rectangle
        // any screen has; refusing it here keeps every later cast honest.
        if (w as i64) * (h as i64) > (1i64 << 28) {
            return None;
        }
        // The compositor's own copy, when this machine will give us one.
        if let Some(px) = dupe::capture(x, y, w, h) {
            return Some(crate::vision::Frame {
                x,
                y,
                w: w as u32,
                h: h as u32,
                px,
                order: crate::vision::Order::Bgra,
            });
        }
        capture_gdi(x, y, w, h)
    }

    /// The fallback, and the only path before 1.5.0. Kept whole rather than folded
    /// into the caller: `--selftest vision` prices one against the other, and a
    /// machine where duplication misbehaves is one configuration switch away from
    /// this being all that runs.
    pub fn capture_gdi(x: i32, y: i32, w: i32, h: i32) -> Option<crate::vision::Frame> {
        if w <= 0 || h <= 0 || (w as i64) * (h as i64) > (1i64 << 28) {
            return None;
        }
        unsafe {
            let screen = GetDC(None);
            if screen.is_invalid() {
                return None;
            }
            let out = DIB.with(|cell| {
                let mut slot = cell.borrow_mut();
                let fits = slot.as_ref().is_some_and(|c| c.w == w && c.h == h);
                if !fits {
                    // Dropped first, so the old objects are gone before the new ones
                    // are asked for rather than both being held at once.
                    *slot = None;
                    *slot = DibCache::new(w, h);
                }
                let cache = slot.as_ref()?;
                if BitBlt(cache.mem, 0, 0, w, h, Some(screen), x, y, SRCCOPY).is_err() {
                    return None;
                }
                // `Vec::with_capacity` rather than `vec![0; n]`: the zeroing pass is
                // a full write of the frame that the copy immediately overwrites.
                let n = cache.bytes();
                let mut buf: Vec<u8> = Vec::with_capacity(n);
                std::ptr::copy_nonoverlapping(cache.bits, buf.as_mut_ptr(), n);
                buf.set_len(n);
                Some(buf)
            });
            ReleaseDC(None, screen);
            Some(crate::vision::Frame {
                x,
                y,
                w: w as u32,
                h: h as u32,
                px: out?,
                order: crate::vision::Order::Bgra,
            })
        }
    }

    pub fn virtual_screen_rect() -> (i32, i32, i32, i32) {
        unsafe {
            (
                GetSystemMetrics(SM_XVIRTUALSCREEN),
                GetSystemMetrics(SM_YVIRTUALSCREEN),
                GetSystemMetrics(SM_CXVIRTUALSCREEN).max(1),
                GetSystemMetrics(SM_CYVIRTUALSCREEN).max(1),
            )
        }
    }

    /// Reads a bitmap off the clipboard, which is what Win+Shift+S leaves behind.
    ///
    /// Handles the 24/32-bit DIBs that the Snipping Tool and browsers produce,
    /// including the V4/V5 headers where the colour masks live inside the header.
    pub fn clipboard_image() -> Option<(u32, u32, Vec<u8>)> {
        unsafe {
            if OpenClipboard(None).is_err() {
                return None;
            }
            let result = (|| {
                const CF_DIB: u32 = 8;
                let handle = GetClipboardData(CF_DIB).ok()?;
                let hglobal = HGLOBAL(handle.0);
                let ptr = GlobalLock(hglobal) as *const u8;
                if ptr.is_null() {
                    return None;
                }
                let size = GlobalSize(hglobal);
                let bytes = std::slice::from_raw_parts(ptr, size);
                let out = parse_dib(bytes);
                let _ = GlobalUnlock(hglobal);
                out
            })();
            let _ = CloseClipboard();
            result
        }
    }

    fn rd_u32(b: &[u8], at: usize) -> u32 {
        u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
    }
    fn rd_i32(b: &[u8], at: usize) -> i32 {
        rd_u32(b, at) as i32
    }

    /// Turns a packed DIB into top-down RGBA.
    fn parse_dib(b: &[u8]) -> Option<(u32, u32, Vec<u8>)> {
        if b.len() < 40 {
            return None;
        }
        let hdr = rd_u32(b, 0) as usize;
        let w = rd_i32(b, 4);
        let raw_h = rd_i32(b, 8);
        let bpp = u16::from_le_bytes([b[14], b[15]]) as u32;
        let compression = rd_u32(b, 16);
        if w <= 0 || raw_h == 0 || !(bpp == 24 || bpp == 32) {
            return None;
        }
        let bottom_up = raw_h > 0;
        let h = raw_h.unsigned_abs();
        let w_u = w as u32;

        // BI_BITFIELDS adds three masks after a plain 40-byte header; V4/V5 headers
        // are bigger and already contain them.
        let mut offset = hdr;
        if compression == 3 && hdr == 40 {
            offset += 12;
        }
        let stride = ((w_u * bpp).div_ceil(32) * 4) as usize;
        if b.len() < offset + stride * h as usize {
            return None;
        }

        let mut out = vec![0u8; (w_u * h * 4) as usize];
        let bytes_pp = (bpp / 8) as usize;
        for row in 0..h {
            let src_row = if bottom_up { h - 1 - row } else { row } as usize;
            let src = offset + src_row * stride;
            for x in 0..w_u as usize {
                let s = src + x * bytes_pp;
                let d = ((row as usize) * w_u as usize + x) * 4;
                out[d] = b[s + 2];
                out[d + 1] = b[s + 1];
                out[d + 2] = b[s];
                // Opaque, whatever the source says. A 32-bit DIB has an alpha
                // channel and GDI leaves it at zero, so copying it through would
                // make every captured pixel fully transparent - which is exactly
                // why the image search never consults alpha either. The test that
                // used to be here chose 255 in both arms and had presumably been
                // meant to read the source; clippy noticed, and the answer is that
                // the constant is correct and the test never was.
                out[d + 3] = 255;
            }
        }
        Some((w_u, h, out))
    }

    /// Local wall-clock time: year, month, day, weekday (0 = Monday), hour, minute.
    ///
    /// Straight from Windows rather than a date crate: no dependency, and it is
    /// already the user's timezone and DST, which is what a schedule means.
    pub fn local_time() -> (u16, u16, u16, u8, u16, u16) {
        unsafe {
            let t = windows::Win32::System::SystemInformation::GetLocalTime();
            let monday_based = ((t.wDayOfWeek + 6) % 7) as u8;
            (t.wYear, t.wMonth, t.wDay, monday_based, t.wHour, t.wMinute)
        }
    }

    /// Title of whatever window currently has focus.
    pub fn foreground_title() -> Option<String> {
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.0.is_null() {
                return None;
            }
            let len = GetWindowTextLengthW(hwnd);
            if len <= 0 {
                return None;
            }
            let mut buf = vec![0u16; len as usize + 1];
            let n = GetWindowTextW(hwnd, &mut buf);
            if n <= 0 {
                return None;
            }
            Some(String::from_utf16_lossy(&buf[..n as usize]))
        }
    }

    pub fn cursor_pos() -> (i32, i32) {
        unsafe {
            let mut p = POINT::default();
            let _ = GetCursorPos(&mut p);
            (p.x, p.y)
        }
    }

    /// Title + rect of the foreground window, skipping our own.
    pub fn foreground_anchor() -> Option<WindowAnchor> {
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.0.is_null() || hwnd == app_hwnd() {
                return None;
            }
            let mut buf = [0u16; 256];
            let len = GetWindowTextW(hwnd, &mut buf);
            if len <= 0 {
                return None;
            }
            let title = String::from_utf16_lossy(&buf[..len as usize]);
            let mut r = RECT::default();
            if GetWindowRect(hwnd, &mut r).is_err() {
                return None;
            }
            Some(WindowAnchor {
                title,
                x: r.left,
                y: r.top,
                w: r.right - r.left,
                h: r.bottom - r.top,
            })
        }
    }

    thread_local! {
        /// Needle and result for the EnumWindows callback below.
        static FIND_STATE: std::cell::RefCell<(String, Option<HWND>)> =
            const { std::cell::RefCell::new((String::new(), None)) };
    }

    unsafe extern "system" fn enum_find_proc(hwnd: HWND, _lp: LPARAM) -> BOOL {
        unsafe {
            if !IsWindowVisible(hwnd).as_bool() {
                return true.into();
            }
            let len = GetWindowTextLengthW(hwnd);
            if len <= 0 {
                return true.into();
            }
            let mut buf = vec![0u16; len as usize + 1];
            let n = GetWindowTextW(hwnd, &mut buf);
            if n <= 0 {
                return true.into();
            }
            let title = String::from_utf16_lossy(&buf[..n as usize]).to_lowercase();
            let mut stop = false;
            FIND_STATE.with(|c| {
                let mut c = c.borrow_mut();
                if c.1.is_none() && !c.0.is_empty() && title.contains(c.0.as_str()) {
                    c.1 = Some(hwnd);
                    stop = true;
                }
            });
            (!stop).into()
        }
    }

    /// Finds a top-level window by title and returns its rectangle.
    ///
    /// Exact match first, then a case-insensitive substring search: window titles
    /// pick up suffixes all the time ("Roblox" becomes "Roblox - Level 7"), and an
    /// exact-only lookup made anchoring fail exactly when it was needed most.
    /// Dots per inch of the display the front window is on. 96 is 100 %.
    pub fn current_dpi() -> u32 {
        unsafe {
            let hwnd = GetForegroundWindow();
            let dpi = if hwnd.0.is_null() { 0 } else { GetDpiForWindow(hwnd) };
            if dpi == 0 { 96 } else { dpi }
        }
    }

    /// How many displays there are, and which one the window in front is on.
    ///
    /// Numbered from 1 in `EnumDisplayMonitors` order, which is the order every
    /// other tool on Windows numbers them in. Zero for the second value means the
    /// question could not be answered - there is no window in front, or its monitor
    /// was not in the enumeration, which happens for a fraction of a second while a
    /// display is being attached.
    ///
    /// Reported, never used to place anything. A monitor index is not a stable
    /// identity across a reboot and must not become one.
    pub fn monitor_here() -> (u32, u32) {
        unsafe {
            let hwnd = GetForegroundWindow();
            let mine = if hwnd.0.is_null() {
                HMONITOR::default()
            } else {
                MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST)
            };
            // (count so far, index of `mine` once seen). A thread local rather than a
            // captured closure because the callback is a plain `extern "system"` fn.
            MONITOR_SCAN.with(|c| *c.borrow_mut() = (0, 0, mine));
            let _ = EnumDisplayMonitors(None, None, Some(count_monitors), LPARAM(0));
            MONITOR_SCAN.with(|c| {
                let (n, at, _) = *c.borrow();
                (n, at)
            })
        }
    }

    thread_local! {
        static MONITOR_SCAN: std::cell::RefCell<(u32, u32, HMONITOR)> =
            const { std::cell::RefCell::new((0, 0, HMONITOR(std::ptr::null_mut()))) };
    }

    unsafe extern "system" fn count_monitors(
        h: HMONITOR,
        _: HDC,
        _: *mut RECT,
        _: LPARAM,
    ) -> BOOL {
        MONITOR_SCAN.with(|c| {
            let mut c = c.borrow_mut();
            c.0 += 1;
            if c.2 == h {
                c.1 = c.0;
            }
        });
        true.into()
    }

    /// The keyboard layout of the window in front, as a language name.
    ///
    /// `en-US`, `ru-RU`. The low word of an `HKL` is a language identifier, and
    /// `LCIDToLocaleName` is the supported way of turning one into a name; the raw
    /// hex would be correct and unreadable.
    pub fn keyboard_layout() -> String {
        unsafe {
            let hwnd = GetForegroundWindow();
            let tid =
                if hwnd.0.is_null() { 0 } else { GetWindowThreadProcessId(hwnd, None) };
            let hkl = GetKeyboardLayout(tid);
            let lcid = (hkl.0 as usize & 0xFFFF) as u32;
            if lcid == 0 {
                return String::new();
            }
            let mut buf = [0u16; 85];
            let n = LCIDToLocaleName(lcid, Some(&mut buf), 0);
            if n <= 1 {
                return String::new();
            }
            // The count includes the terminating null.
            String::from_utf16_lossy(&buf[..(n - 1) as usize])
        }
    }

    /// Where the window in front is, for `SearchArea::ActiveWindow`.
    pub fn foreground_rect() -> Option<(i32, i32, i32, i32)> {
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.0.is_null() {
                return None;
            }
            let mut r = RECT::default();
            if GetWindowRect(hwnd, &mut r).is_err() {
                return None;
            }
            Some((r.left, r.top, r.right - r.left, r.bottom - r.top))
        }
    }

    /// Executable name of the window in front, without its path.
    ///
    /// `PROCESS_QUERY_LIMITED_INFORMATION` rather than the full right: it is the
    /// least this needs, and it is the one that works across an elevation boundary
    /// in the direction that matters.
    pub fn foreground_process() -> String {
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.0.is_null() {
                return String::new();
            }
            let mut pid = 0u32;
            GetWindowThreadProcessId(hwnd, Some(&mut pid));
            if pid == 0 {
                return String::new();
            }
            let Ok(h) = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid) else {
                return String::new();
            };
            let mut buf = [0u16; 260];
            let mut len = buf.len() as u32;
            let ok = QueryFullProcessImageNameW(
                h,
                PROCESS_NAME_WIN32,
                PWSTR(buf.as_mut_ptr()),
                &mut len,
            )
            .is_ok();
            let _ = CloseHandle(h);
            if !ok {
                return String::new();
            }
            let full = String::from_utf16_lossy(&buf[..len as usize]);
            full.rsplit(['\\', '/']).next().unwrap_or(&full).to_string()
        }
    }

    /// Is a process whose name contains `name` running?
    ///
    /// A substring, without case, so `roblox` finds `RobloxPlayerBeta.exe` - asking
    /// somebody to type the exact executable name is asking them to get it wrong.
    pub fn process_running(name: &str) -> bool {
        let needle = name.trim().to_lowercase();
        if needle.is_empty() {
            return false;
        }
        unsafe {
            let Ok(snap) = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0) else {
                return false;
            };
            let mut entry = PROCESSENTRY32W {
                dwSize: std::mem::size_of::<PROCESSENTRY32W>() as u32,
                ..Default::default()
            };
            let mut found = false;
            if Process32FirstW(snap, &mut entry).is_ok() {
                loop {
                    let end = entry
                        .szExeFile
                        .iter()
                        .position(|&c| c == 0)
                        .unwrap_or(entry.szExeFile.len());
                    let exe = String::from_utf16_lossy(&entry.szExeFile[..end]);
                    if exe.to_lowercase().contains(&needle) {
                        found = true;
                        break;
                    }
                    if Process32NextW(snap, &mut entry).is_err() {
                        break;
                    }
                }
            }
            let _ = CloseHandle(snap);
            found
        }
    }

    /// The clipboard as text. Empty when it holds something else, or nothing.
    pub fn clipboard_text() -> String {
        unsafe {
            if OpenClipboard(None).is_err() {
                return String::new();
            }
            let out = (|| {
                const CF_UNICODETEXT: u32 = 13;
                let handle = GetClipboardData(CF_UNICODETEXT).ok()?;
                let hglobal = HGLOBAL(handle.0);
                let ptr = GlobalLock(hglobal) as *const u16;
                if ptr.is_null() {
                    return None;
                }
                let mut len = 0usize;
                while *ptr.add(len) != 0 && len < 1_000_000 {
                    len += 1;
                }
                let text = String::from_utf16_lossy(std::slice::from_raw_parts(ptr, len));
                let _ = GlobalUnlock(hglobal);
                Some(text)
            })();
            let _ = CloseClipboard();
            out.unwrap_or_default()
        }
    }

    /// Replaces the clipboard with `text`. False when Windows would not hand it over,
    /// which happens whenever another application is holding it open.
    pub fn set_clipboard_text(text: &str) -> bool {
        unsafe {
            let mut wide: Vec<u16> = text.encode_utf16().collect();
            wide.push(0);
            let bytes = wide.len() * 2;
            let Ok(h) = GlobalAlloc(GMEM_MOVEABLE, bytes) else {
                return false;
            };
            let ptr = GlobalLock(h) as *mut u16;
            if ptr.is_null() {
                return false;
            }
            std::ptr::copy_nonoverlapping(wide.as_ptr(), ptr, wide.len());
            let _ = GlobalUnlock(h);
            if OpenClipboard(None).is_err() {
                return false;
            }
            let _ = EmptyClipboard();
            const CF_UNICODETEXT: u32 = 13;
            let ok = SetClipboardData(CF_UNICODETEXT, Some(HANDLE(h.0))).is_ok();
            let _ = CloseClipboard();
            ok
        }
    }

    /// The window a title (or the start of one) refers to.
    fn find_window_handle(title: &str) -> Option<HWND> {
        unsafe {
            let mut hwnd = HWND::default();
            let w = wide(title);
            if let Ok(h) = FindWindowW(None, PCWSTR(w.as_ptr())) {
                hwnd = h;
            }
            if hwnd.0.is_null() {
                let needle: String =
                    title.to_lowercase().chars().take(24).collect::<String>().trim().to_string();
                FIND_STATE.with(|c| *c.borrow_mut() = (needle, None));
                let _ = EnumWindows(Some(enum_find_proc), LPARAM(0));
                hwnd = FIND_STATE.with(|c| c.borrow().1.unwrap_or_default());
            }
            if hwnd.0.is_null() { None } else { Some(hwnd) }
        }
    }

    pub fn find_window_rect(title: &str) -> Option<(i32, i32, i32, i32)> {
        unsafe {
            let hwnd = find_window_handle(title)?;
            let mut r = RECT::default();
            if GetWindowRect(hwnd, &mut r).is_err() {
                return None;
            }
            Some((r.left, r.top, r.right - r.left, r.bottom - r.top))
        }
    }

    thread_local! {
        /// Handle collected by `enum_by_process_proc`, and the process name it is
        /// looking for.
        static PROC_FIND: std::cell::RefCell<(String, bool, Option<HWND>)> =
            const { std::cell::RefCell::new((String::new(), false, None)) };
    }

    /// Picks up the first *visible top-level* window belonging to a named process.
    ///
    /// Visible and top-level on purpose: a process owns a great many windows, most of
    /// them message-only or hidden helpers, and activating one of those does nothing
    /// visible while looking exactly like a bug.
    unsafe extern "system" fn enum_by_process_proc(hwnd: HWND, _l: LPARAM) -> BOOL {
        unsafe {
            if !IsWindowVisible(hwnd).as_bool() {
                return BOOL(1);
            }
            if !GetWindow(hwnd, GW_OWNER).unwrap_or_default().0.is_null() {
                return BOOL(1);
            }
            // A window with no title is a tool window or a tray host far more often
            // than it is the thing somebody meant.
            if GetWindowTextLengthW(hwnd) == 0 {
                return BOOL(1);
            }
            let mut pid = 0u32;
            let _ = GetWindowThreadProcessId(hwnd, Some(&mut pid));
            if pid == 0 {
                return BOOL(1);
            }
            let Some(path) = process_path_of(pid) else { return BOOL(1) };
            let hit = PROC_FIND.with(|c| {
                let c = c.borrow();
                if c.1 {
                    // Full path, compared whole and without case.
                    path.eq_ignore_ascii_case(c.0.trim())
                } else {
                    // Just the file name, with `.exe` optional both ways.
                    let file = std::path::Path::new(&path)
                        .file_name()
                        .map(|f| f.to_string_lossy().to_lowercase())
                        .unwrap_or_default();
                    let want = c.0.trim().to_lowercase();
                    let want = want.strip_suffix(".exe").unwrap_or(&want);
                    let have = file.strip_suffix(".exe").unwrap_or(&file);
                    have == want
                }
            });
            if hit {
                PROC_FIND.with(|c| c.borrow_mut().2 = Some(hwnd));
                return BOOL(0);
            }
            BOOL(1)
        }
    }

    /// Full path of a process, by id.
    fn process_path_of(pid: u32) -> Option<String> {
        unsafe {
            let h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid).ok()?;
            let mut buf = [0u16; 512];
            let mut n = buf.len() as u32;
            let ok = QueryFullProcessImageNameW(
                h,
                PROCESS_NAME_FORMAT(0),
                windows::core::PWSTR(buf.as_mut_ptr()),
                &mut n,
            );
            let _ = CloseHandle(h);
            ok.ok()?;
            Some(String::from_utf16_lossy(&buf[..n as usize]))
        }
    }

    /// The window a `WindowRef` names, by whichever of the four ways it asks for.
    fn resolve_window(by: u8, value: &str) -> Option<HWND> {
        let value = value.trim();
        if value.is_empty() {
            return None;
        }
        unsafe {
            match by {
                // Exact title: one call, and Windows does the comparing.
                1 => {
                    let w = wide(value);
                    FindWindowW(None, PCWSTR(w.as_ptr()))
                        .ok()
                        .filter(|h| !h.0.is_null())
                }
                2 | 3 => {
                    PROC_FIND.with(|c| *c.borrow_mut() = (value.to_string(), by == 3, None));
                    let _ = EnumWindows(Some(enum_by_process_proc), LPARAM(0));
                    PROC_FIND.with(|c| c.borrow().2)
                }
                // Title fragment, which is what everything before 1.6.0 did.
                _ => find_window_handle(value),
            }
        }
    }

    /// Does a window matching this reference exist right now?
    pub fn window_exists(by: u8, value: &str) -> bool {
        resolve_window(by, value).is_some()
    }

    /// A balloon from the tray icon.
    ///
    /// Chosen over a message box on purpose: a message box takes the foreground, and
    /// taking the foreground away from the application being automated is how a
    /// macro breaks the very run it is reporting on. A balloon appears beside the
    /// clock and changes nothing.
    ///
    /// Silently does nothing when the tray icon is switched off, which is the honest
    /// behaviour - there is nowhere for it to come from.
    pub fn notify(title: &str, body: &str) -> bool {
        let hwnd = crate::tray::hwnd();
        if hwnd.0.is_null() {
            tracing::info!("notify: {title} - {body} (no tray icon to show it from)");
            return false;
        }
        unsafe {
            let mut nid = NOTIFYICONDATAW {
                cbSize: std::mem::size_of::<NOTIFYICONDATAW>() as u32,
                hWnd: hwnd,
                uID: 1,
                uFlags: NIF_INFO,
                dwInfoFlags: NIIF_INFO,
                ..Default::default()
            };
            // Both fields are fixed-size arrays; anything longer is cut rather than
            // refused, because a notification that is too long to show is still
            // worth showing the beginning of.
            let t = wide(title);
            for (i, c) in t.iter().take(nid.szInfoTitle.len() - 1).enumerate() {
                nid.szInfoTitle[i] = *c;
            }
            let b = wide(body);
            for (i, c) in b.iter().take(nid.szInfo.len() - 1).enumerate() {
                nid.szInfo[i] = *c;
            }
            Shell_NotifyIconW(NIM_MODIFY, &nid).as_bool()
        }
    }

    /// Is it the window in front?
    pub fn window_is_active(by: u8, value: &str) -> bool {
        match resolve_window(by, value) {
            Some(h) => unsafe { GetForegroundWindow() == h },
            None => false,
        }
    }

    pub fn window_rect_of(by: u8, value: &str) -> Option<(i32, i32, i32, i32)> {
        unsafe {
            let hwnd = resolve_window(by, value)?;
            let mut r = RECT::default();
            if GetWindowRect(hwnd, &mut r).is_err() {
                return None;
            }
            Some((r.left, r.top, r.right - r.left, r.bottom - r.top))
        }
    }

    /// Brings a window to the front, and gets away with it.
    ///
    /// `SetForegroundWindow` alone is refused whenever the calling process does not
    /// own the foreground, which is almost always here: the macro is playing and the
    /// game is in front. Attaching to the foreground thread's input queue for the
    /// duration is the documented way round it, and the attachment is always undone -
    /// leaving two input queues joined would make the rest of the run behave very
    /// strangely indeed.
    unsafe fn bring_to_front(hwnd: HWND) -> bool {
        unsafe {
            if IsIconic(hwnd).as_bool() {
                let _ = ShowWindow(hwnd, SW_RESTORE);
            }
            if SetForegroundWindow(hwnd).as_bool() {
                return true;
            }
            let fg = GetForegroundWindow();
            let me = GetCurrentThreadId();
            let other = GetWindowThreadProcessId(fg, None);
            if other == 0 || other == me {
                return false;
            }
            let _ = AttachThreadInput(other, me, true);
            let ok = SetForegroundWindow(hwnd).as_bool();
            let _ = AttachThreadInput(other, me, false);
            ok
        }
    }

    /// Does one thing to one window. `arg` is the pair of numbers for move and
    /// resize, and ignored otherwise.
    ///
    /// Returns whether it happened, so a step can have a miss policy about it.
    pub fn window_action(by: u8, value: &str, action: u8, arg: (i32, i32)) -> bool {
        unsafe {
            let Some(hwnd) = resolve_window(by, value) else {
                return false;
            };
            match action {
                0 => bring_to_front(hwnd),
                1 => ShowWindow(hwnd, SW_MINIMIZE).as_bool(),
                2 => ShowWindow(hwnd, SW_MAXIMIZE).as_bool(),
                3 => ShowWindow(hwnd, SW_RESTORE).as_bool(),
                // Asked to close, rather than terminated: the application gets to run
                // its own shutdown, and to refuse.
                4 => PostMessageW(Some(hwnd), WM_CLOSE, WPARAM(0), LPARAM(0)).is_ok(),
                5 => SetWindowPos(
                    hwnd,
                    None,
                    arg.0,
                    arg.1,
                    0,
                    0,
                    SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE,
                )
                .is_ok(),
                6 => SetWindowPos(
                    hwnd,
                    None,
                    0,
                    0,
                    arg.0.max(1),
                    arg.1.max(1),
                    SWP_NOMOVE | SWP_NOZORDER | SWP_NOACTIVATE,
                )
                .is_ok(),
                7 => {
                    let mut r = RECT::default();
                    if GetWindowRect(hwnd, &mut r).is_err() {
                        return false;
                    }
                    let (w, h) = (r.right - r.left, r.bottom - r.top);
                    // Centred on the virtual desktop, which is the whole of it on one
                    // monitor and the middle of the arrangement on several. Somebody
                    // who wants it centred on one screen can use Move.
                    let (vx, vy, vw, vh) = virtual_screen_rect();
                    SetWindowPos(
                        hwnd,
                        None,
                        vx + (vw - w) / 2,
                        vy + (vh - h) / 2,
                        0,
                        0,
                        SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE,
                    )
                    .is_ok()
                }
                _ => false,
            }
        }
    }

    thread_local! {
        /// Title, handle and when it was resolved: re-running EnumWindows forty
        /// times a second to measure latency would be its own source of latency.
        static PROBE_TARGET: std::cell::RefCell<(String, Option<HWND>, u64)> =
            const { std::cell::RefCell::new((String::new(), None, 0)) };
    }

    /// Round-trip of an empty message through the target window's message loop,
    /// in microseconds. `None` when the window is gone or refused to answer.
    ///
    /// `WM_NULL` is chosen because it does nothing at all: the window's procedure
    /// returns immediately, so what is timed is the wait in the queue rather than
    /// any work the message caused. `SMTO_ABORTIFHUNG` keeps a wedged game from
    /// parking this thread for the whole timeout.
    pub fn probe_window_us(title: &str, timeout_ms: u32) -> Option<u64> {
        unsafe {
            let hwnd = PROBE_TARGET.with(|c| {
                let mut c = c.borrow_mut();
                let stale = now_us().saturating_sub(c.2) > 2_000_000;
                let dead = match c.1 {
                    Some(h) => !IsWindow(Some(h)).as_bool(),
                    None => true,
                };
                if c.0 != title || stale || dead {
                    *c = (title.to_string(), find_window_handle(title), now_us());
                }
                c.1
            })?;
            let t0 = now_us();
            let mut out: usize = 0;
            let r = SendMessageTimeoutW(
                hwnd,
                WM_NULL,
                WPARAM(0),
                LPARAM(0),
                SMTO_ABORTIFHUNG,
                timeout_ms,
                Some(&mut out),
            );
            if r.0 == 0 {
                // Timed out or the window died between the check and the send.
                PROBE_TARGET.with(|c| c.borrow_mut().1 = None);
                return None;
            }
            Some(now_us().saturating_sub(t0))
        }
    }

    unsafe fn enable_shutdown_privilege() {
        unsafe {
            let mut token = HANDLE::default();
            if OpenProcessToken(
                GetCurrentProcess(),
                TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY,
                &mut token,
            )
            .is_err()
            {
                return;
            }
            let mut luid = LUID::default();
            if LookupPrivilegeValueW(None, w!("SeShutdownPrivilege"), &mut luid).is_ok() {
                let tp = TOKEN_PRIVILEGES {
                    PrivilegeCount: 1,
                    Privileges: [LUID_AND_ATTRIBUTES {
                        Luid: luid,
                        Attributes: SE_PRIVILEGE_ENABLED,
                    }],
                };
                let _ = AdjustTokenPrivileges(token, false, Some(&tp), 0, None, None);
            }
            let _ = CloseHandle(token);
        }
    }

    pub fn run_end_action(action: EndAction, delay_s: u32, reason: &str) -> anyhow::Result<()> {
        unsafe {
            match action {
                EndAction::Stop => Ok(()),
                EndAction::Shutdown | EndAction::Reboot => {
                    enable_shutdown_privilege();
                    let msg = wide(reason);
                    let reboot = matches!(action, EndAction::Reboot);
                    InitiateSystemShutdownExW(
                        PCWSTR::null(),
                        PCWSTR(msg.as_ptr()),
                        delay_s,
                        true,
                        reboot,
                        SHTDN_REASON_MAJOR_OTHER
                            | SHTDN_REASON_MINOR_OTHER
                            | SHTDN_REASON_FLAG_PLANNED,
                    )
                    .map_err(|e| anyhow::anyhow!("InitiateSystemShutdownExW failed: {e}"))
                }
                EndAction::LogOff => {
                    enable_shutdown_privilege();
                    ExitWindowsEx(
                        EWX_LOGOFF,
                        SHTDN_REASON_MAJOR_OTHER | SHTDN_REASON_MINOR_OTHER,
                    )
                    .map_err(|e| anyhow::anyhow!("ExitWindowsEx failed: {e}"))
                }
                EndAction::Sleep | EndAction::Hibernate => {
                    enable_shutdown_privilege();
                    let hibernate = matches!(action, EndAction::Hibernate);
                    if SetSuspendState(hibernate, true, false) {
                        Ok(())
                    } else {
                        Err(anyhow::anyhow!(
                            "SetSuspendState failed (hibernation may be disabled)"
                        ))
                    }
                }
            }
        }
    }

    pub fn acquire_single_instance() -> bool {
        unsafe {
            match CreateMutexW(None, true, w!("Local\\MacroRecorder_SingleInstance_v1")) {
                Ok(handle) => {
                    if GetLastError() == ERROR_ALREADY_EXISTS {
                        let _ = CloseHandle(handle);
                        false
                    } else {
                        // Never closed on purpose: the mutex must live as long as the
                        // process. HANDLE has no Drop, so letting it fall out of scope
                        // leaves the kernel object open.
                        true
                    }
                }
                Err(_) => true,
            }
        }
    }

    /// Hides or restores our own top-level window.
    pub fn set_window_hidden(hidden: bool) {
        unsafe {
            let hwnd = app_hwnd();
            if hwnd.0.is_null() {
                return;
            }
            if hidden {
                let _ = ShowWindow(hwnd, SW_HIDE);
            } else {
                let _ = ShowWindow(hwnd, SW_SHOW);
                let _ = SetForegroundWindow(hwnd);
            }
        }
    }

    /// Asks the main window to close, exactly the way the close button does.
    pub fn request_app_close() {
        unsafe {
            let hwnd = app_hwnd();
            if !hwnd.0.is_null() {
                let _ = PostMessageW(Some(hwnd), WM_CLOSE, WPARAM(0), LPARAM(0));
            }
        }
    }

    pub fn focus_existing_instance() {
        unsafe {
            let title = wide(APP_TITLE);
            if let Ok(hwnd) = FindWindowW(None, PCWSTR(title.as_ptr()))
                && !hwnd.0.is_null() {
                    let _ = ShowWindow(hwnd, SW_RESTORE);
                    let _ = SetForegroundWindow(hwnd);
                }
        }
    }

    /// Resolved dynamically so the crate needs no Win32_System_Console feature.
    pub fn attach_parent_console() {
        const ATTACH_PARENT_PROCESS: u32 = 0xFFFF_FFFF;
        unsafe {
            let Ok(kernel32) = GetModuleHandleW(w!("kernel32.dll")) else {
                return;
            };
            let Some(sym) = GetProcAddress(kernel32, s!("AttachConsole")) else {
                return;
            };
            let attach: unsafe extern "system" fn(u32) -> i32 = std::mem::transmute(sym);
            let _ = attach(ATTACH_PARENT_PROCESS);
        }
    }

    pub fn set_dpi_awareness() {
        unsafe {
            let _ = SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
        }
    }

    /// What this process is currently costing: private bytes, open handles, GDI
    /// objects.
    ///
    /// All three are resolved at run time rather than linked. `GetProcessMemoryInfo`
    /// lives in a psapi feature nothing else here needs, and a number that only a
    /// soak test reads is not worth widening the build's dependency surface for. The
    /// same trick is used for `AttachConsole` a few lines up.
    pub fn process_cost() -> (u64, u32, u32) {
        #[repr(C)]
        #[derive(Default)]
        struct MemCountersEx {
            cb: u32,
            page_fault_count: u32,
            peak_working_set: usize,
            working_set: usize,
            quota_peak_paged_pool: usize,
            quota_paged_pool: usize,
            quota_peak_non_paged_pool: usize,
            quota_non_paged_pool: usize,
            pagefile_usage: usize,
            peak_pagefile_usage: usize,
            private_usage: usize,
        }

        unsafe {
            let me = windows::Win32::System::Threading::GetCurrentProcess();
            let mut private = 0u64;
            let mut handles = 0u32;
            let mut gdi = 0u32;

            if let Ok(k32) = GetModuleHandleW(w!("kernel32.dll")) {
                if let Some(sym) =
                    GetProcAddress(k32, s!("K32GetProcessMemoryInfo"))
                {
                    let f: unsafe extern "system" fn(
                        windows::Win32::Foundation::HANDLE,
                        *mut MemCountersEx,
                        u32,
                    ) -> i32 = std::mem::transmute(sym);
                    let mut pmc = MemCountersEx {
                        cb: std::mem::size_of::<MemCountersEx>() as u32,
                        ..Default::default()
                    };
                    if f(me, &mut pmc, pmc.cb) != 0 {
                        private = pmc.private_usage as u64;
                    }
                }
                if let Some(sym) =
                    GetProcAddress(k32, s!("GetProcessHandleCount"))
                {
                    let f: unsafe extern "system" fn(
                        windows::Win32::Foundation::HANDLE,
                        *mut u32,
                    ) -> i32 = std::mem::transmute(sym);
                    let mut n = 0u32;
                    if f(me, &mut n) != 0 {
                        handles = n;
                    }
                }
            }
            if let Ok(u32dll) = GetModuleHandleW(w!("user32.dll"))
                && let Some(sym) = GetProcAddress(u32dll, s!("GetGuiResources"))
                {
                    let f: unsafe extern "system" fn(
                        windows::Win32::Foundation::HANDLE,
                        u32,
                    ) -> u32 = std::mem::transmute(sym);
                    gdi = f(me, 0); // GR_GDIOBJECTS
                }
            (private, handles, gdi)
        }
    }
}

