    impl Topic {
        pub fn article(&self, lang: Lang) -> &Article {
            match lang {
                Lang::En => &self.en,
                Lang::Ru => &self.ru,
                other => MORE
                    .iter()
                    .find(|(id, l, _)| *id == self.id && *l == other)
                    .map(|(_, _, a)| a)
                    .unwrap_or(&self.en),
            }
        }
        pub fn title(&self, lang: Lang) -> &'static str {
            self.article(lang).title
        }
    }

    pub fn all() -> &'static [Topic] {
        TOPICS
    }

    pub fn find(id: &str) -> Option<&'static Topic> {
        TOPICS.iter().find(|t| t.id == id)
    }

    /// Ids in the side table that no topic answers to.
    ///
    /// A typo in one would put an article in the book that nothing can reach, and
    /// the reader would be handed English with no sign anything was wrong.
    pub fn unreachable_translations() -> Vec<&'static str> {
        MORE.iter().map(|(id, _, _)| *id).filter(|id| find(id).is_none()).collect()
    }

    /// Topics whose title or body contains every word typed, ignoring case.
    ///
    /// Every word rather than any: two words typed into a search box mean "both",
    /// and a list that grows as you type is a list you cannot narrow.
    pub fn search(query: &str, lang: Lang) -> Vec<&'static Topic> {
        let words: Vec<String> =
            query.split_whitespace().map(|w| w.to_lowercase()).collect();
        if words.is_empty() {
            return TOPICS.iter().collect();
        }
        TOPICS
            .iter()
            .filter(|t| {
                let a = t.article(lang);
                let hay = format!("{} {}", a.title, a.body).to_lowercase();
                words.iter().all(|w| hay.contains(w.as_str()))
            })
            .collect()
    }

    /// One line of an article, already classified.
    ///
    /// The markup is four characters wide on purpose: `#` a heading, `-` a bullet,
    /// `>` something worth a box round it, and everything else a paragraph. Inline
    /// there is `` `code` `` and `**bold**`. That is the whole language, and it is
    /// enough - a manual that needed tables and images would be a manual that had
    /// stopped explaining and started decorating.
    pub enum Line<'a> {
        Heading(&'a str),
        Bullet(&'a str),
        Note(&'a str),
        Para(&'a str),
        /// A line inside a ``` fence: monospace, spacing kept, no inline markup.
        ///
        /// The one thing the four-character grammar could not express. An example of
        /// what `--check` prints, or of a resolution trace, is a picture made of
        /// characters - re-wrapped and proportionally spaced it stops being one.
        Code(&'a str),
        Blank,
    }

    /// Classifies every line of an article.
    ///
    /// A `Vec` rather than an iterator because the fence is stateful, and a `map`
    /// cannot remember whether it is inside one.
    pub fn lines(body: &str) -> Vec<Line<'_>> {
        let mut out = Vec::new();
        let mut fenced = false;
        for raw in body.lines() {
            let t = raw.trim_end();
            if t.trim().starts_with("```") {
                fenced = !fenced;
                continue;
            }
            if fenced {
                out.push(Line::Code(t));
                continue;
            }
            let t = t.trim();
            out.push(if t.is_empty() {
                Line::Blank
            } else if let Some(rest) = t.strip_prefix("# ") {
                Line::Heading(rest)
            } else if let Some(rest) = t.strip_prefix("- ") {
                Line::Bullet(rest)
            } else if let Some(rest) = t.strip_prefix("> ") {
                Line::Note(rest)
            } else {
                Line::Para(t)
            });
        }
        out
    }

    /// A run of text and how it should look.
    #[derive(Clone, Copy, PartialEq, Eq, Debug)]
    pub enum Style {
        Plain,
        Code,
        Bold,
        Emph,
    }

    /// Splits one line into styled runs.
    ///
    /// Written as a plain scan rather than with a regex because the whole grammar is
    /// three delimiters, and because this project does not take a regex dependency for
    /// anything.
    ///
    /// The style is one value rather than a set, so the delimiters do not nest. That is
    /// enough for what the articles say, and a test asserts none of them tries.
    pub fn runs(text: &str) -> Vec<(Style, String)> {
        let mut out: Vec<(Style, String)> = Vec::new();
        let mut cur = String::new();
        let mut style = Style::Plain;
        // What a code run goes back to, so `code` inside *emphasis* stays emphasised
        // rather than dropping the rest of the phrase back to plain.
        let mut outer = Style::Plain;
        // The last character the reader will actually see, which is what decides
        // whether a star is closing a word or is only a star.
        let mut prev: Option<char> = None;
        let mut chars = text.chars().peekable();
        while let Some(c) = chars.next() {
            match c {
                '`' => {
                    if !cur.is_empty() {
                        out.push((style, std::mem::take(&mut cur)));
                    }
                    if style == Style::Code {
                        style = outer;
                    } else {
                        outer = style;
                        style = Style::Code;
                    }
                }
                '*' if chars.peek() == Some(&'*') && style != Style::Code => {
                    chars.next();
                    if !cur.is_empty() {
                        out.push((style, std::mem::take(&mut cur)));
                    }
                    style = if style == Style::Bold { Style::Plain } else { Style::Bold };
                }
                // A single star, which the prose uses to name a thing it is quoting -
                // *Custom*, *carry on*. It went in as ordinary text until 1.9.1, so
                // every article in every language showed the stars themselves.
                //
                // It has to touch the word it marks: one that opens must be followed by
                // something other than a space, and one that closes must be preceded by
                // one. Without that rule `2 * 3` opens emphasis and slants the rest of
                // the line, which is a worse fault than the one this fixes.
                '*' if style != Style::Code => {
                    let touching = if style == Style::Emph {
                        prev.is_some_and(|p| !p.is_whitespace())
                    } else {
                        chars.peek().is_some_and(|n| !n.is_whitespace())
                    };
                    if !touching {
                        cur.push(c);
                        prev = Some(c);
                        continue;
                    }
                    if !cur.is_empty() {
                        out.push((style, std::mem::take(&mut cur)));
                    }
                    style = if style == Style::Emph { Style::Plain } else { Style::Emph };
                }
                _ => {
                    cur.push(c);
                    prev = Some(c);
                }
            }
        }
        if !cur.is_empty() {
            out.push((style, cur));
        }
        out
    }

