fn make_shadow(p: &Palette) -> egui::Shadow {
    egui::Shadow {
        offset: [p.shadow_offset, p.shadow_offset],
        blur: p.shadow_blur,
        spread: 0,
        color: egui::Color32::from_black_alpha(p.shadow_alpha),
    }
}

/// Applies a theme and returns the fill the central panel should use.
///
/// The translucency of the window and the background of popups have to come from
/// two different places. egui paints combo-box lists, menus and tooltips with
/// `panel_fill`, and those float *above* the app's own content - a see-through list
/// there means reading two layers of text at once. So `panel_fill` stays opaque for
/// the popups, and the window's translucency is applied straight to the central
/// panel's frame by the caller.
#[must_use]
fn apply_theme(ctx: &egui::Context, theme: Theme, transparent_ui: bool) -> egui::Color32 {
    let p = get_palette(theme);
    let mut visuals = if p.dark { egui::Visuals::dark() } else { egui::Visuals::light() };

    visuals.window_fill = p.panel;
    visuals.panel_fill = p.panel;
    visuals.extreme_bg_color = p.bg;
    visuals.window_shadow = make_shadow(&p);
    visuals.popup_shadow = make_shadow(&p);
    visuals.hyperlink_color = p.accent;
    visuals.selection.bg_fill = p.accent;
    visuals.selection.stroke = egui::Stroke::new(2.0, p.focus_border);

    let states = [
        &mut visuals.widgets.noninteractive,
        &mut visuals.widgets.inactive,
        &mut visuals.widgets.hovered,
        &mut visuals.widgets.active,
    ];
    for w in states {
        w.corner_radius = p.widget_round.into();
        w.bg_stroke = egui::Stroke::new(1.0, p.border);
        w.fg_stroke = egui::Stroke::new(1.0, p.text);
    }
    visuals.widgets.noninteractive.bg_fill = p.panel;
    visuals.widgets.noninteractive.fg_stroke = egui::Stroke::new(1.0, p.faint);
    visuals.widgets.inactive.bg_fill = p.widget;
    visuals.widgets.hovered.bg_fill = p.widget_hover;
    visuals.widgets.hovered.bg_stroke = egui::Stroke::new(1.5, p.hover_border);
    visuals.widgets.active.bg_fill = p.widget_active;
    visuals.widgets.active.fg_stroke = egui::Stroke::new(1.0, p.active_fg);
    visuals.widgets.active.bg_stroke = egui::Stroke::new(2.0, p.focus_border);

    let translucent = transparent_ui || p.backdrop > 1;
    let panel_fill = if translucent {
        if p.backdrop > 1 { p.panel } else { rgba(30, 30, 30, 140) }
    } else {
        p.panel
    };

    if translucent {
        // Everything egui might use for a floating surface is forced opaque, and gets
        // a border plus a shadow so it reads as a separate layer.
        visuals.panel_fill = p.bg;
        visuals.window_fill = p.bg;
        visuals.extreme_bg_color = p.bg;
        visuals.window_stroke = egui::Stroke::new(1.0, p.hover_border);
        visuals.window_shadow = make_shadow(&p);
        visuals.popup_shadow = egui::Shadow {
            offset: [0, 4],
            blur: 14,
            spread: 0,
            color: egui::Color32::from_black_alpha(170),
        };
    }

    let mut style = (*ctx.style_of(egui::Theme::Dark)).clone();
    style.visuals = visuals;
    style.animation_time = p.animation_time;
    style.spacing.item_spacing = egui::vec2(8.0, p.item_spacing_y);
    style.spacing.button_padding = egui::vec2(p.button_padding, p.button_padding);

    ctx.set_style_of(egui::Theme::Dark, style.clone());
    ctx.set_style_of(egui::Theme::Light, style);

    // Pushed unconditionally (1 = none) so leaving a backdrop theme clears the effect.
    #[cfg(windows)]
    platform::apply_system_backdrop(platform::app_hwnd(), p.backdrop);

    panel_fill
}

// ============================================================================
// Macro editing helpers
// ============================================================================

fn describe_event(ev: &MacroEvent) -> String {
    match ev.kind {
        InputEventKind::Key { vk, down, .. } => {
            format!("{} {}", if down { "key↓" } else { "key↑" }, vk_name(vk as u32))
        }
        InputEventKind::MouseMove { x, y, .. } => format!("move {x},{y}"),
        InputEventKind::MouseButton { button, down, x, y } => {
            format!("{:?}{} {x},{y}", button, if down { "↓" } else { "↑" })
        }
        InputEventKind::MouseWheel { delta, horizontal, .. } => {
            format!("wheel{} {delta}", if horizontal { " h" } else { "" })
        }
    }
}

/// One macro that is open but not necessarily in front.
///
/// The tab in front keeps its contents in `AppState` rather than here, so `data` is
/// only meaningful for the parked ones. `sync_tabs` is what keeps that true.
#[derive(Clone, Debug, Default)]
pub struct Tab {
    pub data: MacroData,
    pub path: Option<PathBuf>,
}

impl Tab {
    fn label(&self, s: &Strings) -> String {
        match &self.path {
            Some(p) => file_label(p),
            None => s.tab_untitled.to_string(),
        }
    }
}

/// One line of the human-readable summary, mapped back onto its raw events.
#[derive(Clone, Debug)]
pub struct Step {
    /// Index of the first raw event this line covers.
    pub first: usize,
    /// Index of the last one, inclusive.
    pub last: usize,
    pub t_us: u64,
    pub text: String,
}

fn format_dur(us: u64) -> String {
    if us < 1_000 {
        format!("{us} \u{b5}s")
    } else if us < 1_000_000 {
        format!("{} ms", us / 1_000)
    } else if us < 60_000_000 {
        format!("{:.1} s", us as f64 / 1_000_000.0)
    } else {
        format_us(us)
    }
}

fn point(x: i32, y: i32) -> String {
    format!("({x}, {y})")
}

fn button_name(b: MouseButton, s: &Strings) -> String {
    match b {
        MouseButton::Left => s.btn_l.to_string(),
        MouseButton::Right => s.btn_r.to_string(),
        MouseButton::Middle => s.btn_m.to_string(),
        MouseButton::X1 => "X1".into(),
        MouseButton::X2 => "X2".into(),
    }
}

/// The character a key produces, for the "Typed ..." lines.
///
/// Only letters, digits and space: anything else is reported as a key press, which
/// keeps the summary honest instead of guessing at layouts and modifiers.
fn typed_char(vk: u16) -> Option<char> {
    match vk {
        0x41..=0x5A => Some((b'A' + (vk - 0x41) as u8) as char),
        0x30..=0x39 => Some((b'0' + (vk - 0x30) as u8) as char),
        0x20 => Some(' '),
        _ => None,
    }
}

fn find_key_up(events: &[MacroEvent], from: usize, vk: u16) -> Option<usize> {
    events.iter().enumerate().skip(from).find_map(|(j, e)| match e.kind {
        InputEventKind::Key { vk: v, down: false, .. } if v == vk => Some(j),
        _ => None,
    })
}

/// Turns raw events into a readable story: moves, clicks, drags, typing and pauses.
///
/// Every line remembers the event range it came from, so selecting a line in the
/// editor selects exactly those events for deleting, cropping or re-timing.
fn summarize(events: &[MacroEvent], s: &Strings) -> Vec<Step> {
    /// Movement below this is treated as hand tremor rather than a drag.
    const DRAG_PX: i32 = 8;
    /// Two presses closer than this at the same spot read as one double click.
    const DOUBLE_US: u64 = 400_000;
    /// Idle time worth mentioning.
    const IDLE_US: u64 = 300_000;

    let mut out: Vec<Step> = Vec::new();
    let mut i = 0usize;
    let mut prev_end_t = 0u64;

    while i < events.len() {
        let ev = events[i];
        let gap = ev.t_us.saturating_sub(prev_end_t);
        if gap >= IDLE_US && !out.is_empty() {
            out.push(Step {
                first: i,
                last: i,
                t_us: prev_end_t,
                text: s.step_wait.replace("{}", &format_dur(gap)),
            });
        }

        match ev.kind {
            InputEventKind::MouseMove { .. } => {
                let mut last = i;
                while last + 1 < events.len()
                    && matches!(events[last + 1].kind, InputEventKind::MouseMove { .. })
                {
                    last += 1;
                }
                if let InputEventKind::MouseMove { x, y, .. } = events[last].kind {
                    out.push(Step {
                        first: i,
                        last,
                        t_us: ev.t_us,
                        text: s.step_move.replace("{}", &point(x, y)),
                    });
                }
                prev_end_t = events[last].t_us;
                i = last + 1;
            }

            InputEventKind::MouseButton { button, down: true, x, y } => {
                // Walk to the matching release, noting whether the cursor travelled.
                let mut end = i;
                let (mut ex, mut ey) = (x, y);
                let mut moved = false;
                let mut j = i + 1;
                while j < events.len() {
                    match events[j].kind {
                        InputEventKind::MouseButton { button: b2, down: false, x: ux, y: uy }
                            if b2 == button =>
                        {
                            ex = ux;
                            ey = uy;
                            end = j;
                            break;
                        }
                        InputEventKind::MouseMove { x: mx, y: my, .. } => {
                            if (mx - x).abs() > DRAG_PX || (my - y).abs() > DRAG_PX {
                                moved = true;
                            }
                            ex = mx;
                            ey = my;
                        }
                        _ => {}
                    }
                    j += 1;
                }

                let name = button_name(button, s);
                let text = if moved {
                    s.step_drag
                        .replacen("{}", &name, 1)
                        .replacen("{}", &point(x, y), 1)
                        .replacen("{}", &point(ex, ey), 1)
                } else {
                    // A second press of the same button, near the same spot, soon after.
                    let mut second_end = None;
                    if let Some(next) = events.get(end + 1)
                        && let InputEventKind::MouseButton {
                            button: b2,
                            down: true,
                            x: nx,
                            y: ny,
                        } = next.kind
                            && b2 == button
                                && next.t_us.saturating_sub(events[end].t_us) < DOUBLE_US
                                && (nx - x).abs() <= DRAG_PX
                                && (ny - y).abs() <= DRAG_PX
                            {
                                let mut k = end + 2;
                                while k < events.len() {
                                    if let InputEventKind::MouseButton {
                                        button: b3,
                                        down: false,
                                        ..
                                    } = events[k].kind
                                        && b3 == button {
                                            second_end = Some(k);
                                            break;
                                        }
                                    k += 1;
                                }
                            }
                    if let Some(k) = second_end {
                        end = k;
                        s.step_dbl.replacen("{}", &name, 1).replacen("{}", &point(x, y), 1)
                    } else {
                        s.step_click.replacen("{}", &name, 1).replacen("{}", &point(x, y), 1)
                    }
                };

                out.push(Step { first: i, last: end, t_us: ev.t_us, text });
                prev_end_t = events[end].t_us;
                i = end + 1;
            }

            InputEventKind::MouseWheel { delta, horizontal, .. } => {
                let sign = delta >= 0;
                let mut last = i;
                let mut notches = (delta.abs() / 120).max(1);
                while let Some(next) = events.get(last + 1) {
                    match next.kind {
                        InputEventKind::MouseWheel { delta: d2, horizontal: h2, .. }
                            if h2 == horizontal && (d2 >= 0) == sign =>
                        {
                            notches += (d2.abs() / 120).max(1);
                            last += 1;
                        }
                        _ => break,
                    }
                }
                let dir = match (horizontal, sign) {
                    (false, true) => s.dir_up,
                    (false, false) => s.dir_down,
                    (true, true) => s.dir_right,
                    (true, false) => s.dir_left,
                };
                out.push(Step {
                    first: i,
                    last,
                    t_us: ev.t_us,
                    text: s
                        .step_scroll
                        .replacen("{}", dir, 1)
                        .replacen("{}", &notches.to_string(), 1),
                });
                prev_end_t = events[last].t_us;
                i = last + 1;
            }

            InputEventKind::Key { vk, down: true, .. } => {
                // Greedily collect a run of printable keys into one "Typed ..." line.
                let mut chars = String::new();
                let mut last = i;
                let mut j = i;
                while j < events.len() {
                    let InputEventKind::Key { vk: v, down: true, .. } = events[j].kind else {
                        break;
                    };
                    let (Some(c), Some(up)) = (typed_char(v), find_key_up(events, j, v)) else {
                        break;
                    };
                    chars.push(c);
                    last = up;
                    j = up + 1;
                }

                let text = if chars.chars().count() >= 2 {
                    s.step_type.replace("{}", &chars)
                } else {
                    let up = find_key_up(events, i, vk).unwrap_or(i);
                    last = up;
                    let held = events[up].t_us.saturating_sub(ev.t_us);
                    if held > 500_000 {
                        s.step_hold
                            .replacen("{}", &vk_name(vk as u32), 1)
                            .replacen("{}", &format_dur(held), 1)
                    } else {
                        s.step_key.replace("{}", &vk_name(vk as u32))
                    }
                };

                out.push(Step { first: i, last, t_us: ev.t_us, text });
                prev_end_t = events[last].t_us;
                i = last + 1;
            }

            // Stray releases with no matching press: show them as-is rather than hide them.
            _ => {
                out.push(Step {
                    first: i,
                    last: i,
                    t_us: ev.t_us,
                    text: describe_event(&ev),
                });
                prev_end_t = ev.t_us;
                i += 1;
            }
        }
    }
    out
}

/// Removes `[from, to]` and pulls the tail back so no silent gap is left behind.
fn editor_delete_range(data: &mut MacroData, from: usize, to: usize) {
    if data.events.is_empty() {
        return;
    }
    let from = from.min(data.events.len() - 1);
    let to = to.min(data.events.len() - 1).max(from);
    let start_t = data.events[from].t_us;
    let end_t = data.events[to].t_us;
    let removed = end_t.saturating_sub(start_t);
    let gone = to - from + 1;
    data.events.drain(from..=to);
    for ev in data.events.iter_mut().skip(from) {
        ev.t_us = ev.t_us.saturating_sub(removed);
    }
    // The whole point of a marker: the name stays on the same action after the
    // events around it have moved.
    shift_markers(&mut data.markers, from, -(gone as isize));
    data.duration_us = data.duration_us.saturating_sub(removed).max(data.last_t());
    data.refresh_ranges();
}

fn editor_crop(data: &mut MacroData, from: usize, to: usize) {
    if data.events.is_empty() {
        return;
    }
    let from = from.min(data.events.len() - 1);
    let to = to.min(data.events.len() - 1).max(from);
    let slice: Vec<MacroEvent> = data.events[from..=to].to_vec();
    let base = slice.first().map(|e| e.t_us).unwrap_or(0);
    data.events = slice
        .into_iter()
        .map(|mut e| {
            e.t_us = e.t_us.saturating_sub(base);
            e
        })
        .collect();
    // A crop is not two shifts, it is a new numbering: what survives is
    // `from..=to`, renumbered from zero. A marker outside that collapses onto the
    // nearest end rather than being dropped, because the name is the part somebody
    // wrote down.
    let kept = data.events.len();
    for m in data.markers.iter_mut() {
        m.at = m.at.saturating_sub(from).min(kept);
    }
    data.duration_us = data.last_t();
    data.refresh_ranges();
}

fn editor_insert_delay(data: &mut MacroData, at: usize, ms: u64) {
    // Saturating rather than plain: the UI bounds `ms`, but a function that is only
    // total because of its callers is a trap for the next caller.
    let us = ms.saturating_mul(1_000);
    for ev in data.events.iter_mut().skip(at) {
        ev.t_us = ev.t_us.saturating_add(us);
    }
    data.duration_us = data.duration_us.saturating_add(us).max(data.last_t());
}

fn editor_scale(data: &mut MacroData, factor: f64) {
    let f = factor.clamp(0.05, 20.0);
    for ev in data.events.iter_mut() {
        ev.t_us = (ev.t_us as f64 * f) as u64;
    }
    data.duration_us = ((data.duration_us as f64) * f) as u64;
}

fn editor_drop_moves(data: &mut MacroData) {
    // Counted before the retain, per marker, because the events being removed are
    // scattered rather than in one block: a marker moves back by however many
    // movements were in front of it, which is not the same number for each.
    let before: Vec<usize> = data
        .markers
        .iter()
        .map(|m| {
            data.events
                .iter()
                .take(m.at)
                .filter(|e| matches!(e.kind, InputEventKind::MouseMove { .. }))
                .count()
        })
        .collect();
    data.events.retain(|e| !matches!(e.kind, InputEventKind::MouseMove { .. }));
    for (m, n) in data.markers.iter_mut().zip(before) {
        m.at = m.at.saturating_sub(n).min(data.events.len());
    }
    data.refresh_ranges();
}

/// Replaces one event outright.
///
/// Changing a key zeroes its scancode: playback prefers the scancode when it is
/// non-zero, so keeping the old one would silently replay the old key.
fn editor_set_event(data: &mut MacroData, index: usize, kind: InputEventKind) {
    if let Some(ev) = data.events.get_mut(index) {
        ev.kind = kind;
    }
}

/// Moves one event in time, without letting it jump past its neighbours.
fn editor_set_time(data: &mut MacroData, index: usize, t_us: u64) {
    // Both neighbours are read through `get`; this one used a raw index, and it sits
    // ahead of the `get_mut` below that was meant to cover the whole function. A
    // selection left pointing past a recording that another edit has since trimmed
    // reached it first, and the release profile aborts on panic - so the editor took
    // the whole application with it.
    let lo = index.checked_sub(1).and_then(|i| data.events.get(i)).map_or(0, |e| e.t_us);
    let hi = data.events.get(index + 1).map(|e| e.t_us).unwrap_or(u64::MAX);
    if let Some(ev) = data.events.get_mut(index) {
        // `clamp` panics on an inverted window, which unsorted timestamps would give.
        ev.t_us = t_us.clamp(lo, hi.max(lo));
    }
    data.duration_us = data.duration_us.max(data.last_t());
}

fn editor_delete_one(data: &mut MacroData, index: usize) {
    if index < data.events.len() {
        editor_delete_range(data, index, index);
    }
}

/// Copies an event and drops the copy 10 ms later.
fn editor_duplicate(data: &mut MacroData, index: usize) {
    let Some(ev) = data.events.get(index).copied() else {
        return;
    };
    let mut copy = ev;
    copy.t_us = ev.t_us.saturating_add(10_000);
    shift_markers(&mut data.markers, index, 1);
    for e in data.events.iter_mut().skip(index + 1) {
        e.t_us = e.t_us.saturating_add(10_000);
    }
    data.events.insert(index + 1, copy);
    data.duration_us = data.duration_us.saturating_add(10_000).max(data.last_t());
}

/// Swaps one mouse button for another across a range. Returns how many changed.
fn editor_replace_button(
    data: &mut MacroData,
    from: usize,
    to: usize,
    old: MouseButton,
    new: MouseButton,
) -> usize {
    if data.events.is_empty() || old == new {
        return 0;
    }
    let from = from.min(data.events.len() - 1);
    let to = to.min(data.events.len() - 1).max(from);
    let mut n = 0;
    for ev in &mut data.events[from..=to] {
        if let InputEventKind::MouseButton { button, .. } = &mut ev.kind
            && *button == old {
                *button = new;
                n += 1;
            }
    }
    n
}

/// Offsets every screen coordinate in a range - for when the target window moved.
fn editor_shift_coords(data: &mut MacroData, from: usize, to: usize, dx: i32, dy: i32) {
    if data.events.is_empty() || (dx == 0 && dy == 0) {
        return;
    }
    let from = from.min(data.events.len() - 1);
    let to = to.min(data.events.len() - 1).max(from);
    for ev in &mut data.events[from..=to] {
        match &mut ev.kind {
            InputEventKind::MouseMove { x, y, .. }
            | InputEventKind::MouseButton { x, y, .. }
            | InputEventKind::MouseWheel { x, y, .. } => {
                *x += dx;
                *y += dy;
            }
            InputEventKind::Key { .. } => {}
        }
    }
}

/// Keys offered when retyping a keyboard event. Anything else goes in by code.
const EDIT_KEYS: [(&str, u16); 30] = [
    ("Space", 0x20), ("Enter", 0x0D), ("Tab", 0x09), ("Esc", 0x1B),
    ("Backspace", 0x08), ("Delete", 0x2E), ("Shift", 0x10), ("Ctrl", 0x11),
    ("Alt", 0x12), ("Left", 0x25), ("Up", 0x26), ("Right", 0x27), ("Down", 0x28),
    ("A", 0x41), ("B", 0x42), ("C", 0x43), ("D", 0x44), ("E", 0x45), ("Q", 0x51),
    ("R", 0x52), ("S", 0x53), ("W", 0x57), ("1", 0x31), ("2", 0x32), ("3", 0x33),
    ("F1", 0x70), ("F2", 0x71), ("F5", 0x74), ("F8", 0x77), ("F9", 0x78),
];

/// Shifts everything so the first event happens at t = 0.
fn editor_trim_lead(data: &mut MacroData) {
    let Some(first) = data.events.first().map(|e| e.t_us) else {
        return;
    };
    if first == 0 {
        return;
    }
    for ev in data.events.iter_mut() {
        ev.t_us = ev.t_us.saturating_sub(first);
    }
    data.duration_us = data.duration_us.saturating_sub(first).max(data.last_t());
}

// ============================================================================
// Application
// ============================================================================

/// What a palette row does when it is chosen.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PaletteAction {
    Play,
    TestRun,
    Stop,
    Record,
    Editor,
    Vars,
    Runs,
    Check,
    Handbook,
    Save,
    Load,
    /// Insert one step kind, by its index in the Add menu.
    AddStep(usize),
    /// Insert one template's steps.
    Template(usize),
    /// Put one built-in value on the clipboard, ready to paste into whichever field
    /// wanted it. The palette has no way of knowing which field that is, and asking
    /// would be a worse interface than pasting.
    InsertBuiltIn(usize),
}

/// The thin thing eframe owns.
///
/// The state itself lives behind an `Arc<Mutex<..>>` so that a **deferred** viewport
/// can reach it. A deferred viewport's callback has to be `Send + Sync + 'static`,
/// which rules out borrowing the application — and deferred is what the extra windows
/// have to be, because an immediate viewport is drawn from inside the parent's frame
/// and a minimised window on Windows is never given a frame at all. Before this, the
/// editor, the variables window and the run history all froze solid the moment the
/// main window went to the taskbar: they could not be scrolled, clicked or closed.
struct MacroApp {
    inner: Arc<Mutex<AppInner>>,
}

impl MacroApp {
    fn new(
        cc: &eframe::CreationContext<'_>,
        state: Arc<AppState>,
        config: AppConfig,
    ) -> Self {
        let inner = Arc::new(Mutex::new(AppInner::new(cc, state, config)));
        inner.lock().me = Arc::downgrade(&inner);
        Self { inner }
    }
}

impl eframe::App for MacroApp {
    fn logic(&mut self, ctx: &egui::Context, frame: &mut eframe::Frame) {
        self.inner.lock().logic(ctx, frame);
    }

    fn ui(&mut self, ui: &mut egui::Ui, frame: &mut eframe::Frame) {
        self.inner.lock().ui(ui, frame);
    }

    fn on_exit(&mut self, gl: Option<&eframe::glow::Context>) {
        self.inner.lock().on_exit(gl);
    }
}

struct AppInner {
    /// A handle back to the `Arc` holding this, for the window callbacks. Weak, so
    /// the application does not keep itself alive.
    me: std::sync::Weak<Mutex<AppInner>>,

    state: Arc<AppState>,
    config: AppConfig,
    system_lang: Lang,
    status_msg: String,
    theme_dirty: bool,
    // editor
    ed_from: usize,
    ed_to: usize,
    ed_delay_ms: u64,
    ed_scale: f64,
    ed_undo: Option<MacroData>,
    /// The editor lives in its own OS window.
    editor_open: bool,
    /// So does the variables watcher.
    vars_open: bool,
    /// Set when a recording ends with squares to offer. Cleared either way, so the
    /// offer is made once per recording and never nags.
    shots_offer: bool,
    /// Whether we were recording on the previous frame, which is how the moment a
    /// recording ends is noticed without the transport knowing about the UI.
    was_recording: bool,
    /// The same trick for a test run, so its tally can be reported once when it
    /// ends rather than counted up live in the corner of the eye.
    was_test_run: bool,
    /// And for playback, so the step statistics are re-read when a run ends rather
    /// than on every frame.
    was_playing: bool,
    /// Cached summary plus the inputs it was built from, so a long macro is not
    /// re-narrated on every frame.
    ed_steps: Vec<Step>,
    ed_steps_key: (usize, u64, usize),
    /// The single event shown in the inspector.
    ed_cursor: usize,
    /// Which event the current undo snapshot belongs to, so dragging a value does
    /// not overwrite the snapshot on every frame.
    ed_undo_key: Option<usize>,
    ed_pick_deadline: Option<Instant>,
    bulk_from_btn: usize,
    bulk_to_btn: usize,
    bulk_dx: i32,
    bulk_dy: i32,
    /// What the run history knows about each step, read when the editor opens and
    /// after a run ends. Not every frame: it reads and parses the whole history.
    stats: std::collections::HashMap<u64, StepStats>,
    /// The macros that are open but not in front.
    ///
    /// **`AppState` still holds exactly one macro**, and that is deliberate. Every
    /// thread in this program - playback, collector, hooks, scheduler, tray - reaches
    /// into `state.macro_data`, and turning that into a list is the largest and least
    /// necessary structural change in the plan: nothing plays two macros at once, so
    /// nothing below the window needs to know there is more than one.
    ///
    /// So a tab is a *parked* macro, held here on the UI side. Switching swaps the
    /// one in front with the one being switched to, which is two moves of a `MacroData`
    /// and no change to any invariant the engine relies on.
    tabs: Vec<Tab>,
    /// Which tab is in front. Always a valid index into `tabs` once `sync_tabs` has
    /// run, and the entry it names is the one whose contents live in `AppState`.
    tab: usize,
    /// Macro files to play one after another.
    queue: Vec<PathBuf>,
    /// Where the queue has got to while it is running.
    queue_at: Option<usize>,
    /// What the current macro needs, and nothing until Check is pressed.
    deps: Option<Deps>,
    /// A package that has been opened and is waiting to be looked at before it is
    /// unpacked. Nothing is written until the person has read the list.
    pending_pkg: Option<(MacroPackage, PathBuf)>,
    /// What an optimisation pass would remove. Shown before anything is touched,
    /// and cleared whenever the recording changes underneath it.
    cleanup: Option<Cleanup>,
    /// The macro library, read from disk when the panel first asks and after
    /// Refresh. Not every frame: it lists a directory.
    library: Option<Vec<String>>,
    /// Steps picked out for a bulk operation, besides `scr_sel`.
    ///
    /// Empty is the ordinary case and means "just the selected one", so every
    /// existing single-step button keeps working without knowing this exists.
    scr_marked: std::collections::BTreeSet<usize>,
    /// The rows of the Analyze table, and nothing until Analyze is pressed.
    suggestions: Vec<Suggestion>,
    /// The command palette: open, what has been typed, and which row is picked.
    pal_open: bool,
    pal_query: String,
    pal_sel: usize,
    /// The run history window, and the runs it is showing. Read from disk when the
    /// window opens, not on every frame.
    runs_open: bool,
    runs_cache: Option<Vec<runlog::Run>>,
    /// The last health report, and nothing until the button is pressed.
    ///
    /// Not recomputed every frame: it reads the templates folder and resolves called
    /// macros, which is file system work that has no business happening sixty times a
    /// second. Cleared whenever the macro changes, so a stale score is never shown
    /// beside a macro it was not about.
    health: Option<health::Report>,
    /// What is in `templates/` against what this macro asks for. `None` until the
    /// button is pressed: it decodes every picture in the folder, which is not
    /// something to do once a frame.
    resources: Option<Resources>,
    /// A save that is waiting for an answer about overwriting a newer file.
    pending_save: Option<PathBuf>,
    /// The handbook: whether its window is up, which article is open, and what is
    /// typed in its search box.
    ///
    /// `help_topic` is written by whichever section header was last opened, so the
    /// book comes up where the reader already was rather than at the front page.
    /// That is what replaced fifty-one paragraphs of hover text: help at the point
    /// of need, without the point of need being covered in prose.
    help_open: bool,
    help_topic: &'static str,
    /// The topic the main window last handed to the handbook, so a section header
    /// can move it without the next frame dragging it back.
    pushed_topic: &'static str,
    /// Whether the restored window geometry has been looked at yet. Once per run.
    geometry_checked: bool,
    /// Which trace is open in the "why did that happen" panel, by its position in
    /// the newest-first list.
    why_at: usize,
    /// The picture we are looking for, shared with the search thread.
    template: Option<Arc<vision::Template>>,
    ocr_text: String,
    ocr_rect: (i32, i32, i32, i32),
    /// What the panel does to the pixels, and what it expects to read. Both are
    /// here so a profile can be tried against a real screen before it is written
    /// into a step, which is the only way to choose one honestly.
    ocr_prep: ocr::Prep,
    ocr_expect: ocr::Expect,
    /// Fit of the last reading, and the profile that produced it.
    ocr_fit: Option<(f64, ocr::Prep)>,
    /// Two-corner region picker: deadline, and whether we are on the second corner.
    ocr_pick: Option<(Instant, bool)>,
    ocr_corner: (i32, i32),
    /// 0 = story, 1 = raw events, 2 = script.
    ed_view: usize,
    scr_sel: usize,
    scr_add_kind: usize,
    // profiles
    profiles: Vec<String>,
    profile_name: String,
    /// Fill for the central panel - this is what makes the window translucent.
    panel_fill: egui::Color32,
    /// The expander's entries while they are being edited. A working copy rather
    /// than the live one: the keyboard hook reads the live book on every keystroke,
    /// and holding that lock across a frame of rendering is exactly how a low-level
    /// hook gets itself unhooked.
    exp_book: expander::Book,
    /// The exclusion list is a `Vec` in the file and one line in the UI.
    exp_excluded: String,
    exp_dirty: bool,
    // pixel picking
    pick_deadline: Option<Instant>,
    /// When the current "press a key" session started.
    capture_started: Option<Instant>,
}

/// One of the extra windows, described rather than passed as eight arguments.
///
/// `draw` and `closed` are plain function pointers because a deferred viewport's
/// callback has to be `Send + Sync + 'static` and so cannot borrow the application.
struct ExtraWindow {
    id: &'static str,
    title: String,
    size: [f32; 2],
    min: [f32; 2],
    draw: fn(&mut AppInner, &mut egui::Ui),
    closed: fn(&mut AppInner),
}

impl AppInner {
    fn new(cc: &eframe::CreationContext<'_>, state: Arc<AppState>, config: AppConfig) -> Self {
        setup_fonts(&cc.egui_ctx);
        let panel_fill =
            apply_theme(&cc.egui_ctx, theme_at(config.default_theme), config.transparent_ui);
        let exp_book = expander::snapshot();
        Self {
            // Filled in by `MacroApp::new` the moment the Arc around this exists.
            me: std::sync::Weak::new(),
            exp_excluded: exp_book.excluded_windows.join(", "),
            exp_book,
            exp_dirty: false,
            panel_fill,
            state,
            config,
            system_lang: detect_system_lang(),
            status_msg: String::new(),
            theme_dirty: true,
            ed_from: 0,
            ed_to: 0,
            ed_delay_ms: 500,
            ed_scale: 1.0,
            ed_undo: None,
            editor_open: false,
            vars_open: false,
            shots_offer: false,
            was_recording: false,
            was_test_run: false,
            was_playing: false,
            ed_steps: Vec::new(),
            ed_steps_key: (usize::MAX, 0, 0),
            ed_cursor: 0,
            ed_undo_key: None,
            ed_pick_deadline: None,
            bulk_from_btn: 0,
            bulk_to_btn: 1,
            bulk_dx: 0,
            bulk_dy: 0,
            tabs: Vec::new(),
            tab: 0,
            queue: Vec::new(),
            queue_at: None,
            deps: None,
            pending_pkg: None,
            cleanup: None,
            library: None,
            scr_marked: Default::default(),
            stats: Default::default(),
            suggestions: Vec::new(),
            pal_open: false,
            pal_query: String::new(),
            pal_sel: 0,
            runs_open: false,
            runs_cache: None,
            health: None,
            resources: None,
            pending_save: None,
            help_open: false,
            help_topic: "first-run",
            pushed_topic: "first-run",
            geometry_checked: false,
            why_at: 0,
            template: None,
            ocr_text: String::new(),
            ocr_rect: (0, 0, 600, 200),
            ocr_prep: ocr::Prep::default(),
            ocr_expect: ocr::Expect::default(),
            ocr_fit: None,
            ocr_pick: None,
            ocr_corner: (0, 0),
            ed_view: 0,
            scr_sel: 0,
            scr_add_kind: 0,
            profiles: list_profiles(),
            profile_name: String::new(),
            pick_deadline: None,
            capture_started: None,
        }
    }

    fn strs(&self) -> &'static Strings {
        get_strings(self.config.default_lang, self.system_lang)
    }

    fn busy(&self) -> bool {
        self.state.recording.load(Ordering::Relaxed) || self.state.playing.load(Ordering::Relaxed)
    }

    fn snapshot_for_undo(&mut self) {
        self.ed_undo = Some(self.state.macro_data.lock().clone());
    }

    /// Edit path for the inspector: snapshots once per event, so undo returns to
    /// the state before you started fiddling with *this* action rather than to the
    /// previous animation frame.
    fn edit_event<F: FnOnce(&mut MacroData)>(&mut self, index: usize, f: F) {
        if self.busy() {
            return;
        }
        if self.ed_undo_key != Some(index) {
            self.ed_undo = Some(self.state.macro_data.lock().clone());
            self.ed_undo_key = Some(index);
        }
        let mut data = self.state.macro_data.lock();
        f(&mut data);
        let dur = data.duration_us;
        drop(data);
        self.state.recorded_time_us.store(dur, Ordering::Relaxed);
    }

    fn edit<F: FnOnce(&mut MacroData)>(&mut self, f: F) {
        if self.busy() {
            return;
        }
        self.snapshot_for_undo();
        self.ed_undo_key = None;
        let mut data = self.state.macro_data.lock();
        f(&mut data);
        let dur = data.duration_us;
        drop(data);
        self.state.recorded_time_us.store(dur, Ordering::Relaxed);
        // A score shown beside a macro it was not computed from is worse than no
        // score: it is a number that looks checked. The same goes for a cleanup
        // preview counted from events that have since been edited.
        self.health = None;
        self.cleanup = None;
        self.deps = None;
    }

    /// What the history knows about one step, if anything.
    fn stats_for(&self, id: u64) -> Option<StepStats> {
        self.stats.get(&id).copied().filter(|st| st.runs > 0)
    }

    /// Re-reads the per-step numbers from the run history.
    ///
    /// Called when the editor opens and when a run ends, not every frame: it parses
    /// the whole history file, and doing that sixty times a second to show four
    /// numbers would be absurd.
    fn refresh_stats(&mut self) {
        self.stats = runlog::stats();
    }

    /// Looks the macro over without running it.
    ///
    /// Everything the checker cannot know from the macro alone is gathered here -
    /// what is in `templates/`, whether a `Call` resolves, whether a target window is
    /// set, whether this run ends by turning the machine off - and handed in, which
    /// is what keeps `health::check` a pure function that can be tested without a
    /// disk.
    fn run_health_check(&mut self) {
        let report = self.check_now();
        self.health = Some(report);
    }

    /// The check itself, without deciding what to do about the answer.
    ///
    /// Split out because the Run button wants the report and does not want the panel
    /// filled in behind whatever it is about to put on top of it.
    fn check_now(&self) -> health::Report {
        let data = self.state.macro_data.lock().clone();
        let path = self.state.current_path.lock().clone();
        let report = check_macro(&data, CheckEnv::from_config(&self.config), path.as_deref());
        info!(
            "macro checked: {}/100, {} error(s), {} warning(s)",
            report.score,
            report.errors(),
            report.warnings()
        );
        report
    }

    fn do_save(&mut self, path: PathBuf) {
        let s = self.strs();
        let data = self.state.macro_data.lock().clone();
        if data.is_empty() {
            self.status_msg = s.no_macro.to_string();
            return;
        }
        // A macro read from a file this build only half understands is not saved
        // without being asked about. Everything else about this program is
        // recoverable; this one silently destroys the newer half of somebody's work
        // at the moment they think they are protecting it.
        if data.from_future > 0 {
            self.pending_save = Some(path);
            return;
        }
        self.write_macro(path);
    }

    fn write_macro(&mut self, path: PathBuf) {
        let s = self.strs();
        let mut data = self.state.macro_data.lock().clone();
        // A macro read from a newer file keeps that file's version number while it is
        // in memory, because that number is the evidence the guard above is built on.
        // The moment somebody accepts the loss and saves, it stops being true: what
        // goes to disk is this format's contents, and labelling it 99 would leave a
        // file whose version disagrees with what is in it - which is the exact fault
        // this whole guard exists to stop, only now written by us.
        //
        // Found by driving matrix row T-38: the unknown field was correctly gone and
        // the file still said format 99.
        let relabelled = data.from_future > 0;
        if relabelled {
            data.version = format_version();
            data.from_future = 0;
        }
        match save_macro(&path, &data) {
            Ok(()) => {
                if relabelled {
                    // The file on disk is now genuinely this format, so there is
                    // nothing left to warn about and the next save must not ask again.
                    let mut live = self.state.macro_data.lock();
                    live.version = format_version();
                    live.from_future = 0;
                }
                self.config.push_recent(&path);
                *self.state.current_path.lock() = Some(path.clone());
                self.status_msg = s.saved.replace("{}", &file_label(&path));
            }
            Err(e) => self.status_msg = s.save_err.replace("{}", &e.to_string()),
        }
    }

    fn do_load(&mut self, path: PathBuf) {
        let s = self.strs();
        match load_macro(&path) {
            Ok(data) => {
                self.state.recorded_time_us.store(data.duration_us, Ordering::Relaxed);
                *self.state.macro_data.lock() = data;
                *self.state.current_path.lock() = Some(path.clone());
                self.config.push_recent(&path);
                self.ed_undo = None;
                self.health = None;
                self.resources = None;
                self.why_at = 0;
                let said = self.state.macro_data.lock().from_future;
                self.status_msg = if said > 0 {
                    // Said at the moment it is found out, not only when saving is
                    // attempted: somebody who edits for an hour first and only then
                    // meets the dialog has already lost the hour.
                    format!("{}  -  {}", file_label(&path), s.save_newer)
                } else {
                    s.loaded.replace("{}", &file_label(&path))
                };
            }
            Err(e) => self.status_msg = s.load_err.replace("{}", &e.to_string()),
        }
    }

    /// Rebuilds the story only when the macro or the language actually changed.
    fn refresh_steps(&mut self) {
        let s = self.strs();
        let (count, dur, events) = {
            let d = self.state.macro_data.lock();
            (d.events.len(), d.duration_us, d.events.clone())
        };
        let key = (count, dur, self.config.default_lang);
        if key != self.ed_steps_key {
            self.ed_steps = summarize(&events, s);
            self.ed_steps_key = key;
        }
    }

    /// Writes the squares as templates and rewrites the recording as a script.
    ///
    /// Everything or nothing: if a PNG will not write, the pictures that did write
    /// are left where they are but the script is not replaced, so the recording the
    /// user just made is never traded for a half-built script.
    fn make_click_image_steps(&mut self) {
        self.apply_suggestions(None);
    }

    /// Writes the pictures the chosen rows need and rewrites the script to aim at
    /// targets instead of coordinates.
    ///
    /// `picked` selects rows by their position in the shots list; `None` takes them
    /// all, which is what the offer made straight after a recording does.
    ///
    /// The pictures are written before the script is built and only for rows that
    /// were chosen: a `templates/` folder full of squares nobody asked for is the
    /// obvious way for this feature to become annoying.
    fn apply_suggestions(&mut self, picked: Option<&[bool]>) {
        let s = self.strs();
        let shots = self.state.click_shots.lock().clone();
        if shots.is_empty() {
            return;
        }
        let stamp = recording_stamp();
        let mut names = Vec::with_capacity(shots.len());
        let mut failed: Option<String> = None;
        for (n, shot) in shots.iter().enumerate() {
            let name = click_shot_name(&stamp, n + 1);
            let wanted = picked.is_none_or(|p| p.get(n).copied().unwrap_or(false));
            if !wanted {
                // A name is still needed so the positions line up with the shots,
                // but nothing is written for a row nobody ticked.
                names.push(name);
                continue;
            }
            match save_click_shot(shot, &name) {
                Ok(()) => names.push(name),
                Err(e) => {
                    failed = Some(e.to_string());
                    break;
                }
            }
        }
        if let Some(e) = failed {
            self.status_msg = s.save_err.replace("{}", &e);
            return;
        }
        let threshold = self.config.img_threshold.clamp(0.3, 1.0);
        let miss = self.config.click_shot_miss.clone();
        let data = self.state.macro_data.lock().clone();
        let (script, made) =
            script_from_click_shots(&data, &shots, &names, threshold, miss, picked);
        if made == 0 {
            // Every press was a drag, was never released, or was left unticked.
            // Saying so beats replacing the script with one `Play events` step and
            // calling it done.
            self.status_msg = s.rec_shots_done.replace("{}", "0");
            return;
        }
        self.edit(|d| d.script = script);
        self.ed_view = 2;
        self.status_msg = s.analyze_done.replace("{}", &made.to_string());
        info!("recording turned into {made} target steps, templates rec_{stamp}_*");
    }

    /// Drops a run of steps in after the selected one and selects the first of them.
    fn insert_steps(&mut self, steps: Vec<ScriptStep>) {
        if steps.is_empty() {
            return;
        }
        let at = self.scr_sel;
        let n = steps.len();
        self.edit(|d| {
            let pos = (at + 1).min(d.script.len());
            for (i, st) in steps.into_iter().enumerate() {
                d.script.insert(pos + i, st);
            }
        });
        self.scr_marked.clear();
        self.scr_sel = (at + 1).min(self.state.macro_data.lock().script.len().saturating_sub(1));
        let _ = n;
        self.editor_open = true;
        self.ed_view = 2;
    }

    /// Makes sure there is a tab for whatever is currently in front.
    ///
    /// Called once a frame. Cheap: it only touches the vector when the list is empty,
    /// which is the first frame and after the last tab is closed.
    fn sync_tabs(&mut self) {
        if self.tabs.is_empty() {
            self.tabs.push(Tab {
                data: MacroData::default(),
                path: self.state.current_path.lock().clone(),
            });
            self.tab = 0;
        }
        self.tab = self.tab.min(self.tabs.len() - 1);
    }

    /// Parks whatever is in front into its tab, and brings another one forward.
    ///
    /// Refused while something is playing or recording: the engine is reading
    /// `macro_data` on another thread, and swapping it underneath a running macro is
    /// the one way this design could go wrong.
    fn switch_tab(&mut self, to: usize) {
        if self.busy() || to == self.tab || to >= self.tabs.len() {
            return;
        }
        // Park the one in front.
        {
            let mut live = self.state.macro_data.lock();
            let here = &mut self.tabs[self.tab];
            here.data = std::mem::take(&mut *live);
            here.path = self.state.current_path.lock().clone();
            // And bring the other one forward, in the same lock.
            *live = std::mem::take(&mut self.tabs[to].data);
            let dur = live.duration_us;
            drop(live);
            self.state.recorded_time_us.store(dur, Ordering::Relaxed);
        }
        *self.state.current_path.lock() = self.tabs[to].path.clone();
        self.tab = to;
        // Everything computed from the old macro is about the old macro.
        self.ed_undo = None;
        self.health = None;
        self.cleanup = None;
        self.deps = None;
        self.suggestions.clear();
        self.scr_marked.clear();
        self.scr_sel = 0;
        self.ed_from = 0;
        self.ed_to = 0;
    }

    /// The tab strip, and the queue under it.
    fn tabs_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        self.sync_tabs();

        let mut go: Option<usize> = None;
        let mut close: Option<usize> = None;
        ui.horizontal_wrapped(|ui| {
            // The label for the front tab comes from the live state, not from the
            // parked copy, because the parked copy is stale by definition.
            let live_path = self.state.current_path.lock().clone();
            for i in 0..self.tabs.len() {
                let label = if i == self.tab {
                    match &live_path {
                        Some(p) => file_label(p),
                        None => s.tab_untitled.to_string(),
                    }
                } else {
                    self.tabs[i].label(s)
                };
                if ui.selectable_label(i == self.tab, label).clicked() {
                    go = Some(i);
                }
            }
            if ui.add_enabled(!busy, egui::Button::new(s.tab_new)).clicked() {
                self.tabs.push(Tab::default());
                go = Some(self.tabs.len() - 1);
            }
            if ui
                .add_enabled(!busy && self.tabs.len() > 1, egui::Button::new(s.tab_close))
                .clicked()
            {
                close = Some(self.tab);
            }
        });

        if let Some(i) = go {
            self.switch_tab(i);
        }
        if let Some(i) = close {
            // Move away first, so the one being closed is parked rather than live.
            let next = if i == 0 { 1 } else { i - 1 };
            self.switch_tab(next);
            self.tabs.remove(i);
            if self.tab > i {
                self.tab -= 1;
            }
        }
    }

    /// The queue: a list of files to play one after another.
    fn queue_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        ui.horizontal_wrapped(|ui| {
            if ui.add_enabled(!busy, egui::Button::new(s.queue_add)).clicked() {
                if let Some(p) = self.state.current_path.lock().clone() {
                    self.queue.push(p);
                } else {
                    self.status_msg = s.no_macro.to_string();
                }
            }
            if ui.add_enabled(!busy, egui::Button::new(s.queue_clear)).clicked() {
                self.queue.clear();
                self.queue_at = None;
            }
            if ui
                .add_enabled(!busy && !self.queue.is_empty(), egui::Button::new(s.queue_run))
                .clicked()
            {
                self.queue_at = Some(0);
                self.advance_queue();
            }
        });

        if self.queue.is_empty() {
            ui.label(egui::RichText::new(s.queue_none).weak());
            return;
        }
        let mut remove: Option<usize> = None;
        for (i, p) in self.queue.iter().enumerate() {
            ui.horizontal(|ui| {
                let running = self.queue_at == Some(i);
                let mut rt = egui::RichText::new(format!("{}. {}", i + 1, file_label(p)));
                if running {
                    rt = rt.strong();
                }
                ui.label(rt);
                if ui.add_enabled(!busy, egui::Button::new("🗑")).clicked() {
                    remove = Some(i);
                }
            });
        }
        if let Some(i) = remove {
            self.queue.remove(i);
        }
    }

    /// Loads and starts whichever queue entry is next, or stops when there is none.
    ///
    /// Driven from the frame loop rather than from a thread: playback already owns a
    /// thread, and a second one deciding what it plays next would need a protocol
    /// between them. Checking "has it finished?" once a frame needs none.
    fn advance_queue(&mut self) {
        let Some(i) = self.queue_at else { return };
        let Some(path) = self.queue.get(i).cloned() else {
            self.queue_at = None;
            return;
        };
        self.do_load(path);
        start_playback(&self.state);
    }

    /// The capability list, as a row of ticks and a row of warnings.
    ///
    /// Shared by the health panel and the package panel so that what somebody is
    /// shown before importing a stranger's macro is built by the same code as what
    /// they see for their own.
    fn caps_ui(ui: &mut egui::Ui, s: &Strings, c: &health::Caps) {
        let plain: [(bool, &str); 8] = [
            (c.mouse, s.cap_mouse),
            (c.keyboard, s.cap_keyboard),
            (c.screen, s.cap_screen),
            (c.ocr, s.cap_ocr),
            (c.uia, s.cap_uia),
            (c.clipboard, s.cap_clipboard),
            (c.files, s.cap_files),
            (c.windows, s.cap_windows),
        ];
        ui.horizontal_wrapped(|ui| {
            for (on, name) in plain {
                if on {
                    ui.label(egui::RichText::new(format!("\u{2714} {name}")).weak());
                }
            }
        });
        for (on, name) in
            [(c.launch, s.cap_launch), (c.power, s.cap_power), (c.external, s.cap_external)]
        {
            if on {
                ui.label(
                    egui::RichText::new(format!("\u{26a0} {name}"))
                        .color(egui::Color32::from_rgb(255, 200, 90)),
                );
            }
        }
    }

    /// What this macro carries with it, whether it is all here, and the two buttons
    /// that turn it into one file or read one back.
    fn package_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        let here = self
            .state
            .current_path
            .lock()
            .as_ref()
            .and_then(|p| p.parent().map(|d| d.to_path_buf()));

        ui.horizontal_wrapped(|ui| {
            if ui
                .add_enabled(!busy, egui::Button::new(s.pkg_inspect))
                .clicked()
            {
                let data = self.state.macro_data.lock().clone();
                self.deps = Some(collect_deps(&data, here.as_deref()));
            }
            if ui.add_enabled(!busy, egui::Button::new(s.pkg_export)).clicked() {
                self.export_package();
            }
            if ui.add_enabled(!busy, egui::Button::new(s.pkg_import)).clicked() {
                self.open_package();
            }
        });

        // A package waiting to be looked at takes over the panel: reading the list
        // is the point, and burying it under the dependency table would be the same
        // as not showing it.
        if let Some((pkg, path)) = self.pending_pkg.clone() {
            ui.separator();
            ui.label(egui::RichText::new(file_label(&path)).strong());
            // Only the capability list is wanted here, and it is worked out from the
            // steps alone. Everything else is answered as "fine" on purpose: this
            // package has not been unpacked yet, so its pictures are not on this
            // disk and complaining that they are missing would be complaining that
            // it has not been imported.
            let caps = health::check(
                &pkg.main,
                &health::Env {
                    templates: &Default::default(),
                    call_exists: &|_| true,
                    call_targets: &|_| Vec::new(),
                    self_path: None,
                    target_window: true,
                    ocr_lang: true,
                    display: None,
                    power_action: false,
                },
            )
            .caps;
            ui.label(egui::RichText::new(s.pkg_declares).strong());
            Self::caps_ui(ui, s, &caps);
            ui.horizontal_wrapped(|ui| {
                if ui.button(s.pkg_import).clicked() {
                    self.install_pending();
                }
                if ui.button(s.rec_shots_skip).clicked() {
                    self.pending_pkg = None;
                }
            });
            return;
        }

        let Some(deps) = self.deps.as_ref() else { return };
        ui.separator();
        if deps.templates.is_empty() && deps.macros.is_empty() {
            ui.label(egui::RichText::new(s.pkg_none).weak());
            return;
        }
        ui.label(egui::RichText::new(s.pkg_deps).strong());
        for (name, ok) in deps.templates.iter().chain(deps.macros.iter()) {
            let (mark, colour) = if *ok {
                ("\u{2714}", egui::Color32::from_rgb(120, 210, 120))
            } else {
                ("\u{2716}", egui::Color32::from_rgb(255, 130, 110))
            };
            let tail = if *ok { String::new() } else { format!("  ({})", s.pkg_missing) };
            ui.label(egui::RichText::new(format!("{mark} {name}{tail}")).color(colour));
        }
        if deps.all_present() {
            ui.label(
                egui::RichText::new(s.pkg_ready)
                    .color(egui::Color32::from_rgb(120, 210, 120)),
            );
        }
    }

    fn export_package(&mut self) {
        let s = self.strs();
        let data = self.state.macro_data.lock().clone();
        if data.is_empty() {
            self.status_msg = s.no_macro.to_string();
            return;
        }
        let here = self
            .state
            .current_path
            .lock()
            .as_ref()
            .and_then(|p| p.parent().map(|d| d.to_path_buf()));
        let name = self
            .state
            .current_path
            .lock()
            .as_ref()
            .and_then(|p| p.file_stem().map(|f| f.to_string_lossy().to_string()))
            .unwrap_or_else(|| "macro".into());
        let Some(path) = rfd::FileDialog::new()
            .add_filter("Macro package", &["mrpkg"])
            .set_directory(paths::data_dir())
            .set_file_name(format!("{name}.mrpkg"))
            .save_file()
        else {
            return;
        };
        match build_package(&data, here.as_deref(), &name)
            .and_then(|pkg| save_package(&path, &pkg))
        {
            Ok(()) => {
                self.status_msg = s.exported.replace("{}", &file_label(&path));
                info!("package written to {}", path.display());
            }
            Err(e) => self.status_msg = s.save_err.replace("{}", &e.to_string()),
        }
    }

    /// Opens a package and stops. Nothing is written until the list has been read.
    fn open_package(&mut self) {
        let s = self.strs();
        let Some(path) = rfd::FileDialog::new()
            .add_filter("Macro package", &["mrpkg"])
            .set_directory(paths::data_dir())
            .pick_file()
        else {
            return;
        };
        match load_package(&path) {
            Ok(pkg) => self.pending_pkg = Some((pkg, path)),
            Err(e) => self.status_msg = s.load_err.replace("{}", &e.to_string()),
        }
    }

    fn install_pending(&mut self) {
        let s = self.strs();
        let Some((pkg, path)) = self.pending_pkg.take() else { return };
        match install_package(&pkg) {
            Ok(skipped) => {
                self.state
                    .recorded_time_us
                    .store(pkg.main.duration_us, Ordering::Relaxed);
                *self.state.macro_data.lock() = pkg.main;
                *self.state.current_path.lock() = None;
                self.ed_undo = None;
                self.health = None;
                self.deps = None;
                self.status_msg = if skipped.is_empty() {
                    s.pkg_installed.replace("{}", &file_label(&path))
                } else {
                    format!(
                        "{}  {}",
                        s.pkg_installed.replace("{}", &file_label(&path)),
                        s.pkg_skipped.replace("{}", &skipped.join(", "))
                    )
                };
            }
            Err(e) => self.status_msg = s.load_err.replace("{}", &e.to_string()),
        }
    }

    /// **Preview first, always.** The plan is computed and shown; only a second,
    /// separate button applies it.
    ///
    /// A recording is somebody's afternoon. Replacing it with a shorter one on a
    /// single click, sight unseen, is not a trade anybody agreed to — and the
    /// existing single-slot undo is one press of anything else away from being gone.
    fn optimize_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();

        if ui
            .add_enabled(!busy, egui::Button::new(s.opt_preview))
            .clicked()
        {
            let d = self.state.macro_data.lock();
            self.cleanup = Some(plan_cleanup(&d));
        }

        let Some(plan) = self.cleanup else { return };
        if !plan.worth_doing() {
            ui.label(egui::RichText::new(s.opt_none).weak());
            return;
        }

        ui.label(
            egui::RichText::new(
                s.opt_result
                    .replacen("{}", &plan.before.to_string(), 1)
                    .replacen("{}", &plan.after.to_string(), 1),
            )
            .strong(),
        );
        // Itemised, because "18 432 → 4 821" on its own asks to be trusted and this
        // is the one place trust should not be asked for.
        ui.horizontal_wrapped(|ui| {
            for (n, label) in [
                (plan.micro, s.opt_micro),
                (plan.dupes, s.opt_dupes),
                (plan.lead, s.opt_lead),
            ] {
                if n > 0 {
                    ui.label(egui::RichText::new(format!("−{n} {label}")).weak());
                }
            }
            if plan.idle_us > 0 {
                ui.label(
                    egui::RichText::new(format!(
                        "−{} {}",
                        format_dur(plan.idle_us),
                        s.opt_idle
                    ))
                    .weak(),
                );
            }
        });

        if ui.add_enabled(!busy, egui::Button::new(s.opt_apply)).clicked() {
            self.edit(optimize_recording);
            self.cleanup = None;
            self.status_msg = s
                .opt_result
                .replacen("{}", &plan.before.to_string(), 1)
                .replacen("{}", &plan.after.to_string(), 1);
        }
    }

    /// The templates menu.
    fn templates_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        let mut chosen: Option<usize> = None;
        egui::ScrollArea::vertical().max_height(220.0).auto_shrink([false, true]).show(
            ui,
            |ui| {
                for (i, r) in templates::ALL.iter().enumerate() {
                    ui.horizontal(|ui| {
                        if ui
                            .add_enabled(!busy, egui::Button::new(s.tpl_insert))
                            .clicked()
                        {
                            chosen = Some(i);
                        }
                        ui.label((r.name)(s));
                    });
                }
            },
        );
        if let Some(i) = chosen {
            let built = (templates::ALL[i].build)();
            self.insert_steps(built);
            self.status_msg = (templates::ALL[i].name)(s).to_string();
        }
    }

    /// The macro library: every file in `<data>/macros/`, insertable as a `Call`.
    fn library_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        ui.horizontal_wrapped(|ui| {
            if ui.button(s.lib_refresh).clicked() {
                self.library = None;
            }
            if ui.button(s.data_dir).clicked() {
                let dir = paths::sub_dir("macros");
                let _ = std::fs::create_dir_all(&dir);
                run_program(&dir.to_string_lossy(), "");
            }
        });
        if self.library.is_none() {
            self.library = Some(library_macros());
        }
        let names = self.library.clone().unwrap_or_default();
        if names.is_empty() {
            ui.label(egui::RichText::new(s.lib_none).weak());
            return;
        }
        let mut chosen: Option<String> = None;
        egui::ScrollArea::vertical().max_height(200.0).auto_shrink([false, true]).show(
            ui,
            |ui| {
                for n in &names {
                    ui.horizontal(|ui| {
                        if ui
                            .add_enabled(!busy, egui::Button::new(s.lib_insert))
                            .clicked()
                        {
                            chosen = Some(n.clone());
                        }
                        ui.label(n);
                    });
                }
            },
        );
        if let Some(n) = chosen {
            // A `Call` step naming it, which is what the library is for: the macro
            // stays one file, edited and tested on its own.
            self.insert_steps(vec![ScriptStep::new(StepKind::Call {
                path: n.clone(),
                miss: OnMiss::Stop,
            })]);
            self.status_msg = n;
        }
    }

    /// The markers, and the button that puts one down at the current selection.
    ///
    /// Deliberately in the editor beside the event list rather than in a window of
    /// its own: a marker is a name for a place in the recording, and the only moment
    /// anybody knows which place they mean is while they are looking at it.
    fn markers_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        let (markers, total) = {
            let d = self.state.macro_data.lock();
            (d.markers.clone(), d.events.len())
        };

        ui.horizontal_wrapped(|ui| {
            if ui
                .add_enabled(!busy && total > 0, egui::Button::new(s.mk_add))
                .clicked()
            {
                let at = self.ed_from.min(total);
                // Named after where it is, because a marker called "Marker 3" is a
                // number with extra steps. The user renames it in the field beside.
                let name = {
                    let mut n = 1;
                    loop {
                        let candidate = format!("{} {n}", s.mk_name);
                        if !markers.iter().any(|m| m.name == candidate) {
                            break candidate;
                        }
                        n += 1;
                    }
                };
                self.edit(|d| {
                    d.markers.push(Marker { name, at });
                    d.markers.sort_by_key(|m| m.at);
                });
            }
            if markers.is_empty() {
                ui.label(egui::RichText::new(s.mk_none).weak());
            }
        });

        let mut edits: Vec<(usize, String)> = Vec::new();
        let mut remove: Option<usize> = None;
        for (i, m) in markers.iter().enumerate() {
            ui.horizontal_wrapped(|ui| {
                let mut name = m.name.clone();
                if ui
                    .add(egui::TextEdit::singleline(&mut name).desired_width(160.0))
                    .changed()
                {
                    edits.push((i, name));
                }
                ui.label(egui::RichText::new(format!("{} {}", s.mk_at, m.at)).weak());
                if ui.add_enabled(!busy, egui::Button::new("🗑")).clicked() {
                    remove = Some(i);
                }
            });
        }
        if let Some(i) = remove {
            self.edit(|d| {
                if i < d.markers.len() {
                    d.markers.remove(i);
                }
            });
        } else if !edits.is_empty() {
            self.edit(|d| {
                for (i, name) in edits {
                    if let Some(m) = d.markers.get_mut(i) {
                        m.name = name;
                    }
                }
            });
        }
    }

    /// The **Analyze recording** table: one row per click, what it is now, what it
    /// could be, and a tick.
    fn analyze_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        if ui
            .add_enabled(!busy, egui::Button::new(s.analyze_now))
            .clicked()
        {
            let shots = self.state.click_shots.lock().clone();
            let data = self.state.macro_data.lock().clone();
            // The names are provisional until the rows are applied; the analysis only
            // needs them to know an image method is possible at all.
            let stamp = recording_stamp();
            let names: Vec<String> =
                (0..shots.len()).map(|n| click_shot_name(&stamp, n + 1)).collect();
            self.suggestions = analyze_clicks(&data, &shots, &names);
        }
        if self.suggestions.is_empty() {
            ui.label(egui::RichText::new(s.analyze_none).weak());
            return;
        }

        egui::ScrollArea::vertical().max_height(260.0).auto_shrink([false, true]).show(
            ui,
            |ui| {
                egui::Grid::new("analyze_grid").striped(true).show(ui, |ui| {
                    ui.label("");
                    ui.label(egui::RichText::new(s.analyze_col_now).strong());
                    ui.label(egui::RichText::new(s.analyze_col_better).strong());
                    ui.end_row();
                    for sug in self.suggestions.iter_mut() {
                        ui.checkbox(&mut sug.apply, "");
                        ui.label(egui::RichText::new(sug.now(s)).monospace());
                        // Coloured by how much is actually gained: a row whose best
                        // offer is the coordinate it already has should not look like
                        // an improvement.
                        let gain = sug.best.as_ref().map(|m| m.rank()).unwrap_or(0);
                        let colour = match gain {
                            4 => egui::Color32::from_rgb(120, 210, 120),
                            3 => egui::Color32::from_rgb(150, 200, 255),
                            1..=2 => egui::Color32::from_rgb(255, 200, 90),
                            _ => egui::Color32::GRAY,
                        };
                        ui.label(egui::RichText::new(sug.better(s)).color(colour));
                        ui.end_row();
                    }
                });
            },
        );

        let ticked = self.suggestions.iter().filter(|x| x.apply).count();
        if ui
            .add_enabled(!busy && ticked > 0, egui::Button::new(s.analyze_apply))
            .clicked()
        {
            // Back to shot positions: the table only holds the clicks that could
            // become something, so a row's index is not its shot's index.
            let total = self.state.click_shots.lock().len();
            let mut picked = vec![false; total];
            for sug in self.suggestions.iter().filter(|x| x.apply) {
                if let Some(slot) = picked.get_mut(sug.shot) {
                    *slot = true;
                }
            }
            self.apply_suggestions(Some(&picked));
            self.suggestions.clear();
        }
    }

    /// The offer itself, drawn over the main window while it stands.
    fn shots_offer_ui(&mut self, ctx: &egui::Context) {
        if !self.shots_offer {
            return;
        }
        let s = self.strs();
        let count = self.state.click_shots.lock().len();
        if count == 0 {
            self.shots_offer = false;
            return;
        }
        let mut make = false;
        let mut skip = false;
        egui::Window::new(s.rec_shots.replace("{}", &count.to_string()))
            .collapsible(false)
            .resizable(false)
            .anchor(egui::Align2::CENTER_CENTER, [0.0, 0.0])
            .show(ctx, |ui| {
                ui.set_max_width(420.0);
                ui.label(s.rec_shots_ask.replace("{}", &count.to_string()));
                ui.add_space(6.0);
                // The one decision worth making here, because it is the one that
                // decides what a broken macro does at three in the morning.
                let mut miss = self.config.click_shot_miss.clone();
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.rec_shots_miss);
                    egui::ComboBox::from_id_salt("shot_miss")
                        .selected_text(miss.name(s))
                        .width(150.0)
                        .show_ui(ui, |ui| {
                            for i in 0..OnMiss::COUNT {
                                let opt = OnMiss::from_index(i);
                                if ui.selectable_label(miss.index() == i, opt.name(s)).clicked() {
                                    miss = opt;
                                }
                            }
                        });
                });
                self.config.click_shot_miss = miss;
                ui.add_space(6.0);
                ui.horizontal_wrapped(|ui| {
                    make = ui.button(s.rec_shots_make).clicked();
                    skip = ui.button(s.rec_shots_skip).clicked();
                });
            });
        if make {
            self.make_click_image_steps();
            self.shots_offer = false;
        } else if skip {
            // The squares are dropped, not kept: an offer that was declined and
            // then quietly reappears after the next recording is worse than no
            // offer at all.
            self.state.click_shots.lock().clear();
            self.shots_offer = false;
        }
    }

    /// Where the recording was made, set against where it is about to be replayed.
    ///
    /// The comparison is the whole feature. A list of what the machine was doing in
    /// April is trivia; *150 % then, 100 % now* is the answer to the question people
    /// actually ask, which is why every row that differs is coloured and every row
    /// that matches is not.
    fn recinfo_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let info = self.state.macro_data.lock().recorded.clone();
        let Some(then) = info.filter(|i| !i.is_empty()) else {
            ui.label(egui::RichText::new(s.ri_none).weak());
            return;
        };
        let now = RecordingInfo::here();
        let differs = egui::Color32::from_rgb(255, 200, 90);

        // (label, then, now-if-it-differs). `None` for the rows that are facts about
        // the recording rather than about the machine, and so have nothing to differ
        // from.
        let rows: Vec<(&str, String, Option<String>)> = vec![
            (s.ri_when, then.when.clone(), None),
            (
                s.ri_display,
                format!("{}\u{00d7}{}", then.screen_w, then.screen_h),
                (then.screen_w != now.screen_w || then.screen_h != now.screen_h)
                    .then(|| format!("{}\u{00d7}{}", now.screen_w, now.screen_h)),
            ),
            (
                s.ri_scale,
                format!("{} %", then.scale_pct()),
                (then.dpi != now.dpi).then(|| format!("{} %", now.scale_pct())),
            ),
            (
                s.ri_monitor,
                format!("{} / {}", then.monitor, then.monitors),
                (then.monitors != now.monitors)
                    .then(|| format!("{} / {}", now.monitor, now.monitors)),
            ),
            (s.ri_process, then.process.clone(), None),
            (s.ri_window, clip(&then.window, 60), None),
            (
                s.ri_layout,
                then.layout.clone(),
                (!then.layout.is_empty() && then.layout != now.layout)
                    .then(|| now.layout.clone()),
            ),
            (s.ri_app, then.app.clone(), None),
        ];
        for (label, was, changed) in rows {
            if was.trim().is_empty() {
                continue;
            }
            ui.horizontal_wrapped(|ui| {
                ui.label(egui::RichText::new(label).weak());
                match changed {
                    Some(now) => {
                        ui.label(egui::RichText::new(was).color(differs));
                        ui.label(
                            egui::RichText::new(format!("\u{2192} {} {now}", s.ri_now))
                                .color(differs)
                                .strong(),
                        );
                    }
                    None => {
                        ui.label(was);
                    }
                }
            });
        }
    }

    /// Every rung of the cascade the last steps went through, and what decided each.
    ///
    /// Architecturally this was already here: the resolver tries the ways in order
    /// and keeps the winner. All that was missing was not throwing the other ones
    /// away - and the other ones are the answer to "why did it click there", "why
    /// did that take four seconds" and "why does it work on my machine".
    fn why_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let list = traces();
        if list.is_empty() {
            ui.label(egui::RichText::new(s.why_none).weak());
            return;
        }
        if ui.button(s.why_clear).clicked() {
            clear_traces();
            self.why_at = 0;
            return;
        }
        self.why_at = self.why_at.min(list.len() - 1);

        // Newest first, and named by step rather than by number: somebody looking for
        // the step that misbehaved is looking for what it says, not for where it sits.
        egui::ComboBox::from_id_salt("why_pick")
            .selected_text(clip(&list[self.why_at].step, 46))
            .width(360.0)
            .show_ui(ui, |ui| {
                for (i, t) in list.iter().enumerate() {
                    let mark = if t.ok { '\u{2714}' } else { '\u{2716}' };
                    let label = format!("{mark} #{}  {}", t.pc, clip(&t.step, 40));
                    if ui.selectable_label(self.why_at == i, label).clicked() {
                        self.why_at = i;
                    }
                }
            });

        let t = &list[self.why_at];
        ui.separator();
        ui.horizontal_wrapped(|ui| {
            ui.label(egui::RichText::new(s.why_action).weak());
            ui.label(egui::RichText::new(&t.step).strong());
        });

        if !t.attempts.is_empty() {
            ui.add_space(4.0);
            ui.label(egui::RichText::new(s.why_how).weak());
            for a in &t.attempts {
                let (mark, colour) = if a.ok {
                    ("\u{2714}", egui::Color32::from_rgb(120, 210, 120))
                } else {
                    ("\u{2716}", egui::Color32::from_rgb(255, 130, 110))
                };
                let name = Method::from_index(a.method).name(s);
                let detail = if a.detail.is_empty() {
                    if a.ok { s.why_found.to_string() } else { s.why_nothing.to_string() }
                } else {
                    a.detail.clone()
                };
                ui.label(
                    egui::RichText::new(format!(
                        "{mark} {name}  \u{2014}  {detail}  ({})",
                        format_ms(a.took_us)
                    ))
                    .color(colour),
                );
            }
        }

        // The pair that answers the twenty-pixels question, and only when there is
        // a pair: a target found by element has no recorded coordinate to differ
        // from, and inventing one would be inventing a discrepancy.
        if let (Some((rx, ry)), Some((ax, ay))) = (t.recorded, t.actual) {
            ui.add_space(4.0);
            ui.horizontal_wrapped(|ui| {
                ui.label(egui::RichText::new(s.why_coords).weak());
                let moved = (rx, ry) != (ax, ay);
                let colour = if moved {
                    egui::Color32::from_rgb(255, 200, 90)
                } else {
                    ui.visuals().text_color()
                };
                ui.label(
                    egui::RichText::new(format!("{} {rx}, {ry}", s.why_recorded)).weak(),
                );
                ui.label(
                    egui::RichText::new(format!("\u{2192} {} {ax}, {ay}", s.why_actual))
                        .color(colour),
                );
                if moved {
                    ui.label(
                        egui::RichText::new(format!("({:+}, {:+})", ax - rx, ay - ry))
                            .color(colour)
                            .strong(),
                    );
                }
            });
        }

        ui.add_space(4.0);
        ui.horizontal_wrapped(|ui| {
            ui.label(egui::RichText::new(s.why_took).weak());
            ui.label(format_ms(t.took_us));
            if t.tries > 0 {
                ui.label(egui::RichText::new(s.why_tries).weak());
                ui.label(t.tries.to_string());
            }
            if t.cycle > 1 {
                ui.label(egui::RichText::new(s.why_cycle).weak());
                ui.label(t.cycle.to_string());
            }
        });
    }

    /// The templates folder, set against what this macro asks of it.
    fn resources_ui(&mut self, ui: &mut egui::Ui, busy: bool) {
        let s = self.strs();
        ui.horizontal_wrapped(|ui| {
            if ui.add_enabled(!busy, egui::Button::new(s.res_scan)).clicked() {
                let data = self.state.macro_data.lock().clone();
                let path = self.state.current_path.lock().clone();
                let here = path.as_deref().and_then(|p| p.parent());
                self.resources = Some(audit_resources(&data, here));
            }
            if ui.button(s.res_open).clicked() {
                let dir = paths::templates_dir();
                std::fs::create_dir_all(&dir).ok();
                // Handed to whatever the user browses folders with, the same way the
                // run history hands over a screenshot.
                run_program(&dir.to_string_lossy(), "");
            }
        });
        let Some(r) = self.resources.as_ref() else { return };
        ui.separator();
        if r.nothing_to_say() {
            ui.label(egui::RichText::new(s.res_none).weak());
        }

        if !r.missing.is_empty() {
            ui.label(
                egui::RichText::new(s.res_missing)
                    .strong()
                    .color(egui::Color32::from_rgb(255, 130, 110)),
            );
            for n in &r.missing {
                ui.label(
                    egui::RichText::new(format!("\u{2716} {n}"))
                        .color(egui::Color32::from_rgb(255, 130, 110)),
                );
            }
        }

        if !r.unused.is_empty() {
            ui.add_space(4.0);
            ui.label(egui::RichText::new(s.res_unused).strong());
            for (n, size) in &r.unused {
                ui.label(egui::RichText::new(format!("\u{00b7} {n}   {}", bytes(*size))).weak());
            }
            ui.label(
                egui::RichText::new(
                    s.res_size
                        .replacen("{}", &r.unused.len().to_string(), 1)
                        .replacen("{}", &bytes(r.unused_bytes()), 1),
                )
                .weak(),
            );
            // The sentence this whole feature turns on. Without it the list reads as
            // permission, and somebody deletes a picture four other macros need.
            ui.label(
                egui::RichText::new(s.res_caveat)
                    .small()
                    .color(egui::Color32::from_rgb(255, 200, 90)),
            );
        }

        if !r.duplicates.is_empty() {
            ui.add_space(4.0);
            ui.label(egui::RichText::new(s.res_dupes).strong());
            for group in &r.duplicates {
                ui.label(egui::RichText::new(format!("\u{00b7} {}", group.join("  =  "))).weak());
            }
        }

        if !r.used.is_empty() {
            ui.add_space(4.0);
            ui.label(egui::RichText::new(s.res_used).strong());
            ui.label(egui::RichText::new(r.used.join(", ")).weak());
        }
    }

    /// Puts a restored window size right when it comes back unusable.
    ///
    /// eframe remembers the window geometry between runs, and what it remembers is
    /// whatever winit reported at the moment the program closed. Close it while it is
    /// minimising, or while the display is changing scale, and the number saved is
    /// nonsense: this machine had `inner_size_points: Some((x: 64.0, ...))` written
    /// into `app.ron`, and every launch after that came up as a 64-pixel square in
    /// the corner with no way to tell what it was.
    ///
    /// `with_min_inner_size` does not help, because the restored size is applied
    /// after the builder. So the first frame looks at what actually arrived and, if
    /// it is smaller than the window can usefully be, asks for the default back.
    fn fix_window_geometry(&mut self, ctx: &egui::Context) {
        if self.geometry_checked {
            return;
        }
        self.geometry_checked = true;
        let Some(size) = ctx.input(|i| i.viewport().inner_rect.map(|r| r.size())) else {
            return;
        };
        if let Some((w, h)) = usable_window((size.x, size.y)) {
            warn!(
                "restored window was {}x{}, which is unusable - going back to the default",
                size.x as i32, size.y as i32
            );
            ctx.send_viewport_cmd(egui::ViewportCommand::InnerSize(egui::vec2(w, h)));
        }
    }

    /// Declares one of the extra windows.
    ///
    /// **Deferred**, not immediate, and that is the whole point of the shape here. An
    /// immediate viewport is drawn from inside the parent's frame, and on Windows a
    /// minimised window is never given a frame — so every one of these froze the
    /// moment the main window went to the taskbar.
    ///
    /// A deferred callback has to be `Send + Sync + 'static`, so it reaches the
    /// application through a weak handle and a plain function pointer rather than by
    /// borrowing it. `try_lock` rather than `lock`: the main window holds the state
    /// while it draws, and a dropped frame is a great deal better than a deadlock.
    fn extra_window(&self, ctx: &egui::Context, w: ExtraWindow) {
        let me = self.me.clone();
        let ExtraWindow { id, title, size, min, draw, closed } = w;
        ctx.show_viewport_deferred(
            egui::ViewportId::from_hash_of(id),
            egui::ViewportBuilder::default()
                .with_title(title)
                .with_inner_size(size)
                .with_min_inner_size(min),
            move |ui, _class| {
                let Some(inner) = me.upgrade() else { return };
                let Some(mut app) = inner.try_lock() else { return };
                draw(&mut app, ui);
                if ui.input(|i| i.viewport().close_requested()) {
                    closed(&mut app);
                }
            },
        );
    }

    /// The handbook window.
    ///
    /// A **deferred** viewport: its callback owns nothing of the application and
    /// reads a small shared state instead. That is what lets it keep working while
    /// the main window is minimised — an immediate viewport is drawn from inside the
    /// parent's `update`, and on Windows a minimised window receives no redraw at
    /// all, so every child it owned froze the moment it went to the taskbar.
    fn handbook_viewport(&mut self, ctx: &egui::Context) {
        {
            let mut hb = handbook_state().lock();
            hb.lang = lang_of(self.config.default_lang, self.system_lang);
            // Only push a topic the *window* has not already moved past. Pushing
            // unconditionally meant every article the reader opened was reverted by
            // the next frame of the main window, which is a window that fights back.
            if self.help_topic != self.pushed_topic {
                self.pushed_topic = self.help_topic;
                hb.topic = self.help_topic;
                hb.jump = hb.jump.wrapping_add(1);
            }
            if self.help_open {
                hb.open = true;
            } else {
                self.help_open = hb.open;
            }
        }
        if !self.help_open {
            return;
        }
        let s = self.strs();
        ctx.show_viewport_deferred(
            egui::ViewportId::from_hash_of("macro_handbook"),
            egui::ViewportBuilder::default()
                .with_title(s.hb_title)
                .with_inner_size([1000.0, 700.0])
                .with_min_inner_size([560.0, 380.0]),
            move |ui, _class| handbook_window(ui),
        );
    }

    /// The way in: a small mark in the bottom-right corner that stays out of the way.
    ///
    /// An `Area` rather than a widget in the panel, so it does not move when the
    /// panel scrolls and does not push anything about. Drawn weak, and left to
    /// egui's own hover highlight to come forward when the pointer is on it - which
    /// is the whole of what "unobtrusive until wanted" needs to be.
    fn help_button(&mut self, ctx: &egui::Context) {
        let s = self.strs();
        // F1 anywhere, and Escape to leave. Consumed rather than observed, so a text
        // field underneath does not also receive it.
        if ctx.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::F1)) {
            self.help_open = !self.help_open;
        }
        egui::Area::new(egui::Id::new("handbook_button"))
            .anchor(egui::Align2::RIGHT_BOTTOM, [-18.0, -18.0])
            .order(egui::Order::Foreground)
            .show(ctx, |ui| {
                let weak = ui.visuals().weak_text_color();
                let r = ui.add(
                    egui::Button::new(egui::RichText::new("?").size(17.0).color(weak))
                        .min_size(egui::vec2(30.0, 30.0)),
                );
                if r.clicked() {
                    self.help_open = true;
                }
                if r.hovered() {
                    r.on_hover_text(s.hb_open);
                }
            });
    }

    /// What the pre-flight found, when it stood between somebody and the Run button.
    ///
    /// A dialog rather than a line in the status bar, because it is a decision: the
    /// program has just declined to do the thing that was asked for, and the person
    /// who asked is entitled to overrule it. What it must not do is decide quietly
    /// in either direction - start a macro that cannot work, or refuse and say so
    /// somewhere nobody is looking.
    fn preflight_ui(&mut self, ctx: &egui::Context) {
        let Some(rep) = self.state.blocked_by.lock().clone() else { return };
        let s = self.strs();
        let (mut run, mut cancel) = (false, false);
        egui::Window::new(s.pf_title)
            .collapsible(false)
            .resizable(false)
            .anchor(egui::Align2::CENTER_CENTER, [0.0, 0.0])
            .show(ctx, |ui| {
                ui.set_max_width(470.0);
                ui.label(s.pf_body.replace("{}", &rep.errors().to_string()));
                ui.add_space(6.0);
                for f in
                    rep.findings.iter().filter(|f| f.rule.severity() == health::Severity::Error)
                {
                    let where_ = f.step.map(|i| format!("#{i} ")).unwrap_or_default();
                    let detail = if f.detail.is_empty() {
                        String::new()
                    } else {
                        format!(": {}", f.detail)
                    };
                    ui.label(
                        egui::RichText::new(format!(
                            "\u{2716} {where_}{}{detail}",
                            f.rule.text(s)
                        ))
                        .color(egui::Color32::from_rgb(255, 130, 110)),
                    );
                }
                ui.add_space(8.0);
                ui.horizontal_wrapped(|ui| {
                    cancel = ui.button(s.pf_cancel).clicked();
                    run = ui.button(s.pf_run_anyway).clicked();
                });
            });
        if cancel {
            self.status_msg = s.pf_blocked.replace("{}", &rep.errors().to_string());
            *self.state.blocked_by.lock() = None;
        } else if run {
            *self.state.blocked_by.lock() = None;
            // One shot, spent by the attempt below. Anything longer-lived would turn
            // the check back into the button it used to be.
            self.state.preflight_ok.store(true, Ordering::Relaxed);
            start_playback(&self.state);
        }
    }

    /// The one thing that had never been guarded: writing over a file from a later
    /// version of this program.
    ///
    /// Serde drops fields it does not recognise without a word, so such a file loads
    /// looking complete. Saving it writes back the half that survived - and the
    /// person doing it believes they are saving their work.
    fn save_guard_ui(&mut self, ctx: &egui::Context) {
        let Some(path) = self.pending_save.clone() else { return };
        let s = self.strs();
        let said = self.state.macro_data.lock().from_future;
        let (mut save, mut cancel) = (false, false);
        egui::Window::new(s.save_newer)
            .collapsible(false)
            .resizable(false)
            .anchor(egui::Align2::CENTER_CENTER, [0.0, 0.0])
            .show(ctx, |ui| {
                ui.set_max_width(470.0);
                ui.label(egui::RichText::new(file_label(&path)).strong());
                ui.add_space(4.0);
                ui.label(
                    s.save_newer_body
                        .replacen("{}", &said.to_string(), 1)
                        .replacen("{}", &format_version().to_string(), 1),
                );
                ui.add_space(8.0);
                ui.horizontal_wrapped(|ui| {
                    // Its own string, not the Run gate's: this dialog is about
                    // saving, and "Don't run it" on it read as a different
                    // question entirely. Found by driving matrix row T-36.
                    cancel = ui.button(s.save_newer_cancel).clicked();
                    save = ui.button(s.save_newer_anyway).clicked();
                });
            });
        if cancel {
            self.pending_save = None;
        } else if save {
            self.pending_save = None;
            self.write_macro(path);
        }
    }

    fn set_template(&mut self, w: u32, h: u32, rgba: Vec<u8>, name: String) {
        self.template = Some(Arc::new(vision::Template { w, h, rgba, name }));
        *LAST_HIT.lock() = None;
    }

    /// Reads the panel's rectangle with the panel's profile.
    ///
    /// One place, because the panel reads from two: the button, and the moment the
    /// second corner is picked. They must agree about which profile was used or the
    /// number shown next to the text is a lie.
    fn read_ocr_panel(&mut self, s: &Strings) {
        let (x, y, w, h) = self.ocr_rect;
        match ocr::read_region_as(x, y, w, h, self.ocr_prep, &self.ocr_expect) {
            Ok(r) => {
                let text = r.text();
                self.ocr_fit = Some((r.quality, r.prep));
                self.ocr_text =
                    if text.is_empty() { s.ocr_empty.to_string() } else { text };
            }
            Err(e) => {
                self.ocr_fit = None;
                self.ocr_text = format!("{} — {e}", s.ocr_off);
            }
        }
    }

    fn load_template_png(&mut self, path: &Path) {
        let s = self.strs();
        match image::open(path) {
            Ok(img) => {
                let rgba = img.to_rgba8();
                let (w, h) = (rgba.width(), rgba.height());
                self.set_template(w, h, rgba.into_raw(), file_label(path));
                self.status_msg = s.loaded.replace("{}", &file_label(path));
            }
            Err(e) => self.status_msg = s.load_err.replace("{}", &e.to_string()),
        }
    }

    fn search_region(&self) -> Option<(i32, i32, i32, i32)> {
        if self.config.img_region_enabled {
            Some((
                self.config.img_rx,
                self.config.img_ry,
                self.config.img_rw,
                self.config.img_rh,
            ))
        } else {
            None
        }
    }

    fn default_save_path(&self) -> PathBuf {
        self.state.current_path.lock().clone().unwrap_or_else(|| {
            if self.config.compress_on_save {
                paths::data_dir().join("macro.mrz")
            } else {
                paths::default_macro_path()
            }
        })
    }
}

fn file_label(path: &Path) -> String {
    path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
}

fn setup_fonts(ctx: &egui::Context) {
    ctx.set_fonts(font_definitions());
}

/// Exactly the fonts the program draws with.
///
/// Split out of `setup_fonts` so a test can ask them what they can draw. Until 1.9.1
/// the answer to "will this symbol render?" was a hand-curated list somebody had once
/// looked at, which is how two tick marks and a drop-down arrow shipped as empty
/// boxes: a list can only record what was checked, and nobody had checked them.
fn font_definitions() -> egui::FontDefinitions {
    let mut fonts = egui::FontDefinitions::default();
    let candidates = [
        "C:\\Windows\\Fonts\\msyh.ttc",
        "C:\\Windows\\Fonts\\simhei.ttf",
        "C:\\Windows\\Fonts\\meiryo.ttc",
    ];
    for path in candidates {
        if let Ok(data) = std::fs::read(path) {
            fonts.font_data.insert("cjk".into(), egui::FontData::from_owned(data).into());
            if let Some(f) = fonts.families.get_mut(&egui::FontFamily::Proportional) {
                f.push("cjk".into());
            }
            if let Some(f) = fonts.families.get_mut(&egui::FontFamily::Monospace) {
                f.push("cjk".into());
            }
            break;
        }
    }
    fonts
}

/// Mouse button picker shared by the script steps.
fn button_picker(ui: &mut egui::Ui, s: &Strings, salt: &str, button: &mut MouseButton) -> bool {
    let names = [s.btn_l, s.btn_r, s.btn_m, "X1", "X2"];
    let all = [
        MouseButton::Left,
        MouseButton::Right,
        MouseButton::Middle,
        MouseButton::X1,
        MouseButton::X2,
    ];
    let mut changed = false;
    egui::ComboBox::from_id_salt(salt)
        .selected_text(names[all.iter().position(|b| b == button).unwrap_or(0)])
        .width(100.0)
        .show_ui(ui, |ui| {
            for (b, n) in all.iter().zip(names) {
                if ui.selectable_label(button == b, n).clicked() && button != b {
                    *button = *b;
                    changed = true;
                }
            }
        });
    changed
}

/// Editor for one condition, used by If, While and Wait for.
fn condition_ui(
    ui: &mut egui::Ui,
    s: &Strings,
    salt: &str,
    cond: &mut Condition,
    from_panel: Option<(i32, i32, i32, i32)>,
) -> bool {
    let names = [
        s.c_always,
        s.c_var,
        s.c_image,
        s.c_pixel,
        s.c_window,
        s.c_text,
        s.c_process,
        s.c_element,
    ];
    let mut changed = false;

    ui.horizontal_wrapped(|ui| {
        egui::ComboBox::from_id_salt(format!("{salt}_kind"))
            .selected_text(names[cond.kind_index()])
            .width(120.0)
            .show_ui(ui, |ui| {
                for (i, n) in names.iter().enumerate() {
                    if ui.selectable_label(cond.kind_index() == i, *n).clicked()
                        && cond.kind_index() != i
                    {
                        *cond = Condition::from_index(i);
                        changed = true;
                    }
                }
            });
    });

    match cond {
        Condition::Always => {}
        Condition::Var { name, cmp, value } => {
            ui.horizontal_wrapped(|ui| {
                changed |=
                    ui.add(egui::TextEdit::singleline(name).desired_width(90.0)).changed();
                egui::ComboBox::from_id_salt(format!("{salt}_cmp"))
                    .selected_text(cmp.symbol())
                    .width(60.0)
                    .show_ui(ui, |ui| {
                        for c in Cmp::ALL {
                            if ui.selectable_label(*cmp == c, c.symbol()).clicked() {
                                *cmp = c;
                                changed = true;
                            }
                        }
                    });
                changed |= value_ui(ui, s, &format!("{salt}_cv"), value);
            });
        }
        Condition::Image {
            template,
            threshold,
            area,
            lose_at,
            stable_of,
            stable_in,
            edge,
        } => {
            ui.horizontal_wrapped(|ui| {
                ui.label(s.f_template);
                changed |= ui
                    .add(egui::TextEdit::singleline(template).desired_width(150.0))
                    .changed();
                changed |= template_picker(ui, &format!("{salt}_tpl"), template);
                changed |= ui
                    .add(egui::DragValue::new(threshold).range(0.3..=1.0).speed(0.01))
                    .changed();
            });
            changed |= area_ui(ui, s, salt, area);
            ui.horizontal_wrapped(|ui| {
                ui.label(s.f_lose_at);
                changed |= ui
                    .add(egui::DragValue::new(lose_at).range(0.0..=1.0).speed(0.01))
                    .changed();
                ui.label(s.f_stable);
                changed |= ui
                    .add(egui::DragValue::new(stable_of).range(0..=32))
                    .changed();
                ui.label("/");
                changed |= ui
                    .add(egui::DragValue::new(stable_in).range(0..=32))
                    .changed();
                changed |= ui.checkbox(edge, s.f_edge).changed();
            });
        }
        Condition::Pixel { x, y, r, g, b, tol } => {
            ui.horizontal_wrapped(|ui| {
                ui.label("X");
                changed |= ui.add(egui::DragValue::new(x).range(-32000..=32000)).changed();
                ui.label("Y");
                changed |= ui.add(egui::DragValue::new(y).range(-32000..=32000)).changed();
                let mut col = [*r, *g, *b];
                if ui.color_edit_button_srgb(&mut col).changed() {
                    *r = col[0];
                    *g = col[1];
                    *b = col[2];
                    changed = true;
                }
                ui.label(s.pixel_tol);
                changed |= ui.add(egui::DragValue::new(tol).range(0..=255)).changed();
            });
        }
        Condition::Window { title } => {
            ui.horizontal_wrapped(|ui| {
                changed |= ui
                    .add(egui::TextEdit::singleline(title).desired_width(200.0))
                    .changed();
            });
        }
        Condition::Element { query } => {
            changed |= query_ui(ui, s, salt, query);
        }
        Condition::Process { name } => {
            ui.horizontal_wrapped(|ui| {
                changed |= ui
                    .add(egui::TextEdit::singleline(name).desired_width(200.0))
                    .changed();
            });
        }
        Condition::Text { x, y, w, h, needle, prep } => {
            ui.horizontal_wrapped(|ui| {
                ui.label(s.f_needle);
                changed |= ui
                    .add(egui::TextEdit::singleline(needle).desired_width(180.0))
                    .changed();
                changed |= prep_picker(ui, s, &format!("{salt}_ctxt"), prep);
            });
            changed |= region_ui(ui, s, x, y, w, h, from_panel);
        }
    }
    changed
}

/// X / Y / W / H row shared by every step that works on a screen rectangle.
fn region_ui(
    ui: &mut egui::Ui,
    s: &Strings,
    x: &mut i32,
    y: &mut i32,
    w: &mut i32,
    h: &mut i32,
    // The rectangle last picked in the "Text on screen" panel, if any.
    from_panel: Option<(i32, i32, i32, i32)>,
) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(s.f_region);
        ui.label("X");
        changed |= ui.add(egui::DragValue::new(x).range(-32000..=32000)).changed();
        ui.label("Y");
        changed |= ui.add(egui::DragValue::new(y).range(-32000..=32000)).changed();
        ui.label("W");
        changed |= ui.add(egui::DragValue::new(w).range(8..=32000)).changed();
        ui.label("H");
        changed |= ui.add(egui::DragValue::new(h).range(8..=32000)).changed();
        // Retyping four numbers from the test panel is exactly the kind of chore
        // that produces off-by-a-hundred bugs.
        if let Some(r) = from_panel
            && ui.small_button(s.f_from_panel).clicked() {
                *x = r.0;
                *y = r.1;
                *w = r.2;
                *h = r.3;
                changed = true;
            }
    });
    changed
}

/// One row of the hotkey editor. Returns true when the binding changed.
///
/// Two ways to set a key, because one of them always works: click the button and
/// press anything, or pick from the list (which also covers keys the window never
/// receives, such as Pause and the NumPad).
fn hotkey_row(
    ui: &mut egui::Ui,
    s: &Strings,
    label: &str,
    salt: &str,
    slot: u32,
    hk: &mut Hotkey,
) -> bool {
    let mut changed = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(label);

        // Left cell is the action, right cell is the current value: neither can end
        // up blank, and the two no longer say the same thing twice.
        let capturing = CAPTURE_SLOT.load(Ordering::Relaxed) == slot;
        let text = if capturing { s.hk_press } else { s.hk_bind };
        let button = egui::Button::new(text).min_size(egui::vec2(110.0, 0.0));
        if ui.add(button).clicked() {
            if capturing {
                end_capture();
            } else {
                begin_capture(slot);
            }
        }

        egui::ComboBox::from_id_salt(salt)
            .selected_text(vk_name(hk.vk))
            .width(112.0)
            .show_ui(ui, |ui| {
                for (name, vk) in HOTKEY_CHOICES {
                    if ui.selectable_label(hk.vk == vk, name).clicked() && hk.vk != vk {
                        hk.vk = vk;
                        changed = true;
                    }
                }
            });

        changed |= ui.checkbox(&mut hk.ctrl, "Ctrl").changed();
        changed |= ui.checkbox(&mut hk.alt, "Alt").changed();
        changed |= ui.checkbox(&mut hk.shift, "Shift").changed();
        if ui.small_button(s.hk_clear).clicked() && hk.vk != 0 {
            *hk = Hotkey::plain(0);
            changed = true;
        }
    });
    changed
}

impl AppInner {
    /// Script view: the program list plus an inspector for the selected step.
    fn script_ui(&mut self, ui: &mut egui::Ui, list_h: f32) {
        let s = self.strs();
        let busy = self.busy();
        let (steps, total_events) = {
            let d = self.state.macro_data.lock();
            (d.script.clone(), d.events.len())
        };

        if let Err(e) = resolve_blocks(&steps) {
            ui.colored_label(
                egui::Color32::from_rgb(255, 170, 60),
                s.scr_invalid.replace("{}", &e),
            );
        }

        let dead_from = first_unreachable(&steps);
        if dead_from.is_some() {
            ui.colored_label(egui::Color32::from_rgb(255, 170, 60), s.scr_unreachable);
        }

        if steps.is_empty() {
            ui.label(s.scr_none);
        } else {
            let depths = script_depths(&steps);
            let mut pick = None;
            egui::ScrollArea::vertical()
                .id_salt("script")
                .max_height(list_h)
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    for (i, st) in steps.iter().enumerate() {
                        let pad = "    ".repeat(depths[i]);
                        // Marked in the list rather than only in the inspector: the
                        // question "does this macro do anything I cannot take back"
                        // is asked while looking at the whole list, not one step.
                        let mark = if st.kind.dangerous() { " ⚠" } else { "" };
                        let line = format!(
                            "{i:>3} {pad}{}{mark}",
                            describe_step(st, s, total_events)
                        );
                        let mut rt = egui::RichText::new(line).monospace();
                        if !st.enabled {
                            rt = rt.weak().strikethrough();
                        } else if dead_from.map(|d| i >= d).unwrap_or(false) {
                            rt = rt.color(egui::Color32::from_rgb(255, 170, 60));
                        }
                        let picked = i == self.scr_sel || self.scr_marked.contains(&i);
                        // The warning survives as the visible mark in the line
                        // above; it used to be repeated as hover text, which said
                        // the same thing to nobody who had not already seen it.
                        let row = ui.selectable_label(picked, rt);
                        if row.clicked() {
                            pick = Some((i, ui.input(|inp| inp.modifiers)));
                        }
                    }
                });
            if let Some((i, mods)) = pick {
                if mods.shift {
                    // Everything between what was selected and what was clicked.
                    let (a, b) =
                        (self.scr_sel.min(i), self.scr_sel.max(i));
                    self.scr_marked = (a..=b).collect();
                } else if mods.command {
                    // Ctrl adds and removes one at a time. The anchor moves with it
                    // so a following Shift+click reads from where the hand is.
                    if !self.scr_marked.remove(&i) {
                        self.scr_marked.insert(i);
                    }
                    self.scr_marked.insert(self.scr_sel);
                } else {
                    self.scr_marked.clear();
                }
                self.scr_sel = i;
            }
        }

        // ---- what is picked out, and what can be done to it ------------------
        //
        // Only drawn when more than one step is involved. A bar of bulk operations
        // above a single selected step would be six buttons that all mean the same
        // as the four already below it.
        let marked = self.scr_marked.clone();
        if marked.len() > 1 {
            let (from, to) = selection_span(&marked, self.scr_sel);
            ui.horizontal_wrapped(|ui| {
                ui.label(
                    egui::RichText::new(
                        s.sel_count.replace("{}", &marked.len().to_string()),
                    )
                    .strong(),
                );
                if ui.button(s.sel_none).clicked() {
                    self.scr_marked.clear();
                }
                if ui.add_enabled(!busy, egui::Button::new(s.sel_dup)).clicked() {
                    self.edit(|d| duplicate_steps(&mut d.script, from, to));
                    self.scr_marked.clear();
                }
                if ui.add_enabled(!busy, egui::Button::new(s.sel_del)).clicked() {
                    // Backwards, so each removal cannot move the next index.
                    self.edit(|d| {
                        for i in marked.iter().rev() {
                            if *i < d.script.len() {
                                d.script.remove(*i);
                            }
                        }
                    });
                    self.scr_sel = from.saturating_sub(1);
                    self.scr_marked.clear();
                }
                for (label, on) in [(s.sel_enable, true), (s.sel_disable, false)] {
                    if ui.add_enabled(!busy, egui::Button::new(label)).clicked() {
                        self.edit(|d| {
                            for i in marked.iter() {
                                if let Some(st) = d.script.get_mut(*i) {
                                    st.enabled = on;
                                }
                            }
                        });
                    }
                }
            });
            ui.horizontal_wrapped(|ui| {
                let wraps: [(&str, StepKind, StepKind); 3] = [
                    (
                        s.sel_wrap_if,
                        StepKind::If { cond: Condition::Always },
                        StepKind::EndIf,
                    ),
                    (
                        s.sel_wrap_while,
                        StepKind::While { cond: Condition::Always },
                        StepKind::EndWhile,
                    ),
                    (
                        s.sel_wrap_group,
                        StepKind::Group { name: "Group".into() },
                        StepKind::EndGroup,
                    ),
                ];
                for (label, open, close) in wraps {
                    if ui.add_enabled(!busy, egui::Button::new(label)).clicked() {
                        self.edit(|d| wrap_steps(&mut d.script, from, to, open, close));
                        self.scr_marked.clear();
                        self.scr_sel = from;
                        break;
                    }
                }
            });
        }

        // ---- add / move / delete -------------------------------------------
        ui.separator();
        ui.horizontal_wrapped(|ui| {
            let names: Vec<&str> = (0..StepKind::COUNT)
                .map(|i| StepKind::from_index(i).name(s))
                .collect();
            egui::ComboBox::from_id_salt("scr_kind")
                .selected_text(names[self.scr_add_kind.min(StepKind::COUNT - 1)])
                .width(170.0)
                .show_ui(ui, |ui| {
                    for (i, n) in names.iter().enumerate() {
                        ui.selectable_value(&mut self.scr_add_kind, i, *n);
                    }
                });
            if ui.add_enabled(!busy, egui::Button::new(s.scr_add)).clicked() {
                let mut kind = StepKind::from_index(self.scr_add_kind);
                // A fresh "play events" step covers the whole recording: 0…0 would
                // be a single event, which is never what anyone means.
                if let StepKind::PlayEvents { from, to, .. } = &mut kind
                    && *from == 0 && *to == 0 {
                        *to = self.state.macro_data.lock().events.len().saturating_sub(1);
                    }
                let at = self.scr_sel;
                self.edit(|d| {
                    let pos = (at + 1).min(d.script.len());
                    d.script.insert(pos, ScriptStep::new(kind));
                });
                self.scr_sel = (self.scr_sel + 1).min(steps.len());
            }
            // Turning a recorded range into a step is how most scripts start.
            if ui.add_enabled(!busy, egui::Button::new(s.scr_from_sel)).clicked() {
                let (from, to) = (self.ed_from, self.ed_to);
                let at = self.scr_sel;
                self.edit(|d| {
                    let pos = (at + 1).min(d.script.len());
                    d.script.insert(pos, ScriptStep::new(StepKind::PlayEvents { from, to, between: None }));
                });
            }
        });

        if steps.is_empty() {
            return;
        }
        let sel = self.scr_sel.min(steps.len() - 1);
        self.scr_sel = sel;

        ui.horizontal_wrapped(|ui| {
            // Moves the whole picked-out run when there is one, so a group of steps
            // travels together rather than being shuffled through one another.
            let (mfrom, mto) = if marked.len() > 1 {
                selection_span(&marked, sel)
            } else {
                (sel, sel)
            };
            if ui.add_enabled(!busy, egui::Button::new("\u{25b2}")).clicked() && mfrom > 0 {
                self.edit(|d| {
                    move_steps(&mut d.script, mfrom, mto, false);
                });
                self.scr_sel = sel.saturating_sub(1);
                self.scr_marked = marked.iter().map(|i| i.saturating_sub(1)).collect();
            }
            if ui.add_enabled(!busy, egui::Button::new("\u{25bc}")).clicked()
                && mto + 1 < steps.len()
            {
                self.edit(|d| {
                    move_steps(&mut d.script, mfrom, mto, true);
                });
                self.scr_sel = (sel + 1).min(steps.len() - 1);
                self.scr_marked = marked.iter().map(|i| i + 1).collect();
            }
            if ui.add_enabled(!busy, egui::Button::new(s.insp_del_one)).clicked() {
                self.edit(|d| {
                    if sel < d.script.len() {
                        d.script.remove(sel);
                    }
                });
                self.scr_sel = sel.saturating_sub(1);
            }
            let mut on = steps[sel].enabled;
            if ui.checkbox(&mut on, s.scr_enabled).changed() {
                self.edit(|d| {
                    if let Some(st) = d.script.get_mut(sel) {
                        st.enabled = on;
                    }
                });
            }
        });

        // ---- inspector for the selected step --------------------------------
        ui.separator();
        let mut kind = steps[sel].kind.clone();
        let sel_id = steps[sel].id;
        let mut changed = false;

        // What this step has actually done, across every run in the history. Shown
        // above the fields rather than below: "this fails one time in five" changes
        // how the fields underneath should be read.
        if let Some(st) = self.stats_for(sel_id) {
            let colour = if st.success() >= 99.0 {
                egui::Color32::from_rgb(120, 210, 120)
            } else if st.success() >= 90.0 {
                egui::Color32::from_rgb(255, 200, 90)
            } else {
                egui::Color32::from_rgb(255, 130, 110)
            };
            ui.horizontal_wrapped(|ui| {
                ui.label(
                    egui::RichText::new(format!("{} {}", st.runs, s.stats_runs)).weak(),
                );
                ui.label(
                    egui::RichText::new(format!("{:.1}% {}", st.success(), s.stats_success))
                        .color(colour),
                );
                ui.label(
                    egui::RichText::new(format!(
                        "{} {}",
                        s.stats_avg,
                        format_dur(st.average_us())
                    ))
                    .weak(),
                );
                ui.label(
                    egui::RichText::new(format!(
                        "{} {}",
                        s.stats_worst,
                        format_dur(st.worst_us)
                    ))
                    .weak(),
                );
            });
        }

        // Changing the kind starts from that kind's defaults.
        ui.horizontal_wrapped(|ui| {
            let names: Vec<&str> = (0..StepKind::COUNT)
                .map(|i| StepKind::from_index(i).name(s))
                .collect();
            egui::ComboBox::from_id_salt("scr_selkind")
                .selected_text(names[kind.index()])
                .width(170.0)
                .show_ui(ui, |ui| {
                    for (i, n) in names.iter().enumerate() {
                        if ui.selectable_label(kind.index() == i, *n).clicked()
                            && kind.index() != i
                        {
                            kind = StepKind::from_index(i);
                            changed = true;
                        }
                    }
                });
        });

        match &mut kind {
            StepKind::PlayEvents { from, to, between } => {
                let (last, markers) = {
                    let d = self.state.macro_data.lock();
                    (d.events.len().saturating_sub(1), d.markers.clone())
                };
                // Named or numbered, and the numbers stay visible either way: they
                // are what an older build plays and what a lost marker falls back to.
                let mut named = between.is_some();
                if ui
                    .checkbox(&mut named, s.f_by_marker)
                    .changed()
                {
                    *between = if named {
                        let first = markers.first().map(|m| m.name.clone()).unwrap_or_default();
                        let secnd = markers.get(1).map(|m| m.name.clone()).unwrap_or_default();
                        Some((first, secnd))
                    } else {
                        None
                    };
                    changed = true;
                }
                if let Some((a, b)) = between.as_mut() {
                    if markers.len() < 2 {
                        ui.label(egui::RichText::new(s.mk_none).weak());
                    }
                    for (label, slot) in [(s.f_marker_from, a), (s.f_marker_to, b)] {
                        ui.horizontal_wrapped(|ui| {
                            ui.label(label);
                            egui::ComboBox::from_id_salt(format!("mk{label}"))
                                .selected_text(slot.clone())
                                .width(170.0)
                                .show_ui(ui, |ui| {
                                    for m in &markers {
                                        if ui
                                            .selectable_label(*slot == m.name, &m.name)
                                            .clicked()
                                        {
                                            *slot = m.name.clone();
                                            changed = true;
                                        }
                                    }
                                });
                        });
                    }
                }
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.ed_from);
                    changed |= ui
                        .add_enabled(
                            between.is_none(),
                            egui::DragValue::new(from).range(0..=last),
                        )
                        .changed();
                    ui.label(s.ed_to);
                    changed |= ui
                        .add_enabled(
                            between.is_none(),
                            egui::DragValue::new(to).range(0..=last),
                        )
                        .changed();
                });
            }
            StepKind::Wait { ms } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.ed_insert);
                    changed |=
                        ui.add(egui::DragValue::new(ms).range(0..=3_600_000).speed(10.0)).changed();
                });
            }
            StepKind::WaitFor { cond, appear, timeout_ms, adaptive, miss } => {
                changed |= condition_ui(ui, s, "wf", cond, Some(self.ocr_rect));
                ui.horizontal_wrapped(|ui| {
                    changed |= ui.selectable_value(appear, true, s.f_appear).clicked();
                    changed |= ui.selectable_value(appear, false, s.f_gone).clicked();
                    ui.label(s.f_timeout);
                    changed |= ui
                        .add(egui::DragValue::new(timeout_ms).range(0..=3_600_000).speed(50.0))
                        .changed();
                    changed |= ui
                        .checkbox(adaptive, s.f_adaptive)
                        .changed();
                });
                // What the history actually knows about this step, shown beside the
                // box that decides whether to use it. An offer with no numbers behind
                // it is a guess with a checkbox.
                if let Some(st) = self.stats_for(sel_id) {
                    ui.label(
                        egui::RichText::new(
                            s.adaptive_learned
                                .replacen(
                                    "{}",
                                    &format_dur(st.suggested_timeout_ms() * 1000),
                                    1,
                                )
                                .replacen("{}", &st.runs.to_string(), 1),
                        )
                        .weak(),
                    );
                }
                changed |= miss_ui(ui, s, "wf", miss);
            }
            StepKind::ClickImage { template, threshold, button, area, edge, miss } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_template);
                    changed |= ui
                        .add(egui::TextEdit::singleline(template).desired_width(140.0))
                        .changed();
                    changed |= template_picker(ui, "ci_tpl", template);
                    changed |= ui
                        .add(egui::DragValue::new(threshold).range(0.3..=1.0).speed(0.01))
                        .changed();
                    changed |= button_picker(ui, s, "ci", button);
                    changed |= ui.checkbox(edge, s.f_edge).changed();
                });
                changed |= area_ui(ui, s, "ci", area);
                changed |= miss_ui(ui, s, "ci", miss);
            }
            StepKind::FindImage { template, threshold, area, var, edge, miss } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_template);
                    changed |= ui
                        .add(egui::TextEdit::singleline(template).desired_width(140.0))
                        .changed();
                    changed |= template_picker(ui, "fi_tpl", template);
                    changed |= ui
                        .add(egui::DragValue::new(threshold).range(0.3..=1.0).speed(0.01))
                        .changed();
                });
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_into);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(110.0))
                        .changed();
                    changed |= ui.checkbox(edge, s.f_edge).changed();
                });
                ui.horizontal_wrapped(|ui| {
                    ui.label(
                        egui::RichText::new(s.f_find_hint.replace("{}", var)).weak().small(),
                    );
                });
                changed |= area_ui(ui, s, "fi", area);
                changed |= miss_ui(ui, s, "fi", miss);
            }
            StepKind::Click { x, y, button } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label("X");
                    changed |=
                        ui.add(egui::DragValue::new(x).range(-32000..=32000)).changed();
                    ui.label("Y");
                    changed |=
                        ui.add(egui::DragValue::new(y).range(-32000..=32000)).changed();
                    changed |= button_picker(ui, s, "cl", button);
                });
            }
            StepKind::Key { vk, down } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.insp_key);
                    egui::ComboBox::from_id_salt("scr_key")
                        .selected_text(vk_name(*vk as u32))
                        .width(120.0)
                        .show_ui(ui, |ui| {
                            for (name, code) in EDIT_KEYS {
                                if ui.selectable_label(*vk == code, name).clicked()
                                    && *vk != code
                                {
                                    *vk = code;
                                    changed = true;
                                }
                            }
                        });
                    changed |= ui.selectable_value(down, true, s.st_down).clicked();
                    changed |= ui.selectable_value(down, false, s.st_up).clicked();
                });
            }
            StepKind::SetVar { name, op, value } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_var);
                    changed |=
                        ui.add(egui::TextEdit::singleline(name).desired_width(90.0)).changed();
                    egui::ComboBox::from_id_salt("scr_op")
                        .selected_text(op.symbol())
                        .width(60.0)
                        .show_ui(ui, |ui| {
                            for o in VarOp::ALL {
                                if ui.selectable_label(*op == o, o.symbol()).clicked() {
                                    *op = o;
                                    changed = true;
                                }
                            }
                        });
                    ui.label(s.f_value);
                    changed |= value_ui(ui, s, "scr_sv", value);
                });
            }
            StepKind::If { cond } | StepKind::While { cond } => {
                changed |= condition_ui(ui, s, "cnd", cond, Some(self.ocr_rect));
            }
            StepKind::Run { path, args } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_path);
                    changed |= ui
                        .add(egui::TextEdit::singleline(path).desired_width(220.0))
                        .changed();
                });
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_args);
                    changed |= ui
                        .add(egui::TextEdit::singleline(args).desired_width(220.0))
                        .changed();
                });
            }
            StepKind::FindElement { query, var, timeout_ms, miss } => {
                changed |= query_ui(ui, s, "fe", query);
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_into);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(110.0))
                        .changed();
                    ui.label(s.f_timeout);
                    changed |= ui
                        .add(egui::DragValue::new(timeout_ms).range(0..=600_000).speed(50))
                        .changed();
                });
                changed |= miss_ui(ui, s, "fe", miss);
            }
            StepKind::ClickElement { query, button, invoke, timeout_ms, miss } => {
                changed |= query_ui(ui, s, "ce", query);
                ui.horizontal_wrapped(|ui| {
                    changed |= button_picker(ui, s, "ce", button);
                    changed |=
                        ui.checkbox(invoke, s.f_invoke).changed();
                    ui.label(s.f_timeout);
                    changed |= ui
                        .add(egui::DragValue::new(timeout_ms).range(0..=600_000).speed(50))
                        .changed();
                });
                changed |= miss_ui(ui, s, "ce", miss);
            }
            StepKind::ClickTarget { target, button, invoke, reliability, timeout_ms, miss } => {
                changed |= target_ui(ui, s, "ct", target, reliability);
                ui.horizontal_wrapped(|ui| {
                    changed |= button_picker(ui, s, "ct", button);
                    changed |=
                        ui.checkbox(invoke, s.f_invoke).changed();
                    ui.label(s.f_timeout);
                    changed |= ui
                        .add(egui::DragValue::new(timeout_ms).range(0..=600_000).speed(50))
                        .changed();
                });
                changed |= miss_ui(ui, s, "ct", miss);
            }
            StepKind::WaitTarget { target, appear, reliability, timeout_ms, adaptive, miss } => {
                changed |= target_ui(ui, s, "wt", target, reliability);
                ui.horizontal_wrapped(|ui| {
                    changed |= ui
                        .selectable_label(*appear, s.f_appear)
                        .clicked()
                        .then(|| {
                            *appear = true;
                        })
                        .is_some();
                    changed |= ui
                        .selectable_label(!*appear, s.f_gone)
                        .clicked()
                        .then(|| {
                            *appear = false;
                        })
                        .is_some();
                    ui.label(s.f_timeout);
                    changed |= ui
                        .add(egui::DragValue::new(timeout_ms).range(0..=600_000).speed(50))
                        .changed();
                    changed |= ui
                        .checkbox(adaptive, s.f_adaptive)
                        .changed();
                });
                changed |= miss_ui(ui, s, "wt", miss);
            }
            StepKind::ReadTarget { target, var, reliability, prep, miss } => {
                changed |= target_ui(ui, s, "rt", target, reliability);
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_into);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(120.0))
                        .changed();
                });
                changed |= prep_picker(ui, s, "rt", prep);
                changed |= miss_ui(ui, s, "rt", miss);
            }
            StepKind::Window { window, action, x, y, timeout_ms, miss } => {
                changed |= window_ref_ui(ui, s, "wn", window);
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_window_action);
                    let mut ai = action.index();
                    egui::ComboBox::from_id_salt("wn_act")
                        .selected_text(action.name(s))
                        .width(190.0)
                        .show_ui(ui, |ui| {
                            for i in 0..WindowAction::COUNT {
                                let a = WindowAction::from_index(i);
                                let label = if a.dangerous() {
                                    format!("⚠ {}", a.name(s))
                                } else {
                                    a.name(s).to_string()
                                };
                                if ui.selectable_label(ai == i, label).clicked() {
                                    ai = i;
                                }
                            }
                        });
                    let want = WindowAction::from_index(ai);
                    if want != *action {
                        *action = want;
                        changed = true;
                    }
                    // Only the fields this action actually uses: a row of numbers
                    // beside "minimize" is a question nobody asked.
                    if action.uses_xy() {
                        for v in [x, y] {
                            changed |= ui
                                .add(egui::DragValue::new(v).range(-32_768..=32_767))
                                .changed();
                        }
                    }
                    if action.waits() {
                        ui.label(s.f_timeout);
                        changed |= ui
                            .add(
                                egui::DragValue::new(timeout_ms)
                                    .range(0..=600_000)
                                    .speed(50),
                            )
                            .changed();
                    }
                });
                changed |= miss_ui(ui, s, "wn", miss);
            }
            StepKind::Clipboard { action, text, var, timeout_ms, miss } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_clip_action);
                    let mut ai = action.index();
                    egui::ComboBox::from_id_salt("cb_act")
                        .selected_text(action.name(s))
                        .width(180.0)
                        .show_ui(ui, |ui| {
                            for i in 0..ClipAction::COUNT {
                                let a = ClipAction::from_index(i);
                                if ui.selectable_label(ai == i, a.name(s)).clicked() {
                                    ai = i;
                                }
                            }
                        });
                    let want = ClipAction::from_index(ai);
                    if want != *action {
                        *action = want;
                        changed = true;
                    }
                });
                // Only the field this action uses. A text box beside "clear it" is a
                // question nobody asked.
                if action.uses_text() {
                    changed |= ui
                        .add(
                            egui::TextEdit::multiline(text)
                                .desired_rows(2)
                                .desired_width(f32::INFINITY),
                        )
                        .changed();
                }
                if action.uses_var() {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.f_into);
                        changed |= ui
                            .add(egui::TextEdit::singleline(var).desired_width(120.0))
                            .changed();
                        if *action == ClipAction::WaitChange {
                            ui.label(s.f_timeout);
                            changed |= ui
                                .add(
                                    egui::DragValue::new(timeout_ms)
                                        .range(0..=600_000)
                                        .speed(50),
                                )
                                .changed();
                        }
                    });
                }
                changed |= miss_ui(ui, s, "cb", miss);
            }
            StepKind::Notify { title, body } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_title);
                    changed |= ui
                        .add(egui::TextEdit::singleline(title).desired_width(200.0))
                        .changed();
                });
                ui.label(s.f_body);
                changed |= ui
                    .add(
                        egui::TextEdit::multiline(body)
                            .desired_rows(2)
                            .desired_width(f32::INFINITY),
                    )
                    .changed();
            }
            StepKind::Screenshot { path, active_window } => {
                changed |= ui
                    .checkbox(active_window, s.f_shot_window)
                    .changed();
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_shot_path);
                    changed |= ui
                        .add(egui::TextEdit::singleline(path).desired_width(220.0))
                        .changed();
                });
            }
            StepKind::Group { name } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_group_name);
                    changed |= ui
                        .add(egui::TextEdit::singleline(name).desired_width(200.0))
                        .changed();
                });
            }
            StepKind::Recovery { name } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_recovery_name);
                    changed |= ui
                        .add(egui::TextEdit::singleline(name).desired_width(160.0))
                        .changed();
                });
            }
            StepKind::Call { path, miss } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_macro_file);
                    changed |= ui
                        .add(egui::TextEdit::singleline(path).desired_width(220.0))
                        .changed();
                    if ui.button("…").clicked()
                        && let Some(picked) = rfd::FileDialog::new()
                            .add_filter("Macro", &["json", "mrz", "gz"])
                            .set_directory(paths::data_dir())
                            .pick_file()
                        {
                            // Kept relative when it sits beside the macro that names
                            // it, so a project folder can be moved or shared whole.
                            let here = self
                                .state
                                .current_path
                                .lock()
                                .as_ref()
                                .and_then(|p| p.parent().map(|d| d.to_path_buf()));
                            *path = match here.and_then(|d| picked.strip_prefix(d).ok().map(|r| r.to_path_buf())) {
                                Some(rel) => rel.to_string_lossy().to_string(),
                                None => picked.to_string_lossy().to_string(),
                            };
                            changed = true;
                        }
                });
                ui.label(
                    egui::RichText::new(
                        s.call_depth.replace("{}", &MAX_CALL_DEPTH.to_string()),
                    )
                    .weak()
                    .small(),
                );
                changed |= miss_ui(ui, s, "call", miss);
            }
            StepKind::ReadText { x, y, w, h, var, prep } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_var);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(100.0))
                        .changed();
                    changed |= prep_picker(ui, s, "rt", prep);
                });
                changed |= region_ui(ui, s, x, y, w, h, Some(self.ocr_rect));
            }
            StepKind::GetText { source, var } => {
                ui.horizontal_wrapped(|ui| {
                    changed |= source_picker(ui, s, "gt", source);
                    ui.label(s.f_into);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(110.0))
                        .changed();
                });
            }
            StepKind::PutText { sink, text } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_text);
                    changed |= ui
                        .add(egui::TextEdit::singleline(text).desired_width(190.0))
                        .changed();
                    changed |= sink_picker(ui, s, "pt", sink);
                });
            }
            StepKind::ReadNumber { x, y, w, h, var, prep, expect } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_var);
                    changed |= ui
                        .add(egui::TextEdit::singleline(var).desired_width(100.0))
                        .changed();
                    changed |= prep_picker(ui, s, "rn", prep);
                    changed |= expect_picker(ui, s, "rn", expect);
                });
                changed |= region_ui(ui, s, x, y, w, h, Some(self.ocr_rect));
            }
            StepKind::Log { text } => {
                ui.horizontal_wrapped(|ui| {
                    ui.label(s.f_text);
                    changed |= ui
                        .add(egui::TextEdit::singleline(text).desired_width(240.0))
                        .changed();
                });
            }
            _ => {}
        }

        if changed && !busy {
            self.edit_event(sel, |d| {
                if let Some(st) = d.script.get_mut(sel) {
                    st.kind = kind.clone();
                }
            });
        }
    }

    /// The editor, drawn into whatever `Ui` it is given.
    ///
    /// Kept separate from the window plumbing on purpose: if the child viewport is
    /// ever unavailable, this same function can be dropped straight back into the
    /// main window without touching any of the logic.
    fn editor_ui(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let busy = self.busy();
        self.refresh_steps();

        let (count, dur) = {
            let d = self.state.macro_data.lock();
            (d.events.len(), d.duration_us)
        };
        if count == 0 {
            ui.label(s.no_macro);
            return;
        }
        let last_index = count - 1;
        self.ed_cursor = self.ed_cursor.min(last_index);
        self.ed_from = self.ed_from.min(last_index);
        self.ed_to = self.ed_to.min(last_index).max(self.ed_from);

        ui.horizontal_wrapped(|ui| {
            ui.label(s.events.replace("{}", &count.to_string()));
            ui.label(s.duration.replace("{}", &format_us(dur)));
            ui.separator();
            ui.selectable_value(&mut self.ed_view, 0, s.ed_human);
            ui.selectable_value(&mut self.ed_view, 1, s.ed_raw);
            ui.selectable_value(&mut self.ed_view, 2, s.scr_view);
        });
        ui.separator();

        // The list gets whatever is left after the inspector, which is pinned to the
        // bottom - letting the scroll area take the whole window used to push every
        // control off-screen.
        let list_h = (ui.available_height() - 330.0).max(120.0);

        if self.ed_view == 2 {
            self.script_ui(ui, list_h);
            return;
        }

        if self.ed_view == 0 {
            let steps = self.ed_steps.clone();
            let mut pick = None;
            egui::ScrollArea::vertical().id_salt("story").max_height(list_h).auto_shrink(
                [false, false],
            ).show(ui, |ui| {
                for st in &steps {
                    let selected = st.first >= self.ed_from && st.last <= self.ed_to;
                    let line = format!("{}   {}", format_us(st.t_us), st.text);
                    if ui.selectable_label(selected, line).clicked() {
                        pick = Some((st.first, st.last));
                    }
                }
            });
            if let Some((a, b)) = pick {
                self.ed_from = a;
                self.ed_to = b;
                self.ed_cursor = a;
            }
        } else {
            let from = self.ed_from;
            let rows: Vec<(usize, u64, String)> = {
                let d = self.state.macro_data.lock();
                let end = (from + 400).min(count);
                d.events
                    .get(from..end)
                    .unwrap_or(&[])
                    .iter()
                    .enumerate()
                    .map(|(i, ev)| (from + i, ev.t_us, describe_event(ev)))
                    .collect()
            };
            let mut pick = None;
            egui::ScrollArea::vertical().id_salt("raw").max_height(list_h).auto_shrink(
                [false, false],
            ).show(ui, |ui| {
                for (i, t, text) in &rows {
                    let selected = *i == self.ed_cursor;
                    let line = format!("{i:>6}  {}  {text}", format_us(*t));
                    if ui
                        .selectable_label(selected, egui::RichText::new(line).monospace().small())
                        .clicked()
                    {
                        pick = Some(*i);
                    }
                }
            });
            if let Some(i) = pick {
                self.ed_cursor = i;
                self.ed_from = i;
                self.ed_to = i;
            }
        }

        // ---- inspector: one action at a time ---------------------------------
        ui.separator();
        let idx = self.ed_cursor;
        let current = self.state.macro_data.lock().events.get(idx).copied();
        if let Some(ev) = current {
            ui.horizontal_wrapped(|ui| {
                ui.label(egui::RichText::new(s.insp_title).strong());
                ui.label(egui::RichText::new(format!("#{idx}")).weak());
                if ui.small_button("\u{25c0}").clicked() && idx > 0 {
                    self.ed_cursor = idx - 1;
                }
                if ui.small_button("\u{25b6}").clicked() && idx < last_index {
                    self.ed_cursor = idx + 1;
                }
                ui.label(egui::RichText::new(describe_event(&ev)).weak());
            });

            let mut kind = ev.kind;
            let mut kind_changed = false;

            ui.horizontal_wrapped(|ui| {
                ui.label(s.insp_time);
                let mut t_ms = ev.t_us as f64 / 1000.0;
                if ui
                    .add_enabled(
                        !busy,
                        egui::DragValue::new(&mut t_ms).speed(1.0).range(0.0..=1.0e9),
                    )
                    .changed()
                {
                    let t_us = (t_ms * 1000.0).max(0.0) as u64;
                    self.edit_event(idx, |d| editor_set_time(d, idx, t_us));
                }
            });

            match &mut kind {
                InputEventKind::Key { vk, scan, down, extended } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.insp_key);
                        egui::ComboBox::from_id_salt("insp_key")
                            .selected_text(vk_name(*vk as u32))
                            .width(120.0)
                            .show_ui(ui, |ui| {
                                for (name, code) in EDIT_KEYS {
                                    if ui.selectable_label(*vk == code, name).clicked()
                                        && *vk != code
                                    {
                                        *vk = code;
                                        // A stale scancode would replay the old key.
                                        *scan = 0;
                                        kind_changed = true;
                                    }
                                }
                            });
                        let mut raw = *vk as u32;
                        if ui.add(egui::DragValue::new(&mut raw).range(1..=254)).changed() {
                            *vk = raw as u16;
                            *scan = 0;
                            kind_changed = true;
                        }
                        kind_changed |= ui.selectable_value(down, true, s.st_down).clicked();
                        kind_changed |= ui.selectable_value(down, false, s.st_up).clicked();
                        kind_changed |= ui.checkbox(extended, s.insp_extended).changed();
                    });
                }
                InputEventKind::MouseButton { button, down, x, y } => {
                    ui.horizontal_wrapped(|ui| {
                        let names = [s.btn_l, s.btn_r, s.btn_m, "X1", "X2"];
                        let all = [
                            MouseButton::Left,
                            MouseButton::Right,
                            MouseButton::Middle,
                            MouseButton::X1,
                            MouseButton::X2,
                        ];
                        egui::ComboBox::from_id_salt("insp_btn")
                            .selected_text(
                                names[all.iter().position(|b| b == button).unwrap_or(0)],
                            )
                            .width(110.0)
                            .show_ui(ui, |ui| {
                                for (b, n) in all.iter().zip(names) {
                                    if ui.selectable_label(button == b, n).clicked()
                                        && button != b
                                    {
                                        *button = *b;
                                        kind_changed = true;
                                    }
                                }
                            });
                        kind_changed |= ui.selectable_value(down, true, s.st_down).clicked();
                        kind_changed |= ui.selectable_value(down, false, s.st_up).clicked();
                    });
                    ui.horizontal_wrapped(|ui| {
                        ui.label("X");
                        kind_changed |= ui
                            .add(egui::DragValue::new(x).range(-32000..=32000))
                            .changed();
                        ui.label("Y");
                        kind_changed |= ui
                            .add(egui::DragValue::new(y).range(-32000..=32000))
                            .changed();
                        match self.ed_pick_deadline {
                            Some(d) => {
                                let left = d
                                    .saturating_duration_since(Instant::now())
                                    .as_secs()
                                    + 1;
                                ui.label(s.pixel_picking.replace("{}", &left.to_string()));
                            }
                            None => {
                                if ui.button(s.pixel_pick).clicked() {
                                    self.ed_pick_deadline =
                                        Some(Instant::now() + Duration::from_secs(3));
                                }
                            }
                        }
                    });
                }
                InputEventKind::MouseMove { x, y, dx, dy } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label("X");
                        kind_changed |= ui
                            .add(egui::DragValue::new(x).range(-32000..=32000))
                            .changed();
                        ui.label("Y");
                        kind_changed |= ui
                            .add(egui::DragValue::new(y).range(-32000..=32000))
                            .changed();
                        ui.label("dX");
                        kind_changed |= ui.add(egui::DragValue::new(dx)).changed();
                        ui.label("dY");
                        kind_changed |= ui.add(egui::DragValue::new(dy)).changed();
                    });
                    ui.horizontal_wrapped(|ui| match self.ed_pick_deadline {
                        Some(d) => {
                            let left =
                                d.saturating_duration_since(Instant::now()).as_secs() + 1;
                            ui.label(s.pixel_picking.replace("{}", &left.to_string()));
                        }
                        None => {
                            if ui.button(s.pixel_pick).clicked() {
                                self.ed_pick_deadline =
                                    Some(Instant::now() + Duration::from_secs(3));
                            }
                        }
                    });
                }
                InputEventKind::MouseWheel { delta, horizontal, x, y } => {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.insp_delta);
                        kind_changed |= ui
                            .add(egui::DragValue::new(delta).range(-2400..=2400).speed(10.0))
                            .changed();
                        kind_changed |= ui.checkbox(horizontal, s.insp_horiz).changed();
                        ui.label("X");
                        kind_changed |= ui
                            .add(egui::DragValue::new(x).range(-32000..=32000))
                            .changed();
                        ui.label("Y");
                        kind_changed |= ui
                            .add(egui::DragValue::new(y).range(-32000..=32000))
                            .changed();
                    });
                }
            }

            if kind_changed && !busy {
                self.edit_event(idx, |d| editor_set_event(d, idx, kind));
            }

            // A found match becomes a real click in the macro, right after the
            // selected action - the whole point of searching from the editor.
            let hit = *LAST_HIT.lock();
            if let Some(h) = hit
                && h.score as f64 >= self.config.img_threshold {
                    ui.horizontal_wrapped(|ui| {
                        let label = format!("{}  ({}, {})", s.img_insert_click, h.x, h.y);
                        if ui.add_enabled(!busy, egui::Button::new(label)).clicked() {
                            self.edit(|d| editor_insert_click(d, idx, h.x, h.y));
                        }
                    });
                }

            ui.horizontal_wrapped(|ui| {
                if ui.add_enabled(!busy, egui::Button::new(s.insp_dup)).clicked() {
                    self.edit(|d| editor_duplicate(d, idx));
                }
                if ui.add_enabled(!busy, egui::Button::new(s.insp_del_one)).clicked() {
                    self.edit(|d| editor_delete_one(d, idx));
                    self.ed_cursor = idx.saturating_sub(1);
                }
                if ui
                    .add_enabled(self.ed_undo.is_some() && !busy, egui::Button::new(s.ed_undo))
                    .clicked()
                    && let Some(prev) = self.ed_undo.take() {
                        let d = prev.duration_us;
                        *self.state.macro_data.lock() = prev;
                        self.state.recorded_time_us.store(d, Ordering::Relaxed);
                        self.ed_undo_key = None;
                        self.health = None;
                    }
            });
        } else {
            ui.label(s.insp_none);
        }

        // ---- range operations -------------------------------------------------
        ui.separator();
        ui.horizontal_wrapped(|ui| {
            ui.label(s.ed_from);
            ui.add(egui::DragValue::new(&mut self.ed_from).range(0..=last_index));
            ui.label(s.ed_to);
            ui.add(egui::DragValue::new(&mut self.ed_to).range(0..=last_index));
            if self.ed_to < self.ed_from {
                self.ed_to = self.ed_from;
            }
            let (from, to) = (self.ed_from, self.ed_to);
            if ui.add_enabled(!busy, egui::Button::new(s.ed_delete)).clicked() {
                self.edit(|d| editor_delete_range(d, from, to));
            }
            if ui.add_enabled(!busy, egui::Button::new(s.ed_crop)).clicked() {
                self.edit(|d| editor_crop(d, from, to));
            }
            if ui.add_enabled(!busy, egui::Button::new(s.ed_drop_moves)).clicked() {
                self.edit(editor_drop_moves);
            }
            if ui.add_enabled(!busy, egui::Button::new(s.ed_zero)).clicked() {
                self.edit(editor_trim_lead);
            }
        });

        // Markers live here, beside the range fields they name: the only moment
        // anybody knows which place they mean is while they are looking at it.
        egui::CollapsingHeader::new("🔖").id_salt("markers").show(ui, |ui| {
            self.markers_ui(ui);
        });

        ui.horizontal_wrapped(|ui| {
            ui.label(s.ed_insert);
            ui.add(egui::DragValue::new(&mut self.ed_delay_ms).range(0..=600_000).speed(10.0));
            if ui.add_enabled(!busy, egui::Button::new("+")).clicked() {
                let (at, ms) = (self.ed_from, self.ed_delay_ms);
                self.edit(|d| editor_insert_delay(d, at, ms));
            }
            ui.label(s.ed_scale);
            ui.add(egui::DragValue::new(&mut self.ed_scale).range(0.05..=20.0).speed(0.05));
            if ui.add_enabled(!busy, egui::Button::new("\u{2714}")).clicked() {
                let f = self.ed_scale;
                self.edit(|d| editor_scale(d, f));
            }
        });

        // Bulk edits: the two things people actually want across a whole recording.
        ui.horizontal_wrapped(|ui| {
            let names = [s.btn_l, s.btn_r, s.btn_m, "X1", "X2"];
            ui.label(s.bulk_replace);
            egui::ComboBox::from_id_salt("bulk_a")
                .selected_text(names[self.bulk_from_btn.min(4)])
                .width(90.0)
                .show_ui(ui, |ui| {
                    for (i, n) in names.iter().enumerate() {
                        ui.selectable_value(&mut self.bulk_from_btn, i, *n);
                    }
                });
            ui.label("\u{2192}");
            egui::ComboBox::from_id_salt("bulk_b")
                .selected_text(names[self.bulk_to_btn.min(4)])
                .width(90.0)
                .show_ui(ui, |ui| {
                    for (i, n) in names.iter().enumerate() {
                        ui.selectable_value(&mut self.bulk_to_btn, i, *n);
                    }
                });
            if ui.add_enabled(!busy, egui::Button::new("\u{2714}")).clicked() {
                let (from, to) = (self.ed_from, self.ed_to);
                let a = MouseButton::from_index(self.bulk_from_btn);
                let b = MouseButton::from_index(self.bulk_to_btn);
                self.edit(|d| {
                    editor_replace_button(d, from, to, a, b);
                });
            }
        });

        ui.horizontal_wrapped(|ui| {
            ui.label(s.bulk_shift);
            ui.label("dX");
            ui.add(egui::DragValue::new(&mut self.bulk_dx).range(-32000..=32000));
            ui.label("dY");
            ui.add(egui::DragValue::new(&mut self.bulk_dy).range(-32000..=32000));
            if ui.add_enabled(!busy, egui::Button::new("\u{2714}")).clicked() {
                let (from, to, dx, dy) =
                    (self.ed_from, self.ed_to, self.bulk_dx, self.bulk_dy);
                self.edit(|d| editor_shift_coords(d, from, to, dx, dy));
            }
        });
    }

    /// The other half of the debug overlay: what the script knows, not where it
    /// is looking.
    ///
    /// Its own window rather than a panel in the main one for the same reason the
    /// editor has one: this is read while another application is in front, and a
    /// table that is only visible when the recorder has focus is a table nobody
    /// reads. Only open costs anything - `set_watching_vars` is what makes the
    /// interpreter publish at all.
    /// Everything the palette can do, built fresh each time it is opened.
    ///
    /// A flat list of (name, what it does) rather than a tree: the whole point is
    /// that somebody who knows what they want types it instead of remembering which
    /// section it lives in.
    fn palette_commands(&self) -> Vec<(String, PaletteAction)> {
        let s = self.strs();
        let mut out: Vec<(String, PaletteAction)> = vec![
            (s.play.to_string(), PaletteAction::Play),
            (s.test_run.to_string(), PaletteAction::TestRun),
            (s.stop_play.to_string(), PaletteAction::Stop),
            (s.record.to_string(), PaletteAction::Record),
            (s.ed_open.to_string(), PaletteAction::Editor),
            (s.vars_open.to_string(), PaletteAction::Vars),
            (s.runs_open.to_string(), PaletteAction::Runs),
            (s.check_now.to_string(), PaletteAction::Check),
            (s.hb_title.to_string(), PaletteAction::Handbook),
            (s.save.to_string(), PaletteAction::Save),
            (s.load.to_string(), PaletteAction::Load),
        ];
        // Every step kind, so "add a wait" is two keystrokes and a Return rather
        // than a hunt through a drop-down that is about to get longer.
        for i in 0..StepKind::COUNT {
            let kind = StepKind::from_index(i);
            out.push((format!("{} {}", s.scr_add, kind.name(s)), PaletteAction::AddStep(i)));
        }
        // Every template, so a recipe is two keystrokes away rather than behind a
        // collapsed panel nobody opens.
        for (i, r) in templates::ALL.iter().enumerate() {
            out.push((
                format!("{} {}", s.tpl_insert, (r.name)(s)),
                PaletteAction::Template(i),
            ));
        }
        // And the built-in values, which is the whole of proposal 21's "Insert →
        // Built-in value": a menu so nobody has to remember the names.
        for (i, name) in BUILT_INS.iter().enumerate() {
            out.push((
                format!("{} {{{name}}}", s.f_builtin),
                PaletteAction::InsertBuiltIn(i),
            ));
        }
        out
    }

    /// The palette, drawn over everything else.
    ///
    /// Deliberately not a viewport: it is a thing you open, type into and dismiss in
    /// under a second, and a second OS window for that would be slower to appear than
    /// the drop-down it replaces.
    fn palette_ui(&mut self, ctx: &egui::Context) {
        // Ctrl+K anywhere, and Escape to leave. Consumed rather than observed, so a
        // text field underneath does not also receive the K.
        if ctx.input_mut(|i| {
            i.consume_key(egui::Modifiers::COMMAND, egui::Key::K)
        }) {
            self.pal_open = !self.pal_open;
            self.pal_query.clear();
            self.pal_sel = 0;
        }
        if !self.pal_open {
            return;
        }
        if ctx.input(|i| i.key_pressed(egui::Key::Escape)) {
            self.pal_open = false;
            return;
        }

        let s = self.strs();
        let commands = self.palette_commands();
        let hits = palette::rank(&commands, &self.pal_query, |(name, _)| name.as_str());
        let count = hits.len();
        if count > 0 {
            self.pal_sel = self.pal_sel.min(count - 1);
        }
        // Arrow keys move the highlight; Return runs it. Read before the list is
        // drawn so the highlight and the action agree about which row is picked.
        if ctx.input(|i| i.key_pressed(egui::Key::ArrowDown)) && count > 0 {
            self.pal_sel = (self.pal_sel + 1) % count;
        }
        if ctx.input(|i| i.key_pressed(egui::Key::ArrowUp)) && count > 0 {
            self.pal_sel = (self.pal_sel + count - 1) % count;
        }
        let go = ctx.input(|i| i.key_pressed(egui::Key::Enter));

        let mut chosen: Option<PaletteAction> = None;
        egui::Window::new(s.pal_title)
            .collapsible(false)
            .resizable(false)
            .anchor(egui::Align2::CENTER_TOP, [0.0, 60.0])
            .fixed_size([380.0, 0.0])
            .show(ctx, |ui| {
                let field = ui.add(
                    egui::TextEdit::singleline(&mut self.pal_query)
                        .hint_text(s.pal_hint)
                        .desired_width(f32::INFINITY),
                );
                field.request_focus();
                ui.separator();
                if hits.is_empty() {
                    ui.label(egui::RichText::new(s.pal_nothing).weak());
                }
                egui::ScrollArea::vertical().max_height(280.0).show(ui, |ui| {
                    for (i, (name, action)) in hits.iter().enumerate() {
                        if ui.selectable_label(i == self.pal_sel, name.as_str()).clicked() {
                            chosen = Some(*action);
                        }
                        if go && i == self.pal_sel {
                            chosen = Some(*action);
                        }
                    }
                });
            });

        if let Some(action) = chosen {
            self.pal_open = false;
            self.pal_query.clear();
            self.run_palette_action(action);
        }
    }

    fn run_palette_action(&mut self, action: PaletteAction) {
        match action {
            PaletteAction::Play => start_playback(&self.state),
            PaletteAction::TestRun => start_test_run(&self.state),
            PaletteAction::Stop => stop_everything(&self.state),
            PaletteAction::Record => toggle_recording(&self.state),
            PaletteAction::Editor => self.editor_open = true,
            PaletteAction::Vars => self.vars_open = true,
            PaletteAction::Runs => self.runs_open = true,
            PaletteAction::Check => self.run_health_check(),
            PaletteAction::Handbook => self.help_open = true,
            // The same two things the Files section does, so the palette cannot
            // drift into a second, subtly different way of saving.
            PaletteAction::Save => {
                let path = self.default_save_path();
                self.do_save(path);
            }
            PaletteAction::Load => {
                if let Some(path) = rfd::FileDialog::new()
                    .add_filter("Macro", &["json", "mrz", "gz"])
                    .set_directory(paths::data_dir())
                    .pick_file()
                {
                    self.do_load(path);
                }
            }
            PaletteAction::Template(i) => {
                if let Some(r) = templates::ALL.get(i) {
                    let built = (r.build)();
                    self.insert_steps(built);
                    self.status_msg = (r.name)(self.strs()).to_string();
                }
            }
            PaletteAction::InsertBuiltIn(i) => {
                let name = BUILT_INS.get(i).copied().unwrap_or("clipboard");
                let text = format!("{{{name}}}");
                platform::set_clipboard_text(&text);
                self.status_msg = format!("{text}  \u{2192}  {}", self.strs().t_clipboard);
            }
            PaletteAction::AddStep(i) => {
                let mut kind = StepKind::from_index(i);
                // A fresh "play events" step covers the whole recording, the same
                // way the Add button makes one.
                if let StepKind::PlayEvents { from, to, .. } = &mut kind
                    && *from == 0 && *to == 0 {
                        *to = self.state.macro_data.lock().events.len().saturating_sub(1);
                    }
                let at = self.scr_sel;
                self.edit(|d| {
                    let pos = (at + 1).min(d.script.len());
                    d.script.insert(pos, ScriptStep::new(kind));
                });
                // Adding a step from the palette is only useful if you can then see
                // it, and the script list lives in the editor window.
                self.editor_open = true;
                self.ed_view = 2;
            }
        }
    }

    /// The run history, in its own window.
    ///
    /// Read from disk when the window opens and not again while it is up: this is a
    /// diary, not a live view, and re-reading a file sixty times a second to show
    /// twenty lines that have not changed would be absurd.
    fn runs_viewport(&mut self, ctx: &egui::Context) {
        if !self.runs_open {
            self.runs_cache = None;
            return;
        }
        if self.runs_cache.is_none() {
            self.runs_cache = Some(runlog::load());
        }
        self.extra_window(ctx, ExtraWindow {
            id: "macro_runs",
            title: self.strs().runs_title.to_string(),
            size: [560.0, 520.0],
            min: [360.0, 240.0],
            draw: |app, ui| app.runs_window(ui),
            closed: |app| app.runs_open = false,
        });
    }

    /// The body of the runs window.
    ///
    /// A method rather than a closure so a deferred viewport can reach it
    /// through a plain function pointer.
    fn runs_window(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let mut reload = false;

                egui::CentralPanel::default().show(ui, |ui| {
                    let runs = self.runs_cache.as_deref().unwrap_or(&[]);
                    ui.horizontal(|ui| {
                        if ui.button(s.runs_clear).clicked() {
                            let _ = std::fs::remove_dir_all(runlog::dir());
                            reload = true;
                        }
                    });
                    ui.separator();
                    if runs.is_empty() {
                        ui.label(s.runs_none);
                    }
                    egui::ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
                        for run in runs {
                            let colour = match run.outcome {
                                runlog::Outcome::Finished => {
                                    egui::Color32::from_rgb(120, 210, 120)
                                }
                                runlog::Outcome::Stopped => egui::Color32::GRAY,
                                runlog::Outcome::Failed => {
                                    egui::Color32::from_rgb(255, 130, 110)
                                }
                            };
                            ui.label(
                                egui::RichText::new(run.headline()).color(colour).strong(),
                            );
                            ui.label(
                                egui::RichText::new(
                                    s.runs_loops
                                        .replacen("{}", &run.loops.to_string(), 1)
                                        .replacen(
                                            "{}",
                                            &format_dur(run.duration_ms * 1000),
                                            1,
                                        ),
                                )
                                .weak(),
                            );
                            // What the run had to do beyond doing as it was told.
                            // `Completed` was never the whole answer: a run that
                            // finished having fallen back three times and been
                            // through a recovery block is one that is about to stop
                            // finishing, and it used to look exactly like a good one.
                            //
                            // Counts, not a score. Every line here is something the
                            // program observed; a number out of a hundred would be an
                            // opinion, and one shaped like the pre-flight score -
                            // which measures something else entirely - would invite a
                            // comparison that means nothing.
                            let e = &run.effort;
                            ui.label(egui::RichText::new(s.eff_title).weak());
                            if e.quiet() {
                                ui.label(
                                    egui::RichText::new(format!(
                                        "\u{00b7} {}",
                                        s.eff_quiet
                                    ))
                                    .weak(),
                                );
                            } else {
                                let lines: [(u64, &str); 5] = [
                                    (e.fallbacks as u64, s.eff_fallback),
                                    (e.ocr_retries as u64, s.eff_ocr),
                                    (e.recoveries as u64, s.eff_recovery),
                                    (e.recovery_ms, s.eff_overhead),
                                    (e.missed as u64, s.eff_missed),
                                ];
                                for (n, text) in lines {
                                    if n == 0 {
                                        continue;
                                    }
                                    ui.label(
                                        egui::RichText::new(format!(
                                            "\u{00b7} {}",
                                            text.replace("{}", &n.to_string())
                                        ))
                                        .color(egui::Color32::from_rgb(255, 200, 90)),
                                    );
                                }
                            }
                            if e.steps > 0 {
                                ui.label(
                                    egui::RichText::new(
                                        s.eff_steps.replace("{}", &e.steps.to_string()),
                                    )
                                    .weak(),
                                );
                            }
                            if !run.failed_step.is_empty() {
                                ui.label(
                                    egui::RichText::new(format!(
                                        "#{}  {}",
                                        run.failed_at.unwrap_or(0),
                                        run.failed_step
                                    ))
                                    .monospace(),
                                );
                            }
                            if !run.reason.is_empty() {
                                ui.label(format!("{} {}", s.runs_why, run.reason));
                            }
                            // The suggestions, which is the half that turns a
                            // post-mortem into something to do next.
                            if !run.hints.is_empty() {
                                ui.label(egui::RichText::new(s.runs_try).strong());
                                for h in &run.hints {
                                    ui.label(egui::RichText::new(format!("• {h}")).weak());
                                }
                            }
                            if let Some(path) = run.shot_path()
                                && path.exists()
                                    && ui.button(s.runs_shot).clicked()
                                {
                                    // Handed to whatever the user opens PNGs with.
                                    run_program(&path.to_string_lossy(), "");
                                }
                            ui.separator();
                        }
                    });
                });
        if reload {
            self.runs_cache = None;
        }
    }

    fn vars_viewport(&mut self, ctx: &egui::Context) {
        set_watching_vars(self.vars_open);
        if !self.vars_open {
            // Step mode with the window shut would park a run with no button to
            // free it. Closing the window is therefore also "let it go".
            self.state.step_mode.store(false, Ordering::Relaxed);
            return;
        }
        self.extra_window(ctx, ExtraWindow {
            id: "macro_vars",
            title: self.strs().vars_title.to_string(),
            size: [420.0, 480.0],
            min: [300.0, 220.0],
            draw: |app, ui| app.vars_window(ui),
            closed: |app| app.vars_open = false,
        });
    }

    /// The body of the vars window.
    ///
    /// A method rather than a closure so a deferred viewport can reach it
    /// through a plain function pointer.
    fn vars_window(&mut self, ui: &mut egui::Ui) {
        let s = self.strs();
        let state = self.state.clone();

                egui::CentralPanel::default().show(ui, |ui| {
                    let view = script_view();
                    let running = view.as_ref().is_some_and(|v| v.running);

                    ui.horizontal_wrapped(|ui| {
                        ui.label(if running { s.vars_running } else { s.vars_idle });
                        ui.separator();
                        let mut stepping = state.step_mode.load(Ordering::Relaxed);
                        if ui
                            .checkbox(&mut stepping, s.vars_stepmode)
                            .changed()
                        {
                            state.step_mode.store(stepping, Ordering::Relaxed);
                            // Turning it off has to release a run already parked;
                            // turning it on has to start from a clean slate, or a
                            // leftover raised flag lets the first step through.
                            state.step_once.store(!stepping, Ordering::Relaxed);
                        }
                        let waiting = view.as_ref().is_some_and(|v| v.waiting);
                        if ui
                            .add_enabled(waiting, egui::Button::new(s.vars_stepnext))
                            .clicked()
                        {
                            state.step_once.store(true, Ordering::Relaxed);
                        }
                    });
                    ui.separator();

                    match &view {
                        Some(v) => {
                            let depth = if v.depth > 0 {
                                format!("  ↳{}", v.depth)
                            } else {
                                String::new()
                            };
                            ui.label(
                                egui::RichText::new(format!(
                                    "{} {}{depth}  {}",
                                    s.vars_step, v.pc, v.step
                                ))
                                .monospace(),
                            );
                            ui.separator();
                            if v.vars.is_empty() {
                                ui.label(egui::RichText::new(s.vars_none).weak());
                            } else {
                                egui::ScrollArea::vertical()
                                    .id_salt("vars_rows")
                                    .auto_shrink([false, false])
                                    .show(ui, |ui| {
                                        egui::Grid::new("vars_grid")
                                            .num_columns(2)
                                            .striped(true)
                                            .show(ui, |ui| {
                                                ui.label(
                                                    egui::RichText::new(s.vars_name).strong(),
                                                );
                                                ui.label(
                                                    egui::RichText::new(s.vars_value).strong(),
                                                );
                                                ui.end_row();
                                                for (k, val) in &v.vars {
                                                    ui.label(
                                                        egui::RichText::new(k).monospace(),
                                                    );
                                                    // Newlines from an OCR read
                                                    // would each claim a row.
                                                    ui.label(
                                                        egui::RichText::new(
                                                            val.replace('\n', " / "),
                                                        )
                                                        .monospace(),
                                                    );
                                                    ui.end_row();
                                                }
                                            });
                                    });
                            }
                        }
                        None => {
                            ui.label(egui::RichText::new(s.vars_none).weak());
                        }
                    }
                });
                // A parked run publishes nothing new, so nothing would wake the
                // window up to notice the button being pressable.
                ui.ctx().request_repaint_after(Duration::from_millis(120));
    }

    /// Hosts the editor in its own OS window while `editor_open` is set.
    fn editor_viewport(&mut self, ctx: &egui::Context) {
        if !self.editor_open {
            return;
        }
        self.extra_window(ctx, ExtraWindow {
            id: "macro_editor",
            title: self.strs().ed_title.to_string(),
            size: [640.0, 560.0],
            min: [420.0, 320.0],
            draw: |app, ui| app.editor_window(ui),
            closed: |app| app.editor_open = false,
        });
    }

    /// The body of the editor window.
    ///
    /// A method rather than a closure so a deferred viewport can reach it
    /// through a plain function pointer.
    fn editor_window(&mut self, ui: &mut egui::Ui) {

                egui::CentralPanel::default().show(ui, |ui| {
                    self.editor_ui(ui);
                });
    }
}

impl AppInner {
    /// Runs before every frame, **and while the window is hidden or minimised**.
    ///
    /// This is where the separate windows are declared, and it has to be here rather
    /// than in `ui`. On Windows a minimised window receives no redraw at all, so
    /// `ui` stops being called the moment the main window goes to the taskbar — and
    /// with it went every child window the program owns: the handbook could not be
    /// scrolled, clicked or even closed until the main window was brought back.
    ///
    /// eframe provides exactly this hook for it: while the root is hidden it runs no
    /// egui pass, but it does keep calling `logic`, so anything declared here keeps
    /// living. The repaint request below is what keeps that ticking, because a hidden
    /// window is only asked again if something asks for it.
    fn logic(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.handbook_viewport(ctx);
        self.editor_viewport(ctx);
        self.vars_viewport(ctx);
        self.runs_viewport(ctx);
        // While the main window is hidden, nothing else asks for another pass, and
        // without one this is never called again - which would leave every window
        // above frozen at whatever it last drew. Ten times a second is plenty for
        // something a person is reading, and costs nothing when they are not.
        if self.help_open || self.editor_open || self.vars_open || self.runs_open {
            ctx.request_repaint_after(Duration::from_millis(100));
        }
    }

    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let s = self.strs();
        let recording = self.state.recording.load(Ordering::Relaxed);
        let playing = self.state.playing.load(Ordering::Relaxed);
        let paused = self.state.paused.load(Ordering::Relaxed);
        let busy = recording || playing;

        // The window only exists after the first frame, so the backdrop lands here.
        if self.theme_dirty {
            self.panel_fill = apply_theme(
                ui.ctx(),
                theme_at(self.config.default_theme),
                self.config.transparent_ui,
            );
            self.theme_dirty = false;
        }

        // ---- close button -----------------------------------------------------
        // Minimize to tray instead of quitting - unless the tray itself asked us to
        // quit, and never when the icon failed to appear, which would leave the app
        // running with no way to reach it.
        if ui.ctx().input(|i| i.viewport().close_requested()) {
            let to_tray = self.config.tray_enabled
                && self.config.close_to_tray
                && tray::is_active()
                && !ALLOW_CLOSE.load(Ordering::Relaxed);
            if to_tray {
                ui.ctx().send_viewport_cmd(egui::ViewportCommand::CancelClose);
                set_window_visible(false);
            }
        }

        // ---- hotkey binding ---------------------------------------------------
        let slot = CAPTURE_SLOT.load(Ordering::Relaxed);
        if slot != 0 {
            // Keep the window awake and give up after a while so a forgotten binding
            // session can never leave the global hotkeys switched off.
            ui.ctx().request_repaint();
            match self.capture_started {
                Some(t) if t.elapsed() > Duration::from_secs(15) => {
                    self.capture_started = None;
                    end_capture();
                }
                None => self.capture_started = Some(Instant::now()),
                _ => {}
            }
            // Path 1: normal window input (works whenever this window has focus).
            if let Some(hk) = capture_from_window(ui.ctx()) {
                *CAPTURED_KEY.lock() = Some(hk);
            }
        } else {
            self.capture_started = None;
        }

        // Path 2: the low-level hook, which also sees keys while another app is focused.
        let captured = CAPTURED_KEY.lock().take();
        if let Some(hk) = captured {
            if slot != 0 && hk.vk != 0 {
                match slot {
                    1 => self.config.hotkey_record = hk,
                    2 => self.config.hotkey_play = hk,
                    3 => self.config.hotkey_stop = hk,
                    4 => self.config.hotkey_pause = hk,
                    5 => self.config.hotkey_faster = hk,
                    6 => self.config.hotkey_slower = hk,
                    7 => self.config.hotkey_skip = hk,
                    _ => {}
                }
                self.status_msg = format!("{} {}", s.hk_bind, hk.label());
            }
            self.capture_started = None;
            end_capture();
            publish_hotkeys(&self.config);
        }

        // ---- deferred pick of a coordinate for the selected action ------------
        if let Some(deadline) = self.ed_pick_deadline {
            ui.ctx().request_repaint();
            if Instant::now() >= deadline {
                self.ed_pick_deadline = None;
                let (px, py) = platform::cursor_pos();
                let idx = self.ed_cursor;
                let current = self.state.macro_data.lock().events.get(idx).copied();
                if let Some(ev) = current {
                    let mut kind = ev.kind;
                    match &mut kind {
                        InputEventKind::MouseMove { x, y, .. }
                        | InputEventKind::MouseButton { x, y, .. }
                        | InputEventKind::MouseWheel { x, y, .. } => {
                            *x = px;
                            *y = py;
                        }
                        InputEventKind::Key { .. } => {}
                    }
                    self.edit_event(idx, |d| editor_set_event(d, idx, kind));
                }
                self.status_msg = format!("{px}, {py}");
            }
        }

        // ---- deferred OCR region pick ----------------------------------------
        // Two points, because a rectangle cannot be described by one. The first
        // press captures the top-left corner, the second the bottom-right.
        if let Some((deadline, second)) = self.ocr_pick {
            ui.ctx().request_repaint();
            if Instant::now() >= deadline {
                let (px, py) = platform::cursor_pos();
                if second {
                    let (ax, ay) = self.ocr_corner;
                    let x = ax.min(px);
                    let y = ay.min(py);
                    let w = (px - ax).abs().max(8);
                    let h = (py - ay).abs().max(8);
                    self.ocr_rect = (x, y, w, h);
                    self.ocr_pick = None;
                    // Read straight away: seeing the text is the proof it worked.
                    self.read_ocr_panel(s);
                } else {
                    self.ocr_corner = (px, py);
                    self.ocr_pick = Some((Instant::now() + Duration::from_secs(3), true));
                }
            }
        }

        // ---- deferred pixel pick ---------------------------------------------
        if let Some(deadline) = self.pick_deadline
            && Instant::now() >= deadline {
                self.pick_deadline = None;
                let (x, y) = platform::cursor_pos();
                self.config.pixel_x = x;
                self.config.pixel_y = y;
                if let Some((r, g, b)) = platform::screen_pixel(x, y) {
                    self.config.pixel_r = r;
                    self.config.pixel_g = g;
                    self.config.pixel_b = b;
                }
                self.status_msg = s.done.to_string();
            }

        if self.state.pixel_triggered.swap(false, Ordering::Relaxed) {
            self.status_msg = s.status_pixel.to_string();
        }

        // A run has just ended, so there are new numbers to read.
        if self.was_playing && !playing {
            self.refresh_stats();
            // And if a queue is running, the next entry is now due.
            if let Some(i) = self.queue_at {
                let next = i + 1;
                if next < self.queue.len() && !self.state.stop_play.load(Ordering::Relaxed) {
                    self.queue_at = Some(next);
                    self.advance_queue();
                } else {
                    // Ran out, or somebody pressed stop - which stops the lot.
                    self.queue_at = None;
                }
            }
        }
        self.was_playing = playing;

        // The tally is the whole answer to "did it really not touch anything?", so it
        // is reported the moment the rehearsal ends and then left on screen.
        let testing_now = self.state.test_run.load(Ordering::Relaxed);
        if self.was_test_run && !testing_now {
            self.status_msg = s
                .test_done
                .replacen("{}", &selftest::suppressed().to_string(), 1)
                .replacen("{}", &selftest::skipped().to_string(), 1);
        }
        self.was_test_run = testing_now;

        // Drawn before the main panel so it is a sibling window, not a nested one.
        // The moment a recording stops is the moment the squares are worth
        // something, and it is also the only moment the user is looking at this
        // window rather than at the thing they were recording.
        if self.was_recording && !recording {
            self.shots_offer = !self.state.click_shots.lock().is_empty();
            self.health = None;
        }
        self.was_recording = recording;

        let ctx = ui.ctx().clone();
        // The three separate windows are declared in `logic`, not here, so that
        // they keep living while this window is minimised.
        self.palette_ui(&ctx);
        self.shots_offer_ui(&ctx);
        self.fix_window_geometry(&ctx);
        self.preflight_ui(&ctx);
        self.save_guard_ui(&ctx);
        self.help_button(&ctx);
        // The overlay owns its own window on its own thread; this only says whether
        // it should be there. Idempotent, so calling it every frame costs a load.
        WATCHING.store(self.config.debug_overlay, Ordering::Relaxed);
        overlay::set_enabled(self.config.debug_overlay);

        let panel = egui::Frame::central_panel(ui.style()).fill(self.panel_fill);
        egui::CentralPanel::default().frame(panel).show(ui, |ui| {
            egui::ScrollArea::vertical().show(ui, |ui| {
                ui.horizontal(|ui| {
                    ui.heading(APP_TITLE);
                    ui.label(egui::RichText::new(format!("v{APP_VERSION}")).weak());
                });
                ui.separator();

                // ---- transport ------------------------------------------------
                ui.horizontal(|ui| {
                    let label = if recording { s.stop_rec } else { s.record };
                    if ui.add_enabled(!playing, egui::Button::new(label)).clicked() {
                        toggle_recording(&self.state);
                    }
                    ui.label(egui::RichText::new(self.config.hotkey_record.label()).weak());
                });
                ui.horizontal(|ui| {
                    let label = if playing { s.stop_play } else { s.play };
                    if ui.add_enabled(!recording, egui::Button::new(label)).clicked() {
                        toggle_playback(&self.state);
                    }
                    let label = if paused { s.resume } else { s.pause };
                    if ui.add_enabled(playing, egui::Button::new(label)).clicked() {
                        toggle_pause(&self.state);
                    }
                    ui.label(egui::RichText::new(self.config.hotkey_play.label()).weak());
                });
                // Its own row rather than a third button beside Play: the two do the
                // same thing to the same macro and differ only in whether it is real,
                // which is exactly the pair of buttons somebody clicks the wrong one of.
                ui.horizontal(|ui| {
                    if ui
                        .add_enabled(
                            !recording && !playing,
                            egui::Button::new(s.test_run),
                        )
                        .clicked()
                    {
                        start_test_run(&self.state);
                    }
                });

                // ---- live status ----------------------------------------------
                if recording {
                    ui.label(
                        s.rec_time.replace("{}", &format_us(current_rec_time_us(&self.state))),
                    );
                } else {
                    let rt = self.state.recorded_time_us.load(Ordering::Relaxed);
                    if rt > 0 {
                        ui.label(s.rec_done.replace("{}", &format_us(rt)));
                    }
                }
                if playing || self.state.play_count.load(Ordering::Relaxed) > 0 {
                    let c = self.state.play_count.load(Ordering::Relaxed);
                    if self.state.loop_play.load(Ordering::Relaxed) {
                        ui.label(s.play_inf.replace("{}", &c.to_string()));
                    } else {
                        let l = self.state.play_count_limit.load(Ordering::Relaxed);
                        ui.label(
                            s.play_lim
                                .replacen("{}", &c.to_string(), 1)
                                .replacen("{}", &l.to_string(), 1),
                        );
                    }
                }
                ui.separator();

                // ---- playback --------------------------------------------------
                egui::CollapsingHeader::new(s.sec_playback).default_open(true).show(ui, |ui| {
                    // Worked out from the settings rather than remembered, so it can
                    // never claim a profile the boxes below no longer spell out.
                    let current = PlaybackProfile::detect(&self.config);
                    ui.horizontal(|ui| {
                        ui.label(s.play_profile);
                        let mut pick = current.index();
                        egui::ComboBox::from_id_salt("play_profile")
                            .selected_text(current.name(s))
                            .width(150.0)
                            .show_ui(ui, |ui| {
                                for i in 0..PlaybackProfile::COUNT {
                                    let p = PlaybackProfile::from_index(i);
                                    // "Custom" is a description, not a choice: there
                                    // is nothing for it to apply.
                                    if p == PlaybackProfile::Custom && current != p {
                                        continue;
                                    }
                                    if ui.selectable_label(pick == i, p.name(s)).clicked() {
                                        pick = i;
                                    }
                                }
                            });
                        let chosen = PlaybackProfile::from_index(pick);
                        if chosen != current {
                            chosen.apply(&mut self.config);
                        }
                    });
                    ui.checkbox(&mut self.config.loop_play, s.loop_cb);
                    if !self.config.loop_play {
                        ui.horizontal(|ui| {
                            ui.label(s.play_count);
                            ui.add(
                                egui::DragValue::new(&mut self.config.play_count_limit)
                                    .range(1..=9999),
                            );
                        });
                    }
                    ui.add(egui::Slider::new(&mut self.config.speed, 0.1..=3.0).text(s.speed));
                    ui.horizontal(|ui| {
                        ui.label(s.repeat_delay);
                        ui.add(
                            egui::DragValue::new(&mut self.config.repeat_delay_ms)
                                .range(0..=600_000)
                                .speed(10.0),
                        );
                    });
                    ui.horizontal(|ui| {
                        ui.label(s.jitter);
                        ui.add(egui::DragValue::new(&mut self.config.jitter_pct).range(0..=50));
                    });
                    // One setting, two switches: picking either turns the other off.
                    ui.horizontal_wrapped(|ui| {
                        if ui.radio(self.config.absolute_mouse, s.abs_mouse).clicked() {
                            self.config.absolute_mouse = true;
                        }
                        if ui.radio(!self.config.absolute_mouse, s.mouse_rel).clicked() {
                            self.config.absolute_mouse = false;
                        }
                    });
                    ui.checkbox(&mut self.config.human_mouse, s.human_mouse);
                    if self.config.human_mouse {
                        ui.add(
                            egui::Slider::new(&mut self.config.human_curve, 0..=100)
                                .text(s.human_curve),
                        );
                        // Spelled out instead of hidden in a tooltip: the setting does
                        // nothing to a recording that already holds real movement, and
                        // that is indistinguishable from it being broken.
                    }
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.mouse_jitter);
                        ui.add(
                            egui::DragValue::new(&mut self.config.mouse_jitter_px).range(0..=60),
                        );
                    });
                });

                // ---- recording -------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_recording)
                    .show(ui, |ui| {
                    ui.checkbox(&mut self.config.capture_mouse_moves, s.capture_moves);
                    ui.horizontal(|ui| {
                        ui.label(s.sample_rate);
                        ui.add(
                            egui::DragValue::new(&mut self.config.mouse_sample_ms).range(1..=100),
                        );
                    });
                    ui.separator();
                    ui.checkbox(&mut self.config.record_click_shots, s.rec_shots_cb);
                    if self.config.record_click_shots {
                        ui.horizontal(|ui| {
                            ui.label(s.rec_shots_size);
                            ui.add(
                                egui::DragValue::new(&mut self.config.click_shot_size)
                                    .range(16..=512)
                                    .speed(2.0),
                            );
                        });
                        let n = self.state.click_shots.lock().len();
                        if n > 0 {
                            ui.label(
                                egui::RichText::new(
                                    s.rec_shots.replace("{}", &n.to_string()),
                                )
                                .weak()
                                .small(),
                            );
                        }
                    }
                });
                help_from(&mut self.help_topic, "recording", hr);

                // ---- target window ---------------------------------------------
                // Everything that depends on which window the macro is aimed at, in
                // one place: what it is, how coordinates follow it, and how well it
                // keeps up. Splitting these across Playback and Recording made three
                // halves of one decision look like three unrelated settings.
                let hr = egui::CollapsingHeader::new(s.sec_target)
                    .show(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.tgt_title);
                        ui.add(
                            egui::TextEdit::singleline(&mut self.config.target_title)
                                .desired_width(200.0),
                        );
                    });
                    // The recording already noted which window was in front when it
                    // started, so the title never has to be typed out by hand.
                    let recorded = self
                        .state
                        .macro_data
                        .lock()
                        .anchor
                        .as_ref()
                        .map(|a| a.title.clone());
                    ui.horizontal_wrapped(|ui| {
                        let hit = ui
                            .add_enabled(
                                recorded.is_some(),
                                egui::Button::new(s.tgt_from_rec),
                            )
                            .clicked();
                        if hit
                            && let Some(t) = &recorded {
                                self.config.target_title = t.clone();
                            }
                    });
                    let shown = recorded.unwrap_or_else(|| s.anchor_none.to_string());
                    ui.label(
                        egui::RichText::new(s.anchor_of.replace("{}", &shown)).weak().small(),
                    );
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.f_by);
                        let mut bi = self.config.target_by.min(By::COUNT - 1);
                        egui::ComboBox::from_id_salt("tgt_by")
                            .selected_text(By::from_index(bi).name(s))
                            .width(160.0)
                            .show_ui(ui, |ui| {
                                for i in 0..By::COUNT {
                                    ui.selectable_value(&mut bi, i, By::from_index(i).name(s));
                                }
                            });
                        self.config.target_by = bi;
                    });
                    ui.checkbox(&mut self.config.target_pause_unfocused, s.tgt_focus);

                    ui.separator();
                    ui.label(egui::RichText::new(s.grp_anchor).strong());
                    ui.checkbox(&mut self.config.record_window_anchor, s.anchor_rec);
                    ui.checkbox(&mut self.config.record_session_info, s.rec_session);
                    ui.checkbox(&mut self.config.use_window_anchor, s.anchor_use);
                    if self.config.use_window_anchor {
                        ui.checkbox(&mut self.config.anchor_scale, s.anchor_scale);
                    }

                    ui.separator();
                    ui.label(egui::RichText::new(s.grp_speed).strong());
                    ui.checkbox(&mut self.config.frame_guard, s.fg_cb);
                    if self.config.frame_guard {
                        ui.checkbox(&mut self.config.frame_guard_auto, s.fg_auto);
                        if self.config.frame_guard_auto {
                            let m = self.state.perf_frame_us.load(Ordering::Relaxed);
                            let text = if m > 0 {
                                s.fg_measured
                                    .replace("{}", &format!("{:.1}", m as f64 / 1000.0))
                            } else {
                                s.fg_manual.to_string()
                            };
                            ui.label(egui::RichText::new(text).weak().small());
                        }
                        ui.horizontal_wrapped(|ui| {
                            ui.label(s.fg_fps);
                            ui.add(
                                egui::DragValue::new(&mut self.config.frame_guard_fps)
                                    .range(5..=240),
                            );
                        });
                        // Seeing what the guard cost is what tells you whether the FPS
                        // figure is set sensibly.
                        let added = self.state.fg_added_us.load(Ordering::Relaxed);
                        if added > 0 {
                            ui.label(
                                egui::RichText::new(s.fg_added.replace(
                                    "{}",
                                    &format!("{:.1}", added as f64 / 1_000_000.0),
                                ))
                                .weak()
                                .small(),
                            );
                        }
                    }
                    ui.checkbox(&mut self.config.perf_enabled, s.perf_cb);
                    let st = *self.state.perf_stats.lock();
                    // Under a handful of samples every percentile is the same number,
                    // which would look like a measurement without being one.
                    if !st.found || st.samples < 8 {
                        ui.label(egui::RichText::new(s.perf_none).weak());
                    } else {
                        let fps =
                            |us: u64| if us == 0 { 0.0 } else { 1_000_000.0 / us as f64 };
                        ui.label(s.perf_frametime.replace(
                            "{}",
                            &format!("{:.1}", st.avg_us as f64 / 1000.0),
                        ));
                        ui.label(
                            s.perf_avg.replace("{}", &format!("{:.0}", fps(st.avg_us))),
                        );
                        ui.label(
                            s.perf_low1.replace("{}", &format!("{:.0}", fps(st.p99_us))),
                        );
                        ui.label(
                            s.perf_low01
                                .replace("{}", &format!("{:.0}", fps(st.p999_us))),
                        );
                        ui.label(s.perf_stutter.replace("{}", &st.stutters.to_string()));
                    }
                    if self.config.perf_enabled || self.config.frame_guard {
                        ui.ctx().request_repaint_after(Duration::from_millis(400));
                    }
                });
                help_from(&mut self.help_topic, "target-window", hr);

                // ---- time limit -------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_limit)
                    .show(ui, |ui| {
                    ui.checkbox(&mut self.config.time_limit_enabled, s.time_limit_cb);
                    if self.config.time_limit_enabled {
                        ui.horizontal(|ui| {
                            ui.label(s.time_limit_h);
                            ui.add(
                                egui::DragValue::new(&mut self.config.time_limit_h).range(0..=240),
                            );
                            ui.label(s.time_limit_m);
                            ui.add(
                                egui::DragValue::new(&mut self.config.time_limit_m).range(0..=59),
                            );
                            ui.label(s.time_limit_s);
                            ui.add(
                                egui::DragValue::new(&mut self.config.time_limit_s).range(0..=59),
                            );
                        });
                    }
                    let actions = [
                        s.action_stop,
                        s.action_shutdown,
                        s.action_reboot,
                        s.action_sleep,
                        s.action_hibernate,
                        s.action_logoff,
                    ];
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.action_on_limit);
                        for (i, name) in actions.iter().enumerate() {
                            ui.selectable_value(&mut self.config.action_on_completion, i, *name);
                        }
                    });
                    if matches!(self.config.action_on_completion, 1 | 2) {
                        ui.horizontal(|ui| {
                            ui.label(s.shutdown_delay);
                            ui.add(
                                egui::DragValue::new(&mut self.config.shutdown_delay_s)
                                    .range(0..=600),
                            );
                        });
                    }
                });
                help_from(&mut self.help_topic, "limit", hr);

                // ---- pixel condition ---------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_pixel)
                    .show(ui, |ui| {
                    ui.checkbox(&mut self.config.pixel_enabled, s.pixel_cb);
                    ui.horizontal(|ui| {
                        ui.label("X");
                        ui.add(
                            egui::DragValue::new(&mut self.config.pixel_x).range(-32000..=32000),
                        );
                        ui.label("Y");
                        ui.add(
                            egui::DragValue::new(&mut self.config.pixel_y).range(-32000..=32000),
                        );
                    });
                    ui.horizontal(|ui| {
                        let mut col = [
                            self.config.pixel_r,
                            self.config.pixel_g,
                            self.config.pixel_b,
                        ];
                        if ui.color_edit_button_srgb(&mut col).changed() {
                            self.config.pixel_r = col[0];
                            self.config.pixel_g = col[1];
                            self.config.pixel_b = col[2];
                        }
                        ui.label(s.pixel_tol);
                        ui.add(
                            egui::DragValue::new(&mut self.config.pixel_tolerance).range(0..=255),
                        );
                    });
                    ui.horizontal(|ui| {
                        ui.selectable_value(&mut self.config.pixel_mode, 0, s.pixel_match);
                        ui.selectable_value(&mut self.config.pixel_mode, 1, s.pixel_differ);
                    });
                    match self.pick_deadline {
                        Some(d) => {
                            let left = d.saturating_duration_since(Instant::now()).as_secs() + 1;
                            ui.label(s.pixel_picking.replace("{}", &left.to_string()));
                        }
                        None => {
                            if ui.button(s.pixel_pick).clicked() {
                                self.pick_deadline =
                                    Some(Instant::now() + Duration::from_secs(3));
                            }
                        }
                    }
                });
                help_from(&mut self.help_topic, "pixel", hr);

                // ---- editor --------------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_editor)
                    .show(ui, |ui| {
                    let count = self.state.macro_data.lock().events.len();
                    if count == 0 {
                        ui.label(s.no_macro);
                    } else {
                        self.refresh_steps();
                        ui.horizontal_wrapped(|ui| {
                            if ui.button(s.ed_open).clicked() {
                                self.editor_open = true;
                            }
                            ui.label(
                                egui::RichText::new(
                                    s.ed_steps.replace("{}", &self.ed_steps.len().to_string()),
                                )
                                .weak(),
                            );
                        });
                    }
                });
                help_from(&mut self.help_topic, "editor", hr);

                // ---- open macros and the queue --------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_tabs)
                    .show(ui, |ui| {
                    self.tabs_ui(ui);
                });
                help_from(&mut self.help_topic, "tabs", hr);
                let hr = egui::CollapsingHeader::new(s.sec_queue)
                    .show(ui, |ui| {
                    self.queue_ui(ui);
                });
                help_from(&mut self.help_topic, "queue", hr);

                // ---- templates and the library --------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_package)
                    .show(ui, |ui| {
                    self.package_ui(ui);
                });
                help_from(&mut self.help_topic, "package", hr);
                let hr = egui::CollapsingHeader::new(s.sec_optimize)
                    .show(ui, |ui| {
                    self.optimize_ui(ui);
                });
                help_from(&mut self.help_topic, "optimize", hr);
                let hr = egui::CollapsingHeader::new(s.sec_templates)
                    .show(ui, |ui| {
                    self.templates_ui(ui);
                });
                help_from(&mut self.help_topic, "recipes", hr);
                let hr = egui::CollapsingHeader::new(s.sec_library)
                    .show(ui, |ui| {
                    self.library_ui(ui);
                });
                help_from(&mut self.help_topic, "library", hr);

                // ---- analyze the recording ------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_analyze)
                    .show(ui, |ui| {
                    self.analyze_ui(ui);
                });
                help_from(&mut self.help_topic, "analyze", hr);

                // ---- where the recording came from ----------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_recinfo)
                    .show(ui, |ui| {
                    self.recinfo_ui(ui);
                });
                help_from(&mut self.help_topic, "recinfo", hr);

                // ---- why a step did what it did -------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_why)
                    .show(ui, |ui| {
                    self.why_ui(ui);
                });
                help_from(&mut self.help_topic, "why", hr);

                // ---- what is in the templates folder --------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_res)
                    .show(ui, |ui| {
                    self.resources_ui(ui, busy);
                });
                help_from(&mut self.help_topic, "templates-folder", hr);

                // ---- macro health ---------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_health)
                    .show(ui, |ui| {
                    if ui
                        .add_enabled(!busy, egui::Button::new(s.check_now))
                        .clicked()
                    {
                        self.run_health_check();
                    }
                    let Some(rep) = self.health.as_ref() else {
                        ui.label(egui::RichText::new(s.check_never).weak());
                        return;
                    };

                    // The score first, coloured by what it means, because it is the
                    // one thing somebody glances at before starting a night run.
                    let colour = match rep.score {
                        90..=100 => egui::Color32::from_rgb(120, 210, 120),
                        60..=89 => egui::Color32::from_rgb(255, 200, 90),
                        _ => egui::Color32::from_rgb(255, 130, 110),
                    };
                    ui.label(
                        egui::RichText::new(
                            s.check_score.replace("{}", &rep.score.to_string()),
                        )
                        .color(colour)
                        .strong(),
                    );

                    if rep.findings.is_empty() {
                        ui.label(s.check_clean);
                    }

                    // What was looked at and found to be in order, before the list of
                    // what is not. A report that can only say what is wrong cannot
                    // tell "nothing is wrong" from "nothing was checked", and those
                    // are very different pieces of news at one in the morning.
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(s.check_passed).strong());
                    for (ok, n, line) in rep.checks.lines() {
                        let text = line.text(s);
                        let text = if line.counted() {
                            text.replace("{}", &n)
                        } else {
                            text.to_string()
                        };
                        let (mark, colour) = if ok {
                            ("\u{2714}", egui::Color32::from_rgb(120, 210, 120))
                        } else {
                            ("\u{2716}", egui::Color32::from_rgb(255, 130, 110))
                        };
                        ui.label(egui::RichText::new(format!("{mark} {text}")).color(colour));
                    }
                    ui.add_space(4.0);

                    let section = |ui: &mut egui::Ui,
                                   title: &str,
                                   want: health::Severity,
                                   mark: &str,
                                   colour: egui::Color32| {
                        let mut first = true;
                        for f in rep.findings.iter().filter(|f| f.rule.severity() == want) {
                            if first {
                                ui.label(egui::RichText::new(title).strong());
                                first = false;
                            }
                            // The step number is what turns a complaint into
                            // somewhere to click.
                            let where_ = match f.step {
                                Some(i) => format!("#{i} "),
                                None => String::new(),
                            };
                            let detail = if f.detail.is_empty() {
                                String::new()
                            } else {
                                format!(": {}", f.detail)
                            };
                            ui.label(
                                egui::RichText::new(format!(
                                    "{mark} {where_}{}{detail}",
                                    f.rule.text(s)
                                ))
                                .color(colour),
                            );
                        }
                    };
                    section(
                        ui,
                        s.check_errors,
                        health::Severity::Error,
                        "✖",
                        egui::Color32::from_rgb(255, 130, 110),
                    );
                    section(
                        ui,
                        s.check_warnings,
                        health::Severity::Warning,
                        "⚠",
                        egui::Color32::from_rgb(255, 200, 90),
                    );

                    // How it aims, which is the half a list of complaints cannot say.
                    let a = &rep.aiming;
                    if a.total() > 0 || a.guarded > 0 {
                        ui.separator();
                        ui.label(egui::RichText::new(s.check_aiming).strong());
                        let mut line: Vec<String> = Vec::new();
                        if a.element > 0 {
                            line.push(format!("{} × {}", a.element, s.c_element));
                        }
                        if a.image > 0 {
                            line.push(format!("{} × {}", a.image, s.c_image));
                        }
                        if a.text > 0 {
                            line.push(format!("{} × {}", a.text, s.c_text));
                        }
                        if a.fixed > 0 {
                            line.push(format!("{} × {}", a.fixed, s.a_abs_click));
                        }
                        if a.guarded > 0 {
                            line.push(format!("{} × {}", a.guarded, s.m_onmiss));
                        }
                        ui.label(egui::RichText::new(line.join("  ·  ")).weak());
                    }

                    // The capability manifest. Worked out from the steps, so it
                    // cannot be wrong about a macro somebody else wrote.
                    ui.separator();
                    ui.label(egui::RichText::new(s.check_caps).strong());
                    let c = &rep.caps;
                    #[allow(unused)]
                    let plain: [(bool, &str); 8] = [
                        (c.mouse, s.cap_mouse),
                        (c.keyboard, s.cap_keyboard),
                        (c.screen, s.cap_screen),
                        (c.ocr, s.cap_ocr),
                        (c.uia, s.cap_uia),
                        (c.clipboard, s.cap_clipboard),
                        (c.files, s.cap_files),
                        (c.windows, s.cap_windows),
                    ];
                    ui.horizontal_wrapped(|ui| {
                        for (on, name) in plain {
                            if on {
                                ui.label(egui::RichText::new(format!("✔ {name}")).weak());
                            }
                        }
                    });
                    // The three that deserve a second look get their own colour and
                    // their own line, rather than being lost in a row of ticks.
                    for (on, name) in
                        [(c.launch, s.cap_launch), (c.power, s.cap_power), (c.external, s.cap_external)]
                    {
                        if on {
                            ui.label(
                                egui::RichText::new(format!("⚠ {name}"))
                                    .color(egui::Color32::from_rgb(255, 200, 90)),
                            );
                        }
                    }
                });
                help_from(&mut self.help_topic, "health", hr);

                // ---- run history ----------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_runs)
                    .show(ui, |ui| {
                    if ui
                        .button(s.runs_open)
                        .clicked()
                    {
                        self.runs_open = true;
                    }
                    ui.checkbox(&mut self.config.failure_shots, s.shots_cb);
                });
                help_from(&mut self.help_topic, "runs", hr);

                // ---- scheduler ------------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_schedule)
                    .show(ui, |ui| {
                    ui.checkbox(&mut self.config.schedule_enabled, s.sch_enabled);
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.sch_time);
                        ui.add(egui::DragValue::new(&mut self.config.schedule_h).range(0..=23));
                        ui.label(":");
                        ui.add(egui::DragValue::new(&mut self.config.schedule_m).range(0..=59));
                    });
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.sch_days);
                        let names =
                            [s.day_mon, s.day_tue, s.day_wed, s.day_thu, s.day_fri, s.day_sat,
                             s.day_sun];
                        for (i, n) in names.iter().enumerate() {
                            let bit = 1u8 << i;
                            let on = self.config.schedule_days & bit != 0;
                            if ui.selectable_label(on, *n).clicked() {
                                if on {
                                    self.config.schedule_days &= !bit;
                                } else {
                                    self.config.schedule_days |= bit;
                                }
                            }
                        }
                    });
                    if self.config.schedule_enabled {
                        ui.label(
                            egui::RichText::new(s.sch_next.replace(
                                "{}",
                                &format!(
                                    "{:02}:{:02}",
                                    self.config.schedule_h, self.config.schedule_m
                                ),
                            ))
                            .weak(),
                        );
                    }
                });
                help_from(&mut self.help_topic, "schedule", hr);

                // ---- text expander ---------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_expander)
                    .show(ui, |ui| {
                    let triggers =
                        [s.exp_tr_inherit, s.exp_tr_delim, s.exp_tr_prefix, s.exp_tr_instant];
                    let inserts = [s.exp_in_type, s.exp_in_paste];
                    let actions =
                        [s.exp_ac_text, s.exp_ac_play, s.exp_ac_stop, s.exp_ac_run];

                    self.exp_dirty |=
                        ui.checkbox(&mut self.exp_book.enabled, s.exp_enable).changed();

                    ui.separator();
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.exp_default_trigger);
                        let mut idx = trigger_index(&self.exp_book.default_trigger).max(1);
                        egui::ComboBox::from_id_salt("exp_deftrig")
                            .selected_text(triggers[idx])
                            .show_ui(ui, |ui| {
                                // Inherit is meaningless as the global answer, so the
                                // global list starts at the one after it.
                                for (i, name) in triggers.iter().enumerate().skip(1) {
                                    if ui.selectable_label(idx == i, *name).clicked() {
                                        idx = i;
                                    }
                                }
                            });
                        let picked = trigger_from_index(idx, "");
                        if picked != self.exp_book.default_trigger {
                            self.exp_book.default_trigger = picked;
                            self.exp_dirty = true;
                        }
                    });
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.exp_delims);
                        self.exp_dirty |= ui
                            .add(
                                egui::TextEdit::singleline(&mut self.exp_book.delimiters)
                                    .desired_width(180.0),
                            )
                            .changed();
                    });
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.exp_excluded_lbl);
                        if ui
                            .add(
                                egui::TextEdit::singleline(&mut self.exp_excluded)
                                    .desired_width(180.0),
                            )
                            .changed()
                        {
                            self.exp_book.excluded_windows = self
                                .exp_excluded
                                .split(',')
                                .map(|x| x.trim().to_string())
                                .filter(|x| !x.is_empty())
                                .collect();
                            self.exp_dirty = true;
                        }
                    });

                    ui.separator();
                    ui.label(
                        egui::RichText::new(s.exp_count.replace(
                            "{}",
                            &self
                                .exp_book
                                .entries
                                .iter()
                                .filter(|e| e.enabled)
                                .count()
                                .to_string(),
                        ))
                        .weak(),
                    );

                    let mut remove: Option<usize> = None;
                    egui::ScrollArea::vertical().max_height(260.0).show(ui, |ui| {
                        for i in 0..self.exp_book.entries.len() {
                            ui.horizontal_wrapped(|ui| {
                                let e = &mut self.exp_book.entries[i];
                                self.exp_dirty |= ui.checkbox(&mut e.enabled, "").changed();
                                self.exp_dirty |= ui
                                    .add(
                                        egui::TextEdit::singleline(&mut e.abbr)
                                            .hint_text(s.exp_abbr)
                                            .desired_width(80.0),
                                    )
                                    .changed();

                                let mut ti = trigger_index(&e.trigger);
                                egui::ComboBox::from_id_salt(format!("exp_tr{i}"))
                                    .selected_text(triggers[ti])
                                    .width(110.0)
                                    .show_ui(ui, |ui| {
                                        for (k, name) in triggers.iter().enumerate() {
                                            if ui.selectable_label(ti == k, *name).clicked() {
                                                ti = k;
                                            }
                                        }
                                    });
                                let prefix = match &e.trigger {
                                    expander::Trigger::Prefix(p) => p.clone(),
                                    _ => ";;".to_string(),
                                };
                                let picked = trigger_from_index(ti, &prefix);
                                if picked != e.trigger {
                                    e.trigger = picked;
                                    self.exp_dirty = true;
                                }
                                if let expander::Trigger::Prefix(p) = &mut e.trigger {
                                    self.exp_dirty |= ui
                                        .add(
                                            egui::TextEdit::singleline(p)
                                                .hint_text(s.exp_prefix)
                                                .desired_width(44.0),
                                        )
                                        .changed();
                                }

                                let mut ai = action_index(&e.action);
                                egui::ComboBox::from_id_salt(format!("exp_ac{i}"))
                                    .selected_text(actions[ai])
                                    .width(104.0)
                                    .show_ui(ui, |ui| {
                                        for (k, name) in actions.iter().enumerate() {
                                            if ui.selectable_label(ai == k, *name).clicked() {
                                                ai = k;
                                            }
                                        }
                                    });
                                let want_act = action_from_index(ai);
                                if want_act != e.action {
                                    e.action = want_act;
                                    self.exp_dirty = true;
                                }

                                let mut ii = usize::from(e.insert == expander::Insert::Paste);
                                egui::ComboBox::from_id_salt(format!("exp_in{i}"))
                                    .selected_text(inserts[ii])
                                    .width(84.0)
                                    .show_ui(ui, |ui| {
                                        for (k, name) in inserts.iter().enumerate() {
                                            if ui.selectable_label(ii == k, *name).clicked() {
                                                ii = k;
                                            }
                                        }
                                    });
                                let want = if ii == 1 {
                                    expander::Insert::Paste
                                } else {
                                    expander::Insert::Type
                                };
                                if want != e.insert {
                                    e.insert = want;
                                    self.exp_dirty = true;
                                }

                                let cases = [s.case_exact, s.case_ignore, s.case_follow];
                                let mut ci = e.case.index();
                                egui::ComboBox::from_id_salt(format!("exp_case{i}"))
                                    .selected_text(cases[ci])
                                    .width(104.0)
                                    .show_ui(ui, |ui| {
                                        for (k, name) in cases.iter().enumerate() {
                                            if ui.selectable_label(ci == k, *name).clicked() {
                                                ci = k;
                                            }
                                        }
                                    });
                                let want_case = expander::Case::from_index(ci);
                                if want_case != e.case {
                                    e.case = want_case;
                                    self.exp_dirty = true;
                                }

                                if ui.button("🗑").clicked() {
                                    remove = Some(i);
                                }
                            });
                            self.exp_dirty |= ui
                                .add(
                                    egui::TextEdit::multiline(
                                        &mut self.exp_book.entries[i].text,
                                    )
                                    .hint_text(s.exp_text)
                                    .desired_rows(2)
                                    .desired_width(f32::INFINITY),
                                )
                                .changed();
                            ui.separator();
                        }
                    });
                    if let Some(i) = remove {
                        self.exp_book.entries.remove(i);
                        self.exp_dirty = true;
                    }

                    ui.horizontal_wrapped(|ui| {
                        if ui.button(s.exp_add).clicked() {
                            self.exp_book.entries.push(expander::Entry {
                                enabled: true,
                                abbr: String::new(),
                                text: String::new(),
                                trigger: expander::Trigger::Inherit,
                                insert: expander::Insert::Type,
                                action: expander::Action::Text,
                                case: expander::Case::Exact,
                            });
                            self.exp_dirty = true;
                        }
                        if ui.button(s.exp_reload).clicked() {
                            expander::load();
                            self.exp_book = expander::snapshot();
                            self.exp_excluded = self.exp_book.excluded_windows.join(", ");
                            self.exp_dirty = false;
                        }
                        if ui.button(s.exp_open).clicked() {
                            run_program(&paths::expansions_path().to_string_lossy(), "");
                        }
                    });

                    // Applied at the end of the frame rather than on each keystroke:
                    // an entry is edited a character at a time, and writing the file
                    // that often would be silly.
                    if self.exp_dirty {
                        expander::replace(self.exp_book.clone());
                        if let Err(e) = expander::save_current() {
                            self.status_msg = format!("expansions.json: {e}");
                        }
                        self.exp_dirty = false;
                    }
                });
                help_from(&mut self.help_topic, "expander", hr);

                // ---- text on screen --------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_ocr)
                    .show(ui, |ui| {
                    let (mut rx, mut ry, mut rw, mut rh) = self.ocr_rect;
                    region_ui(ui, s, &mut rx, &mut ry, &mut rw, &mut rh, None);
                    self.ocr_rect = (rx, ry, rw, rh);

                    ui.horizontal_wrapped(|ui| {
                        prep_picker(ui, s, "panel", &mut self.ocr_prep);
                        expect_picker(ui, s, "panel", &mut self.ocr_expect);
                    });
                    // The language the recogniser reads in, which is not always the
                    // language Windows is displayed in - and before 1.7.0 there was
                    // no way to say so.
                    ui.horizontal_wrapped(|ui| {
                        ui.label(s.ocr_lang);
                        let langs = ocr::available_languages();
                        let current = self.config.ocr_lang.clone();
                        let shown = langs
                            .iter()
                            .find(|(tag, _)| *tag == current)
                            .map(|(_, name)| name.as_str())
                            .unwrap_or(s.ocr_lang_auto);
                        egui::ComboBox::from_id_salt("ocr_lang")
                            .selected_text(shown)
                            .show_ui(ui, |ui| {
                                if ui
                                    .selectable_label(current.is_empty(), s.ocr_lang_auto)
                                    .clicked()
                                {
                                    self.config.ocr_lang.clear();
                                    ocr::set_language("");
                                }
                                for (tag, name) in langs {
                                    if ui.selectable_label(current == *tag, name).clicked() {
                                        self.config.ocr_lang = tag.clone();
                                        ocr::set_language(tag);
                                    }
                                }
                            });
                    });
                    ui.horizontal_wrapped(|ui| {
                        if ui.button(s.ocr_read).clicked() {
                            self.read_ocr_panel(s);
                        }
                        match self.ocr_pick {
                            Some((d, second)) => {
                                let left =
                                    d.saturating_duration_since(Instant::now()).as_secs() + 1;
                                let msg = if second { s.ocr_corner2 } else { s.ocr_corner1 };
                                ui.label(msg.replace("{}", &left.to_string()));
                            }
                            None => {
                                if ui.button(s.pixel_pick).clicked() {
                                    self.ocr_pick =
                                        Some((Instant::now() + Duration::from_secs(3), false));
                                }
                            }
                        }
                    });

                    if let Some((fit, used)) = self.ocr_fit {
                        // Not a confidence from the engine - a judgement about the
                        // shape of what came back. Shown so a profile can be chosen
                        // by comparing numbers rather than by squinting.
                        let names =
                            [s.p_none, s.p_ui, s.p_small, s.p_game, s.p_digits, s.p_auto];
                        let name = names[used.index().min(names.len() - 1)];
                        ui.label(
                            egui::RichText::new(
                                s.ocr_quality
                                    .replacen("{}", &format!("{fit:.2}"), 1)
                                    .replacen("{}", name, 1),
                            )
                            .weak()
                            .small(),
                        );
                    }
                    if !self.ocr_text.is_empty() {
                        egui::ScrollArea::vertical().max_height(120.0).id_salt("ocr_out").show(
                            ui,
                            |ui| {
                                ui.label(
                                    egui::RichText::new(&self.ocr_text).monospace().small(),
                                );
                            },
                        );
                    }
                });
                help_from(&mut self.help_topic, "ocr", hr);

                // ---- image search ---------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_vision)
                    .show(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        if ui.button(s.img_paste).clicked() {
                            match platform::clipboard_image() {
                                Some((w, h, rgba)) => {
                                    self.set_template(w, h, rgba, "clipboard".into());
                                    self.status_msg = format!("{w}x{h}");
                                }
                                None => self.status_msg = s.img_none.to_string(),
                            }
                        }
                        if ui.button(s.img_load).clicked()
                            && let Some(path) = rfd::FileDialog::new()
                                .add_filter("PNG", &["png"])
                                .set_directory(paths::templates_dir())
                                .pick_file()
                            {
                                self.load_template_png(&path);
                            }
                        let has = self.template.is_some();
                        if ui.add_enabled(has, egui::Button::new(s.img_save)).clicked()
                            && let (Some(tpl), Some(path)) = (
                                self.template.clone(),
                                rfd::FileDialog::new()
                                    .add_filter("PNG", &["png"])
                                    .set_directory(paths::templates_dir())
                                    .set_file_name("template.png")
                                    .save_file(),
                            ) {
                                let saved = image::RgbaImage::from_raw(
                                    tpl.w,
                                    tpl.h,
                                    tpl.rgba.clone(),
                                )
                                .ok_or_else(|| anyhow::anyhow!("bad template buffer"))
                                .and_then(|img| Ok(img.save(&path)?));
                                if saved.is_ok() {
                                    // Written now because now is the only moment the
                                    // scale it was cut at is still known.
                                    save_template_meta(
                                        &path,
                                        &TemplateMeta { dpi: platform::current_dpi() },
                                    );
                                }
                                match saved {
                                    Ok(()) => {
                                        self.status_msg =
                                            s.saved.replace("{}", &file_label(&path))
                                    }
                                    Err(e) => {
                                        self.status_msg =
                                            s.save_err.replace("{}", &e.to_string())
                                    }
                                }
                            }
                    });

                    match self.template.as_ref() {
                        Some(t) => ui.label(
                            egui::RichText::new(format!("{}  {}x{}", t.name, t.w, t.h)).weak(),
                        ),
                        None => ui.label(egui::RichText::new(s.img_none).weak()),
                    };

                    ui.add(
                        egui::Slider::new(&mut self.config.img_threshold, 0.3..=1.0)
                            .text(s.img_threshold),
                    );
                    ui.checkbox(&mut self.config.img_multiscale, s.img_multiscale);
                    ui.checkbox(&mut self.config.debug_overlay, s.img_overlay);
                    ui.checkbox(&mut self.config.fast_capture, s.fast_capture);
                    if ui.button(s.vars_open).clicked() {
                        self.vars_open = true;
                    }
                    ui.checkbox(&mut self.config.img_region_enabled, s.img_region);
                    if self.config.img_region_enabled {
                        ui.horizontal_wrapped(|ui| {
                            ui.label("X");
                            ui.add(
                                egui::DragValue::new(&mut self.config.img_rx)
                                    .range(-32000..=32000),
                            );
                            ui.label("Y");
                            ui.add(
                                egui::DragValue::new(&mut self.config.img_ry)
                                    .range(-32000..=32000),
                            );
                            ui.label("W");
                            ui.add(
                                egui::DragValue::new(&mut self.config.img_rw).range(8..=32000),
                            );
                            ui.label("H");
                            ui.add(
                                egui::DragValue::new(&mut self.config.img_rh).range(8..=32000),
                            );
                        });
                    }

                    let busy_search = SEARCHING.load(Ordering::Relaxed);
                    ui.horizontal_wrapped(|ui| {
                        let can = self.template.is_some() && !busy_search;
                        if ui.add_enabled(can, egui::Button::new(s.img_find)).clicked()
                            && let Some(tpl) = self.template.clone() {
                                spawn_search(
                                    tpl,
                                    self.search_region(),
                                    self.config.img_multiscale,
                                );
                            }
                        if busy_search {
                            ui.spinner();
                            ui.label(s.img_searching);
                        }
                    });

                    if !busy_search {
                        let hit = *LAST_HIT.lock();
                        if let Some(h) = hit {
                            let text = if h.score as f64 >= self.config.img_threshold {
                                s.img_found
                                    .replacen("{}", &format!("({}, {})", h.x, h.y), 1)
                                    .replacen("{}", &format!("{:.3}", h.score), 1)
                            } else {
                                s.img_not_found.replace("{}", &format!("{:.3}", h.score))
                            };
                            ui.label(text);
                        }
                    }

                    // Repaint while a search runs so the spinner actually spins.
                    if busy_search {
                        ui.ctx().request_repaint_after(Duration::from_millis(80));
                    }
                });
                help_from(&mut self.help_topic, "vision", hr);

                // ---- hotkeys --------------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_hotkeys)
                    .show(ui, |ui| {
                    let mut changed = false;
                    changed |=
                        hotkey_row(ui, s, s.hk_record, "hk1", 1, &mut self.config.hotkey_record);
                    changed |=
                        hotkey_row(ui, s, s.hk_play, "hk2", 2, &mut self.config.hotkey_play);
                    changed |=
                        hotkey_row(ui, s, s.hk_pause, "hk4", 4, &mut self.config.hotkey_pause);
                    changed |=
                        hotkey_row(ui, s, s.hk_stop, "hk3", 3, &mut self.config.hotkey_stop);
                    ui.separator();
                    // These three act while the macro is running.
                    changed |=
                        hotkey_row(ui, s, s.hk_faster, "hk5", 5, &mut self.config.hotkey_faster);
                    changed |=
                        hotkey_row(ui, s, s.hk_slower, "hk6", 6, &mut self.config.hotkey_slower);
                    changed |=
                        hotkey_row(ui, s, s.hk_skip, "hk7", 7, &mut self.config.hotkey_skip);
                    if changed {
                        publish_hotkeys(&self.config);
                        request_hotkey_refresh();
                    }
                    if HK_FAILED.load(Ordering::Relaxed) != 0 {
                        ui.colored_label(egui::Color32::from_rgb(255, 170, 60), s.hk_failed);
                    }
                });
                help_from(&mut self.help_topic, "hotkeys", hr);

                // ---- appearance ------------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_appearance)
                    .show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(s.theme);
                        egui::ComboBox::from_id_salt("theme")
                            .selected_text(THEME_NAMES[self.config.default_theme])
                            .show_ui(ui, |ui| {
                                for (i, name) in THEME_NAMES.iter().enumerate() {
                                    if ui
                                        .selectable_label(self.config.default_theme == i, *name)
                                        .clicked()
                                    {
                                        self.config.default_theme = i;
                                        self.theme_dirty = true;
                                    }
                                }
                            });
                    });
                    if ui.checkbox(&mut self.config.transparent_ui, s.transparent_ui).changed() {
                        self.theme_dirty = true;
                    }
                    if ui.checkbox(&mut self.config.always_on_top, s.on_top).changed() {
                        let level = if self.config.always_on_top {
                            egui::viewport::WindowLevel::AlwaysOnTop
                        } else {
                            egui::viewport::WindowLevel::Normal
                        };
                        ui.ctx()
                            .send_viewport_cmd(egui::viewport::ViewportCommand::WindowLevel(level));
                    }
                    ui.checkbox(&mut self.config.tray_enabled, s.tray_cb);
                    if self.config.tray_enabled {
                        ui.checkbox(&mut self.config.close_to_tray, s.close_tray_cb);
                    }
                    ui.horizontal(|ui| {
                        ui.label(s.language);
                        egui::ComboBox::from_id_salt("lang")
                            .selected_text(match self.config.default_lang {
                                1 => "English",
                                2 => "Русский",
                                3 => "Українська",
                                4 => "Português",
                                5 => "Español",
                                6 => "中文",
                                _ => s.lang_auto,
                            })
                            .show_ui(ui, |ui| {
                                let names = [
                                    s.lang_auto,
                                    "English",
                                    "Русский",
                                    "Українська",
                                    "Português",
                                    "Español",
                                    "中文",
                                ];
                                for (i, name) in names.iter().enumerate() {
                                    if ui
                                        .selectable_label(self.config.default_lang == i, *name)
                                        .clicked()
                                    {
                                        self.config.default_lang = i;
                                    }
                                }
                            });
                    });
                    if ui.button(s.lang_template).clicked() {
                        let idx = self.config.default_lang.saturating_sub(1);
                        match export_lang_template(idx) {
                            Ok(p) => self.status_msg = s.exported.replace("{}", &file_label(&p)),
                            Err(e) => {
                                self.status_msg = s.save_err.replace("{}", &e.to_string());
                            }
                        }
                    }
                });
                help_from(&mut self.help_topic, "appearance", hr);

                // ---- profiles ---------------------------------------------------------
                let hr = egui::CollapsingHeader::new(s.sec_profiles)
                    .show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(s.prof_name);
                        ui.add(
                            egui::TextEdit::singleline(&mut self.profile_name)
                                .desired_width(120.0),
                        );
                        if ui.button(s.prof_save).clicked() && !self.profile_name.trim().is_empty()
                        {
                            let path = profile_path(&self.profile_name);
                            match save_config_to(&path, &self.config) {
                                Ok(()) => {
                                    self.profiles = list_profiles();
                                    self.status_msg =
                                        s.saved.replace("{}", &file_label(&path));
                                }
                                Err(e) => {
                                    self.status_msg = s.save_err.replace("{}", &e.to_string())
                                }
                            }
                        }
                    });
                    let names = self.profiles.clone();
                    ui.horizontal_wrapped(|ui| {
                        for name in names {
                            if ui.small_button(&name).clicked() {
                                let path = profile_path(&name);
                                let mut cfg = load_config_from(&path);
                                cfg.recent_files = self.config.recent_files.clone();
                                self.config = cfg;
                                self.profile_name = name.clone();
                                self.theme_dirty = true;
                                publish_hotkeys(&self.config);
                                request_hotkey_refresh();
                                self.status_msg = s.loaded.replace("{}", &name);
                            }
                        }
                    });
                    if ui.button(s.prof_delete).clicked() && !self.profile_name.trim().is_empty() {
                        let _ = std::fs::remove_file(profile_path(&self.profile_name));
                        self.profiles = list_profiles();
                        self.status_msg = s.done.to_string();
                    }
                });
                help_from(&mut self.help_topic, "profiles", hr);

                // ---- files ------------------------------------------------------------
                egui::CollapsingHeader::new(s.sec_files).default_open(true).show(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        if ui.button(s.save).clicked() {
                            let path = self.default_save_path();
                            self.do_save(path);
                        }
                        if ui.button(s.save_as).clicked() {
                            let ext = if self.config.compress_on_save { "mrz" } else { "json" };
                            if let Some(path) = rfd::FileDialog::new()
                                .add_filter("Macro", &["json", "mrz"])
                                .set_directory(paths::data_dir())
                                .set_file_name(format!("macro.{ext}"))
                                .save_file()
                            {
                                self.do_save(path);
                            }
                        }
                        if ui.button(s.load).clicked() {
                            let path = self
                                .state
                                .current_path
                                .lock()
                                .clone()
                                .unwrap_or_else(paths::default_macro_path);
                            self.do_load(path);
                        }
                        if ui.button(s.open_file).clicked()
                            && let Some(path) = rfd::FileDialog::new()
                                .add_filter("Macro", &["json", "mrz", "gz"])
                                .set_directory(paths::data_dir())
                                .pick_file()
                            {
                                self.do_load(path);
                            }
                        if ui.add_enabled(!busy, egui::Button::new(s.clear)).clicked() {
                            *self.state.macro_data.lock() = MacroData::default();
                            self.state.recorded_time_us.store(0, Ordering::Relaxed);
                            *self.state.current_path.lock() = None;
                            self.ed_undo = None;
                            self.health = None;
                            self.status_msg = s.cleared.to_string();
                        }
                    });

                    ui.horizontal_wrapped(|ui| {
                        if ui.button(s.export_exe).clicked() {
                            let data = self.state.macro_data.lock().clone();
                            if data.is_empty() {
                                self.status_msg = s.no_macro.to_string();
                            } else if let Some(path) = rfd::FileDialog::new()
                                .add_filter("Executable", &["exe"])
                                .set_directory(paths::data_dir())
                                .set_file_name("macro-player.exe")
                                .save_file()
                            {
                                let payload = Payload {
                                    loops: if self.config.loop_play {
                                        0
                                    } else {
                                        self.config.play_count_limit
                                    },
                                    speed: self.config.speed,
                                    absolute_mouse: self.config.absolute_mouse,
                                    repeat_delay_ms: self.config.repeat_delay_ms,
                                    macro_data: data,
                                };
                                match export_self_running_exe(&path, &payload) {
                                    Ok(()) => {
                                        self.status_msg =
                                            s.exported.replace("{}", &file_label(&path))
                                    }
                                    Err(e) => {
                                        self.status_msg =
                                            s.save_err.replace("{}", &e.to_string())
                                    }
                                }
                            }
                        }
                        if ui.button(s.export_ahk).clicked() {
                            let data = self.state.macro_data.lock().clone();
                            if data.is_empty() {
                                self.status_msg = s.no_macro.to_string();
                            } else if let Some(path) = rfd::FileDialog::new()
                                .add_filter("AutoHotkey", &["ahk"])
                                .set_directory(paths::data_dir())
                                .set_file_name("macro.ahk")
                                .save_file()
                            {
                                let loops = if self.config.loop_play {
                                    0
                                } else {
                                    self.config.play_count_limit
                                };
                                match export_ahk(&path, &data, loops) {
                                    Ok(()) => {
                                        self.status_msg =
                                            s.exported.replace("{}", &file_label(&path))
                                    }
                                    Err(e) => {
                                        self.status_msg =
                                            s.save_err.replace("{}", &e.to_string())
                                    }
                                }
                            }
                        }
                    });

                    ui.checkbox(&mut self.config.compress_on_save, s.compress);

                    if !self.config.recent_files.is_empty() {
                        let recent = self.config.recent_files.clone();
                        ui.horizontal_wrapped(|ui| {
                            ui.label(s.recent);
                            for path in recent {
                                let name = file_label(Path::new(&path));
                                let label = if name.is_empty() { path.clone() } else { name };
                                if ui.small_button(label).on_hover_text(&path).clicked() {
                                    self.do_load(PathBuf::from(path.clone()));
                                }
                            }
                        });
                    }

                    ui.label(
                        egui::RichText::new(format!(
                            "{} {}",
                            s.data_dir,
                            paths::data_dir().display()
                        ))
                        .weak()
                        .small(),
                    );
                });

                if ui.button(s.save_settings).clicked() {
                    self.config.sanitize();
                    match save_config(&self.config) {
                        Ok(()) => self.status_msg = s.settings_saved.to_string(),
                        Err(e) => self.status_msg = s.save_err.replace("{}", &e.to_string()),
                    }
                }

                ui.separator();

                // ---- footer -------------------------------------------------------------
                let (count, dur) = {
                    let d = self.state.macro_data.lock();
                    (d.events.len(), d.duration_us)
                };
                ui.horizontal(|ui| {
                    ui.label(s.events.replace("{}", &count.to_string()));
                    if dur > 0 {
                        ui.label(s.duration.replace("{}", &format_us(dur)));
                    }
                });

                if playing {
                    let sp = *self.state.speed.lock();
                    ui.label(
                        egui::RichText::new(s.status_speed.replace("{}", &format!("{sp:.2}")))
                            .weak(),
                    );
                }

                let testing = self.state.test_run.load(Ordering::Relaxed);
                let status = if !self.status_msg.is_empty() {
                    self.status_msg.clone()
                } else if recording {
                    s.status_rec.to_string()
                } else if playing && !target_window_ready(&self.state) {
                    s.status_waiting.to_string()
                } else if self.state.held_by_desktop.load(Ordering::Relaxed) {
                    s.status_held.to_string()
                } else if paused {
                    s.status_paused.to_string()
                } else if testing {
                    // Ahead of "Playing…", because the difference between the two is
                    // the only thing on this line worth reading.
                    s.status_test.to_string()
                } else if playing {
                    s.status_play.to_string()
                } else {
                    format!(
                        "{} [{} · {} · {}]",
                        s.status_ready,
                        self.config.hotkey_record.label(),
                        self.config.hotkey_play.label(),
                        self.config.hotkey_stop.label()
                    )
                };
                ui.label(format!("ℹ {status}"));
            });
        });

        // Idempotent every frame: the engine can never drift from the UI.
        self.config.sanitize();
        apply_config_to_state(&self.config, &self.state);
        ui.ctx().request_repaint_after(Duration::from_millis(100));
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        if CAPTURE_SLOT.load(Ordering::Relaxed) != 0 {
            end_capture();
        }
        self.state.stop_play.store(true, Ordering::Relaxed);
        self.state.paused.store(false, Ordering::Relaxed);
        stop_recording(&self.state);

        // Let the playback thread release anything it was holding.
        let deadline = Instant::now() + Duration::from_millis(400);
        while self.state.playing.load(Ordering::Relaxed) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(10));
        }

        self.config.sanitize();
        if let Err(e) = save_config(&self.config) {
            warn!("could not autosave config: {e}");
        }

        #[cfg(windows)]
        {
            let tid = HOOK_THREAD_ID.load(Ordering::Relaxed);
            if tid != 0 {
                unsafe {
                    let _ = win32::PostThreadMessageW(
                        tid,
                        win32::WM_QUIT,
                        win32::WPARAM(0),
                        win32::LPARAM(0),
                    );
                }
            }
        }
        info!("application exiting gracefully");
    }
}

// ============================================================================
// Command line & headless playback
// ============================================================================

struct CliArgs {
    play: Option<PathBuf>,
    loops: Option<u64>,
    speed: Option<f64>,
    no_gui: bool,
    selftest: Option<String>,
    /// Pins the correlation kernel to one instruction set. Off by default: the
    /// executable carries all of them and picks by CPUID.
    simd: Option<String>,
    help: bool,
    version: bool,
    /// Check a macro and exit, without running a step of it.
    check: bool,
    /// Start a headless run even if the check found something fatal.
    no_check: bool,
}

fn parse_cli() -> CliArgs {
    let mut args = CliArgs {
        play: None,
        loops: None,
        speed: None,
        no_gui: false,
        selftest: None,
        simd: None,
        help: false,
        version: false,
        check: false,
        no_check: false,
    };
    let mut it = std::env::args().skip(1);
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--play" | "-p" => args.play = it.next().map(PathBuf::from),
            "--loops" | "-n" => args.loops = it.next().and_then(|v| v.parse().ok()),
            "--speed" | "-s" => args.speed = it.next().and_then(|v| v.parse().ok()),
            "--no-gui" => args.no_gui = true,
            "--check" => args.check = true,
            "--no-check" => args.no_check = true,
            "--selftest" => args.selftest = it.next(),
            "--simd" => args.simd = it.next(),
            "--help" | "-h" => args.help = true,
            "--version" | "-V" => args.version = true,
            _ => {}
        }
    }
    args
}

const HELP_TEXT: &str = "\
Macro Recorder - record and replay mouse & keyboard on Windows.

USAGE:
    macro-recorder [OPTIONS]

OPTIONS:
    -p, --play <FILE>    Load a macro (.json / .mrz) on start
    -n, --loops <N>      Repeat count (0 = infinite)
    -s, --speed <X>      Playback speed multiplier (0.05 - 10.0)
        --no-gui         Play the macro headless and exit
        --check          Check --play <FILE> and exit without running it.
                         Exit code 0 if it is fit to run, 1 if it is not,
                         2 if the file could not be read at all. Warnings
                         are printed and do not change the code.
        --no-check       Let --no-gui start even when the pre-flight check
                         found something fatal. The check still runs and is
                         still logged.
        --selftest <W>   Run a self-test and exit.
                         W: timing, vision, simd, dryrun, target, recovery,
                            script[=rounds], churn[=secs],
                            soak[=hours, fractions allowed]
        --simd <SET>     Pin the image-search kernel to one instruction set:
                         auto (default), scalar, sse2, avx, avx2, avx512.
                         All of them are in this .exe; auto picks by CPUID.
                         --selftest simd prints what each one is worth here.
    -h, --help           Show this help
    -V, --version        Show the version

Without --no-gui the options simply pre-load the GUI.
";

/// Plays a macro without any window. Shared by `--no-gui` and exported executables.
/// An evenly spaced recording of `n` events: move, press, release, repeating.
///
/// Synthetic on purpose. A real recording has uneven gaps, and uneven gaps make it
/// impossible to tell scheduler jitter from the recording's own shape.
fn synthetic_macro(n: usize, gap_us: u64) -> MacroData {
    let events: Vec<MacroEvent> = (0..n)
        .map(|i| {
            let t = i as u64 * gap_us;
            let x = 200 + (i % 300) as i32;
            let kind = match i % 3 {
                0 => InputEventKind::MouseMove { x, y: 300, dx: 1, dy: 0 },
                1 => InputEventKind::MouseButton {
                    button: MouseButton::Left,
                    down: true,
                    x,
                    y: 300,
                },
                _ => InputEventKind::MouseButton {
                    button: MouseButton::Left,
                    down: false,
                    x,
                    y: 300,
                },
            };
            MacroEvent { t_us: t, kind }
        })
        .collect();
    let dur = events.last().map(|e| e.t_us).unwrap_or(0);
    MacroData::new(events, dur)
}

/// A recording shaped like a person: a stream of small moves with one click every
/// 350 ms, rather than sixty-six clicks a second.
///
/// The evenly spaced macro above is deliberately pathological, and it makes the frame
/// guard look ruinous - a press every 15 ms cannot be stretched to two frames without
/// dominating the run. Real recordings leave far more room than the guard ever asks
/// for, and this one exists to show by how much.
fn human_paced_macro(cycles: usize) -> MacroData {
    let mut events = Vec::new();
    let mut t = 0u64;
    for c in 0..cycles {
        for i in 0..50i32 {
            let x = 300 + (c % 200) as i32 + i;
            events.push(MacroEvent {
                t_us: t,
                kind: InputEventKind::MouseMove { x, y: 400, dx: 1, dy: 0 },
            });
            t += 5_000;
        }
        let x = 300 + (c % 200) as i32;
        events.push(MacroEvent {
            t_us: t,
            kind: InputEventKind::MouseButton { button: MouseButton::Left, down: true, x, y: 400 },
        });
        // A 60 ms press and a 40 ms gap before the next stream of moves.
        t += 60_000;
        events.push(MacroEvent {
            t_us: t,
            kind: InputEventKind::MouseButton { button: MouseButton::Left, down: false, x, y: 400 },
        });
        t += 40_000;
    }
    let dur = events.last().map(|e| e.t_us).unwrap_or(0);
    MacroData::new(events, dur)
}

struct TimingReport {
    label: String,
    dispatched: usize,
    mean_us: f64,
    p50_us: u64,
    p99_us: u64,
    max_us: u64,
    drift_us: i64,
    slips: u64,
    slipped_ms: u64,
    longest_burst: usize,
    guard_added_ms: u64,
    wall_ms: u128,
}

/// Runs one scenario through the real `playback_loop` with the OS calls suppressed.
fn timing_scenario(
    label: &str,
    data: &MacroData,
    speed: f64,
    guard_fps: Option<u64>,
    human: bool,
    stall_at: usize,
    stall_us: u64,
) -> TimingReport {
    let (tx, _rx) = unbounded();
    let state = AppState::new(tx);
    state.loop_play.store(false, Ordering::Relaxed);
    state.play_count_limit.store(1, Ordering::Relaxed);
    state.absolute_mouse.store(true, Ordering::Relaxed);
    state.human_mouse.store(human, Ordering::Relaxed);
    *state.speed.lock() = speed;
    match guard_fps {
        Some(fps) => {
            state.frame_guard.store(true, Ordering::Relaxed);
            state.frame_guard_auto.store(false, Ordering::Relaxed);
            state.frame_guard_fps.store(fps, Ordering::Relaxed);
        }
        None => state.frame_guard.store(false, Ordering::Relaxed),
    }
    state.playing.store(true, Ordering::Relaxed);
    let generation = state.play_generation.fetch_add(1, Ordering::SeqCst) + 1;

    selftest::arm(data.events.len(), stall_at, stall_us);
    let started = Instant::now();
    playback_loop(state.clone(), data.clone(), generation);
    let wall_ms = started.elapsed().as_millis();
    let (trace, slips, slipped_us) = selftest::disarm();

    // Lateness against the schedule the scheduler was actually working to, so a
    // deliberate slip or a guard hold is not counted twice: those move the schedule.
    let mut late: Vec<u64> =
        trace.iter().map(|(due, act)| act.saturating_sub(*due)).collect();
    let drift_us = trace
        .last()
        .map(|(due, act)| *act as i64 - *due as i64)
        .unwrap_or(0);

    // The point of the whole exercise: after a stall, does the backlog go out as a
    // burst? A healthy run has gaps near the recorded spacing; a catch-up storm has
    // a long run of dispatches microseconds apart.
    let mut longest_burst = 0usize;
    let mut current = 0usize;
    for w in trace.windows(2) {
        if w[1].1.saturating_sub(w[0].1) < 500 {
            current += 1;
            longest_burst = longest_burst.max(current);
        } else {
            current = 0;
        }
    }

    let n = late.len().max(1) as f64;
    let mean_us = late.iter().sum::<u64>() as f64 / n;
    late.sort_unstable();
    let at = |q: f64| -> u64 {
        if late.is_empty() {
            0
        } else {
            late[(((late.len() - 1) as f64) * q).round() as usize]
        }
    };

    TimingReport {
        label: label.to_string(),
        dispatched: trace.len(),
        mean_us,
        p50_us: at(0.5),
        p99_us: at(0.99),
        max_us: late.last().copied().unwrap_or(0),
        drift_us,
        slips,
        slipped_ms: slipped_us / 1000,
        longest_burst,
        guard_added_ms: state.fg_added_us.load(Ordering::Relaxed) / 1000,
        wall_ms,
    }
}

/// Median of `n` runs. Screen capture varies enough that one sample is a rumour.
fn median_ms(n: usize, mut f: impl FnMut()) -> f64 {
    let mut v: Vec<u128> = (0..n)
        .map(|_| {
            let t = Instant::now();
            f();
            t.elapsed().as_micros()
        })
        .collect();
    v.sort_unstable();
    v[v.len() / 2] as f64 / 1000.0
}

/// The top-left `w` x `h` of a frame, so search cost can be measured against
/// different haystack sizes without re-capturing and inheriting capture's noise.
fn crop_frame(hay: &vision::Frame, w: u32, h: u32) -> vision::Frame {
    let (w, h) = (w.min(hay.w), h.min(hay.h));
    let mut px = Vec::with_capacity((w * h * 4) as usize);
    for row in 0..h {
        let src = (row * hay.w * 4) as usize;
        px.extend_from_slice(&hay.px[src..src + (w * 4) as usize]);
    }
    vision::Frame { x: hay.x, y: hay.y, w, h, px, order: hay.order }
}

/// A square cut out of whatever is on screen, which will therefore match.
fn crop_template(hay: &vision::Frame, at: u32, size: u32, name: &str) -> vision::Template {
    let size = size.min(hay.w.saturating_sub(at)).min(hay.h.saturating_sub(at)).max(2);
    let mut px = Vec::with_capacity((size * size * 4) as usize);
    for row in 0..size {
        let src = (((at + row) * hay.w + at) * 4) as usize;
        px.extend_from_slice(&hay.px[src..src + (size * 4) as usize]);
    }
    // A template is always red-first and always opaque; the mask reads the alpha
    // byte and a screen grab does not have one worth reading.
    vision::Frame { x: 0, y: 0, w: size, h: size, px, order: hay.order }.as_template(name)
}

/// Random pixels, which will not match anything on screen.
fn noise_template(size: u32, name: &str) -> vision::Template {
    let mut rng = Rng::new();
    let mut rgba = vec![255u8; (size * size * 4) as usize];
    for px in rgba.as_chunks_mut::<4>().0 {
        px[0] = rng.below(256) as u8;
        px[1] = rng.below(256) as u8;
        px[2] = rng.below(256) as u8;
    }
    vision::Template { w: size, h: size, rgba, name: name.to_string() }
}

/// Applies `--simd`, and says what it actually got.
///
/// A pin the processor cannot honour is not an error. The executable carries every
/// kernel, so the honest thing is to run the fastest one this machine can and say
/// which that was - silently running something other than what was asked for is how
/// a benchmark ends up measuring the wrong thing.
fn apply_simd_flag(want: &str) {
    let want = want.trim();
    if want.eq_ignore_ascii_case("auto") {
        vision::force_isa(None);
        info!("image-search kernel: auto");
        return;
    }
    match vision::Isa::parse(want) {
        Some(isa) => {
            vision::force_isa(Some(isa));
            let got = vision::active();
            if got == isa {
                println!("image-search kernel pinned to {}", got.name());
            } else {
                println!(
                    "--simd {want}: this processor has no {} - running {} instead",
                    isa.name(),
                    got.name()
                );
            }
            info!("image-search kernel: asked for {}, running {}", isa.name(), got.name());
        }
        None => println!(
            "--simd {want}: not a kernel name. Try auto, scalar, sse2, avx, avx2 or \
             avx512 - leaving the choice to the processor."
        ),
    }
}

/// A haystack that is the same on every machine and every run.
///
/// Detail at three sizes, not one. The first version of this was per-pixel hash
/// noise, which looks maximally distinctive and is exactly the wrong thing: the
/// search runs a coarse pass over a shrunken copy first, shrinking averages
/// per-pixel noise away to a flat grey, and the coarse pass then picked a region at
/// random. Every kernel agreed on the same wrong region, which is a true answer to a
/// question nobody asked. Blocks, texture and grain instead - which is also what a
/// real screen has.
fn simd_bench_frame(w: u32, h: u32) -> vision::Frame {
    /// A cheap, well-mixed hash. Deterministic on purpose: a kernel that disagrees
    /// should disagree the same way twice.
    fn hash(a: usize, b: usize) -> usize {
        let mut v = a.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ b.wrapping_mul(0xC2B2_AE3D_27D4_EB4F);
        v ^= v >> 29;
        v = v.wrapping_mul(0xBF58_476D_1CE4_E5B9);
        v ^ (v >> 32)
    }
    let mut px = vec![255u8; (w as usize) * (h as usize) * 4];
    for y in 0..h as usize {
        for x in 0..w as usize {
            // 8-pixel blocks survive the shrink and are what the coarse pass steers
            // by; 2-pixel texture and per-pixel grain are what the fine pass pins
            // the position down with.
            let block = (hash(x / 8, y / 8) & 0xff) as i32;
            let texture = ((hash(x / 2, y / 2) & 0x3f) as i32) - 32;
            let grain = ((hash(x, y) & 0x0f) as i32) - 8;
            let v = (block * 3 / 4 + texture + grain).clamp(0, 255) as u8;
            let o = (y * w as usize + x) * 4;
            px[o] = v;
            px[o + 1] = v.rotate_left(3);
            px[o + 2] = 255 - v;
        }
    }
    vision::Frame { x: 0, y: 0, w, h, px, order: vision::Order::Rgba }
}

/// Every correlation kernel in this executable, on the processor in front of you.
///
/// This is the answer to "can one .exe hold x86-64, x86-64-v2/v3/v4 and
/// znver1..znver5 at once and pick at run time" - it can, for the code where the
/// flag would have made a difference, and this prints what each one is actually
/// worth here rather than asking anyone to believe a table of speed-ups.
///
/// Two questions, in this order: do they all give the same answer, and which is
/// fastest. The first is the one that can lose a macro - a kernel that is quick and
/// wrong finds buttons in the wrong place.
fn run_simd_selftest() -> Result<()> {
    println!("Self-test: image-search kernels\n");
    println!(
        "One executable, every instruction set. `-C target-cpu` chooses one at build\n\
         time; this chooses at start-up, from CPUID. The one thing a target-cpu flag\n\
         also changes and no run-time choice can is the scheduling model - that stays\n\
         with whatever this .exe was built for."
    );

    // The pin, if there was one, and the choice the processor would have made on its
    // own - which is what this test is here to show.
    let pinned = vision::active();
    vision::force_isa(None);
    let auto = vision::active();
    if pinned != auto {
        println!("\n--simd pinned this run to {}; automatic choice is {}", pinned.name(), auto.name());
    }

    println!("\nKernels compiled into this .exe");
    println!(
        "{:<9} {:>7}  {:<36} {:>8} {:>9}",
        "kernel", "floats", "equivalent -C target-cpu", "here?", "chosen"
    );
    for (isa, ok) in vision::isa_report() {
        println!(
            "{:<9} {:>7}  {:<36} {:>8} {:>9}",
            isa.name(),
            isa.width(),
            isa.target_cpus(),
            if ok { "yes" } else { "no" },
            if isa == auto { "<--" } else { "" }
        );
    }
    if vision::Isa::Avx512.supported() {
        println!(
            "\nThis processor has AVX-512, which is the one step where wider is not\n\
             automatically faster: on Zen 4 the 512-bit operations go through 256-bit\n\
             units, and on several Intel parts they pull the core's clock down. The\n\
             two kernels are raced once at start-up and the wide one has to win by\n\
             five per cent to be taken. It {}.",
            if auto == vision::Isa::Avx512 { "did" } else { "did not" }
        );
    }

    // ---- the same search, run by each of them -------------------------------
    // One thread on purpose. The kernel is what is under test, and a parallel sweep
    // measures the scheduler as much as the arithmetic.
    vision::set_max_threads(1);
    let hay = simd_bench_frame(1280, 720);
    println!(
        "\nSame search over 1280x720, one thread, median of 5. Sizes 63 and 100 are\n\
         there because they are not a whole number of vectors: they run the tail of\n\
         every kernel, which is where a wide one gets its lead handed back."
    );
    let mut wrong_spot = 0usize;
    let mut disagreed = 0usize;
    let mut worst_score_gap = 0.0f32;
    for size in [32u32, 63, 100, 128] {
        let at = 200u32;
        let tpl = crop_template(&hay, at, size, "kernel");
        let want = (at + size / 2) as i32;
        println!("\nTemplate {size}x{size}, planted at ({want}, {want})");
        println!(
            "{:<9} {:>9} {:>11} {:>14} {:>8} {:>9}",
            "kernel", "ms", "vs scalar", "found at", "score", "agrees"
        );
        let mut base_ms = 0.0f64;
        let mut base: Option<vision::Hit> = None;
        for (isa, ok) in vision::isa_report().into_iter().rev() {
            if !ok {
                continue;
            }
            vision::force_isa(Some(isa));
            let ms = median_ms(5, || {
                let _ = vision::find(&hay, &tpl, false);
            });
            let hit = vision::find(&hay, &tpl, false);
            let (found, score) = match &hit {
                Some(h) => (format!("({}, {})", h.x, h.y), h.score),
                None => ("none".to_string(), 0.0),
            };
            let agrees = match (&base, &hit) {
                // The reference row. It also has to have found the planted
                // template, or every "same" below it is agreement about nonsense.
                (None, Some(h)) => {
                    base_ms = ms;
                    base = hit;
                    if h.x != want || h.y != want {
                        wrong_spot += 1;
                        "PLANTED ELSEWHERE"
                    } else {
                        "reference"
                    }
                }
                (None, None) => {
                    base_ms = ms;
                    wrong_spot += 1;
                    "NOT FOUND"
                }
                (Some(b), Some(h)) => {
                    // Float addition is not associative, so a wider kernel folds the
                    // same numbers in a different order and lands a few ULPs away.
                    // The position has to be identical; the score only has to be
                    // recognisably the same number.
                    let gap = (b.score - h.score).abs();
                    worst_score_gap = worst_score_gap.max(gap);
                    if b.x == h.x && b.y == h.y && gap <= 1e-3 {
                        "same"
                    } else {
                        disagreed += 1;
                        "DIFFERENT"
                    }
                }
                (Some(_), None) => {
                    disagreed += 1;
                    "LOST IT"
                }
            };
            println!(
                "{:<9} {:>9.1} {:>10.2}x {:>14} {:>8.3} {:>9}",
                isa.name(),
                ms,
                if ms > 0.0 { base_ms / ms } else { 0.0 },
                found,
                score,
                agrees
            );
        }
    }

    vision::set_max_threads(0);
    vision::force_isa(if pinned == auto { None } else { Some(pinned) });

    println!(
        "\nWorst score gap between kernels: {worst_score_gap:.6} (a few ULPs is the\n\
         float addition being folded in a different order, not a different answer)."
    );
    if wrong_spot == 0 && disagreed == 0 {
        println!(
            "PASS - every kernel this processor can run found the planted template in\n\
             the same place. Running {} from here on.",
            vision::active().name()
        );
        Ok(())
    } else {
        println!("FAIL - {wrong_spot} bad reference run(s), {disagreed} disagreement(s)");
        anyhow::bail!("the vector kernels do not agree with the scalar one")
    }
}

fn run_vision_selftest() -> Result<()> {
    // UI Automation is COM, and COM has to be started on the thread that uses it.
    // The playback thread does this for itself; this one has to be told.
    virtual_desktop::init_thread();
    let (vx, vy, vw, vh) = platform::virtual_screen_rect();
    let mpx = |w: u32, h: u32| (w as f64 * h as f64) / 1_000_000.0;
    println!("Self-test: vision and OCR");
    println!(
        "Virtual screen: {vw}x{vh} at ({vx},{vy}), {:.2} megapixels\n",
        mpx(vw as u32, vh as u32)
    );

    // ---- capture -----------------------------------------------------------
    println!("Screen capture");
    println!("{:<14} {:>9} {:>9} {:>8} {:>10}", "region", "Mpx", "ms", "MB", "ms/Mpx");
    let sizes: Vec<(i32, i32)> = [(320, 240), (640, 480), (1280, 720), (1920, 1080), (vw, vh)]
        .into_iter()
        .filter(|(w, h)| *w <= vw && *h <= vh)
        .collect();
    for (w, h) in &sizes {
        let (w, h) = (*w, *h);
        let ms = median_ms(7, || {
            let _ = platform::capture(vx, vy, w, h);
        });
        let m = mpx(w as u32, h as u32);
        println!(
            "{:<14} {:>9.2} {:>9.1} {:>8.1} {:>10.1}",
            format!("{w}x{h}"),
            m,
            ms,
            (w as f64 * h as f64 * 4.0) / 1_048_576.0,
            if m > 0.0 { ms / m } else { 0.0 }
        );
    }

    // ---- where a capture's time actually goes -------------------------------
    // The claim under test: the GDI object churn and the second copy were the
    // expensive parts. They were not. `BitBlt` from the desktop DC is a readback
    // out of whatever the compositor is holding the screen in, and it is the floor
    // - the DC and the copy out are rounding error beside it. Printed rather than
    // asserted, because the split is a property of the machine's graphics stack.
    println!("\nWhere a capture goes");
    println!(
        "{:<14} {:>9} {:>9} {:>9} {:>9} {:>9} {:>9}",
        "region", "GetDC", "+BitBlt", "+copy", "old DDB", "mem->mem", "blt %"
    );
    for (w, h) in &sizes {
        let (w, h) = (*w, *h);
        let dc_ms = median_ms(9, || {
            let _ = platform::probe_screen_dc();
        });
        let blt_ms = median_ms(9, || {
            let _ = platform::probe_blt(vx, vy, w, h);
        });
        let all_ms = median_ms(9, || {
            let _ = platform::capture(vx, vy, w, h);
        });
        let ddb_ms = median_ms(9, || {
            let _ = platform::probe_blt_ddb(vx, vy, w, h);
        });
        let mem_ms = median_ms(9, || {
            let _ = platform::probe_blt_mem(w, h);
        });
        println!(
            "{:<14} {:>9.2} {:>9.2} {:>9.2} {:>9.2} {:>9.2} {:>8.0}%",
            format!("{w}x{h}"),
            dc_ms,
            blt_ms,
            all_ms,
            ddb_ms,
            mem_ms,
            if all_ms > 0.0 { 100.0 * blt_ms / all_ms } else { 0.0 }
        );
    }

    // ---- the fast path against the old one ----------------------------------
    // Two questions, in this order: does it give the same pixels, and is it
    // actually faster. The first is the one that can lose a macro - a capture that
    // is quick and wrong finds buttons in the wrong place.
    //
    // "The same pixels" cannot be tested by comparing two captures for equality,
    // and the first version of this table tried. A screen with anything live on it
    // - a game, a video, a blinking caret - differs from itself between any two
    // looks, and the table dutifully reported that 97 % of the frame had changed.
    // It had. So the comparison is against the screen's own rate of change: take
    // two captures the old way, then one of each, and ask whether the two methods
    // disagree more than the old method disagrees with itself over the same
    // interval. If they do not, the difference is the screen moving, not the code.
    //
    // The swap column is the one that would catch a channel order mistake, and it
    // is read backwards on purpose: swapping red and blue has to make the match
    // *worse*. If it ever makes it better, the fast path is handing back BGRA
    // labelled RGBA and every template in the program is being matched against its
    // own mirror.
    /// Compares a fast capture against the old one, only where the screen was
    /// demonstrably holding still.
    ///
    /// Returns (still pixels, of those how many the two methods disagree about,
    /// how many they would disagree about with red and blue swapped).
    ///
    /// This is the shape the test had to take, and it took two goes to get there.
    /// Comparing two captures outright fails on any screen with something live on
    /// it: the first version reported 97 % of the frame changed, and it had - there
    /// was a game running. Sampling only the pixels two consecutive captures agreed
    /// about was better but still not enough, because a pixel in a continuously
    /// re-rendered scene lands on the same value twice often enough to matter.
    /// Three consecutive captures, all three agreeing, is the bar: a pixel that
    /// held still across two whole intervals was not being drawn, and a pixel that
    /// was not being drawn has to read the same whichever interface fetched it.
    fn agreement(
        a: &[&vision::Frame],
        b: &vision::Frame,
    ) -> (u64, u64, u64) {
        let Some(first) = a.first() else { return (0, u64::MAX, 0) };
        if a.iter().any(|f| f.px.len() != b.px.len()) || first.px.is_empty() {
            return (0, u64::MAX, 0);
        }
        let (mut still, mut bad, mut bad_swapped) = (0u64, 0u64, 0u64);
        let n = b.px.len() / 4;
        for i in 0..n {
            let o = i * 4;
            let q = &first.px[o..o + 3];
            if a.iter().skip(1).any(|f| f.px[o..o + 3] != *q) {
                continue; // that pixel was being drawn; it proves nothing
            }
            still += 1;
            let r = &b.px[o..o + 3];
            if q != r {
                bad += 1;
            }
            if !(q[0] == r[2] && q[1] == r[1] && q[2] == r[0]) {
                bad_swapped += 1;
            }
        }
        (still, bad, bad_swapped)
    }

    println!("\nDesktop Duplication against GDI");
    println!(
        "{:<12} {:>8} {:>8} {:>7} {:>9} {:>9} {:>9} {:>7}",
        "region", "GDI ms", "fast ms", "faster", "still px", "disagree", "if swapped", "quiet?"
    );
    let mut any_fast = false;
    for (w, h) in &sizes {
        let (w, h) = (*w, *h);
        platform::set_fast_capture(false);
        let gdi_ms = median_ms(9, || {
            let _ = platform::capture(vx, vy, w, h);
        });
        // Three the old way back to back, so a pixel that held still across both
        // intervals can be told from one that merely repeated a value once.
        let a1 = platform::capture(vx, vy, w, h);
        let a2 = platform::capture(vx, vy, w, h);
        let a3 = platform::capture(vx, vy, w, h);
        platform::reset_capture_counters();
        platform::set_fast_capture(true);
        let fast_ms = median_ms(9, || {
            let _ = platform::capture(vx, vy, w, h);
        });
        let b = platform::capture(vx, vy, w, h);
        let (hits, reused, misses) = platform::capture_counters();
        let used_fast = misses == 0 && (hits + reused) > 0;
        any_fast |= used_fast;

        let (still, bad, bad_swapped) = match (&a1, &a2, &a3, &b) {
            (Some(a1), Some(a2), Some(a3), Some(b)) => agreement(&[a1, a2, a3], b),
            _ => (0, u64::MAX, 0),
        };
        let total = (w as u64) * (h as u64);
        // A pixel that was not being drawn has to read the same either way. One in
        // a hundred is left for a screen that started drawing it again between the
        // third capture and the fourth; a channel order or a row pitch mistake is
        // not one in a hundred, it is most of the frame - which is what the swap
        // column is there to show by contrast.
        let enough = still >= 2_000;
        let rate = if still == 0 { 1.0 } else { bad as f64 / still as f64 };
        let swap_rate = if still == 0 { 0.0 } else { bad_swapped as f64 / still as f64 };
        let agrees = enough && bad != u64::MAX && rate <= 0.01 && bad_swapped >= bad;
        println!(
            "{:<12} {:>8.2} {:>8.2} {:>6.1}x {:>8.0}% {:>8.2}% {:>9.1}% {:>7}",
            format!("{w}x{h}"),
            gdi_ms,
            fast_ms,
            if fast_ms > 0.0 { gdi_ms / fast_ms } else { 0.0 },
            100.0 * still as f64 / total as f64,
            rate * 100.0,
            swap_rate * 100.0,
            if !used_fast {
                "n/a"
            } else if !enough {
                "busy"
            } else if agrees {
                "yes"
            } else {
                "busy"
            }
        );
    }
    if !any_fast {
        println!(
            "  Duplication is not available here, so every row above is GDI twice \n\
             \x20 and `agrees` reads n/a. That is the fallback working as intended."
        );
    }

    // ---- the check that does not care what the screen is doing --------------
    // Counting pixels is only decisive on a screen that is holding still, and the
    // machine this was written on had a game running on it, so it never was. This
    // asks the question the program actually cares about instead: cut a template
    // out of a frame the old way and look for it in a frame taken the new way.
    //
    // Every mistake the fast path could make shows up here, and each one shows up
    // differently. Red and blue swapped: the correlation collapses, because the
    // greys it is built from are computed from the wrong channels. A row pitch
    // ignored: the picture shears and the hit lands somewhere else, or nowhere.
    // Coordinates taken from the wrong monitor: the hit is in the wrong place by a
    // screen's width. A frame served stale: the score drops but the position is
    // exactly right, which is the one answer that is not a fault.
    {
        platform::set_fast_capture(false);
        let old = platform::capture(vx, vy, vw.min(1280), vh.min(720));
        platform::set_fast_capture(true);
        let new = platform::capture(vx, vy, vw.min(1280), vh.min(720));
        match (old, new) {
            (Some(old), Some(new)) => {
                // The busiest 96-pixel square in the frame: a flat one correlates
                // with everything and would prove nothing.
                let side = 96u32;
                let mut best = (0u32, 0u32, -1.0f64);
                let step = 64u32;
                let mut y = 0;
                while y + side < old.h {
                    let mut x = 0;
                    while x + side < old.w {
                        let (mut sum, mut sq) = (0.0f64, 0.0f64);
                        for r in (0..side).step_by(8) {
                            for c in (0..side).step_by(8) {
                                let i = (((y + r) * old.w + x + c) * 4) as usize;
                                let v = old.px[i + 1] as f64;
                                sum += v;
                                sq += v * v;
                            }
                        }
                        let n = ((side / 8) * (side / 8)) as f64;
                        let var = sq / n - (sum / n) * (sum / n);
                        if var > best.2 {
                            best = (x, y, var);
                        }
                        x += step;
                    }
                    y += step;
                }
                let (tx, ty, _) = best;
                let mut px = Vec::with_capacity((side * side * 4) as usize);
                for r in 0..side {
                    let o = (((ty + r) * old.w + tx) * 4) as usize;
                    px.extend_from_slice(&old.px[o..o + (side * 4) as usize]);
                }
                let tpl =
                    vision::Frame { x: 0, y: 0, w: side, h: side, px, order: old.order }
                        .as_template("cross-check");
                // The same square, cut out of the duplicated frame where the template
                // came from. If those pixels match the template, the two paths agree
                // about where things are - whatever the search then decided.
                //
                // This exists because the search's answer alone is not evidence. The
                // fixture picks the most contrasty square it can find, and contrast is
                // not the same as uniqueness: a square of horizontal interface banding
                // has plenty of variance and still matches equally well a few pixels to
                // the left. That is what happened - this check reported "WRONG PLACE,
                // off by 4 px" on a machine where an independent test showed the two
                // paths agreeing exactly. A test that cries wolf about the capture path
                // is worse than no test, because the next person spends a day on it.
                let same_pixels = {
                    let want = tpl.rgba.len();
                    let mut cut = Vec::with_capacity(want);
                    for r in 0..side {
                        let o = (((ty + r) * new.w + tx) * 4) as usize;
                        if o + (side * 4) as usize <= new.px.len() {
                            cut.extend_from_slice(&new.px[o..o + (side * 4) as usize]);
                        }
                    }
                    let cut = vision::Frame {
                        x: 0,
                        y: 0,
                        w: side,
                        h: (cut.len() / (side as usize * 4)) as u32,
                        px: cut,
                        order: new.order,
                    }
                    .to_rgba();
                    // A handful of bytes may differ where the cursor sat; a layout
                    // mistake is not a handful, it is most of the square.
                    let n = cut.len().min(want);
                    let off = (0..n)
                        .filter(|i| i % 4 != 3)
                        .filter(|i| cut[*i].abs_diff(tpl.rgba[*i]) > 8)
                        .count();
                    n > 0 && (off as f64) / (n as f64) < 0.01
                };
                match vision::find(&new, &tpl, false) {
                    Some(hit) => {
                        let want_x = new.x + tx as i32 + side as i32 / 2;
                        let want_y = new.y + ty as i32 + side as i32 / 2;
                        let err = (hit.x - want_x).abs().max((hit.y - want_y).abs());
                        println!(
                            "\nA {side}x{side} template cut from a GDI frame, looked for in a \n\
                             duplicated one: found at {},{} - wanted {want_x},{want_y} - \
                             off by {err} px, score {:.3}\n  \
                             {}",
                            hit.x,
                            hit.y,
                            hit.score,
                            if err <= 1 {
                                "Same place. Channel order, row pitch and monitor origin \
                                 are all right."
                            } else if same_pixels {
                                "Same pixels at the place it was cut from, so the two \
                                 capture paths agree; this square simply appears in more \
                                 than one place and the search picked another. A property \
                                 of what was on screen, not a fault."
                            } else {
                                "WRONG PLACE - the duplicated frame is not laid out the \
                                 way the old one is."
                            }
                        );
                    }
                    None => println!("\nThe cross-check template was not found at all."),
                }
            }
            _ => println!("\nThe cross-check needs both capture paths and did not get them."),
        }
    }

    // ---- a frame nobody changed has to come back unchanged ------------------
    // The reuse path is the one that makes a polling loop nearly free, and it is
    // also the one that could quietly serve a stale screen. Two looks at a settled
    // rectangle with no new frame between them must be identical to the byte; if
    // the compositor did send a frame, the check has nothing to say and says so.
    {
        platform::set_fast_capture(true);
        let (w, h) = (320.min(vw), 240.min(vh));
        platform::reset_capture_counters();
        let f1 = platform::capture(vx, vy, w, h);
        let f2 = platform::capture(vx, vy, w, h);
        let (hits, reused, _) = platform::capture_counters();
        let verdict = match (&f1, &f2) {
            _ if hits > 1 => "the screen moved - nothing to conclude".to_string(),
            (Some(a), Some(b)) if a.px == b.px => {
                format!("identical, {reused} of {} looks reused a frame", hits + reused)
            }
            (Some(_), Some(_)) => "DIFFERENT with no new frame - the reuse path is wrong"
                .to_string(),
            _ => "a capture failed".to_string(),
        };
        println!("\nTwo looks at an unchanged rectangle: {verdict}");
    }
    platform::reset_capture_counters();

    // ---- the same rectangle, over and over ----------------------------------
    // What a polling loop does. The cached bitmap is what this row is for: before
    // it, every one of these built and destroyed a DC and a bitmap.
    {
        let (w, h) = (400.min(vw), 300.min(vh));
        let n = 200;
        let t0 = std::time::Instant::now();
        let mut ok = 0usize;
        for _ in 0..n {
            if platform::capture(vx, vy, w, h).is_some() {
                ok += 1;
            }
        }
        let per = t0.elapsed().as_secs_f64() * 1000.0 / n as f64;
        let (hits, reused, misses) = platform::capture_counters();
        println!(
            "\n{n} captures of the same {w}x{h} rectangle back to back: \
             {per:.2} ms each, {ok}/{n} succeeded"
        );
        // The interesting column is `unchanged`. A script waiting for something to
        // appear looks at a screen that is not moving, and a frame the compositor
        // never sent is a frame nobody had to read back.
        println!(
            "  new frames {hits}, unchanged {reused}, fell back to GDI {misses}"
        );
    }

    let Some(hay) = platform::capture(vx, vy, vw, vh) else {
        println!("\nCould not capture the screen - the rest of this test needs it.");
        return Ok(());
    };

    // ---- search, by template size -------------------------------------------
    // `find` has no early exit: it sweeps every candidate and returns the best one.
    // So a miss should cost what a hit costs, and if it does not, that is worth
    // knowing - it would mean a script's poll rate depends on what is on screen.
    println!("\nTemplate search, single scale, whole screen as haystack");
    println!(
        "{:<16} {:>9} {:>10} {:>9} {:>8} {:>10}",
        "template", "hit ms", "miss ms", "score", "err px", "vs 1 thread"
    );
    for size in [32u32, 64, 128, 256] {
        if size + 8 >= hay.w.min(hay.h) {
            continue;
        }
        let hit_tpl = crop_template(&hay, size, size, "hit");
        let miss_tpl = noise_template(size, "miss");
        let hit_ms = median_ms(5, || {
            let _ = vision::find(&hay, &hit_tpl, false);
        });
        let miss_ms = median_ms(5, || {
            let _ = vision::find(&hay, &miss_tpl, false);
        });
        // Speed means nothing if the answer moved: the template was cut from a known
        // spot, so the hit has to come back pointing at it.
        let found = vision::find(&hay, &hit_tpl, false);
        let want_x = hay.x + (size + size / 2) as i32;
        let want_y = hay.y + (size + size / 2) as i32;
        let (score, err) = match found {
            Some(h) => (h.score, (h.x - want_x).abs().max((h.y - want_y).abs())),
            None => (0.0, -1),
        };
        // The same search with the threads taken away. A different answer here is a
        // regression; the same answer means a template that matches in many places.
        vision::set_max_threads(1);
        let serial = vision::find(&hay, &hit_tpl, false);
        vision::set_max_threads(0);
        let agree = match (&found, &serial) {
            (Some(a), Some(b)) => {
                if a.x == b.x && a.y == b.y { "same" } else { "DIFFERENT" }
            }
            (None, None) => "same",
            _ => "DIFFERENT",
        };
        println!(
            "{:<16} {:>9.1} {:>10.1} {:>9.3} {:>8} {:>10}",
            format!("{size}x{size}"),
            hit_ms,
            miss_ms,
            score,
            err,
            agree
        );
    }

    // ---- search, by haystack size -------------------------------------------
    println!("\nSearch cost against haystack size, 64x64 template");
    println!("{:<16} {:>9} {:>9} {:>10}", "haystack", "Mpx", "ms", "ms/Mpx");
    let tpl64 = crop_template(&hay, 64, 64, "probe");
    for (w, h) in &sizes {
        let sub = crop_frame(&hay, *w as u32, *h as u32);
        if sub.w < 128 || sub.h < 128 {
            continue;
        }
        let ms = median_ms(5, || {
            let _ = vision::find(&sub, &tpl64, false);
        });
        let m = mpx(sub.w, sub.h);
        println!(
            "{:<16} {:>9.2} {:>9.1} {:>10.1}",
            format!("{}x{}", sub.w, sub.h),
            m,
            ms,
            if m > 0.0 { ms / m } else { 0.0 }
        );
    }

    let multi_ms = median_ms(3, || {
        let _ = vision::find(&hay, &tpl64, true);
    });
    println!("\nThe same 64x64 template with 'try other scales' on: {multi_ms:.1} ms");

    // ---- what a script step actually costs ----------------------------------
    let step_ms = median_ms(5, || {
        if let Some(f) = platform::capture(vx, vy, vw, vh) {
            let _ = vision::find(&f, &tpl64, false);
        }
    });
    println!(
        "\nOne script image step, capture and search over the whole screen: {step_ms:.1} ms\n\
         A `While` loop polling for that picture therefore runs at about {:.1} checks \
         per second.",
        if step_ms > 0.0 { 1000.0 / step_ms } else { 0.0 }
    );

    // ---- what the search area is worth --------------------------------------
    // The point of the release, measured rather than promised: a script step is a
    // capture plus a search, and both scale with the area it is allowed to look at.
    println!("\nOne script image step by search area, 64x64 template");
    println!(
        "{:<16} {:>9} {:>10} {:>9} {:>12}",
        "area", "capture", "search", "total ms", "checks/sec"
    );
    for (w, h) in
        [(vw, vh), (1920, 1080), (1280, 720), (800, 600), (400, 300), (200, 150)]
    {
        if w > vw || h > vh {
            continue;
        }
        let cap_ms = median_ms(5, || {
            let _ = platform::capture(vx, vy, w, h);
        });
        let sub_frame = crop_frame(&hay, w as u32, h as u32);
        let find_ms = median_ms(5, || {
            let _ = vision::find(&sub_frame, &tpl64, false);
        });
        let total = cap_ms + find_ms;
        println!(
            "{:<16} {:>9.1} {:>10.1} {:>9.1} {:>12.1}",
            format!("{w}x{h}"),
            cap_ms,
            find_ms,
            total,
            if total > 0.0 { 1000.0 / total } else { 0.0 }
        );
    }

    // ---- what the vector kernel is worth ------------------------------------
    // Stage 4 found a sevenfold win by measuring rather than guessing, so the same
    // rule applies to the kernel that replaced it: print both numbers.
    let chosen = vision::active();
    println!(
        "\nCorrelation kernel ({} - {})",
        chosen.name(),
        chosen.target_cpus()
    );
    println!("{:<16} {:>10} {:>10} {:>9} {:>10}", "template", "plain ms", "vector ms", "speed-up", "same spot");
    for size in [32u32, 64, 128] {
        if size + 8 >= hay.w.min(hay.h) {
            continue;
        }
        let tpl = crop_template(&hay, size, size, "kernel");
        vision::force_isa(Some(vision::Isa::Scalar));
        let plain_ms = median_ms(3, || {
            let _ = vision::find(&hay, &tpl, false);
        });
        let plain = vision::find(&hay, &tpl, false);
        // Back to the tier this process settled on, rather than to `auto` - `auto`
        // would re-run the AVX-512 race in the middle of a benchmark.
        vision::force_isa(Some(chosen));
        let vec_ms = median_ms(3, || {
            let _ = vision::find(&hay, &tpl, false);
        });
        let vectored = vision::find(&hay, &tpl, false);
        let same = match (&plain, &vectored) {
            (Some(a), Some(b)) => {
                if a.x == b.x && a.y == b.y { "same" } else { "DIFFERENT" }
            }
            (None, None) => "same",
            _ => "DIFFERENT",
        };
        println!(
            "{:<16} {:>10.1} {:>10.1} {:>9.2} {:>10}",
            format!("{size}x{size}"),
            plain_ms,
            vec_ms,
            if vec_ms > 0.0 { plain_ms / vec_ms } else { 0.0 },
            same
        );
    }

    // ---- what outline matching costs ----------------------------------------
    println!("\nGrey against outline matching, 64x64 template");
    println!("{:<16} {:>10} {:>9} {:>10}", "mode", "ms", "score", "err px");
    {
        let tpl = crop_template(&hay, 64, 64, "edge");
        let want_x = hay.x + 64 + 32;
        let want_y = hay.y + 64 + 32;
        for (name, edge) in [("grey", false), ("outline", true)] {
            let ms = median_ms(3, || {
                let _ = vision::find_mode(&hay, &tpl, false, edge);
            });
            let (score, err) = match vision::find_mode(&hay, &tpl, false, edge) {
                Some(h) => (h.score, (h.x - want_x).abs().max((h.y - want_y).abs())),
                None => (0.0, -1),
            };
            println!("{name:<16} {ms:>10.1} {score:>9.3} {err:>10}");
        }
    }

    // ---- OCR ----------------------------------------------------------------
    println!("\nText recognition");
    println!("{:<14} {:>9} {:>8}", "region", "ms", "lines");
    for (w, h) in [(200, 80), (400, 200), (800, 600)] {
        if w > vw || h > vh {
            continue;
        }
        let mut lines = 0usize;
        let mut failed: Option<String> = None;
        let ms = median_ms(3, || match ocr::read_region(vx, vy, w, h) {
            Ok(boxes) => lines = boxes.len(),
            Err(e) => failed = Some(e.to_string()),
        });
        match &failed {
            Some(e) => {
                println!("{:<14} {:>9} {:>8}   {e}", format!("{w}x{h}"), "-", "-");
                break;
            }
            None => println!("{:<14} {:>9.1} {:>8}", format!("{w}x{h}"), ms, lines),
        }
    }

    // ---- what preparing the pixels costs and buys ---------------------------
    // The claim being tested: preparation is worth more than a second engine would
    // be. A profile that costs three times as much and reads the same text is not.
    println!("\nText recognition by preparation profile, 400x200 region");
    println!("{:<16} {:>9} {:>8} {:>8} {:>10}", "profile", "ms", "lines", "chars", "fit");
    for prep in
        [ocr::Prep::None, ocr::Prep::Ui, ocr::Prep::Small, ocr::Prep::Game, ocr::Prep::Digits]
    {
        let (w, h) = (400.min(vw), 200.min(vh));
        let mut lines = 0usize;
        let mut chars = 0usize;
        let mut fit = 0.0f64;
        let mut failed: Option<String> = None;
        let ms = median_ms(3, || {
            match ocr::read_region_as(vx, vy, w, h, prep, &ocr::Expect::Any) {
                Ok(r) => {
                    lines = r.boxes.len();
                    chars = r.text().chars().count();
                    fit = r.quality;
                }
                Err(e) => failed = Some(e.to_string()),
            }
        });
        match &failed {
            Some(e) => {
                println!("{:<16}   {e}", format!("{prep:?}"));
                break;
            }
            None => println!(
                "{:<16} {:>9.1} {:>8} {:>8} {:>10.2}",
                format!("{prep:?}"),
                ms,
                lines,
                chars,
                fit
            ),
        }
    }

    // ---- what asking Windows costs ------------------------------------------
    // The first rung of the cascade, and only the first rung if it is faster than
    // the picture search. Against a game it finds nothing at all, which is the
    // honest answer rather than a fault.
    println!("\nUI Automation, against whatever window is in front");
    println!("{:<30} {:>9} {:>8}", "query", "ms", "found");
    for (label, q) in [
        (
            "any button, front window",
            uia::Query { control: "Button".into(), in_front: true, ..Default::default() },
        ),
        (
            "any button, whole desktop",
            uia::Query { control: "Button".into(), in_front: false, ..Default::default() },
        ),
        (
            "name substring, front window",
            uia::Query {
                name: "e".into(),
                control: "Button".into(),
                in_front: true,
                ..Default::default()
            },
        ),
    ] {
        let mut found = false;
        let ms = median_ms(3, || found = uia::find(&q, 0).is_some());
        println!("{:<30} {:>9.1} {:>8}", label, ms, if found { "yes" } else { "no" });
    }

    println!(
        "\nHow to read this:\n\
         - The step cost is the one that matters. It is the floor under how often a\n\
           script can look at the screen, and nothing in a `Wait for` or a `While` can\n\
           beat it.\n\
         - hit and miss columns should be near-equal. `find` has no early exit, so a\n\
           script polling for a button that is not there yet pays the same as one that\n\
           finds it immediately. Predictable, if not cheap.\n\
         - ms/Mpx says how the cost scales. Multiply it by 8.29 for a 4K screen or by\n\
           the total area of a multi-monitor desktop, which is what a script step\n\
           actually sweeps.\n\
         - A zero in the lines column means OCR ran but read nothing where it looked,\n\
           so the timing is for an empty region. Point it at some text to price a real\n\
           read.\n\
         - err px is how far the hit landed from where the template was cut out. It has\n\
           to stay at 0 or 1. A faster search that answers in the wrong place is not a\n\
           faster search - unless the last column says the single-threaded sweep gives\n\
           the same answer, in which case the template matches in several places and\n\
           the screen, not the code, decided which one won.\n\
         - The area table is what this release is for. Compare the bottom row against\n\
           the top one: that ratio is what a script gains by being told where to look.\n\
         - The kernel table prices the vector path against the plain one. `same spot`\n\
           has to say `same`: the two differ in the last bits of an f32, and if that\n\
           ever decides which position wins, the release finds pictures in different\n\
           places on different processors.\n\
         - Outline matching costs an extra pass over each plane and scores lower on\n\
           the same picture. That is expected - it is a different measurement - and it\n\
           earns its place when a template stops matching after a theme change.\n\
         - The profile table is the case for preparing the pixels. Compare chars and\n\
           fit, not only ms: a profile that costs three times as much and reads the\n\
           same text is not worth having, and one that reads twice as much for twice\n\
           the cost is.\n\
         - UI Automation belongs at the front of the cascade only if it is faster than\n\
           the picture search here. Zero found against a game is the expected answer."
    );
    Ok(())
}

/// Hammers the playback lifecycle looking for races.
///
/// Everything here is one transition away from another one: start while a previous
/// run is still winding down, pause between the schedule check and the send, stop
/// during a frame-guard hold. None of it shows up in ordinary use, because ordinary
/// use makes one transition every few minutes rather than a hundred a second.
///
/// Recording is deliberately left out. Its lifecycle installs global hooks and would
/// capture whatever the machine's owner did for the next ten minutes, and the races
/// worth hunting - generation cancellation, released presses, the pause clock - all
/// live on the playback side.
fn run_churn_selftest(seconds: u64) -> Result<()> {
    let (tx, _rx) = unbounded();
    let state = AppState::new(tx);
    // Long enough that a run is almost always in progress when the next transition
    // arrives, which is the whole point.
    *state.macro_data.lock() = synthetic_macro(4000, 5_000);
    state.loop_play.store(true, Ordering::Relaxed);
    state.absolute_mouse.store(true, Ordering::Relaxed);
    *state.speed.lock() = 1.0;

    selftest::arm_dry();
    println!("Self-test: lifecycle churn");
    println!("{seconds} s, no input is actually sent.\n");

    // If a transition wedges, nothing below will ever report it - so something has to
    // be watching from outside.
    let beat = Arc::new(AtomicU64::new(0));
    {
        let beat = beat.clone();
        std::thread::spawn(move || {
            let mut last = 0u64;
            let mut idle = 0u32;
            loop {
                std::thread::sleep(Duration::from_secs(1));
                let now = beat.load(Ordering::Relaxed);
                idle = if now == last { idle + 1 } else { 0 };
                last = now;
                if idle >= 30 {
                    println!("\nDEADLOCK: no transition completed for 30 s. Aborting.");
                    std::process::exit(2);
                }
            }
        });
    }

    let mut rng = Rng::new();
    let started = Instant::now();
    let deadline = started + Duration::from_secs(seconds);
    let mut transitions = 0u64;
    let mut stuck_presses = 0u64;
    let mut extra_releases = 0u64;
    let mut overlapped = 0u64;
    let mut blamed = [0u64; 7];
    let mut next_report = started + Duration::from_secs(30);

    while Instant::now() < deadline {
        let pick = rng.below(7) as usize;
        match pick {
            0 => start_playback(&state),
            1 => stop_playback(&state),
            2 => toggle_playback(&state),
            3 => toggle_pause(&state),
            4 => state.skip_step.store(true, Ordering::Relaxed),
            5 => *state.speed.lock() = 0.1 + (rng.below(30) as f64) / 10.0,
            _ => {
                let on = rng.below(2) == 1;
                state.frame_guard.store(on, Ordering::Relaxed);
                state.frame_guard_fps.store(5 + rng.below(236), Ordering::Relaxed);
            }
        }
        transitions += 1;
        beat.fetch_add(1, Ordering::Relaxed);

        // Two loops at once would mean a generation escaped cancellation.
        if selftest::live() > 1 {
            overlapped += 1;
        }

        // Every so often, stop properly and check that nothing was left held down.
        if rng.below(20) == 0 {
            stop_playback(&state);
            // Waiting for `playing` alone is not enough: the loop clears that flag
            // and then releases what it held, so a check racing in between would
            // report a press that was about to be let go.
            let settle = Instant::now() + Duration::from_millis(600);
            while (state.playing.load(Ordering::Relaxed) || selftest::live() > 0)
                && Instant::now() < settle
            {
                std::thread::sleep(Duration::from_millis(5));
            }
            let held = selftest::held();
            if held > 0 {
                stuck_presses += 1;
                blamed[pick] += 1;
                println!(
                    "  STUCK PRESS: {held} still down after a stop, transition {transitions}"
                );
            } else if held < 0 {
                extra_releases += 1;
                blamed[pick] += 1;
            }
        }

        std::thread::sleep(Duration::from_millis(1 + rng.below(20)));

        if Instant::now() >= next_report {
            println!(
                "  {:>4} s  {transitions} transitions, live {}, peak {}, held {}",
                started.elapsed().as_secs(),
                selftest::live(),
                selftest::peak_live(),
                selftest::held()
            );
            next_report += Duration::from_secs(30);
        }
    }

    stop_playback(&state);
    let settle = Instant::now() + Duration::from_secs(3);
    while (state.playing.load(Ordering::Relaxed) || selftest::live() > 0)
        && Instant::now() < settle
    {
        std::thread::sleep(Duration::from_millis(10));
    }

    let live = selftest::live();
    let peak = selftest::peak_live();
    println!("\n{:<36} {}", "transitions", transitions);
    println!("{:<36} {}", "playback loops still running", live);
    println!("{:<36} {}", "most loops running at once", peak);
    println!("{:<36} {}", "moments with two loops at once", overlapped);
    println!("{:<36} {}", "stops that left a press down", stuck_presses);
    println!("{:<36} {}", "stops with an unmatched release", extra_releases);
    if stuck_presses + extra_releases > 0 {
        const NAMES: [&str; 7] =
            ["start", "stop", "toggle", "pause", "skip", "speed", "guard"];
        print!("  last transition before each:");
        for (i, n) in NAMES.iter().enumerate() {
            if blamed[i] > 0 {
                print!("  {n}={}", blamed[i]);
            }
        }
        println!();
    }

    let serious = live > 0 || peak > 1 || overlapped > 0 || stuck_presses > 0;
    println!(
        "\n{}",
        if serious {
            "NOT clean. A press left down, or a generation that escaped cancellation, \
             is a real fault - the counters above say which."
        } else if extra_releases > 0 {
            "No press was ever left down and no generation escaped cancellation.\n\
             The unmatched releases come from pausing mid-press: the pause lets the \
             button go, and on resume the recording plays its own release for a button \
             that is no longer held. Harmless to Windows, but it is a real deviation \
             from the recording and the count above says how often it happens."
        } else {
            "Clean. Every stop released what it was holding, no generation escaped \
             cancellation, and nothing wedged."
        }
    );
    Ok(())
}

/// Runs for hours doing what a long unattended session does, and records what it
/// costs while doing it.
///
/// Leaks are invisible below an hour, and a soak that needs somebody sitting in front
/// of Task Manager writing numbers down is a soak that does not get run. So it samples
/// itself: private bytes, open handles and GDI objects, which between them cover the
/// three things this application allocates in bulk - replay buffers, the WinRT objects
/// behind OCR, and the bitmaps behind screen capture.
fn run_soak_selftest(hours: f64) -> Result<()> {
    let (tx, _rx) = unbounded();
    let state = AppState::new(tx);
    *state.macro_data.lock() = synthetic_macro(2000, 5_000);
    state.loop_play.store(true, Ordering::Relaxed);
    state.absolute_mouse.store(true, Ordering::Relaxed);
    state.frame_guard.store(true, Ordering::Relaxed);
    state.frame_guard_auto.store(false, Ordering::Relaxed);
    state.frame_guard_fps.store(30, Ordering::Relaxed);
    *state.speed.lock() = 1.0;

    selftest::arm_dry();
    println!("Self-test: soak");
    println!(
        "{hours:.1} h. Replay runs continuously; the screen is captured every 2 s and \n\
         read every 5 s, which is what a script polling for a picture does. No input \n\
         is sent, but the screen is being looked at, so leave something on it.\n"
    );

    // A twelve-hour run that stops doing anything after ten minutes reports nothing
    // useful unless something is watching where it stopped. Phases are numbered so a
    // second thread can name the one the loop is stuck in.
    const PHASES: [&str; 5] =
        ["waiting", "capturing the screen", "reading text", "sampling cost", "restarting"];
    let phase = Arc::new(AtomicUsize::new(0));
    let beat = Arc::new(AtomicU64::new(0));
    {
        let (phase, beat) = (phase.clone(), beat.clone());
        std::thread::spawn(move || {
            let mut last = 0u64;
            let mut idle = 0u64;
            loop {
                std::thread::sleep(Duration::from_secs(30));
                let now = beat.load(Ordering::Relaxed);
                idle = if now == last { idle + 30 } else { 0 };
                last = now;
                if idle >= 120 && idle.is_multiple_of(120) {
                    println!(
                        "  STALLED {idle}s in: {}",
                        PHASES[phase.load(Ordering::Relaxed).min(4)]
                    );
                }
            }
        });
    }

    // The console stops accepting writes while text is selected in it, and a soak
    // whose only record is a console it cannot write to has no record at all.
    let csv = paths::log_dir().join("soak.csv");
    let append = |line: &str| {
        use std::io::Write;
        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&csv) {
            let _ = writeln!(f, "{line}");
        }
    };
    append("minute,private_mb,handles,gdi,peak_gdi,captures,reads,restarts,slept_s,worst_stall_s");
    println!("A copy of every row is appended to {}\n", csv.display());

    start_playback(&state);
    let (vx, vy, vw, vh) = platform::virtual_screen_rect();
    let tpl = platform::capture(vx, vy, vw.min(256), vh.min(256))
        .map(|f| f.as_template("soak"));

    let started = Instant::now();
    let end = started + Duration::from_secs_f64(hours * 3600.0);
    let mut next_capture = started;
    let mut next_ocr = started;
    let mut next_report = started;
    let mut captures = 0u64;
    let mut reads = 0u64;
    let mut restarts = 0u64;
    let mut first: Option<(u64, u32, u32)> = None;

    println!(
        "{:>8} {:>12} {:>10} {:>8} {:>10} {:>9} {:>9} {:>9}",
        "elapsed", "private MB", "handles", "GDI", "captures", "reads", "restarts", "slept s"
    );

    // Two clocks: `Instant` stops while the machine is asleep, wall time does not.
    // Their divergence is how a suspended laptop is told apart from a wedged loop.
    let wall0 = std::time::SystemTime::now();
    let mut worst_stall = 0u64;
    let mut worst_phase = 0usize;
    let mut peak_gdi = 0u32;
    let mut ocr_failures = 0u64;
    let mut ocr_enabled = true;

    while Instant::now() < end {
        let now = Instant::now();
        beat.fetch_add(1, Ordering::Relaxed);

        let mark = |p: usize, phase: &AtomicUsize| {
            phase.store(p, Ordering::Relaxed);
            Instant::now()
        };

        if !state.playing.load(Ordering::Relaxed) {
            let t = mark(4, &phase);
            restarts += 1;
            start_playback(&state);
            let took = t.elapsed().as_secs();
            if took > worst_stall {
                worst_stall = took;
                worst_phase = 4;
            }
        }

        if now >= next_capture {
            let t = mark(1, &phase);
            if let (Some(frame), Some(t2)) = (platform::capture(vx, vy, vw, vh), tpl.as_ref())
            {
                let _ = vision::find(&frame, t2, false);
                captures += 1;
            }
            let took = t.elapsed().as_secs();
            if took > worst_stall {
                worst_stall = took;
                worst_phase = 1;
            }
            next_capture = Instant::now() + Duration::from_secs(2);
        }

        if ocr_enabled && now >= next_ocr {
            let t = mark(2, &phase);
            match ocr::read_region(vx, vy, 400.min(vw), 200.min(vh)) {
                Ok(_) => reads += 1,
                Err(_) => ocr_failures += 1,
            }
            let took = t.elapsed().as_secs();
            if took > worst_stall {
                worst_stall = took;
                worst_phase = 2;
            }
            // One slow read is the machine being busy. A minute is the engine not
            // coming back, and there is no sense spending eleven hours finding that
            // out over and over.
            if took >= 60 {
                ocr_enabled = false;
                println!("  Text recognition took {took}s and has been switched off for the rest of the run.");
            }
            next_ocr = Instant::now() + Duration::from_secs(5);
        }

        let (_, _, gdi_now) = platform::process_cost();
        peak_gdi = peak_gdi.max(gdi_now);

        if now >= next_report {
            let t = mark(3, &phase);
            let (private, handles, gdi) = platform::process_cost();
            let mono = started.elapsed().as_secs();
            let wall = wall0.elapsed().map(|d| d.as_secs()).unwrap_or(mono);
            let slept = wall.saturating_sub(mono);
            if first.is_none() && mono >= 300 {
                // The first five minutes are warm-up: caches fill and allocators
                // settle, and counting that as growth would cry wolf every time.
                first = Some((private, handles, gdi));
            }
            let mb = private as f64 / 1_048_576.0;
            println!(
                "{:>7}m {:>12.1} {:>10} {:>8} {:>10} {:>9} {:>9} {:>9}",
                mono / 60,
                mb,
                handles,
                gdi,
                captures,
                reads,
                restarts,
                slept
            );
            append(&format!(
                "{},{:.1},{},{},{},{},{},{},{},{}",
                mono / 60,
                mb,
                handles,
                gdi,
                peak_gdi,
                captures,
                reads,
                restarts,
                slept,
                worst_stall
            ));
            let _ = t;
            // Every minute for the first ten, then every ten. Ten minutes of silence
            // at the start says nothing about whether the loop is alive, which is the
            // first thing anybody watching a soak wants to know.
            let interval = if mono < 600 { 60 } else { 600 };
            next_report = Instant::now() + Duration::from_secs(interval);
        }

        phase.store(0, Ordering::Relaxed);
        std::thread::sleep(Duration::from_millis(200));
    }

    stop_playback(&state);
    std::thread::sleep(Duration::from_secs(2));
    let (private, handles, gdi) = platform::process_cost();
    let mono = started.elapsed().as_secs();
    let wall = wall0.elapsed().map(|d| d.as_secs()).unwrap_or(mono);
    let slept = wall.saturating_sub(mono);
    println!("\n{:<30} {}", "captures", captures);
    println!("{:<30} {}", "OCR reads", reads);
    println!("{:<30} {}", "OCR failures", ocr_failures);
    println!("{:<30} {}", "playback restarts", restarts);
    println!("{:<30} {}", "peak GDI objects", peak_gdi);
    println!("{:<30} {} s", "time the machine was asleep", slept);
    println!(
        "{:<30} {} s in: {}",
        "longest single stall", worst_stall, PHASES[worst_phase]
    );

    // A run that spent most of itself asleep or wedged has not soaked anything, and
    // saying so is more use than a growth figure computed from four samples.
    let expected = (mono / 2).max(1);
    if captures * 4 < expected {
        println!(
            "\nOnly {captures} captures in {} minutes - this run did far less work than \
             it should have. Look at the stall and sleep figures above before reading \
             anything into the growth numbers.",
            mono / 60
        );
    }

    match first {
        Some((p0, h0, g0)) => {
            let dp = private as f64 / 1_048_576.0 - p0 as f64 / 1_048_576.0;
            let dh = handles as i64 - h0 as i64;
            let dg = gdi as i64 - g0 as i64;
            println!("\ngrowth since the five-minute mark:");
            println!("  {:<28} {dp:+.1} MB", "private bytes");
            println!("  {:<28} {dh:+}", "handles");
            println!("  {:<28} {dg:+}", "GDI objects");
            // A few MB of allocator drift over hours is normal; a steady climb is not,
            // and handles or GDI objects should be flat to within a handful.
            let ok = dp < 32.0 && dh.abs() < 50 && dg.abs() < 50;
            println!(
                "\n{}",
                if ok {
                    "Flat. Nothing accumulated over the run."
                } else {
                    "Something is accumulating. Compare the per-sample rows above: a \
                     straight climb points at a leak, a step points at one operation."
                }
            );
        }
        None => println!("\nToo short to judge growth - run for at least fifteen minutes."),
    }
    Ok(())
}

fn run_selftest(which: &str) -> Result<()> {
    // `churn=600` runs for ten minutes; plain `churn` for five.
    // Two parses, because the soak is measured in hours and everything else in
    // whole units. `soak=0.35` used to parse as a `u64`, fail, and fall through to
    // the twelve-hour default without a word - which is a very long time to wait
    // for a twenty-minute answer, and it is exactly what happened while this
    // release was being tested.
    let (name, arg, hours) = match which.split_once('=') {
        Some((n, a)) => (n, a.parse::<u64>().ok(), a.parse::<f64>().ok()),
        None => (which, None, None),
    };
    if which.contains('=') && arg.is_none() && hours.is_none() {
        println!("'{which}': the part after '=' is not a number - ignoring it");
    }
    match name {
        "timing" => run_timing_selftest(),
        "vision" => run_vision_selftest(),
        "simd" | "isa" | "kernel" => run_simd_selftest(),
        "churn" => run_churn_selftest(arg.unwrap_or(300).clamp(5, 7200)),
        "soak" => run_soak_selftest(hours.unwrap_or(12.0).clamp(0.01, 48.0)),
        "script" => run_script_selftest(arg.unwrap_or(200).clamp(1, 100_000)),
        "dryrun" => run_dryrun_selftest(),
        "target" => run_target_selftest(),
        "recovery" => run_recovery_selftest(),
        _ => {
            println!(
                "unknown self-test '{which}'. \
                 Available: timing, vision, simd, dryrun, target, recovery, \
                 churn[=seconds], soak[=hours], script[=rounds]"
            );
            Ok(())
        }
    }
}

/// Drives the recovery machinery on a real playback thread.
///
/// The unit tests check the arithmetic: that a block is found by name, that blocks
/// balance, that a policy naming a missing block is an error. What they cannot check
/// is the interpreter jumping into one, running it, coming back and trying the
/// failed step again - which is four control-flow transfers and the only part that
/// can go wrong in a way nobody notices until four in the morning.
///
/// Runs dry.
fn run_recovery_selftest() -> Result<()> {
    virtual_desktop::init_thread();
    selftest::arm_dry();
    println!("Self-test: recovery blocks\n");

    let mut failures: Vec<String> = Vec::new();
    let mut checks = 0u32;
    let mut check = |name: &str, ok: bool, detail: String| {
        checks += 1;
        println!("{:<52} {:>8}  {detail}", name, if ok { "ok" } else { "FAILED" });
        if !ok {
            failures.push(name.to_string());
        }
    };
    println!("{:<52} {:>8}  detail", "check", "result");

    // A picture that certainly is not on screen, so the step always misses.
    let missing = |miss: OnMiss| {
        ScriptStep::new(StepKind::ClickImage {
            template: "no_such_template_ever".into(),
            threshold: 0.99,
            button: MouseButton::Left,
            area: SearchArea::Rect { x: 0, y: 0, w: 32, h: 32 },
            edge: false,
            miss,
        })
    };
    let bump = |name: &str| {
        ScriptStep::new(StepKind::SetVar {
            name: name.into(),
            op: VarOp::Add,
            value: Value::Num(1.0),
        })
    };

    let run = |script: Vec<ScriptStep>| -> (ScriptEnd, std::collections::HashMap<String, Value>) {
        let (tx, _rx) = unbounded();
        let state = AppState::new(tx);
        state.play_generation.store(1, Ordering::Relaxed);
        state.failure_shots.store(false, Ordering::Relaxed);
        let mut data = MacroData::new(
            vec![MacroEvent {
                t_us: 0,
                kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
            }],
            1000,
        );
        data.script = script;
        // Ids, which is what the tally keys on and what `normalize` would give it.
        data.normalize().ok();
        let mut ctx = ScriptCtx {
            state: &state,
            data: &data,
            generation: 1,
            map: CoordMap::IDENTITY,
            vars: Default::default(),
            templates: Default::default(),
            last_text: String::new(),
            last_hit: Default::default(),
            latched: Default::default(),
            history: Default::default(),
            tally: Default::default(),
            learned: Default::default(),
            recover_stack: Vec::new(),
            recovered: Default::default(),
            pc: 0,
            step_id: 0,
            failure: None,
            run_folder: String::new(),
            depth: 0,
            called: Default::default(),
            notes: Default::default(),
        };
        let mut pressed = PressedInputs::default();
        let mut mover = MoveEngine::new(&state);
        let mut guard = FrameGuard::new(&state);
        let end = run_script(&mut ctx, &mut pressed, &mut mover, &mut guard);
        (end, ctx.vars)
    };

    // ---- the block runs, and the step is tried again -------------------------
    {
        let (end, vars) = run(vec![
            missing(OnMiss::Recover { name: "fix".into() }),
            bump("after"),
            ScriptStep::new(StepKind::Exit),
            ScriptStep::new(StepKind::Recovery { name: "fix".into() }),
            bump("inside"),
            ScriptStep::new(StepKind::EndRecovery),
        ]);
        let get = |n: &str| vars.get(n).map_or(0.0, |v| v.as_num());
        check(
            "the block runs when the step misses",
            get("inside") >= 1.0,
            format!("inside = {}", get("inside")),
        );
        // The step is retried, misses again, and recovers again - up to the cap.
        // What matters is that it ends rather than looping for ever.
        check(
            "and the run ends rather than recovering for ever",
            end == ScriptEnd::Finished,
            format!("{end:?}, block ran {} time(s)", get("inside")),
        );
        check(
            "the depth cap is what stops it",
            get("inside") <= MAX_RECOVER_DEPTH as f64 + 1.0,
            format!("{} runs, cap is {MAX_RECOVER_DEPTH}", get("inside")),
        );
    }

    // ---- a block nobody wrote ------------------------------------------------
    {
        let (end, vars) = run(vec![
            missing(OnMiss::Recover { name: "nowhere".into() }),
            bump("after"),
        ]);
        check(
            "a policy naming no block ends the run rather than walking on",
            end == ScriptEnd::Finished && !vars.contains_key("after"),
            format!("{end:?}, after = {:?}", vars.get("after")),
        );
    }

    // ---- the block is skipped in normal flow ---------------------------------
    {
        let (_end, vars) = run(vec![
            bump("before"),
            ScriptStep::new(StepKind::Recovery { name: "fix".into() }),
            bump("inside"),
            ScriptStep::new(StepKind::EndRecovery),
            bump("after"),
        ]);
        let get = |n: &str| vars.get(n).map_or(0.0, |v| v.as_num());
        check(
            "walking past a block does not run it",
            get("before") == 1.0 && get("inside") == 0.0 && get("after") == 1.0,
            format!(
                "before = {}, inside = {}, after = {}",
                get("before"),
                get("inside"),
                get("after")
            ),
        );
    }

    check(
        "nothing was left held down",
        selftest::held() == 0,
        format!("held = {}", selftest::held()),
    );

    selftest::disarm();
    println!("\n{checks} checks, {} failed", failures.len());
    if failures.is_empty() {
        println!(
            "\nA recovery block runs when its step misses, the step is tried again \
             afterwards, and a block that recovers into itself stops at the cap \
             instead of running until morning."
        );
        Ok(())
    } else {
        println!("\nFAILED: {}", failures.join(", "));
        anyhow::bail!("{} check(s) failed", failures.len())
    }
}

/// Drives the target cascade on a real playback thread.
///
/// The unit tests check the arithmetic: that a cascade sorts, that an unfilled way
/// is dropped, that a recorded click turns into four ways of finding it. What they
/// cannot check is the interpreter actually walking one - falling from a method that
/// is not there to the next, spending the timeout once around the whole cascade
/// rather than once per method, and writing down which method won.
///
/// Runs dry, so nothing reaches the screen. Every method except `Point` is expected
/// to fail here: there is no such element, no such picture and no such window, which
/// is exactly the fall-through the cascade exists for.
fn run_target_selftest() -> Result<()> {
    virtual_desktop::init_thread();
    selftest::arm_dry();
    println!("Self-test: the target cascade\n");

    let mut failures: Vec<String> = Vec::new();
    let mut checks = 0u32;
    let mut check = |name: &str, ok: bool, detail: String| {
        checks += 1;
        println!("{:<52} {:>8}  {detail}", name, if ok { "ok" } else { "FAILED" });
        if !ok {
            failures.push(name.to_string());
        }
    };
    println!("{:<52} {:>8}  detail", "check", "result");

    let (tx, _rx) = unbounded();
    let state = AppState::new(tx);
    state.play_generation.store(1, Ordering::Relaxed);
    let data = MacroData::new(
        vec![MacroEvent {
            t_us: 0,
            kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
        }],
        1000,
    );

    let mut ctx = ScriptCtx {
        state: &state,
        data: &data,
        generation: 1,
        map: CoordMap::IDENTITY,
        vars: Default::default(),
        templates: Default::default(),
        last_text: String::new(),
        last_hit: Default::default(),
        latched: Default::default(),
        history: Default::default(),
        tally: Default::default(),
        learned: Default::default(),
        recover_stack: Vec::new(),
        recovered: Default::default(),
        pc: 0,
        step_id: 0,
        failure: None,
        run_folder: String::new(),
        depth: 0,
        called: Default::default(),
        notes: Default::default(),
    };

    // Everything but the coordinate is unfindable here, on purpose.
    let full = Target {
        label: "Start".into(),
        methods: vec![
            Method::Element {
                query: uia::Query {
                    name: "no such element anywhere".into(),
                    automation_id: String::new(),
                    control: "Button".into(),
                    in_front: false,
                },
            },
            Method::Image {
                template: "no_such_template_ever".into(),
                threshold: 0.99,
                area: SearchArea::Rect { x: 0, y: 0, w: 32, h: 32 },
                edge: false,
            },
            Method::WindowPoint {
                window: "no such window title anywhere".into(),
                dx: 5,
                dy: 5,
            },
            Method::Point { x: 321, y: 654 },
        ],
    };

    let t0 = Instant::now();
    let hit = ctx.resolve_target(&full, Reliability::Maximum);
    let took = t0.elapsed();
    check(
        "the cascade falls through to the coordinate",
        hit.as_ref().map(|(x, y, _)| (*x, *y)) == Some((321, 654)),
        format!("{:?}", hit.as_ref().map(|(x, y, _)| (*x, *y))),
    );
    check(
        "and says which way found it",
        ctx.vars.get("Start.method").map(|v| v.as_text()).as_deref() == Some(EN.mt_point),
        format!("{:?}", ctx.vars.get("Start.method").map(|v| v.as_text())),
    );
    check(
        "match_x / match_y carry the answer for the click",
        ctx.vars.get("match_x").map(|v| v.as_num()) == Some(321.0)
            && ctx.vars.get("match_y").map(|v| v.as_num()) == Some(654.0),
        format!(
            "{:?}, {:?}",
            ctx.vars.get("match_x").map(|v| v.as_num()),
            ctx.vars.get("match_y").map(|v| v.as_num())
        ),
    );
    // Four methods, three of which have to be given up on. If this took minutes the
    // timeout had leaked into the cascade instead of staying around it.
    check(
        "giving up on three ways costs a moment, not a minute",
        took < Duration::from_secs(10),
        format!("{} ms for the whole cascade", took.as_millis()),
    );

    // Fast tries the best one only - which here is the one that cannot work, so the
    // whole target fails. That is the trade the setting names.
    let fast = ctx.resolve_target(&full, Reliability::Fast);
    check(
        "Fast tries one way and accepts failing",
        fast.is_none(),
        format!("{:?}", fast.map(|(x, y, _)| (x, y))),
    );

    // A target with nothing in it must not resolve to anything at all. An empty
    // element query matches the root, and clicking the middle of the window because
    // a field was left blank is the bug this guards.
    let empty = Target { label: "nothing".into(), methods: Vec::new() };
    check(
        "a target that names nothing finds nothing",
        ctx.resolve_target(&empty, Reliability::Maximum).is_none(),
        "no accidental click at the middle of the screen".into(),
    );

    // And the step around it: a whole run through the interpreter, with the step's
    // own timeout and miss policy.
    let mut data2 = MacroData::new(
        vec![MacroEvent {
            t_us: 0,
            kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
        }],
        1000,
    );
    data2.script = vec![
        ScriptStep::new(StepKind::ClickTarget {
            target: full.clone(),
            button: MouseButton::Left,
            invoke: true,
            reliability: Reliability::Maximum,
            timeout_ms: 500,
            miss: OnMiss::Stop,
        }),
        ScriptStep::new(StepKind::SetVar {
            name: "after".into(),
            op: VarOp::Add,
            value: Value::Num(1.0),
        }),
    ];
    let mut ctx2 = ScriptCtx {
        state: &state,
        data: &data2,
        generation: 1,
        map: CoordMap::IDENTITY,
        vars: Default::default(),
        templates: Default::default(),
        last_text: String::new(),
        last_hit: Default::default(),
        latched: Default::default(),
        history: Default::default(),
        tally: Default::default(),
        learned: Default::default(),
        recover_stack: Vec::new(),
        recovered: Default::default(),
        pc: 0,
        step_id: 0,
        failure: None,
        run_folder: String::new(),
        depth: 0,
        called: Default::default(),
        notes: Default::default(),
    };
    let mut pressed = PressedInputs::default();
    let mut mover = MoveEngine::new(&state);
    let mut guard = FrameGuard::new(&state);
    let end = run_script(&mut ctx2, &mut pressed, &mut mover, &mut guard);
    check(
        "a click on a target that fell through still clicks",
        end == ScriptEnd::Finished
            && ctx2.vars.get("after").map(|v| v.as_num()) == Some(1.0),
        format!("ended {end:?}, the step after it ran"),
    );
    check(
        "and nothing was left held down",
        selftest::held() == 0,
        format!("held = {}", selftest::held()),
    );

    selftest::disarm();
    println!("\n{checks} checks, {} failed", failures.len());
    if failures.is_empty() {
        println!(
            "\nA target is tried one way at a time, in order, and says which way \
             worked. A cascade with nothing findable in it costs a moment and ends \
             at the coordinate the recording started from."
        );
        Ok(())
    } else {
        println!("\nFAILED: {}", failures.join(", "));
        anyhow::bail!("{} check(s) failed", failures.len())
    }
}

/// Proves that a test run touches nothing.
///
/// This is the one self-test whose failure is not a wrong number but a real click on
/// somebody's real desktop, so it does not check the flag - it checks the effect.
/// The suppression counter is incremented at the same place the send would have
/// happened, so a run that reports suppressed sends is a run that reached those
/// sites and did not make them; and the `Run a program` step really does name a
/// command that would leave a file behind, so the absence of that file is evidence
/// rather than assertion.
///
/// It runs the two paths separately because they suppress in different places: flat
/// replay through `send_input_event`, and the script interpreter through its own
/// step-by-step gate.
fn run_dryrun_selftest() -> Result<()> {
    virtual_desktop::init_thread();
    println!("Self-test: the test run\n");

    let dir = paths::sub_dir("selftest");
    let _ = std::fs::create_dir_all(&dir);
    let breach = dir.join("dryrun_breach.tmp");
    let _ = std::fs::remove_file(&breach);

    let mut failures: Vec<String> = Vec::new();
    let mut checks = 0u32;
    let mut check = |name: &str, ok: bool, detail: String| {
        checks += 1;
        println!("{:<52} {:>8}  {detail}", name, if ok { "ok" } else { "FAILED" });
        if !ok {
            failures.push(name.to_string());
        }
    };

    println!("{:<52} {:>8}  detail", "check", "result");

    // ---- flat replay, through the button the user presses --------------------
    // Not `arm_dry`: the point is to exercise `start_test_run` itself, including the
    // part that lifts the suppression again when the run ends. A test that armed the
    // flag by hand would pass with that half missing.
    let (tx, _rx) = unbounded();
    let state = AppState::new(tx);
    *state.macro_data.lock() = synthetic_macro(600, 200);
    state.loop_play.store(false, Ordering::Relaxed);
    state.play_count_limit.store(1, Ordering::Relaxed);
    state.absolute_mouse.store(true, Ordering::Relaxed);
    *state.speed.lock() = 10.0;

    start_test_run(&state);
    let armed = selftest::dry();
    let deadline = Instant::now() + Duration::from_secs(30);
    while (state.playing.load(Ordering::Relaxed) || selftest::live() > 0)
        && Instant::now() < deadline
    {
        std::thread::sleep(Duration::from_millis(20));
    }

    let sent = selftest::suppressed();
    let held = selftest::held();
    check(
        "flat replay: the suppression went on",
        armed,
        format!("dry() during the run = {armed}"),
    );
    check(
        "flat replay: every input was suppressed, not sent",
        sent >= 600,
        format!("{sent} suppressed (600 events, at least one send each)"),
    );
    check(
        "flat replay: nothing was left held down",
        held == 0,
        format!("held = {held}"),
    );
    check(
        "the suppression was lifted when the run ended",
        !selftest::dry() && !state.test_run.load(Ordering::Relaxed),
        format!("dry() = {}, test_run = {}", selftest::dry(), state.test_run.load(Ordering::Relaxed)),
    );

    // ---- the script interpreter, and the two steps it must step over ---------
    // From here on the flag is armed by hand, because these run the interpreter
    // directly to get the variables back out of it.
    selftest::arm_dry();

    let bump = |name: &str| {
        ScriptStep::new(StepKind::SetVar {
            name: name.into(),
            op: VarOp::Add,
            value: Value::Num(1.0),
        })
    };
    // A command that would certainly leave a mark. `run_program` splits arguments on
    // whitespace and hands them to the executable, so the file name must not contain
    // any - which is why the working directory is moved rather than the path spelled
    // out.
    let prev_cwd = std::env::current_dir().ok();
    let _ = std::env::set_current_dir(&dir);
    let script = vec![
        bump("before"),
        ScriptStep::new(StepKind::Run {
            path: "cmd.exe".into(),
            args: "/c copy nul dryrun_breach.tmp".into(),
        }),
        bump("between"),
        ScriptStep::new(StepKind::Exit),
        bump("after"),
    ];

    let (tx2, _rx2) = unbounded();
    let state2 = AppState::new(tx2);
    state2.play_generation.store(1, Ordering::Relaxed);
    let mut data = MacroData::new(
        vec![MacroEvent {
            t_us: 0,
            kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
        }],
        1000,
    );
    data.script = script;
    let mut ctx = ScriptCtx {
        state: &state2,
        data: &data,
        generation: 1,
        map: CoordMap::IDENTITY,
        vars: Default::default(),
        templates: Default::default(),
        last_text: String::new(),
        last_hit: Default::default(),
        latched: Default::default(),
        history: Default::default(),
        tally: Default::default(),
        learned: Default::default(),
        recover_stack: Vec::new(),
        recovered: Default::default(),
        pc: 0,
        step_id: 0,
        failure: None,
        run_folder: String::new(),
        depth: 0,
        called: Default::default(),
        notes: Default::default(),
    };
    let mut pressed = PressedInputs::default();
    let mut mover = MoveEngine::new(&state2);
    let mut guard = FrameGuard::new(&state2);
    let skipped_before = selftest::skipped();
    let end = run_script(&mut ctx, &mut pressed, &mut mover, &mut guard);
    let skipped = selftest::skipped() - skipped_before;

    // Give a child that should never have existed time to exist, so the check is
    // about whether it was started rather than about how fast this thread is.
    std::thread::sleep(Duration::from_millis(400));
    let breached = breach.exists();
    let _ = std::fs::remove_file(&breach);
    if let Some(p) = prev_cwd {
        let _ = std::env::set_current_dir(p);
    }

    let get = |n: &str| ctx.vars.get(n).map_or(0.0, |v| v.as_num());
    check(
        "no program was started",
        !breached,
        if breached {
            "the file the skipped command would have written IS THERE".into()
        } else {
            "the file it would have written is absent".into()
        },
    );
    check(
        "both dangerous steps were counted as skipped",
        skipped == 2,
        format!("{skipped} skipped (Run a program, Quit the app)"),
    );
    check(
        "the script walked past them instead of stopping",
        get("before") == 1.0 && get("between") == 1.0 && get("after") == 1.0,
        format!(
            "before = {}, between = {}, after = {}, ended {end:?}",
            get("before"),
            get("between"),
            get("after")
        ),
    );

    // ---- a rehearsal that fails still says why -------------------------------
    // Deliberately not written to the real history: this checks the diagnosis, and
    // filling somebody's run history with self-test entries to do it would be rude.
    let (tx3, _rx3) = unbounded();
    let state3 = AppState::new(tx3);
    state3.play_generation.store(1, Ordering::Relaxed);
    // Screenshots off: there is nothing here worth photographing, and a self-test has
    // no business leaving PNGs behind.
    state3.failure_shots.store(false, Ordering::Relaxed);
    let mut data3 = MacroData::new(
        vec![MacroEvent {
            t_us: 0,
            kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
        }],
        1000,
    );
    data3.script = vec![ScriptStep::new(StepKind::ClickImage {
        template: "no_such_template_ever".into(),
        threshold: 0.85,
        button: MouseButton::Left,
        area: SearchArea::FullScreen,
        edge: false,
        miss: OnMiss::Stop,
    })];
    let mut ctx3 = ScriptCtx {
        state: &state3,
        data: &data3,
        generation: 1,
        map: CoordMap::IDENTITY,
        vars: Default::default(),
        templates: Default::default(),
        last_text: String::new(),
        last_hit: Default::default(),
        latched: Default::default(),
        history: Default::default(),
        tally: Default::default(),
        learned: Default::default(),
        recover_stack: Vec::new(),
        recovered: Default::default(),
        pc: 0,
        step_id: 0,
        failure: None,
        run_folder: String::new(),
        depth: 0,
        called: Default::default(),
        notes: Default::default(),
    };
    let mut p3 = PressedInputs::default();
    let mut m3 = MoveEngine::new(&state3);
    let mut g3 = FrameGuard::new(&state3);
    let end3 = run_script(&mut ctx3, &mut p3, &mut m3, &mut g3);
    let rec = ctx3.failure.take();
    check(
        "a step that ends the run leaves a record behind",
        end3 == ScriptEnd::Finished && rec.is_some(),
        format!(
            "ended {end3:?}, record {}",
            if rec.is_some() { "written" } else { "MISSING" }
        ),
    );
    if let Some(r) = &rec {
        check(
            "the record says which step, and why, in numbers",
            r.failed_at == Some(0) && r.reason.contains("0.85") && !r.failed_step.is_empty(),
            format!("#{:?}  {}", r.failed_at, r.reason),
        );
        check(
            "and what to try next",
            !r.hints.is_empty(),
            format!("{} suggestion(s): {}", r.hints.len(), r.hints.join(" / ")),
        );
    }

    selftest::disarm();

    println!("\n{checks} checks, {} failed", failures.len());
    if failures.is_empty() {
        println!(
            "\nA test run reaches every step and sends nothing. The two steps that go \
             past the input queue were stepped over, and the program they name was \
             never started. A step that ends the run explains itself in the numbers \
             the program already had."
        );
        Ok(())
    } else {
        println!("\nFAILED: {}", failures.join(", "));
        anyhow::bail!("{} check(s) failed", failures.len())
    }
}

/// Drives the script interpreter through the 1.5.0 paths, on real threads.
///
/// The unit tests check the pieces: that a policy round-trips, that `break_target`
/// counts nesting, that a drag is not a click. What they cannot check is the
/// interpreter actually running - the retry loop sleeping and being cancelled, a
/// call handing its variables down and getting them back, a recursion guard firing
/// eight frames deep, a step gate parking a run and something else releasing it.
/// Those are all about a playback thread and the flags other threads set under it,
/// and the only way to test them is to run one.
///
/// Everything runs dry: `arm_dry` silences all five `SendInput` call sites, so
/// nothing here reaches the operating system.
fn run_script_selftest(rounds: u64) -> Result<()> {
    use std::sync::atomic::AtomicU64;

    virtual_desktop::init_thread();
    selftest::arm_dry();
    println!("Self-test: the script interpreter\n");

    let dir = paths::sub_dir("selftest");
    let _ = std::fs::create_dir_all(&dir);

    let mut failures: Vec<String> = Vec::new();
    let mut checks = 0u32;
    let mut check = |name: &str, ok: bool, detail: String| {
        checks += 1;
        println!("{:<52} {:>8}  {detail}", name, if ok { "ok" } else { "FAILED" });
        if !ok {
            failures.push(name.to_string());
        }
    };

    // A script whose steps can be counted from outside. `Log` is the only step that
    // touches nothing and leaves a trace, so the counting is done by wrapping the
    // run instead: what matters is where the program counter stopped, and that is
    // visible in the variables the run leaves behind.
    let run = |script: Vec<ScriptStep>, vars: Vec<(&str, Value)>| -> (ScriptEnd, std::collections::HashMap<String, Value>, Duration) {
        let (tx, _rx) = unbounded();
        let state = AppState::new(tx);
        // `stopping()` compares the run's generation against the live one, and a
        // fresh AppState starts at zero. A harness that forgot this would see every
        // run cancelled before its first step - which is exactly what it did.
        state.play_generation.store(1, Ordering::Relaxed);
        let mut data = MacroData::new(vec![MacroEvent {
            t_us: 0,
            kind: InputEventKind::Key { vk: 0x20, scan: 0, down: true, extended: false },
        }], 1000);
        data.script = script;
        let mut ctx = ScriptCtx {
            state: &state,
            data: &data,
            generation: 1,
            map: CoordMap::IDENTITY,
            vars: vars.into_iter().map(|(k, v)| (k.to_string(), v)).collect(),
            templates: Default::default(),
            last_text: String::new(),
            last_hit: Default::default(),
            latched: Default::default(),
            history: Default::default(),
            tally: Default::default(),
            learned: Default::default(),
            recover_stack: Vec::new(),
            recovered: Default::default(),
            pc: 0,
            step_id: 0,
            failure: None,
            run_folder: String::new(),
            depth: 0,
            called: Default::default(),
            notes: Default::default(),
        };
        let mut pressed = PressedInputs::default();
        let mut mover = MoveEngine::new(&state);
        let mut guard = FrameGuard::new(&state);
        let t0 = Instant::now();
        let end = run_script(&mut ctx, &mut pressed, &mut mover, &mut guard);
        (end, ctx.vars, t0.elapsed())
    };

    let bump = |name: &str| {
        ScriptStep::new(StepKind::SetVar {
            name: name.into(),
            op: VarOp::Add,
            value: Value::Num(1.0),
        })
    };
    // A picture that certainly is not on screen: no such template file exists, so
    // `find_image_into` returns false without ever looking.
    let missing = |miss: OnMiss| {
        ScriptStep::new(StepKind::ClickImage {
            template: "no_such_template_ever".into(),
            threshold: 0.99,
            button: MouseButton::Left,
            area: SearchArea::Rect { x: 0, y: 0, w: 32, h: 32 },
            edge: false,
            miss,
        })
    };

    // ---- the four policies, one at a time -----------------------------------
    println!("What a step that finds nothing does\n");
    println!("{:<52} {:>8}  detail", "check", "result");

    {
        let (end, vars, _) = run(vec![missing(OnMiss::Continue), bump("after")], vec![]);
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        check(
            "carry on: the next step still runs",
            end == ScriptEnd::Finished && after == 1.0,
            format!("{end:?}, after = {after}"),
        );
    }
    {
        let (end, vars, _) = run(vec![missing(OnMiss::Stop), bump("after")], vec![]);
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        check(
            "stop: the next step does not run",
            end == ScriptEnd::Finished && after == 0.0,
            format!("{end:?}, after = {after}"),
        );
    }
    {
        // while true { miss(Break); bump(inner) }  then bump(after)
        let script = vec![
            ScriptStep::new(StepKind::While { cond: Condition::Always }),
            missing(OnMiss::Break),
            bump("inner"),
            ScriptStep::new(StepKind::EndWhile),
            bump("after"),
        ];
        let (end, vars, took) = run(script, vec![]);
        let inner = vars.get("inner").map_or(-1.0, |v| v.as_num());
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        check(
            "leave the loop: an endless loop ends, once",
            end == ScriptEnd::Finished && inner == -1.0 && after == 1.0,
            format!("{end:?}, inner = {inner}, after = {after}, {:.0} ms", took.as_secs_f64() * 1000.0),
        );
    }
    {
        let times = 3;
        let delay = 120u64;
        let (end, vars, took) =
            run(vec![missing(OnMiss::Retry { times, delay_ms: delay }), bump("after")], vec![]);
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        let ms = took.as_secs_f64() * 1000.0;
        // Three retries at 120 ms each is 360 ms of napping, and `nap` sleeps in
        // 15 ms slices, so the floor is real and the ceiling is generous.
        let waited = ms >= (times as f64 * delay as f64 * 0.8);
        check(
            "try again: it waits, then stops",
            end == ScriptEnd::Finished && after == 0.0 && waited,
            format!("{end:?}, after = {after}, {ms:.0} ms for {times}x{delay} ms"),
        );
    }

    // ---- calling another macro ----------------------------------------------
    println!("\nCalling another macro\n");
    println!("{:<52} {:>8}  detail", "check", "result");

    // A callee that adds one to `n` and writes a string back.
    let child = {
        let mut d = MacroData::new(vec![], 0);
        d.script = vec![
            ScriptStep::new(StepKind::SetVar {
                name: "n".into(),
                op: VarOp::Add,
                value: Value::Num(1.0),
            }),
            ScriptStep::new(StepKind::SetVar {
                name: "from_child".into(),
                op: VarOp::Set,
                value: Value::Str("yes".into()),
            }),
        ];
        d
    };
    let child_path = dir.join("selftest_child.json");
    save_macro(&child_path, &child)?;

    {
        let script = vec![
            ScriptStep::new(StepKind::Call {
                path: child_path.to_string_lossy().to_string(),
                miss: OnMiss::Stop,
            }),
            bump("after"),
        ];
        let (end, vars, _) = run(script, vec![("n", Value::Num(41.0))]);
        let n = vars.get("n").map_or(0.0, |v| v.as_num());
        let back = vars.get("from_child").map(|v| v.to_string()).unwrap_or_default();
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        check(
            "variables go in and come back out",
            end == ScriptEnd::Finished && n == 42.0 && back == "yes" && after == 1.0,
            format!("n = {n}, from_child = {back:?}, after = {after}"),
        );
    }
    {
        let script = vec![
            ScriptStep::new(StepKind::Call {
                path: "no_such_macro_anywhere.json".into(),
                miss: OnMiss::Stop,
            }),
            bump("after"),
        ];
        let (end, vars, _) = run(script, vec![]);
        let after = vars.get("after").map_or(0.0, |v| v.as_num());
        check(
            "a file that will not load obeys its policy",
            end == ScriptEnd::Finished && after == 0.0,
            format!("{end:?}, after = {after}"),
        );
    }
    {
        // The one that would take the process down without a cap: a macro that
        // calls itself. Written to disk under its own name so the call really does
        // reload it rather than recursing on an in-memory copy.
        let self_path = dir.join("selftest_recursive.json");
        let mut recursive = MacroData::new(vec![], 0);
        recursive.script = vec![
            ScriptStep::new(StepKind::SetVar {
                name: "depth".into(),
                op: VarOp::Add,
                value: Value::Num(1.0),
            }),
            ScriptStep::new(StepKind::Call {
                path: self_path.to_string_lossy().to_string(),
                miss: OnMiss::Continue,
            }),
        ];
        save_macro(&self_path, &recursive)?;
        let script = vec![ScriptStep::new(StepKind::Call {
            path: self_path.to_string_lossy().to_string(),
            miss: OnMiss::Continue,
        })];
        let (end, vars, took) = run(script, vec![]);
        let depth = vars.get("depth").map_or(0.0, |v| v.as_num());
        // One `SetVar` per level, and the cap stops it entering the ninth.
        let want = MAX_CALL_DEPTH as f64;
        check(
            "a macro that calls itself stops at the cap",
            end == ScriptEnd::Finished && depth == want,
            format!("ran {depth} levels, cap is {want}, {:.0} ms", took.as_secs_f64() * 1000.0),
        );
    }

    // ---- the step gate -------------------------------------------------------
    println!("\nPausing before each step\n");
    println!("{:<52} {:>8}  detail", "check", "result");
    {
        let (tx, _rx) = unbounded();
        let state = AppState::new(tx);
        state.play_generation.store(1, Ordering::Relaxed);
        let mut data = MacroData::new(vec![], 0);
        data.script = (0..5).map(|_| bump("n")).collect();
        state.step_mode.store(true, Ordering::Relaxed);
        set_watching_vars(true);

        let st = state.clone();
        let done = Arc::new(AtomicU64::new(0));
        let d2 = done.clone();
        let handle = std::thread::Builder::new().name("gate".into()).spawn(move || {
            let mut ctx = ScriptCtx {
                state: &st,
                data: &data,
                generation: 1,
                map: CoordMap::IDENTITY,
                vars: Default::default(),
                templates: Default::default(),
                last_text: String::new(),
                last_hit: Default::default(),
                latched: Default::default(),
                history: Default::default(),
                tally: Default::default(),
                learned: Default::default(),
                recover_stack: Vec::new(),
                recovered: Default::default(),
                pc: 0,
                step_id: 0,
                failure: None,
                run_folder: String::new(),
                depth: 0,
                called: Default::default(),
                notes: Default::default(),
            };
            let mut pressed = PressedInputs::default();
            let mut mover = MoveEngine::new(&st);
            let mut guard = FrameGuard::new(&st);
            let end = run_script(&mut ctx, &mut pressed, &mut mover, &mut guard);
            d2.store(1, Ordering::Relaxed);
            (end, ctx.vars.get("n").map_or(0.0, |v| v.as_num()))
        })?;

        // It must be parked, and it must be publishing what it is parked on.
        std::thread::sleep(Duration::from_millis(250));
        let parked = script_view().is_some_and(|v| v.waiting);
        let still_running = done.load(Ordering::Relaxed) == 0;
        check(
            "the run parks before its first step",
            parked && still_running,
            format!("waiting = {parked}, finished = {}", !still_running),
        );

        // Let it through one step at a time and watch the counter follow.
        let mut seen = Vec::new();
        for _ in 0..5 {
            state.step_once.store(true, Ordering::Relaxed);
            std::thread::sleep(Duration::from_millis(120));
            seen.push(script_view().map_or(0, |v| v.pc));
        }
        state.step_mode.store(false, Ordering::Relaxed);
        state.step_once.store(true, Ordering::Relaxed);
        let (end, n) = handle.join().map_err(|_| anyhow::anyhow!("the gate thread panicked"))?;
        check(
            "letting it through one step at a time runs them all",
            end == ScriptEnd::Finished && n == 5.0,
            format!("{end:?}, n = {n}, program counter went {seen:?}"),
        );
        set_watching_vars(false);
    }
    {
        // The failure mode that would be worst: a run parked in step mode that Stop
        // cannot reach. The gate has to answer to `stop_play` as well as to the
        // button, or the only way out would be to kill the process.
        let (tx, _rx) = unbounded();
        let state = AppState::new(tx);
        state.play_generation.store(1, Ordering::Relaxed);
        let mut data = MacroData::new(vec![], 0);
        data.script = (0..3).map(|_| bump("n")).collect();
        state.step_mode.store(true, Ordering::Relaxed);
        set_watching_vars(true);
        let st = state.clone();
        let handle = std::thread::Builder::new().name("gate2".into()).spawn(move || {
            let mut ctx = ScriptCtx {
                state: &st,
                data: &data,
                generation: 1,
                map: CoordMap::IDENTITY,
                vars: Default::default(),
                templates: Default::default(),
                last_text: String::new(),
                last_hit: Default::default(),
                latched: Default::default(),
                history: Default::default(),
                tally: Default::default(),
                learned: Default::default(),
                recover_stack: Vec::new(),
                recovered: Default::default(),
                pc: 0,
                step_id: 0,
                failure: None,
                run_folder: String::new(),
                depth: 0,
                called: Default::default(),
                notes: Default::default(),
            };
            let mut pressed = PressedInputs::default();
            let mut mover = MoveEngine::new(&st);
            let mut guard = FrameGuard::new(&st);
            run_script(&mut ctx, &mut pressed, &mut mover, &mut guard)
        })?;
        std::thread::sleep(Duration::from_millis(200));
        let t0 = Instant::now();
        state.stop_play.store(true, Ordering::Relaxed);
        let end = handle.join().map_err(|_| anyhow::anyhow!("the gate thread panicked"))?;
        let ms = t0.elapsed().as_secs_f64() * 1000.0;
        check(
            "Stop releases a run parked in step mode",
            end == ScriptEnd::Stopped && ms < 1000.0,
            format!("{end:?} after {ms:.0} ms"),
        );
        set_watching_vars(false);
    }

    // ---- the stress round ----------------------------------------------------
    // Every policy, in a loop, with calls nested under it, run until something
    // either leaks a press or stops agreeing with itself. The counters here are the
    // same ones stage 5 watches: a press left held is the failure this program can
    // least afford.
    println!("\n{rounds} rounds of every policy, with calls under them\n");
    {
        let mut ends = std::collections::BTreeMap::<String, u64>::new();
        let t0 = Instant::now();
        let mut worst_held = 0i64;
        for r in 0..rounds {
            let miss = match r % 4 {
                0 => OnMiss::Continue,
                1 => OnMiss::Stop,
                2 => OnMiss::Break,
                _ => OnMiss::Retry { times: 1, delay_ms: 0 },
            };
            let script = vec![
                ScriptStep::new(StepKind::While { cond: Condition::Always }),
                ScriptStep::new(StepKind::Call {
                    path: child_path.to_string_lossy().to_string(),
                    miss: OnMiss::Continue,
                }),
                missing(miss),
                ScriptStep::new(StepKind::Break),
                ScriptStep::new(StepKind::EndWhile),
                bump("after"),
            ];
            let (end, _, _) = run(script, vec![("n", Value::Num(0.0))]);
            *ends.entry(format!("{end:?}")).or_default() += 1;
            worst_held = worst_held.max(selftest::held().abs());
        }
        let per = t0.elapsed().as_secs_f64() * 1000.0 / rounds as f64;
        println!("  ends: {ends:?}");
        check(
            "no press left held across the whole stress run",
            worst_held == 0,
            format!("worst |held| = {worst_held}, {per:.2} ms a round"),
        );
        check(
            "every round ended in a way the interpreter names",
            ends.keys().all(|k| k == "Finished"),
            format!("{} distinct endings", ends.len()),
        );
    }

    let _ = std::fs::remove_file(&child_path);
    let _ = std::fs::remove_file(dir.join("selftest_recursive.json"));
    selftest::disarm();

    println!("\n{checks} checks, {} failed", failures.len());
    if !failures.is_empty() {
        println!("  {}", failures.join("\n  "));
        anyhow::bail!("{} script self-test check(s) failed", failures.len());
    }
    println!(
        "\nHow to read this:\n\
         - The four policies are the whole of what 1.5.0 changed about a step that\n\
           finds nothing, and `carry on` has to still be indistinguishable from\n\
           1.4.0 or every existing macro has changed behaviour.\n\
         - `try again` is timed rather than counted: the retries are only useful if\n\
           they actually wait, and a retry loop that spins is worse than none.\n\
         - The recursion round is the one that would otherwise end the process. With\n\
           `panic = \"abort\"` a stack overflow is not an error anybody handles.\n\
         - `Stop releases a run parked in step mode` is the one to look at first if\n\
           step mode ever feels wrong. A run that only the Next button can free, in\n\
           a program whose whole point is a global stop key, would be a trap."
    );
    Ok(())
}

fn run_timing_selftest() -> Result<()> {
    // 3000 events 5 ms apart is 15 seconds per scenario: long enough for drift to
    // show, short enough that the whole set runs in about two minutes.
    const N: usize = 3000;
    const GAP_US: u64 = 5_000;
    let data = synthetic_macro(N, GAP_US);
    // Same order of length, but paced the way a person clicks.
    let paced = human_paced_macro(45);
    println!("Self-test: replay timing");
    println!("{N} events, {} ms apart, no input is actually sent.\n", GAP_US / 1000);

    let runs = [
        timing_scenario("baseline 1.0x", &data, 1.0, None, false, usize::MAX, 0),
        timing_scenario("slow 0.1x", &data, 0.1, None, false, usize::MAX, 0),
        timing_scenario("fast 3.0x", &data, 3.0, None, false, usize::MAX, 0),
        timing_scenario("400 ms stall", &data, 1.0, None, false, N / 2, 400_000),
        timing_scenario("guard 30 FPS", &data, 1.0, Some(30), false, usize::MAX, 0),
        timing_scenario("guard + stall", &data, 1.0, Some(30), false, N / 2, 400_000),
        timing_scenario("human movement", &data, 1.0, None, true, usize::MAX, 0),
        timing_scenario("paced, no guard", &paced, 1.0, None, false, usize::MAX, 0),
        timing_scenario("paced + guard", &paced, 1.0, Some(30), false, usize::MAX, 0),
    ];

    println!(
        "{:<16} {:>6} {:>9} {:>8} {:>9} {:>9} {:>8} {:>6} {:>8} {:>7} {:>8}",
        "scenario",
        "events",
        "mean us",
        "p50 us",
        "p99 us",
        "max us",
        "drift ms",
        "slips",
        "slip ms",
        "burst",
        "guard ms"
    );
    for r in &runs {
        println!(
            "{:<16} {:>6} {:>9.0} {:>8} {:>9} {:>9} {:>8} {:>6} {:>8} {:>7} {:>8}",
            r.label,
            r.dispatched,
            r.mean_us,
            r.p50_us,
            r.p99_us,
            r.max_us,
            r.drift_us / 1000,
            r.slips,
            r.slipped_ms,
            r.longest_burst,
            r.guard_added_ms
        );
    }

    println!("\nwall clock per scenario:");
    for r in &runs {
        println!("  {:<16} {:>6} ms", r.label, r.wall_ms);
    }

    println!(
        "\nHow to read this:\n\
         - p99 is the honest accuracy figure. Under one frame of whatever the target\n\
           renders at is fine; tens of milliseconds on an idle machine is not.\n\
         - drift is the last event's lateness. It should not grow with the run.\n\
         - burst is the longest run of dispatches under 500 us apart. On a 5 ms\n\
           recording anything above 1 means the backlog went out in a clump, which is\n\
           the failure the slip logic exists to prevent. The stall rows are the ones\n\
           that matter: they should slip once and keep burst low.\n\
         - guard ms is what the frame guard added. Compare the two `paced` rows, not\n\
           the `guard 30 FPS` one: the evenly spaced macro clicks every 15 ms, which no\n\
           person does, so the guard has to stretch every press and the cost is an\n\
           artefact of the test shape rather than a forecast for real use."
    );
    Ok(())
}

/// Plays a macro with no window.
///
/// `here` is the file the macro came from, when there was one: a `Call` step
/// resolves a relative name next to the macro that named it, and that is the only
/// place that knowledge exists. An exported player has no file and passes `None`,
/// which is the documented limitation rather than an oversight.
///
/// `config` is applied in full. Until 1.7.0 it was not, and the gap was quiet and
/// wide: this function took four values and built a default `AppState` for
/// everything else, so a macro run from Task Scheduler lost the frame guard, the
/// window anchoring, the pause-while-not-in-front, human-like movement, timing
/// jitter, fast capture and the failure screenshot - twenty-four of the
/// twenty-eight settings the interface applies. The same macro behaved one way in
/// the window and another way from a `.bat`, with nothing said about it.
/// `--check`: says whether a macro is fit to run, and stops.
///
/// This is the half of the pre-flight that the window cannot provide. A macro in
/// Task Scheduler runs at four in the morning with nobody to read a panel, and the
/// failure people actually hit - a template renamed, a called macro moved - is
/// knowable in a tenth of a second before any input is sent. Put this in front of
/// the real run and the night's work either happens or does not happen, instead of
/// happening halfway.
///
/// The exit code is the product: 0 fit, 1 not, 2 unreadable. Warnings print and do
/// not change it, because a fixed coordinate is not a reason to cancel a run.
/// Draws the handbook window.
///
/// A free function rather than a method: a deferred viewport's callback must be
/// `Send + Sync + 'static`, so there is no application here to reach into. Everything
/// it needs is in `handbook_state()`.
///
/// Two panes, because a manual with no table of contents is one you can only read in
/// order, and nobody reads a manual in order.
fn handbook_window(root: &mut egui::Ui) {
    let (lang, topic, mut query, jump) = {
        let hb = handbook_state().lock();
        (hb.lang, hb.topic, hb.query.clone(), hb.jump)
    };
    // Language index 0 means "whatever the system is", and the second argument is
    // what that resolves to — so passing the chosen language there asks for exactly
    // that language without a second table lookup of our own.
    let s = get_strings(0, lang);
    let mut chose: Option<&'static str> = None;

    // A little longer than egui's default, which makes a wheel notch land rather
    // than snap. Set here rather than globally: the rest of the program is controls,
    // where a snappy list is right; this is prose, where the eye has to follow.
    root.style_mut().scroll_animation.points_per_second = 1400.0;
    root.style_mut().scroll_animation.duration = egui::Rangef::new(0.12, 0.35);
    // While the pointer is over the window, keep drawing: a scroll animation that is
    // only stepped when an event arrives moves in jerks.
    if root.ctx().input(|i| i.pointer.has_pointer()) {
        root.ctx().request_repaint();
    }

    egui::CentralPanel::default().show(root, |ui| {
        egui::Panel::left("hb_list")
            .resizable(true)
            .default_size(272.0)
            .size_range(180.0..=440.0)
            .show(ui, |ui| {
                ui.add_space(8.0);
                if ui
                    .add(
                        egui::TextEdit::singleline(&mut query)
                            .hint_text(s.hb_search)
                            .desired_width(f32::INFINITY),
                    )
                    .changed()
                {
                    handbook_state().lock().query = query.clone();
                }
                let hits: Vec<&'static handbook::Topic> = {
                    let mut hb = handbook_state().lock();
                    let key = (query.clone(), lang);
                    if hb.hits_for.as_ref() != Some(&key) {
                        hb.hits = handbook::search(&query, lang)
                            .into_iter()
                            .map(|t| t.id)
                            .collect();
                        hb.hits_for = Some(key);
                    }
                    hb.hits.iter().filter_map(|id| handbook::find(id)).collect()
                };
                if hits.is_empty() {
                    ui.add_space(10.0);
                    ui.label(egui::RichText::new(s.hb_none).weak());
                }
                let accent = ui.visuals().hyperlink_color;
                egui::ScrollArea::vertical()
                    .auto_shrink([false, false])
                    .show(ui, |ui| {
                        for group in handbook::Group::ALL {
                            let mine: Vec<_> =
                                hits.iter().filter(|t| t.group == group).collect();
                            if mine.is_empty() {
                                continue;
                            }
                            ui.add_space(10.0);
                            ui.label(
                                egui::RichText::new(group.title(lang))
                                    .small()
                                    .strong()
                                    .color(accent),
                            );
                            for t in mine {
                                if ui
                                    .selectable_label(topic == t.id, t.title(lang))
                                    .clicked()
                                {
                                    chose = Some(t.id);
                                }
                            }
                        }
                        ui.add_space(14.0);
                    });
            });

        let Some(article) = handbook::find(topic).map(|t| t.article(lang)) else {
            return;
        };
        // A new article starts at its own beginning rather than at the scroll offset
        // of the one before it, which is halfway down a page nobody has read. The
        // salt changes with the article, so each gets its own remembered position.
        egui::ScrollArea::vertical()
            .auto_shrink([false, false])
            .id_salt(("hb_article", jump))
            .show(ui, |ui| {
                ui.set_max_width(760.0_f32.min(ui.available_width()));
                ui.add_space(12.0);
                ui.heading(article.title);
                ui.add_space(4.0);
                ui.separator();
                article_ui(ui, article.body);
                ui.add_space(28.0);
            });
    });

    if let Some(id) = chose {
        let mut hb = handbook_state().lock();
        hb.topic = id;
        hb.jump = hb.jump.wrapping_add(1);
    }
    if root.input(|i| i.viewport().close_requested()) {
        handbook_state().lock().open = false;
    }
}

/// Draws one article.
///
/// The markup is deliberately four characters wide - `#` heading, `-` bullet,
/// `>` something worth a box round it, and inline `` `code` `` and `**bold**`. A
/// manual that needed more than that would be a manual that had stopped explaining
/// and started decorating.
///
/// Paragraphs go through a `LayoutJob` rather than a row of labels, because a row of
/// labels wraps between the labels and not inside them, and a sentence with a piece
/// of code in the middle of it would break in the wrong places.
fn article_ui(ui: &mut egui::Ui, body: &str) {
    let v = ui.visuals().clone();
    let body_size = 14.0;
    let plain = v.text_color();
    let dim = v.weak_text_color();
    let accent = v.hyperlink_color;

    // The measure is taken once, from the column the article is set in, rather than
    // from whatever `available_width` happens to be inside a nested layout. A bullet
    // is drawn inside a horizontal row, where that number is the width left after
    // the dot - and a paragraph wrapped to the wrong width overflows its column
    // rather than wrapping short, which is how bullets came to run off the edge.
    let column = ui.available_width();
    let job_for = |text: &str, colour: egui::Color32, size: f32, w: f32, dot: bool| {
        let mut job = egui::text::LayoutJob::default();
        job.wrap.max_width = w;
        if dot {
            job.append(
                "\u{2022}  ",
                0.0,
                egui::TextFormat {
                    font_id: egui::FontId::new(size, egui::FontFamily::Proportional),
                    color: dim,
                    ..Default::default()
                },
            );
        }
        for (style, run) in handbook::runs(text) {
            let (family, colour, size) = match style {
                handbook::Style::Plain => (egui::FontFamily::Proportional, colour, size),
                handbook::Style::Bold => (egui::FontFamily::Proportional, plain, size),
                handbook::Style::Code => (egui::FontFamily::Monospace, accent, size - 1.0),
                handbook::Style::Emph => (egui::FontFamily::Proportional, colour, size),
            };
            job.append(
                &run,
                0.0,
                egui::TextFormat {
                    font_id: egui::FontId::new(size, family),
                    color: colour,
                    // The shipped proportional font has one weight, so bold is a
                    // brighter colour and emphasis has to be the slant.
                    italics: style == handbook::Style::Emph,
                    ..Default::default()
                },
            );
        }
        job
    };

    let mut after_blank = true;
    for line in handbook::lines(body) {
        match line {
            handbook::Line::Blank => {
                if !after_blank {
                    ui.add_space(7.0);
                }
                after_blank = true;
            }
            handbook::Line::Heading(t) => {
                ui.add_space(12.0);
                ui.label(egui::RichText::new(t).size(16.0).strong().color(accent));
                ui.add_space(3.0);
                after_blank = false;
            }
            handbook::Line::Bullet(t) => {
                // Indented rather than laid out horizontally. A horizontal row hands
                // its children a width to extend into rather than one to wrap at, so
                // a long bullet ran off the right edge while the paragraph above it
                // wrapped correctly.
                ui.indent("hb_bullet", |ui| {
                    let job = job_for(t, plain, body_size, column - 22.0, true);
                    ui.label(job);
                });
                after_blank = false;
            }
            handbook::Line::Note(t) => {
                ui.add_space(6.0);
                egui::Frame::new()
                    .fill(v.faint_bg_color)
                    .inner_margin(egui::Margin::symmetric(10, 8))
                    .corner_radius(egui::CornerRadius::same(4))
                    .show(ui, |ui| {
                        let job = job_for(t, dim, body_size, column - 24.0, false);
                        ui.label(job);
                    });
                ui.add_space(4.0);
                after_blank = false;
            }
            handbook::Line::Code(t) => {
                ui.label(
                    egui::RichText::new(t)
                        .monospace()
                        .size(body_size - 1.0)
                        .color(dim),
                );
                after_blank = false;
            }
            handbook::Line::Para(t) => {
                let job = job_for(t, plain, body_size, column, false);
                ui.label(job);
                after_blank = false;
            }
        }
    }
}

/// What the handbook window needs to draw itself.
///
/// Behind an `Arc<Mutex<..>>` because the window is a **deferred** viewport, and a
/// deferred viewport's callback has to be `Send + Sync + 'static` - it cannot borrow
/// the application.
///
/// Deferred rather than immediate for one reason, and it is a Windows one: an
/// immediate viewport is drawn from inside the parent's `update`, and a minimised
/// window on Windows receives no `RedrawRequested` at all. So the moment the main
/// window went to the taskbar, every child window it owned stopped responding -
/// could not be scrolled, could not be closed, could not be moved. A deferred
/// viewport is driven by its own redraws and does not care what the parent is doing.
#[derive(Default)]
pub struct HandbookState {
    pub open: bool,
    pub topic: &'static str,
    pub query: String,
    pub lang: Lang,
    /// The last search and its answer.
    ///
    /// Without this, every frame lowercased all forty-six articles again — about a
    /// hundred kilobytes of allocation and case folding per frame, for a list that
    /// only changes when somebody types. It is what made the window feel heavy.
    pub hits: Vec<&'static str>,
    pub hits_for: Option<(String, Lang)>,
    /// Bumped when the topic changes, so the article pane can scroll back to the top
    /// instead of keeping the offset from the article you were just reading.
    pub jump: u64,
}

static HANDBOOK: OnceLock<Arc<Mutex<HandbookState>>> = OnceLock::new();

fn handbook_state() -> &'static Arc<Mutex<HandbookState>> {
    HANDBOOK.get_or_init(|| {
        Arc::new(Mutex::new(HandbookState { topic: "first-run", ..Default::default() }))
    })
}

/// Remembers which handbook article a section belongs to.
///
/// Takes the response rather than wrapping the call: a `CollapsingHeader` body
/// closure borrows the whole application, so there is nothing left over to hand to a
/// wrapper. Costs one comparison per section per frame and no pixels at all, which
/// is what makes it a better answer than a help icon beside every heading.
fn help_from<R>(
    slot: &mut &'static str,
    topic: &'static str,
    r: egui::CollapsingResponse<R>,
) {
    if r.header_response.clicked() {
        *slot = topic;
    }
}

/// Whether the command line asked to run past a failed pre-flight.
///
/// Read from the arguments rather than passed down, because the exported
/// self-running player reaches `run_headless` without going through `parse_cli` at
/// all - and somebody who exported a macro and has looked at what the check objects
/// to needs the same way past it as everybody else.
fn preflight_may_be_skipped() -> bool {
    std::env::args().any(|a| a == "--no-check")
}

fn run_check(path: Option<&Path>, config: &AppConfig) -> Result<()> {
    let Some(path) = path else {
        eprintln!("--check needs --play <FILE>");
        std::process::exit(2);
    };
    let data = match load_macro(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("{}: {e:#}", path.display());
            std::process::exit(2);
        }
    };
    // English, whatever the window is set to: this goes into a scheduler's log, and
    // a log in a language chosen for a screen nobody is at is a log in the wrong
    // language.
    let s = get_strings(0, Lang::En);
    let rep = check_macro(&data, CheckEnv::from_config(config), Some(path));
    println!("{}", path.display());
    for line in report_lines(&rep, s) {
        println!("  {line}");
    }
    println!("  {}/100", rep.score);
    let caps: Vec<&str> = [
        (rep.caps.mouse, s.cap_mouse),
        (rep.caps.keyboard, s.cap_keyboard),
        (rep.caps.screen, s.cap_screen),
        (rep.caps.ocr, s.cap_ocr),
        (rep.caps.uia, s.cap_uia),
        (rep.caps.clipboard, s.cap_clipboard),
        (rep.caps.files, s.cap_files),
        (rep.caps.windows, s.cap_windows),
        (rep.caps.launch, s.cap_launch),
        (rep.caps.power, s.cap_power),
        (rep.caps.external, s.cap_external),
    ]
    .into_iter()
    .filter_map(|(on, n)| on.then_some(n))
    .collect();
    if !caps.is_empty() {
        println!("  {} {}", s.check_caps, caps.join(", "));
    }
    std::process::exit(if rep.ready() { 0 } else { 1 });
}

fn run_headless(
    data: MacroData,
    here: Option<PathBuf>,
    config: &AppConfig,
    loops: u64,
    speed: f64,
    absolute: bool,
    delay_ms: u64,
) -> Result<()> {
    // The pre-flight, in the one place it is worth the most. Nobody is at this
    // screen: a macro that cannot work fails on the step it fails on, having already
    // done half a night's work, and the reason was knowable before the first click.
    //
    // Errors stop it and warnings do not, which is the same rule the window uses.
    // `--no-check` is the way past it for somebody who has looked and disagrees -
    // and the check still runs and is still written to the log, because the point is
    // to have said so, not to have won the argument.
    let rep = check_macro(&data, CheckEnv::from_config(config), here.as_deref());
    let s = get_strings(0, Lang::En);
    if !rep.ready() {
        for line in report_lines(&rep, s) {
            warn!("{line}");
        }
        if !preflight_may_be_skipped() {
            anyhow::bail!(
                "this macro has {} thing(s) wrong with it that will stop it working. \
                 Fix them, or pass --no-check to run it anyway",
                rep.errors()
            );
        }
        warn!("--no-check: starting anyway");
    } else if rep.warnings() > 0 {
        for line in report_lines(&rep, s) {
            info!("{line}");
        }
    }

    let (tx, rx) = unbounded();
    let state = AppState::new(tx);
    // Everything the window would have applied, first...
    apply_config_to_state(config, &state);
    // ...then the few things the caller is entitled to override: the command line
    // beats the file, and an exported player carries its own choices.
    state.loop_play.store(loops == 0, Ordering::Relaxed);
    state.play_count_limit.store(loops.max(1), Ordering::Relaxed);
    state.absolute_mouse.store(absolute, Ordering::Relaxed);
    state.repeat_delay_ms.store(delay_ms, Ordering::Relaxed);
    *state.speed.lock() = speed.clamp(0.05, 10.0);
    *state.current_path.lock() = here;

    std::thread::spawn(move || while rx.recv().is_ok() {});

    #[cfg(windows)]
    {
        let st = state.clone();
        std::thread::Builder::new()
            .name("hooks".into())
            .spawn(move || input_hook_thread(st, HookMode::HotkeysOnly, false))?;
    }

    println!("Playing {} events…", data.events.len());
    let generation = state.play_generation.fetch_add(1, Ordering::SeqCst) + 1;
    state.playing.store(true, Ordering::Relaxed);
    playback_loop(state, data, generation);
    println!("Done.");
    Ok(())
}

// ============================================================================
// Entry point
// ============================================================================

fn init_logging() -> Option<tracing_appender::non_blocking::WorkerGuard> {
    let appender = tracing_appender::rolling::daily(paths::log_dir(), "macro-recorder.log");
    let (writer, guard) = tracing_appender::non_blocking(appender);
    let filter = tracing_subscriber::EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info"));
    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_writer(writer)
        .with_ansi(false)
        .init();
    Some(guard)
}

/// Taskbar / title-bar icon, with a fallback if the embedded blob is the wrong size.
fn load_window_icon() -> egui::IconData {
    if ICON_RGBA.len() == (ICON_SIZE * ICON_SIZE * 4) as usize {
        egui::IconData { rgba: ICON_RGBA.to_vec(), width: ICON_SIZE, height: ICON_SIZE }
    } else {
        warn!("embedded icon has an unexpected size - using the OS default");
        egui::IconData::default()
    }
}

fn main() -> Result<()> {
    init_epoch();
    let _log_guard = init_logging();
    platform::set_dpi_awareness();

    // An exported self-running executable carries its macro appended to the image.
    if let Some(payload) = read_self_payload() {
        platform::attach_parent_console();
        info!("running as an exported macro player");
        let mut data = payload.macro_data;
        if data.normalize().is_err() {
            return Ok(());
        }
        // An exported player has its own folder, so it reads its own settings file
        // if somebody put one there and defaults otherwise. The payload still wins
        // for the four choices it carries - they were made when the .exe was built.
        let config = load_config();
        return run_headless(
            data,
            None,
            &config,
            payload.loops,
            payload.speed,
            payload.absolute_mouse,
            payload.repeat_delay_ms,
        );
    }

    let args = parse_cli();
    if let Some(want) = args.simd.as_deref() {
        platform::attach_parent_console();
        apply_simd_flag(want);
    }
    if args.help || args.version {
        platform::attach_parent_console();
        if args.version {
            println!("macro-recorder {APP_VERSION}");
        } else {
            print!("{HELP_TEXT}");
        }
        return Ok(());
    }

    if let Some(which) = args.selftest.as_deref() {
        platform::attach_parent_console();
        return run_selftest(which);
    }

    let mut config = load_config();
    publish_hotkeys(&config);
    info!("data directory: {}", paths::data_dir().display());

    // Before `--no-gui`, and deliberately so: `--check --play x --no-gui` has to
    // check and stop rather than check and then run the thing anyway.
    if args.check {
        platform::attach_parent_console();
        return run_check(args.play.as_deref(), &config);
    }

    if args.no_gui {
        platform::attach_parent_console();
        let path = args.play.clone().context("--no-gui requires --play <FILE>")?;
        let data = load_macro(&path)?;
        return run_headless(
            data,
            Some(path),
            &config,
            args.loops.unwrap_or(if config.loop_play { 0 } else { config.play_count_limit }),
            args.speed.unwrap_or(config.speed),
            config.absolute_mouse,
            config.repeat_delay_ms,
        );
    }

    if !platform::acquire_single_instance() {
        platform::focus_existing_instance();
        info!("another instance is already running - exiting");
        return Ok(());
    }

    let (tx, rx) = unbounded();
    let state = AppState::new(tx);
    apply_config_to_state(&config, &state);

    paths::ensure_dirs();
    expander::load();
    expander::start_worker();

    {
        let st = state.clone();
        std::thread::Builder::new()
            .name("collector".into())
            .spawn(move || collector_thread(rx, st))?;
    }

    {
        let st = state.clone();
        std::thread::Builder::new()
            .name("scheduler".into())
            .spawn(move || scheduler_thread(st))?;
    }

    {
        let st = state.clone();
        std::thread::Builder::new()
            .name("perf".into())
            .spawn(move || perf_thread(st))?;
    }

    #[cfg(windows)]
    {
        let st = state.clone();
        let tray_on = config.tray_enabled;
        std::thread::Builder::new()
            .name("hooks".into())
            .spawn(move || input_hook_thread(st, HookMode::Full, tray_on))?;
    }

    if let Some(path) = args.play.clone() {
        match load_macro(&path) {
            Ok(data) => {
                state.recorded_time_us.store(data.duration_us, Ordering::Relaxed);
                *state.macro_data.lock() = data;
                *state.current_path.lock() = Some(path.clone());
                config.push_recent(&path);
            }
            Err(e) => warn!("could not preload {}: {e}", path.display()),
        }
    }
    if let Some(n) = args.loops {
        config.loop_play = n == 0;
        config.play_count_limit = n.max(1);
    }
    if let Some(sp) = args.speed {
        config.speed = sp;
    }
    config.sanitize();
    apply_config_to_state(&config, &state);

    let mut viewport = egui::ViewportBuilder::default()
        .with_inner_size([DEFAULT_WINDOW.0, DEFAULT_WINDOW.1])
        .with_min_inner_size([MIN_WINDOW.0, MIN_WINDOW.1])
        .with_icon(load_window_icon())
        .with_transparent(true);
    if config.always_on_top {
        viewport = viewport.with_always_on_top();
    }

    let options = eframe::NativeOptions { viewport, ..Default::default() };
    let st = state.clone();

    eframe::run_native(
        APP_TITLE,
        options,
        Box::new(move |cc| Ok(Box::new(MacroApp::new(cc, st, config)))),
    )
    .map_err(|e| anyhow::anyhow!("{e}"))
}

