    #[test]
    fn a_missing_called_macro_is_an_error_but_a_variable_path_is_not_guessed_at() {
        let no = |_: &str| false;
        let none = |_: &str| Vec::new();
        let templates = kind_env(&[]);
        let env = health::Env {
            templates: &templates,
            call_exists: &no,
            call_targets: &none,
            self_path: None,
            target_window: true,
            ocr_lang: true,
            display: None,
            power_action: false,
        };
        let data = macro_of(
            1,
            vec![
                ScriptStep::new(StepKind::Call { path: "login.mrz".into(), miss: OnMiss::Stop }),
                // Built at run time out of a variable: there is nothing to resolve
                // without running the macro, and guessing would cry wolf every time.
                ScriptStep::new(StepKind::Call { path: "{which}.mrz".into(), miss: OnMiss::Stop }),
            ],
        );
        let r = health::check(&data, &env);
        let missing: Vec<&str> = r
            .findings
            .iter()
            .filter(|f| f.rule == health::Rule::CallMissing)
            .map(|f| f.detail.as_str())
            .collect();
        assert_eq!(missing, vec!["login.mrz"]);
        assert!(r.caps.external, "a Call is an external dependency");
    }

    #[test]
    fn a_loop_knows_whether_it_can_end() {
        let endless = vec![
            ScriptStep::new(StepKind::While { cond: Condition::Always }),
            ScriptStep::new(StepKind::Wait { ms: 100 }),
            ScriptStep::new(StepKind::EndWhile),
        ];
        assert!(has(
            &check_with(&macro_of(1, endless), &kind_env(&[])),
            health::Rule::LoopWithNoWayOut
        ));

        // A break ends it.
        let with_break = vec![
            ScriptStep::new(StepKind::While { cond: Condition::Always }),
            ScriptStep::new(StepKind::Break),
            ScriptStep::new(StepKind::EndWhile),
        ];
        assert!(!has(
            &check_with(&macro_of(1, with_break), &kind_env(&[])),
            health::Rule::LoopWithNoWayOut
        ));

        // So does a miss policy that leaves it.
        let with_policy = vec![
            ScriptStep::new(StepKind::While { cond: Condition::Always }),
            ScriptStep::new(StepKind::ClickImage {
                template: "x".into(),
                threshold: 0.9,
                button: MouseButton::Left,
                area: SearchArea::ActiveWindow,
                edge: false,
                miss: OnMiss::Break,
            }),
            ScriptStep::new(StepKind::EndWhile),
        ];
        assert!(!has(
            &check_with(&macro_of(1, with_policy), &kind_env(&["x"])),
            health::Rule::LoopWithNoWayOut
        ));

        // And a condition that is not "always" is its own way out.
        let conditional = vec![
            ScriptStep::new(StepKind::While {
                cond: Condition::Var {
                    name: "n".into(),
                    cmp: Cmp::Lt,
                    value: Value::Num(10.0),
                },
            }),
            ScriptStep::new(StepKind::EndWhile),
        ];
        assert!(!has(
            &check_with(&macro_of(1, conditional), &kind_env(&[])),
            health::Rule::LoopWithNoWayOut
        ));
    }

    #[test]
    fn a_break_inside_a_nested_loop_does_not_count_for_the_outer_one() {
        // The part worth getting right: a `Break` two levels down ends the inner
        // loop and says nothing about this one.
        let script = vec![
            ScriptStep::new(StepKind::While { cond: Condition::Always }), // 0, outer
            ScriptStep::new(StepKind::While { cond: Condition::Always }), // 1, inner
            ScriptStep::new(StepKind::Break),                             // 2, ends inner
            ScriptStep::new(StepKind::EndWhile),                          // 3
            ScriptStep::new(StepKind::EndWhile),                          // 4
        ];
        let r = check_with(&macro_of(1, script), &kind_env(&[]));
        let endless: Vec<Option<usize>> = r
            .findings
            .iter()
            .filter(|f| f.rule == health::Rule::LoopWithNoWayOut)
            .map(|f| f.step)
            .collect();
        assert_eq!(endless, vec![Some(0)], "only the outer loop is endless");
    }

    #[test]
    fn the_same_warning_over_and_over_is_one_habit_not_twelve_problems() {
        // Twelve fixed coordinates should dent the score, not flatten it - a score
        // that collapses to zero stops being read.
        let many: Vec<ScriptStep> = (0..12)
            .map(|i| {
                ScriptStep::new(StepKind::Click {
                    x: i * 10,
                    y: 100,
                    button: MouseButton::Left,
                })
            })
            .collect();
        let r = check_with(&macro_of(1, many), &kind_env(&[]));
        assert_eq!(r.warnings(), 12);
        assert_eq!(r.aiming.fixed, 12);
        // 5 + 3+3+3 + 1x8 = 22
        assert_eq!(r.score, 78);
        assert!(r.score > 0, "a score of zero tells nobody anything");
    }

    #[test]
    fn errors_cost_far_more_than_warnings() {
        let one_error = macro_of(
            2,
            vec![ScriptStep::new(StepKind::PlayEvents { from: 0, to: 99, between: None })],
        );
        let one_warning = macro_of(
            2,
            vec![ScriptStep::new(StepKind::Click { x: 1, y: 1, button: MouseButton::Left })],
        );
        assert_eq!(check_with(&one_error, &kind_env(&[])).score, 80);
        assert_eq!(check_with(&one_warning, &kind_env(&[])).score, 95);
    }

    #[test]
    fn capabilities_are_worked_out_from_the_steps_not_declared() {
        // The manifest has to be right about a macro somebody else wrote.
        let script = vec![
            ScriptStep::new(StepKind::Run { path: "notepad".into(), args: String::new() }),
            ScriptStep::new(StepKind::ReadText {
                x: 0,
                y: 0,
                w: 10,
                h: 10,
                var: "t".into(),
                prep: ocr::Prep::default(),
            }),
            ScriptStep::new(StepKind::GetText {
                source: TextSource::Clipboard,
                var: "c".into(),
            }),
            ScriptStep::new(StepKind::Call { path: "other".into(), miss: OnMiss::Stop }),
        ];
        let r = check_with(&macro_of(1, script), &kind_env(&[]));
        assert!(r.caps.launch, "Run a program starts a program");
        assert!(r.caps.ocr && r.caps.screen, "reading text looks at the screen");
        assert!(r.caps.clipboard);
        assert!(r.caps.external);
        assert!(r.caps.risky(), "launching and calling out both deserve a second look");
        assert!(!r.caps.power, "the end action is a setting, not part of the macro");
    }

